# ═══════════════════════════════════════════════════════════════
# NULL合并运算符（用于默认值处理）
# ═══════════════════════════════════════════════════════════════
`%||%` <- function(a, b) {
  if (is.null(a)) b else a
}

# ═══════════════════════════════════════════════════════════════
# 控制台输出增强工具函数
# ═══════════════════════════════════════════════════════════════

# 打印主标题（双线框）
print_main_title <- function(title, width = 60) {
  top <- paste0("╔", strrep("═", width - 2), "╗")
  padding <- width - nchar(title) - 4
  left_pad <- floor(padding / 2)
  right_pad <- ceiling(padding / 2)
  middle <- paste0("║", strrep(" ", left_pad), title, strrep(" ", right_pad), "║")
  bottom <- paste0("╚", strrep("═", width - 2), "╝")
  cat("\n", top, "\n", middle, "\n", bottom, "\n\n", sep = "")
}

# 打印次级标题（单线框）
print_sub_title <- function(title, width = 50) {
  top <- paste0("┌", strrep("─", width - 2), "┐")
  padding <- width - nchar(title) - 4
  left_pad <- floor(padding / 2)
  right_pad <- ceiling(padding / 2)
  middle <- paste0("│", strrep(" ", left_pad), title, strrep(" ", right_pad), "│")
  bottom <- paste0("└", strrep("─", width - 2), "┘")
  cat(top, "\n", middle, "\n", bottom, "\n", sep = "")
}

# 打印分隔线
print_separator <- function(char = "━", width = 60) {
  cat(strrep(char, width), "\n")
}

# 打印状态信息（带图标）
print_status <- function(status = "info", message) {
  icons <- list(
    success = "✓",
    error = "✗",
    warning = "⚠",
    info = "ℹ",
    detail = "🔍",
    time = "⏱",
    cluster = "📊",
    database = "🗄",
    ai = "🤖",
    validate = "✅",
    score = "📈"
  )
  icon <- icons[[status]] %||% "•"
  cat(sprintf("  %s %s\n", icon, message))
}

# 打印进度条
print_progress_bar <- function(current, total, width = 40, label = "") {
  percent <- current / total
  filled <- round(width * percent)
  bar <- paste0(
    "[",
    strrep("█", filled),
    strrep("░", width - filled),
    "] ",
    sprintf("%3.0f%%", percent * 100)
  )
  if (label != "") {
    cat(sprintf("%s %s (%d/%d)\n", label, bar, current, total))
  } else {
    cat(sprintf("%s (%d/%d)\n", bar, current, total))
  }
}

# 打印表格
print_table <- function(data, headers, col_widths = NULL) {
  if (is.null(col_widths)) {
    col_widths <- rep(15, length(headers))
  }

  # 打印表头
  header_line <- paste0("│ ", paste(sapply(seq_along(headers), function(i) {
    sprintf(paste0("%-", col_widths[i], "s"), headers[i])
  }), collapse = " │ "), " │")

  top_line <- paste0("┌", strrep("─", nchar(header_line) - 2), "┐")
  sep_line <- paste0("├", strrep("─", nchar(header_line) - 2), "┤")
  bottom_line <- paste0("└", strrep("─", nchar(header_line) - 2), "┘")

  cat(top_line, "\n", header_line, "\n", sep_line, "\n", sep = "")

  # 打印数据行
  for (row in data) {
    row_line <- paste0("│ ", paste(sapply(seq_along(row), function(i) {
      sprintf(paste0("%-", col_widths[i], "s"), substr(as.character(row[i]), 1, col_widths[i]))
    }), collapse = " │ "), " │")
    cat(row_line, "\n")
  }

  cat(bottom_line, "\n")
}

