# 打印时间统计
print_timing <- function(start_time, label = "操作") {
  elapsed <- round(as.numeric(difftime(Sys.time(), start_time, units = "secs")), 2)
  cat(sprintf("  ⏱ %s耗时: %.2f秒\n", label, elapsed))
}

# 打印流程进度总览
print_pipeline_progress <- function(current_step) {
  steps <- c("数据加载", "质量控制", "标准化", "降维分析", "聚类", "AURA注释")

  cat("\n")
  print_separator("═", 60)
  cat("  📍 流程进度:\n")
  for (i in seq_along(steps)) {
    if (i < current_step) {
      cat(sprintf("    ✓ %s\n", steps[i]))
    } else if (i == current_step) {
      cat(sprintf("    ▶ %s (进行中)\n", steps[i]))
    } else {
      cat(sprintf("    ○ %s\n", steps[i]))
    }
  }
  print_separator("═", 60)
  cat("\n")
}

