# 创建测试结果文件夹（使用时间戳+模式+样本命名）
create_test_result_folder <- function(mode = NULL, sample_name = NULL) {
  # 获取当前时间戳（格式：2025.10.23.15.40）
  timestamp <- format(Sys.time(), "%Y.%m.%d.%H.%M")

  # 构建文件夹名称：时间戳+模式+样本名
  folder_name <- timestamp

  # 添加模式标签
  if (!is.null(mode)) {
    mode_label <- switch(mode,
      "batch" = "批量",
      "constrained" = "逐簇",
      "single" = "单簇",
      mode # 如果不匹配，使用原值
    )
    folder_name <- paste0(folder_name, "+", mode_label)
  }

  # 添加样本名称（从路径中提取）
  if (!is.null(sample_name) && nchar(sample_name) > 0) {
    # 如果是完整路径，提取最后一个文件夹名或文件名（去掉扩展名）
    sample_clean <- basename(sample_name)
    sample_clean <- gsub("\\.(h5|rds|h5ad)$", "", sample_clean) # 去掉扩展名
    sample_clean <- gsub("[^a-zA-Z0-9_\\-]", "_", sample_clean) # 替换特殊字符
    folder_name <- paste0(folder_name, "+", sample_clean)
  }

  # 测试结果保存目录（示例为用户环境路径，实际部署可按需改为相对路径）
  # 【用户指定】固定保存到 R6/r6/测试结果（绝对路径）
  fixed_base_dir <- "C:/Users/12860/Desktop/SingleR_Cursor/R6/r6"

  # 创建主测试结果文件夹
  main_folder <- file.path(fixed_base_dir, "测试结果")
  if (!dir.exists(main_folder)) {
    dir.create(main_folder, recursive = TRUE)
    cat("  ✓ 创建主测试结果文件夹:", main_folder, "\n")
  }

  # 创建当前测试的子文件夹（带时间戳+模式+样本）
  test_folder <- file.path(main_folder, folder_name)
  if (!dir.exists(test_folder)) {
    dir.create(test_folder, recursive = TRUE)
    cat("  ✓ 创建测试子文件夹:", test_folder, "\n")
  } else {
    cat("  ℹ️ 测试文件夹已存在:", test_folder, "\n")
  }

  # 输出绝对路径信息
  cat("\n")
  cat("  ═══════════════════════════════════════\n")
  cat("  📁 测试结果保存位置\n")
  cat("  ═══════════════════════════════════════\n")
  cat("  固定路径:", main_folder, "\n")
  cat("  本次测试:", test_folder, "\n")
  cat("  ═══════════════════════════════════════\n\n")

  return(test_folder)
}

# 保存参数列表到MD文件
save_parameters_to_md <- function(folder, resolution, dims_range, qc_params, sample_path = NULL) {
  file_path <- file.path(folder, "参数列表.md")

  content <- paste0(
    "# 测试参数列表\n\n",
    "## 测试时间\n",
    "- 时间: ", format(Sys.time(), "%Y年%m月%d日 %H:%M:%S"), "\n\n",
    "## 样本信息\n",
    "- 样本路径: ", if (!is.null(sample_path)) sample_path else "未记录", "\n\n",
    "## 聚类参数\n",
    "- 分辨率 (Resolution): ", resolution, "\n\n",
    "## 降维参数\n",
    "- Dims范围: ", paste(dims_range, collapse = ":"), "\n",
    "- Dims最小值: ", min(dims_range), "\n",
    "- Dims最大值: ", max(dims_range), "\n\n",
    "## 质控过滤参数\n",
    "- 最小基因数 (nFeature_RNA): ", qc_params$min_features %||% "未设置", "\n",
    "- 最大基因数 (nFeature_RNA): ", qc_params$max_features %||% "未设置", "\n",
    "- 最小UMI数 (nCount_RNA): ", qc_params$min_counts %||% "未设置", "\n",
    "- 最大UMI数 (nCount_RNA): ", qc_params$max_counts %||% "未设置", "\n",
    "- 最大线粒体比例 (%): ", qc_params$max_mito %||% "未设置", "\n\n",
    "## 备注\n",
    "此测试使用上述参数进行单细胞RNA测序分析。\n"
  )

  writeLines(content, file_path, useBytes = TRUE)
  cat("  ✓ 参数列表已保存至:", file_path, "\n")

  return(file_path)
}

# 初始化日志系统
init_log_system <- function(folder) {
  tryCatch(
    {
      # 创建日志文件
      log_files <- list(
        main = file.path(folder, "analysis_log.txt"),
        debug = file.path(folder, "debug_log.txt"),
        error = file.path(folder, "error_log.txt")
      )

      # 写入日志头部
      for (log_type in names(log_files)) {
        log_file <- log_files[[log_type]]
        header <- paste0(
          "═══════════════════════════════════════════════════\n",
          toupper(log_type), " LOG - AURA 2.0 Analysis\n",
          "═══════════════════════════════════════════════════\n",
          "Start Time: ", format(Sys.time(), "%Y-%m-%d %H:%M:%S"), "\n",
          "═══════════════════════════════════════════════════\n\n"
        )
        writeLines(header, log_file, useBytes = TRUE)
      }

      cat("  ✓ 日志系统已初始化\n")
      cat("    - 主日志:", log_files$main, "\n")
      cat("    - 调试日志:", log_files$debug, "\n")
      cat("    - 错误日志:", log_files$error, "\n")

      return(log_files)
    },
    error = function(e) {
      cat("  ⚠️ 日志系统初始化失败:", e$message, "\n")
      return(NULL)
    }
  )
}

# =====================================
# 日志辅助函数
# =====================================

# 🎯 全局静默模式控制（减少数据库查询输出）
# TRUE = 精简输出（只显示关键信息）
# FALSE = 详细输出（显示所有数据库查询细节）
QUIET_DATABASE_QUERIES <- TRUE

# 写入信息级别日志
log_info <- function(message, log_file = NULL) {
  # 静默模式下跳过数据库查询的详细输出
  if (QUIET_DATABASE_QUERIES) {
    skip_patterns <- c(
      "📥 输入基因", "→ ", "📚 数据库", "📋 ", "🔍 开始匹配",
      "✓ 匹配完成", "🏆 Top", "🎯 .*摘要", "⏱ 耗时"
    )
    for (p in skip_patterns) {
      if (grepl(p, message)) {
        return(invisible(NULL))
      }
    }
  }
  cat(message, "\n")
  if (!is.null(log_file) && file.exists(log_file)) {
    cat(format(Sys.time(), "[%H:%M:%S] "), message, "\n",
      file = log_file, append = TRUE
    )
  }
}

# 写入调试级别日志
log_debug <- function(message, log_file = NULL) {
  # 静默模式下完全跳过调试输出
  if (QUIET_DATABASE_QUERIES) {
    return(invisible(NULL))
  }
  cat(message, "\n")
  if (!is.null(log_file) && file.exists(log_file)) {
    cat(format(Sys.time(), "[%H:%M:%S] "), message, "\n",
      file = log_file, append = TRUE
    )
  }
}

# 写入警告级别日志（始终显示）
log_warn <- function(message, log_file = NULL) {
  cat(message, "\n")
  if (!is.null(log_file) && file.exists(log_file)) {
    cat(format(Sys.time(), "[%H:%M:%S] WARNING: "), message, "\n",
      file = log_file, append = TRUE
    )
  }
}

# 写入错误级别日志（始终显示）
log_error <- function(message, log_file = NULL) {
  cat(message, "\n")
  if (!is.null(log_file) && file.exists(log_file)) {
    cat(format(Sys.time(), "[%H:%M:%S] ERROR: "), message, "\n",
      file = log_file, append = TRUE
    )
  }
}

# 写入跟踪级别日志
log_trace <- function(message, log_file = NULL) {
  if (!is.null(log_file) && file.exists(log_file)) {
    # 【修复】限制message长度，避免巨大堆栈信息
    if (nchar(message) > 500) {
      message <- paste0(substr(message, 1, 500), "... [截断]")
    }
    cat(format(Sys.time(), "[%H:%M:%S] TRACE: "), message, "\n",
      file = log_file, append = TRUE
    )
  }
}

# 写入分隔符
log_separator <- function(title = NULL, log_file = NULL) {
  # 静默模式下跳过数据库查询的分隔符
  if (QUIET_DATABASE_QUERIES && !is.null(title)) {
    skip_patterns <- c("KEGG", "PanglaoDB", "CellMarker", "scType", "clusterProfiler")
    for (p in skip_patterns) {
      if (grepl(p, title)) {
        return(invisible(NULL))
      }
    }
  }

  sep_line <- paste(rep("=", 60), collapse = "")
  if (!is.null(title)) {
    cat(sep_line, "\n", title, "\n", sep_line, "\n")
    if (!is.null(log_file) && file.exists(log_file)) {
      cat(sep_line, "\n", title, "\n", sep_line, "\n",
        file = log_file, append = TRUE
      )
    }
  } else {
    cat(sep_line, "\n")
    if (!is.null(log_file) && file.exists(log_file)) {
      cat(sep_line, "\n", file = log_file, append = TRUE)
    }
  }
}

# 启动计时器
start_timer <- function(description = NULL) {
  return(Sys.time())
}

# 停止计时器并记录
stop_timer <- function(timer, log_file = NULL) {
  elapsed <- as.numeric(difftime(Sys.time(), timer, units = "secs"))
  message <- sprintf("⏱ 耗时: %.2f秒", elapsed)
  cat(message, "\n")
  if (!is.null(log_file) && file.exists(log_file)) {
    cat(message, "\n", file = log_file, append = TRUE)
  }
  return(elapsed)
}

# 初始化对话记录MD文件
init_conversation_log <- function(folder) {
  file_path <- file.path(folder, "对话记录.md")

  content <- paste0(
    "# AURA分析对话记录\n\n",
    "## 测试信息\n",
    "- 开始时间: ", format(Sys.time(), "%Y年%m月%d日 %H:%M:%S"), "\n",
    "- 分析模式: AURA 2.0 多模辩论引擎\n\n",
    "---\n\n"
  )

  writeLines(content, file_path, useBytes = TRUE)

  return(file_path)
}

# 追加对话内容到记录文件
append_conversation <- function(file_path, cluster_id, conversation_data) {
  if (!file.exists(file_path)) {
    cat("  ⚠️ 对话记录文件不存在，跳过追加\n")
    return(FALSE)
  }

  # 构建对话内容
  content <- paste0(
    "\n## Cluster ", cluster_id, " 分析记录\n\n",
    "### 基本信息\n",
    "- 时间: ", format(Sys.time(), "%Y-%m-%d %H:%M:%S"), "\n",
    "- Cluster ID: ", cluster_id, "\n",
    "- Top Markers: ", conversation_data$top_markers %||% "无", "\n\n"
  )

  # 添加知识图谱信息
  if (!is.null(conversation_data$knowledge_base)) {
    content <- paste0(
      content,
      "### 知识图谱信息\n",
      "- GO富集分析: ", if (!is.null(conversation_data$knowledge_base$go_enrichment)) "已完成" else "未完成", "\n",
      "- KEGG通路分析: ", if (!is.null(conversation_data$knowledge_base$kegg_pathways)) "已完成" else "未完成", "\n",
      "- PanglaoDB查询: ", if (!is.null(conversation_data$knowledge_base$panglao_results)) "已完成" else "未完成", "\n\n"
    )
  }

  # 添加辩论历史
  if (!is.null(conversation_data$debate_history) && length(conversation_data$debate_history) > 0) {
    content <- paste0(content, "### 辩论过程\n\n")

    # 【方案1改进】正确处理批量模式和逐簇模式的辩论历史
    # 批量模式：debate_history可能是list(round1=..., round2=..., round3=...)
    # 逐簇模式：debate_history可能是list(list(debater_A=..., response_A=...), ...)

    # 检查是否是批量模式（通过检查round1/round2/round3结构）
    is_batch_structure <- !is.null(names(conversation_data$debate_history)) &&
      any(grepl("^round[0-9]+$", names(conversation_data$debate_history)))

    if (is_batch_structure) {
      # 【新增】批量模式的结构 - 显示真实辩论历史
      content <- paste0(
        content,
        "**批量分析模式：所有簇通过一次三轮辩论完成注释**\n\n",
        "注：以下辩论历史是所有簇共享的批量辩论结果\n\n"
      )

      # 【第1轮】初步判断
      if (!is.null(conversation_data$debate_history$round1)) {
        round1 <- conversation_data$debate_history$round1
        content <- paste0(content, "#### 第1轮辩论：初步判断\n\n")

        # 辩手A
        if (!is.null(round1$result_A)) {
          content <- paste0(
            content,
            "**辩手A (", round1$model_A %||% round1$result_A$model %||% "Unknown", "):**\n\n",
            "```json\n",
            substr(round1$result_A$full_response %||% "无响应", 1, 800), "\n",
            if (nchar(round1$result_A$full_response %||% "") > 800) "...(JSON已截断，完整内容见裁判裁决)\n" else "",
            "```\n\n"
          )
        }

        # 辩手B
        if (!is.null(round1$result_B)) {
          content <- paste0(
            content,
            "**辩手B (", round1$model_B %||% round1$result_B$model %||% "Unknown", "):**\n\n",
            "```json\n",
            substr(round1$result_B$full_response %||% "无响应", 1, 800), "\n",
            if (nchar(round1$result_B$full_response %||% "") > 800) "...(JSON已截断，完整内容见裁判裁决)\n" else "",
            "```\n\n"
          )
        }
      }

      # 【第2轮】交叉质询
      if (!is.null(conversation_data$debate_history$round2)) {
        round2 <- conversation_data$debate_history$round2
        content <- paste0(content, "#### 第2轮辩论：交叉质询\n\n")

        # 辩手B质询辩手A
        if (!is.null(round2$critique_of_A)) {
          content <- paste0(
            content,
            "**辩手B质询辩手A的观点：**\n\n",
            "```\n",
            substr(round2$critique_of_A, 1, 600), "\n",
            if (nchar(round2$critique_of_A) > 600) "...(已截断)\n" else "",
            "```\n\n"
          )
        }

        # 辩手A质询辩手B
        if (!is.null(round2$critique_of_B)) {
          content <- paste0(
            content,
            "**辩手A质询辩手B的观点：**\n\n",
            "```\n",
            substr(round2$critique_of_B, 1, 600), "\n",
            if (nchar(round2$critique_of_B) > 600) "...(已截断)\n" else "",
            "```\n\n"
          )
        }
      }

      # 第3轮（裁判裁决）会在后面的"裁判判决"部分显示
    } else {
      # 【改进】逐簇模式也可能有round1/round2结构（与批量模式相同）
      # 检查是否有round1/round2（但不是批量标记）
      if (!is.null(conversation_data$debate_history$round1)) {
        # 逐簇模式，完整3轮辩论
        content <- paste0(content, "**逐簇分析模式：每个簇独立完成三轮辩论**\n\n")

        # 【第1轮】初步判断
        round1 <- conversation_data$debate_history$round1
        content <- paste0(content, "#### 第1轮辩论：初步判断\n\n")

        # 辩手A
        if (!is.null(round1$result_A)) {
          content <- paste0(
            content,
            "**辩手A (", round1$model_A %||% round1$result_A$model %||% "Unknown", "):**\n\n",
            "- 细胞类型：", round1$result_A$cell_type %||% "Unknown", "\n",
            "- 理由：\n```\n",
            substr(round1$result_A$reasoning %||% "无", 1, 400), "\n",
            if (nchar(round1$result_A$reasoning %||% "") > 400) "...(已截断)\n" else "",
            "```\n\n"
          )
        }

        # 辩手B
        if (!is.null(round1$result_B)) {
          content <- paste0(
            content,
            "**辩手B (", round1$model_B %||% round1$result_B$model %||% "Unknown", "):**\n\n",
            "- 细胞类型：", round1$result_B$cell_type %||% "Unknown", "\n",
            "- 理由：\n```\n",
            substr(round1$result_B$reasoning %||% "无", 1, 400), "\n",
            if (nchar(round1$result_B$reasoning %||% "") > 400) "...(已截断)\n" else "",
            "```\n\n"
          )
        }

        # 【第2轮】交叉质询
        if (!is.null(conversation_data$debate_history$round2)) {
          round2 <- conversation_data$debate_history$round2
          content <- paste0(content, "#### 第2轮辩论：交叉质询\n\n")

          # 辩手B质询辩手A
          if (!is.null(round2$critique_of_A)) {
            content <- paste0(
              content,
              "**辩手B质询辩手A的观点：**\n\n",
              "```\n",
              substr(round2$critique_of_A, 1, 500), "\n",
              if (nchar(round2$critique_of_A) > 500) "...(已截断)\n" else "",
              "```\n\n"
            )
          }

          # 辩手A质询辩手B
          if (!is.null(round2$critique_of_B)) {
            content <- paste0(
              content,
              "**辩手A质询辩手B的观点：**\n\n",
              "```\n",
              substr(round2$critique_of_B, 1, 500), "\n",
              if (nchar(round2$critique_of_B) > 500) "...(已截断)\n" else "",
              "```\n\n"
            )
          }
        }

        # 第3轮（裁判裁决）会在后面的"裁判判决"部分显示
      } else {
        # 旧版本或未知结构
        content <- paste0(
          content,
          "**分析完成**\n\n",
          "- 辩论历史结构未识别\n",
          "- 最终注释基于综合数据库证据\n\n"
        )
      }
    }
  } else {
    # 没有辩论历史
    content <- paste0(content, "### 辩论过程\n\n**无辩论历史记录**\n\n")
  }

  # 添加裁判判决
  if (!is.null(conversation_data$referee_decision)) {
    content <- paste0(
      content,
      "### 裁判判决\n",
      "- 裁判模型: ", conversation_data$referee_model %||% "Unknown", "\n",
      "- 最终注释: **", conversation_data$final_annotation %||% "Unknown", "**\n",
      "- 推理依据:\n```\n",
      conversation_data$reasoning %||% "无", "\n",
      "```\n\n"
    )
  }

  # 添加验证结果
  if (!is.null(conversation_data$validation_result)) {
    content <- paste0(
      content,
      "### 验证结果\n",
      "- 生物学评分: ", round(conversation_data$validation_result$biological_score %||% 0, 3), "\n\n"
    )
  }

  # 添加质量指标（如果存在）
  if (!is.null(conversation_data$marker_specificity) || !is.null(conversation_data$database_support)) {
    content <- paste0(
      content,
      "### 质量指标\n",
      "- **Marker Metrics**:\n",
      "  - Specificity: ", round(conversation_data$marker_specificity %||% 0, 3), "\n",
      "  - Expression: ", round(conversation_data$marker_expression %||% 0, 3), "\n",
      "  - Significance: ", round(conversation_data$marker_significance %||% 0, 3), "\n",
      "- **Referee Decision**: ", conversation_data$referee_decision %||% "Unknown", "\n",
      "- **Database Support**: ", conversation_data$database_support %||% "0/3", "\n\n"
    )
  }

  content <- paste0(content, "---\n\n")

  # 追加到文件
  tryCatch(
    {
      cat(content, file = file_path, append = TRUE)
      return(TRUE)
    },
    error = function(e) {
      cat("  ✗ 追加对话记录失败:", e$message, "\n")
      return(FALSE)
    }
  )
}

# 保存UMAP和t-SNE图片
save_visualization_plots <- function(folder, pbmc_obj, has_aura = FALSE) {
  # 【增强容错】每个步骤独立try-catch，确保单个步骤失败不影响其他步骤

  saved_files <- list()

  # 确保文件夹存在
  tryCatch(
    {
      if (!dir.exists(folder)) {
        dir.create(folder, recursive = TRUE)
        cat("  ✓ 创建可视化图片文件夹:", folder, "\n")
      }
    },
    error = function(e) {
      cat("  ✗ 创建文件夹失败:", e$message, "\n")
      return(list())
    }
  )

  cat("\n═══════════════════════════════════════\n")
  cat("保存可视化图片\n")
  cat("═══════════════════════════════════════\n")

  # 【调试】输出降维信息
  cat("  [调试] Seurat对象降维槽位:", paste(names(pbmc_obj@reductions), collapse = ", "), "\n")
  cat("  [调试] 降维数量:", length(pbmc_obj@reductions), "\n")

  # 【步骤1】保存UMAP图
  tryCatch(
    {
      # 【修复】更可靠的检查方式
      has_umap <- "umap" %in% names(pbmc_obj@reductions) && !is.null(pbmc_obj@reductions[["umap"]])
      cat("  [调试] has_umap检测结果:", has_umap, "\n")

      if (has_umap) {
        cat("  → 正在生成UMAP图...\n")
        umap_file <- file.path(folder, "UMAP_plot.png")

        if (has_aura && !is.null(pbmc_obj$AURA_annotation)) {
          # 使用AURA注释着色
          cell_types <- unique(pbmc_obj$AURA_annotation)
          cell_colors <- assign_celltype_color(cell_types)

          p_umap <- DimPlot(pbmc_obj,
            reduction = "umap",
            group.by = "AURA_annotation",
            label = TRUE,
            label.size = 6,
            label.box = TRUE,
            repel = TRUE,
            cols = cell_colors
          ) +
            ggtitle("UMAP - AURA细胞类型注释") +
            theme_minimal() +
            theme(
              legend.position = "right",
              legend.key.size = unit(1.2, "cm"),
              legend.text = element_text(size = 12)
            )
        } else {
          # 使用cluster编号着色
          p_umap <- DimPlot(pbmc_obj,
            reduction = "umap",
            group.by = "seurat_clusters",
            label = TRUE,
            label.size = 5,
            repel = TRUE
          ) +
            ggtitle("UMAP - Cluster编号") +
            theme_minimal()
        }

        ggsave(umap_file, p_umap, width = 12, height = 10, dpi = 300)
        saved_files$umap <- umap_file
        cat("  ✓ UMAP图已保存:", umap_file, "\n")
      } else {
        cat("  ⚠️ Seurat对象中无UMAP降维结果，跳过\n")
      }
    },
    error = function(e) {
      cat("  ✗ UMAP图保存失败:", e$message, "\n")
      cat("    可能原因: 降维未完成或ggplot2绘图错误\n")
    }
  )

  # 【步骤2】保存t-SNE图
  tryCatch(
    {
      # 【修复】更可靠的检查方式
      has_tsne <- "tsne" %in% names(pbmc_obj@reductions) && !is.null(pbmc_obj@reductions[["tsne"]])
      cat("  [调试] has_tsne检测结果:", has_tsne, "\n")

      if (has_tsne) {
        cat("  → 正在生成t-SNE图...\n")
        tsne_file <- file.path(folder, "tSNE_plot.png")

        if (has_aura && !is.null(pbmc_obj$AURA_annotation)) {
          # 使用AURA注释着色
          cell_types <- unique(pbmc_obj$AURA_annotation)
          cell_colors <- assign_celltype_color(cell_types)

          p_tsne <- DimPlot(pbmc_obj,
            reduction = "tsne",
            group.by = "AURA_annotation",
            label = TRUE,
            label.size = 6,
            label.box = TRUE,
            repel = TRUE,
            cols = cell_colors
          ) +
            ggtitle("t-SNE - AURA细胞类型注释") +
            theme_minimal() +
            theme(
              legend.position = "right",
              legend.key.size = unit(1.2, "cm"),
              legend.text = element_text(size = 12)
            )
        } else {
          # 使用cluster编号着色
          p_tsne <- DimPlot(pbmc_obj,
            reduction = "tsne",
            group.by = "seurat_clusters",
            label = TRUE,
            label.size = 5,
            repel = TRUE
          ) +
            ggtitle("t-SNE - Cluster编号") +
            theme_minimal()
        }

        ggsave(tsne_file, p_tsne, width = 12, height = 10, dpi = 300)
        saved_files$tsne <- tsne_file
        cat("  ✓ t-SNE图已保存:", tsne_file, "\n")
      } else {
        cat("  ⚠️ Seurat对象中无t-SNE降维结果，跳过\n")
      }
    },
    error = function(e) {
      cat("  ✗ t-SNE图保存失败:", e$message, "\n")
      cat("    可能原因: 降维未完成或ggplot2绘图错误\n")
    }
  )

  cat("═══════════════════════════════════════\n")
  cat("可视化图片保存完成\n")
  cat("  - 成功保存:", length(saved_files), "个图片\n")
  cat("═══════════════════════════════════════\n\n")

  return(saved_files)
}

