# 安全的Markdown渲染函数（如果markdown包不可用则回退到纯文本）
safe_markdown_render <- function(text) {
  if (is.null(text) || nchar(text) == 0) {
    return("")
  }
  tryCatch(
    {
      HTML(markdown::markdownToHTML(
        text = text,
        fragment.only = TRUE,
        options = c("smartypants", "tables")
      ))
    },
    error = function(e) {
      # 回退到预格式化文本
      tags$pre(style = "white-space: pre-wrap; word-wrap: break-word; font-family: 'Microsoft YaHei', sans-serif;", text)
    }
  )
}

