# ═══════════════════════════════════════════════════════════════
# gprofiler2 API说明：
# gprofiler2服务器（biit.cs.ut.ee）可能因网络原因无法访问
# 失败时会自动跳过，不影响其他数据库的使用
# ═══════════════════════════════════════════════════════════════

# 从数据集路径提取组织类型
extract_tissue_from_dataset <- function(dataset_path) {
  tryCatch(
    {
      # 方法1: 从可选的自定义 marker_config.csv 读取组织（非默认来源；默认由下方数据集路径名称推断）
      # 方法1: 从marker_config.csv读取
      marker_config_path <- file.path(dataset_path, "marker_config.csv")
      if (file.exists(marker_config_path)) {
        marker_config <- read.csv(marker_config_path, stringsAsFactors = FALSE)
        if ("tissue" %in% colnames(marker_config) && nrow(marker_config) > 0) {
          tissue <- marker_config$tissue[1]
          if (!is.na(tissue) && tissue != "") {
            return(tissue)
          }
        }
      }

      # 方法2: 从数据集路径名称推断
      dataset_name <- basename(dataset_path)
      # 移除数字前缀 (如 "6_Segerstolpe_Pancreas" -> "Segerstolpe_Pancreas")
      dataset_name <- gsub("^[0-9]+_", "", dataset_name)

      # 常见组织类型映射
      tissue_patterns <- list(
        "Pancreas" = c("Pancreas", "pancreas", "胰腺"),
        "Brain" = c("Brain", "brain", "大脑", "Hypothalamus", "下丘脑"),
        "Heart" = c("Heart", "heart", "心脏"),
        "Liver" = c("Liver", "liver", "肝脏"),
        "Lung" = c("Lung", "lung", "肺"),
        "PBMC" = c("PBMC", "pbmc"),
        "Breast" = c("Breast", "breast", "乳腺", "Mammary"),
        "Thymus" = c("Thymus", "thymus", "胸腺"),
        "Bladder" = c("Bladder", "bladder", "膀胱"),
        "Trachea" = c("Trachea", "trachea", "气管"),
        "Spleen" = c("Spleen", "spleen", "脾脏"),
        "Bone Marrow" = c("Marrow", "marrow", "骨髓"),
        "Muscle" = c("Muscle", "muscle", "肌肉"),
        "Tongue" = c("Tongue", "tongue", "舌头")
      )

      for (tissue_type in names(tissue_patterns)) {
        patterns <- tissue_patterns[[tissue_type]]
        for (pattern in patterns) {
          if (grepl(pattern, dataset_name, ignore.case = TRUE)) {
            return(tissue_type)
          }
        }
      }

      # 方法3: 如果都失败，返回Unknown
      return("Unknown")
    },
    error = function(e) {
      return("Unknown")
    }
  )
}

# ═══════════════════════════════════════════════════════════════
# 固定细胞类型颜色映射（确保每次运行颜色一致）
# 基于参考图片优化的鲜艳易区分配色方案
# ═══════════════════════════════════════════════════════════════
FIXED_CELLTYPE_COLORS <- c(
  # 主要免疫细胞
  "T cells" = "#FF4500", # 橙红色 - T细胞（鲜艳易识别）
  "B cells" = "#1E90FF", # 道奇蓝 - B细胞（参考图片蓝色）
  "NK cells" = "#9370DB", # 中紫色 - NK细胞（紫色系）
  "Monocytes" = "#00CED1", # 深天蓝 - 单核细胞（参考图片青色）
  "Macrophages" = "#0000CD", # 中蓝色 - 巨噬细胞（参考图片深蓝）
  "DC" = "#BA55D3", # 中兰花紫 - 树突状细胞（紫色系）
  "Mast cells" = "#FF1493", # 深粉红 - 肥大细胞（粉色系）

  # 基质细胞
  "Fibroblasts" = "#FFD700", # 金色 - 成纤维细胞（参考图片金黄色）
  "Endothelial" = "#00FF7F", # 春绿色 - 内皮细胞（参考图片翠绿）

  # 肿瘤细胞
  "Cancer" = "#FF69B4", # 热粉红 - 肿瘤细胞（参考图片粉红色）

  # 其他常见细胞类型
  "Neutrophils" = "#FFA500", # 橙色 - 中性粒细胞
  "Plasma cells" = "#8B008B", # 深洋红 - 浆细胞
  "Epithelial" = "#32CD32" # 酸橙绿 - 上皮细胞
)

# 辅助函数：为任意细胞类型分配颜色（支持扩展）
assign_celltype_color <- function(cell_types) {
  # 备用颜色池（排除已使用的固定颜色，避免混淆）
  # 选择鲜艳且与固定颜色明显不同的颜色
  BACKUP_COLORS <- c(
    "#FF6347", # 番茄红
    "#4682B4", # 钢蓝
    "#DDA0DD", # 梅红
    "#20B2AA", # 浅海绿
    "#F0E68C", # 卡其色
    "#BC8F8F", # 玫瑰棕
    "#778899", # 浅石板灰
    "#B0C4DE", # 浅钢蓝
    "#FFFFE0", # 浅黄
    "#00FA9A", # 中春绿
    "#48D1CC", # 中绿松石
    "#C71585", # 中紫罗兰红
    "#191970", # 午夜蓝
    "#FFE4B5", # 鹿皮色
    "#FFDEAD", # 纳瓦白
    "#FDF5E6", # 老花色
    "#6B8E23", # 橄榄军服绿
    "#FF8C00", # 深橙
    "#EE82EE", # 紫罗兰
    "#98FB98" # 苍绿
  )

  # 获取已使用的固定颜色
  used_colors <- as.character(FIXED_CELLTYPE_COLORS)

  # 过滤掉与固定颜色相同的备用颜色
  available_backup <- BACKUP_COLORS[!BACKUP_COLORS %in% used_colors]

  # 为每个细胞类型分配颜色
  colors <- sapply(cell_types, function(ct) {
    if (ct %in% names(FIXED_CELLTYPE_COLORS)) {
      # 使用固定颜色
      return(FIXED_CELLTYPE_COLORS[[ct]])
    } else {
      # 对于未定义的类型，基于名称确定性地选择备用颜色
      set.seed(sum(utf8ToInt(ct))) # 基于类型名称生成种子
      idx <- (sum(utf8ToInt(ct)) %% length(available_backup)) + 1
      return(available_backup[idx])
    }
  })

  names(colors) <- cell_types
  return(colors)
}

