# 混元 (腾讯元宝) API函数
ask_hunyuan <- function(question, system_prompt = "你是一位单细胞RNA测序的专家", api_key = NULL, max_tokens = NULL, use_fast_model = FALSE) {
  api_url <- "https://api.hunyuan.cloud.tencent.com/v1/chat/completions"
  if (is.null(api_key) || api_key == "") {
    api_key <- Sys.getenv("HUNYUAN_API_KEY")
  }
  if (is.null(api_key) || api_key == "") {
    return(list(error = "API密钥未提供，请在环境变量中配置或在界面中输入"))
  }

  # 动态设置max_tokens
  if (is.null(max_tokens)) {
    is_batch_request <- grepl("\\\"0\\\".*\\\"1\\\".*\\\"2\\\"", question) ||
      grepl("Cluster 0.*Cluster 1.*Cluster 2", question) ||
      grepl("请为以下.*个簇", question)

    max_tokens <- if (is_batch_request) {
      cat("ℹ️ [混元] 批量模式，使用max_tokens=16000（模型最大值）\n")
      16000 # hunyuan-t1最大支持16K output
    } else if (grepl("细胞类型|cell.*type|annotation|注释|JSON", question, ignore.case = TRUE)) {
      cat("ℹ️ [混元] 注释任务，使用max_tokens=16000（模型最大值）\n")
      16000
    } else {
      3000
    }
  }

  headers <- c(
    "Authorization" = paste("Bearer", api_key),
    "Content-Type"  = "application/json"
  )
  # 💡 根据 use_fast_model 参数选择模型
  if (use_fast_model) {
    model_name <- "hunyuan-turbos-latest"
    cat("ℹ️ 使用 hunyuan-turbos-latest 快速模型（max_tokens: ", max_tokens, "）\n")
  } else {
    model_name <- "hunyuan-t1-latest"
    cat("ℹ️ 使用 hunyuan-t1-latest 思考模型（max_tokens: ", max_tokens, "）\n")
  }

  body <- list(
    model = model_name,
    messages = list(
      list(role = "system", content = system_prompt),
      list(role = "user", content = question)
    ),
    temperature = 0,
    max_tokens = max_tokens,
    seed = 42
  )

  tryCatch(
    {
      resp <- POST(api_url, add_headers(.headers = headers),
        body = toJSON(body, auto_unbox = TRUE),
        encode = "json", timeout(600)
      ) # 🧠 思考模型需要更长超时时间
      if (status_code(resp) != 200) {
        return(list(error = paste("API请求失败，状态码:", status_code(resp))))
      }
      cnt <- content(resp, "parsed")
      if (!is.null(cnt$choices) && length(cnt$choices) > 0) {
        response_content <- cnt$choices[[1]]$message$content
        finish_reason <- cnt$choices[[1]]$finish_reason
        if (!is.null(finish_reason) && finish_reason == "length") {
          cat("⚠️ [混元] API返回被截断！原因: 达到max_tokens限制\n")
          cat("  ℹ️ 连接成功，但内容被截断（测试场景下max_tokens可能过小）\n")
          # 测试场景：即使被截断也返回成功，证明连接正常
          return(list(
            success = response_content,
            truncated = TRUE,
            finish_reason = finish_reason,
            usage = cnt$usage,
            model = cnt$model,
            warning = "返回内容被截断，建议增加max_tokens"
          ))
        }
        return(list(success = response_content, finish_reason = finish_reason, usage = cnt$usage, model = cnt$model))
      }
      return(list(error = "API返回格式错误"))
    },
    error = function(e) {
      return(list(error = paste("API请求错误:", e$message)))
    }
  )
}

