# 阶跃星辰 (StepFun) API函数

# 阶跃星辰 (StepFun) API函数
ask_stepfun <- function(question, system_prompt = "你是一位单细胞RNA测序的专家", api_key = NULL, max_tokens = NULL, use_fast_model = FALSE) {
  api_url <- "https://api.stepfun.com/v1/chat/completions"
  if (is.null(api_key) || api_key == "") {
    api_key <- Sys.getenv("STEPFUN_API_KEY")
  }
  if (is.null(api_key) || api_key == "") {
    return(list(error = "API密钥未提供，请在环境变量中配置或在界面中输入"))
  }

  # 动态设置max_tokens
  if (is.null(max_tokens)) {
    is_batch_request <- grepl("\\\"0\\\".*\\\"1\\\".*\\\"2\\\"", question) ||
      grepl("Cluster 0.*Cluster 1.*Cluster 2", question) ||
      grepl("请为以下.*个簇", question)

    max_tokens <- if (is_batch_request) {
      cat("ℹ️ [阶跃] 批量模式，使用max_tokens=5000（避免超时）\n")
      5000 # 降低到5000避免连接超时
    } else if (grepl("细胞类型|cell.*type|annotation|注释|JSON", question, ignore.case = TRUE)) {
      cat("ℹ️ [阶跃] 注释任务，使用max_tokens=5000（避免超时）\n")
      5000
    } else {
      3000
    }
  }

  headers <- c(
    "Authorization" = paste("Bearer", api_key),
    "Content-Type"  = "application/json"
  )
  # 💡 根据 use_fast_model 参数选择模型
  if (use_fast_model) {
    model_name <- "step-2-mini"
    cat("ℹ️ 使用 step-2-mini 快速模型（max_tokens: ", max_tokens, "）\n")
  } else {
    model_name <- "step-3"
    cat("ℹ️ 使用 step-3 思考模型（max_tokens: ", max_tokens, "）\n")
  }

  body <- list(
    model = model_name,
    messages = list(
      list(role = "system", content = system_prompt),
      list(role = "user", content = question)
    ),
    temperature = 0,
    max_tokens = max_tokens,
    seed = 42
  )

  tryCatch(
    {
      resp <- POST(api_url, add_headers(.headers = headers),
        body = toJSON(body, auto_unbox = TRUE),
        encode = "json", timeout(600)
      ) # 思考模型需要更长超时时间
      if (status_code(resp) != 200) {
        return(list(error = paste("API请求失败，状态码:", status_code(resp))))
      }
      cnt <- content(resp, "parsed")
      if (!is.null(cnt$choices) && length(cnt$choices) > 0) {
        # step-3推理模型：同时读取 reasoning 和 content 字段
        reasoning_content <- cnt$choices[[1]]$message$reasoning
        final_content <- cnt$choices[[1]]$message$content

        # 组合思考过程和最终回答
        if (!is.null(reasoning_content) && nchar(reasoning_content) > 0) {
          response_content <- paste0("[思考过程]\n", reasoning_content, "\n\n[最终回答]\n", final_content)
        } else {
          response_content <- final_content
        }

        finish_reason <- cnt$choices[[1]]$finish_reason
        # 检查截断（但如果有返回内容，仍然返回成功）
        if (!is.null(finish_reason) && finish_reason == "length") {
          # 如果返回内容不为空，即使有截断也返回成功（测试场景）
          if (!is.null(response_content) && nchar(response_content) > 0) {
            cat("⚠️ [阶跃星辰] API返回被截断！原因: 达到max_tokens限制\n")
            cat("  返回内容长度:", nchar(response_content), "字符\n")
            cat("  ℹ️ 但返回内容不为空，认为连接成功\n")
            return(list(
              success = response_content,
              truncated = TRUE,
              finish_reason = finish_reason,
              usage = cnt$usage,
              model = cnt$model,
              warning = "返回内容可能被截断，建议增加max_tokens"
            ))
          } else {
            # 返回内容为空，认为是真正的截断错误
            cat("⚠️ [阶跃星辰] API返回被截断！原因: 达到max_tokens限制\n")
            cat("  返回内容长度: 0 字符（可能API响应格式异常）\n")
            return(list(
              error = "API返回被截断（返回内容为空）",
              truncated = TRUE,
              partial_content = response_content,
              usage = cnt$usage,
              model = cnt$model
            ))
          }
        }
        return(list(success = response_content, finish_reason = finish_reason, usage = cnt$usage, model = cnt$model))
      }
      return(list(error = "API返回格式错误"))
    },
    error = function(e) {
      return(list(error = paste("API请求错误:", e$message)))
    }
  )
}

