# ==================== AURA 2.0 函数 ====================
# 多模辩论引擎 (原MultiLLM_Consensus_Engine已废弃，现使用辩论机制)
# 此函数保留仅作为向后兼容，实际调用DebateReferee_Engine
MultiLLM_Consensus_Engine_DEPRECATED <- function(knowledge_base, seurat_obj = NULL, api_keys = list()) {
  cat("警告: MultiLLM_Consensus_Engine已废弃，自动转换为辩论引擎\n")
  return(DebateReferee_Engine(knowledge_base, seurat_obj, api_keys))
}

# AURA 2.0 多模辩论决策引擎（新核心）
# 使用辩论-裁判机制替代原有的简单投票共识
MultiLLM_Consensus_Engine <- function(knowledge_base, seurat_obj = NULL, api_keys = list(),
                                      debater_A = "deepseek", debater_B = "kimi", referee = "glm",
                                      enable_rules = FALSE) { # 规则引擎已禁用
  tryCatch(
    {
      cat("╔═══════════════════════════════════════════════════════════╗\n")
      cat("║         AURA 2.0 多模辩论引擎启动                          ║\n")
      cat("╚═══════════════════════════════════════════════════════════╝\n")
      cat("模式: 辩论-裁判机制 | 规则引擎:", if (enable_rules) "启用" else "禁用", "\n\n")

      # 获取标记基因
      markers <- if (!is.null(knowledge_base$input_markers)) {
        knowledge_base$input_markers
      } else if (!is.null(knowledge_base$marker_genes)) {
        rownames(knowledge_base$marker_genes)
      } else {
        return(list(success = FALSE, error = "无法获取标记基因"))
      }

      # 应用前置规则（如果启用）
      if (enable_rules) {
        cat("应用前置规则引擎...\n")
        pre_rules <- RulesEngine$apply_pre_rules(markers, knowledge_base$enhanced_prompt %||% "")
        if (!is.null(knowledge_base$enhanced_prompt)) {
          knowledge_base$enhanced_prompt <- pre_rules$prompt
        }
        knowledge_base$pre_rules_warnings <- pre_rules$warnings
      }

      # 调用辩论引擎
      debate_result <- DebateReferee_Engine(
        knowledge_base = knowledge_base,
        seurat_obj = seurat_obj,
        api_keys = api_keys,
        debater_A = debater_A,
        debater_B = debater_B,
        referee = referee
      )

      # 应用后置规则（如果启用）
      if (enable_rules && !is.null(debate_result$cell_type)) {
        cat("应用后置规则引擎...\n")
        post_rules <- RulesEngine$apply_post_rules(
          cell_type = debate_result$cell_type,
          markers = markers
        )
        debate_result$post_rules <- post_rules
        debate_result$needs_review <- post_rules$needs_review
      }

      # 转换为统一的返回格式（兼容原有代码）
      result <- list(
        success = TRUE,
        final_annotation = debate_result$cell_type,
        llm_votes = paste0("辩论: ", debater_A, " vs ", debater_B, " → ", referee, "裁判"),
        voting_details = list(),
        responses = list(),
        # 辩论特有数据
        debate_history = debate_result$debate_history,
        reasoning = debate_result$reasoning,
        key_genes = debate_result$key_genes,
        referee_model = debate_result$referee_model,
        # 规则引擎数据
        pre_rules = if (enable_rules) debate_result$pre_rules else NULL,
        post_rules = if (enable_rules) debate_result$post_rules else NULL,
        needs_review = if (enable_rules) debate_result$needs_review else FALSE
      )

      cat("\n✅ AURA 2.0 辩论引擎完成\n")
      cat("最终注释:", result$final_annotation, "\n")
      if (result$needs_review) {
        cat("⚠️ 需要人工复核\n")
      }
      cat("\n")

      return(result)
    },
    error = function(e) {
      cat("AURA 2.0 多模辩论引擎错误:", e$message, "\n")
      return(list(
        success = FALSE,
        error = paste("辩论引擎错误:", e$message),
        final_annotation = "Unknown"
      ))
    }
  )
}

# 解析LLM响应
parse_llm_response <- function(response_text, top_markers, markers_data) {
  tryCatch(
    {
      # 使用正则表达式提取细胞类型
      # 匹配常见的细胞类型表达模式
      patterns <- c(
        "细胞类型[：:]+\\s*([^\\n,;]+)",
        "Cell Type[：:]+\\s*([^\\n,;]+)",
        "结论[：:]+\\s*([^\\n,;]+)",
        "判断[：:]+\\s*([^\\n,;]+)",
        "是([^(细胞|类型|Cell|Type)]+)细胞",
        "identified as ([^\\.]+)",
        "classified as ([^\\.]+)"
      )

      cell_type <- NULL
      for (pattern in patterns) {
        match <- regmatches(response_text, regexpr(pattern, response_text, perl = TRUE, ignore.case = TRUE))
        if (length(match) > 0) {
          # 提取细胞类型名称
          type_match <- gsub(pattern, "\\1", match, perl = TRUE)
          type_match <- trimws(gsub("^[:：]+|[:：]+$", "", type_match))
          if (nchar(type_match) > 1 && nchar(type_match) < 50) {
            cell_type <- type_match
            break
          }
        }
      }

      # 如果正则匹配失败，尝试关键词提取
      if (is.null(cell_type)) {
        # 常见细胞类型关键词
        cell_type_keywords <- c(
          "T cell", "B cell", "NK cell", "macrophage", "monocyte", "dendritic cell",
          "neutrophil", "eosinophil", "basophil", "mast cell",
          "stem cell", "progenitor", "precursor",
          "endothelial", "epithelial", "fibroblast", "adipocyte",
          "neuron", "glial", "astrocyte", "oligodendrocyte", "microglia"
        )

        for (keyword in cell_type_keywords) {
          if (grepl(keyword, response_text, ignore.case = TRUE)) {
            cell_type <- keyword
            break
          }
        }
      }

      # 如果仍然没有找到，使用简单规则
      if (is.null(cell_type)) {
        # 查找可能的细胞类型名称
        words <- unlist(strsplit(response_text, "[\\s\\n\\.,;:]+"))
        # 过滤掉太短或太长的词
        words <- words[nchar(words) > 2 & nchar(words) < 30]
        if (length(words) > 0) {
          cell_type <- words[1] # 使用第一个词作为细胞类型
        }
      }

      # 提取关键证据基因
      evidence_genes <- extract_evidence_genes(response_text, top_markers)

      list(
        cell_type = cell_type %||% "Unknown",
        evidence_genes = evidence_genes,
        full_response = response_text,
        reasoning = extract_reasoning(response_text)
      )
    },
    error = function(e) {
      cat("解析LLM响应失败:", e$message, "\n")
      list(
        cell_type = "Unknown",
        evidence_genes = top_markers[1:min(3, length(top_markers))],
        full_response = response_text,
        reasoning = "解析失败"
      )
    }
  )
}


# 提取证据基因
extract_evidence_genes <- function(response_text, available_markers) {
  mentioned_genes <- c()
  for (gene in available_markers[1:min(20, length(available_markers))]) {
    if (grepl(gene, response_text, ignore.case = TRUE)) {
      mentioned_genes <- c(mentioned_genes, gene)
    }
  }
  return(unique(mentioned_genes))
}

# 提取推理过程
extract_reasoning <- function(response_text) {
  # 提取包含推理的句子
  sentences <- unlist(strsplit(response_text, "[。.!?？!]+"))
  reasoning_sentences <- sentences[sapply(sentences, function(s) {
    grepl("因为|由于|基于|because|based on|due to", s, ignore.case = TRUE)
  })]

  if (length(reasoning_sentences) > 0) {
    return(paste(head(reasoning_sentences, 3), collapse = "。"))
  }
  return(substr(response_text, 1, min(200, nchar(response_text))))
}

# 计算共识决策
calculate_consensus_decision <- function(llm_results, knowledge_base) {
  tryCatch(
    {
      cat("计算多LLM共识决策...\n")

      # 1. 跨模型一致性分析
      cell_types <- sapply(llm_results, function(r) r$cell_type)
      type_counts <- table(cell_types)

      # 找到最常见的细胞类型
      most_common_type <- names(type_counts)[which.max(type_counts)]
      consistency_score <- max(type_counts) / length(cell_types)

      cat("细胞类型分布:", paste(names(type_counts), type_counts, sep = ":", collapse = ", "), "\n")
      cat("一致性分数:", consistency_score, "\n")

      # 2. 找出支持共识类型的模型
      consensus_models <- names(cell_types[cell_types == most_common_type])

      # 3. 整合证据
      all_evidence_genes <- unique(unlist(lapply(llm_results, function(r) r$evidence_genes)))
      all_reasoning <- paste(sapply(llm_results, function(r) r$reasoning), collapse = "\n\n")

      # 4. 生成共识报告
      consensus_report <- list(
        cell_type = most_common_type,
        consistency_ratio = consistency_score,
        llm_votes = length(consensus_models),
        total_llms = length(llm_results),
        voting_summary = paste(length(consensus_models), "/", length(llm_results), "一致"),
        evidence_genes = all_evidence_genes,
        reasoning = all_reasoning,
        detailed_results = llm_results
      )

      cat("共识决策完成:", most_common_type, "一致性:", consistency_score, "\n")

      return(consensus_report)
    },
    error = function(e) {
      cat("计算共识决策失败:", e$message, "\n")
      # 返回默认结果
      list(
        cell_type = "Unknown",
        consistency_ratio = 0.0,
        llm_votes = 0,
        total_llms = length(llm_results),
        voting_summary = "0/0",
        evidence_genes = c(),
        reasoning = "共识计算失败",
        detailed_results = llm_results
      )
    }
  )
}

# 计算生物学可信度
calculate_biological_credibility <- function(knowledge_base, predicted_type) {
  tryCatch(
    {
      if (is.null(knowledge_base) || is.null(predicted_type) || predicted_type == "Unknown") {
        return(0.0)
      }

      credibility <- 0.0

      # 1. 基于CellMarker数据库匹配的可信度
      if (!is.null(knowledge_base$cellmarker_analysis)) {
        cellmarker_result <- knowledge_base$cellmarker_analysis
        if (!is.null(cellmarker_result$cell_types) && length(cellmarker_result$cell_types) > 0) {
          # 检查预测的细胞类型是否在CellMarker结果中
          type_match <- sapply(cellmarker_result$cell_types, function(type) {
            grepl(predicted_type, type, ignore.case = TRUE) ||
              grepl(type, predicted_type, ignore.case = TRUE)
          })

          if (any(type_match)) {
            credibility <- credibility + 0.4
          }

          # 基于匹配的标记基因数量
          if (!is.null(cellmarker_result$matched_genes) && length(cellmarker_result$matched_genes) > 0) {
            credibility <- credibility + min(length(cellmarker_result$matched_genes) * 0.05, 0.3)
          }
        }
      }

      # 2. 基于功能富集分析的可信度
      if (!is.null(knowledge_base$functional_analysis)) {
        functional_result <- knowledge_base$functional_analysis
        # 检查是否富集到相关的生物学过程
        if (!is.null(functional_result$significant_terms) && length(functional_result$significant_terms) > 0) {
          credibility <- credibility + 0.2
        }
      }

      # 3. 基于通路分析的可信度
      if (!is.null(knowledge_base$pathway_analysis)) {
        pathway_result <- knowledge_base$pathway_analysis
        if (!is.null(pathway_result$significant_pathways) && length(pathway_result$significant_pathways) > 0) {
          credibility <- credibility + 0.2
        }
      }

      # 4. 基于文献支持的可信度
      if (!is.null(knowledge_base$literature_analysis)) {
        literature_result <- knowledge_base$literature_analysis
        if (!is.null(literature_result$total_articles) && literature_result$total_articles > 10) {
          credibility <- credibility + min(literature_result$total_articles / 1000, 0.3)
        }
      }

      return(min(credibility, 1.0))
    },
    error = function(e) {
      cat("计算生物学可信度失败:", e$message, "\n")
      return(0.0)
    }
  )
}

# 生成简化版Prompt
generate_simple_prompt <- function(cluster_id, marker_count = 20) {
  tryCatch(
    {
      cat("生成简化版Prompt，簇", cluster_id, "标记基因数:", marker_count, "\n")

      prompt_parts <- c(
        "你是一位专业的单细胞RNA测序数据分析专家。",
        "",
        paste("请对细胞簇", cluster_id, "进行准确的细胞类型鉴定。"),
        "",
        "【任务要求】",
        "1. 基于以下差异表达基因进行细胞类型判断",
        "2. 考虑基因的表达模式和生物学功能",
        "3. 给出具体的细胞类型名称和判断依据",
        "4. 提供3-5个关键的证据基因",
        "",
        "【输出格式】",
        "细胞类型：[具体的细胞类型名称]",
        "判断依据：[简要说明判断的主要理由]",
        "关键证据基因：[3-5个最重要的支持基因]",
        "置信度：[0-1之间的数值]",
        "",
        "请开始分析："
      )

      return(paste(prompt_parts, collapse = "\n"))
    },
    error = function(e) {
      cat("生成简化版Prompt失败:", e$message, "\n")
      return("请分析给定的标记基因，判断细胞类型。")
    }
  )
}

# 生成自定义Prompt
generate_custom_prompt <- function(knowledge_base, cluster_id, prompt_type, databases, marker_count) {
  tryCatch(
    {
      cat("生成自定义Prompt，簇", cluster_id, "类型:", prompt_type, "\n")

      # 获取标记基因数据
      markers_data <- knowledge_base$marker_genes
      if (is.null(markers_data) || nrow(markers_data) == 0) {
        return(generate_simple_prompt(cluster_id, marker_count))
      }

      top_markers <- markers_data$gene[1:min(marker_count, nrow(markers_data))]

      # 根据类型生成不同复杂度的Prompt
      if (prompt_type == "simple") {
        return(generate_simple_prompt(cluster_id, marker_count))
      }

      # 完整版Prompt基于现有的build_super_prompt函数
      full_prompt <- build_super_prompt(knowledge_base, top_markers)

      # 根据选择的数据库过滤内容
      if (!is.null(databases) && length(databases) > 0) {
        prompt_lines <- unlist(strsplit(full_prompt, "\n"))

        # 根据选择的数据库保留相应内容
        filtered_lines <- c()
        keep_section <- FALSE
        current_section <- ""

        for (line in prompt_lines) {
          if (grepl("【.*】", line)) {
            # 新的章节开始
            current_section <- line
            keep_section <- FALSE

            # 检查是否需要保留该章节
            if (grepl("标记基因", current_section)) {
              keep_section <- TRUE
            } else if (grepl("CellMarker", current_section) && "cellmarker" %in% databases) {
              keep_section <- TRUE
            } else if (grepl("功能富集", current_section) && "gprofiler" %in% databases) {
              keep_section <- TRUE
            } else if (grepl("通路分析", current_section) && "kegg" %in% databases) {
              keep_section <- TRUE
            } else if (grepl("STRINGdb", current_section) && "stringdb" %in% databases) {
              keep_section <- TRUE
            }
          }

          if (keep_section || grepl("^(任务要求|输出格式|请开始分析)", line)) {
            filtered_lines <- c(filtered_lines, line)
          }
        }

        return(paste(filtered_lines, collapse = "\n"))
      }

      return(full_prompt)
    },
    error = function(e) {
      cat("生成自定义Prompt失败:", e$message, "\n")
      return(generate_simple_prompt(cluster_id, marker_count))
    }
  )
}

# 计算Prompt统计信息
calculate_prompt_stats <- function(prompt_text) {
  tryCatch(
    {
      if (is.null(prompt_text) || prompt_text == "") {
        return(list(
          char_count = 0,
          word_count = 0,
          line_count = 0,
          database_count = 0,
          marker_count = 0,
          timestamp = format(Sys.time(), "%H:%M:%S")
        ))
      }

      # 基本统计
      char_count <- nchar(prompt_text)
      lines <- unlist(strsplit(prompt_text, "\n"))
      line_count <- length(lines)
      words <- unlist(strsplit(prompt_text, "[\\s\\n\\.,;:]+"))
      word_count <- length(words[words != ""])

      # 计算数据库数量（统计包含数据库名称的章节）
      database_sections <- sum(sapply(
        c("CellMarker", "STRINGdb", "功能富集", "通路分析"),
        function(db) grepl(db, prompt_text)
      ))

      # 计算标记基因数量（粗略估计）
      marker_matches <- regmatches(prompt_text, gregexpr("[A-Z0-9]+[A-Z][a-z0-9]*", prompt_text, perl = TRUE))
      marker_count <- length(unique(marker_matches[[1]]))

      return(list(
        char_count = char_count,
        word_count = word_count,
        line_count = line_count,
        database_count = database_sections,
        marker_count = marker_count,
        timestamp = format(Sys.time(), "%H:%M:%S")
      ))
    },
    error = function(e) {
      cat("计算Prompt统计失败:", e$message, "\n")
      return(list(
        char_count = 0,
        word_count = 0,
        line_count = 0,
        database_count = 0,
        marker_count = 0,
        timestamp = format(Sys.time(), "%H:%M:%S")
      ))
    }
  )
}

# 构建超级Prompt
build_super_prompt <- function(knowledge_base, top_markers) {
  prompt_parts <- c()

  # 1. 基本任务描述
  prompt_parts <- c(
    prompt_parts,
    "你是一位专业的单细胞RNA测序数据分析专家。请基于以下提供的多维度生物学证据，",
    "对给定的细胞簇进行准确的细胞类型鉴定。请综合考虑标记基因表达、功能富集、",
    "通路分析和文献证据，给出最准确的细胞类型判断。"
  )

  # 2. 标记基因信息
  prompt_parts <- c(
    prompt_parts,
    "",
    "【标记基因表达数据】",
    "以下是该细胞簇的Top差异表达基因："
  )

  # 添加标记基因详细信息（增强版 - 表格化显示）
  if (!is.null(knowledge_base$marker_genes)) {
    markers_df <- knowledge_base$marker_genes

    # 检查是否是data.frame且有行
    if (is.data.frame(markers_df) && nrow(markers_df) > 0 && "gene" %in% colnames(markers_df)) {
      markers_df <- markers_df[1:min(20, nrow(markers_df)), , drop = FALSE]

      # 检查是否有定量数据
      has_quant <- all(c("avg_log2FC", "pct.1", "pct.2", "p_val_adj") %in% colnames(markers_df))

      if (has_quant) {
        # ===== 增强版：表格化显示定量数据 =====
        prompt_parts <- c(
          prompt_parts,
          "",
          "⚠️ 重要：以下是经过严格统计筛选的TOP差异表达基因及其定量数据",
          "请仔细查看每个基因的log2FC（表达倍数）、表达率和统计显著性",
          "",
          "┌────────────────────────────────────────────────────────────────┐",
          "│ 基因     │ log2FC │ 本簇%  │ 其他%  │ 特异性  │ 校正P值     │",
          "├────────────────────────────────────────────────────────────────┤"
        )

        for (i in seq_len(nrow(markers_df))) {
          gene <- markers_df$gene[i]
          if (is.null(gene) || is.na(gene) || gene == "") next

          logfc <- markers_df$avg_log2FC[i]
          pct1 <- markers_df$pct.1[i]
          pct2 <- markers_df$pct.2[i]
          pval <- markers_df$p_val_adj[i]

          if (!is.na(logfc) && !is.na(pct1) && !is.na(pct2) && !is.na(pval)) {
            specificity <- (pct1 - pct2) * 100
            prompt_parts <- c(prompt_parts, sprintf(
              "│ %-8s │ %6.2f │ %6.1f │ %6.1f │ %7.1f │ %.2e │",
              substr(gene, 1, 8),
              logfc,
              pct1 * 100,
              pct2 * 100,
              specificity,
              pval
            ))
          }
        }

        prompt_parts <- c(
          prompt_parts,
          "└────────────────────────────────────────────────────────────────┘",
          "",
          "💡 定量数据解读指南：",
          "  • log2FC > 1.0  : 表达上调超过2倍，提示该基因在本簇高表达",
          "  • 本簇% > 70%   : 该基因在本簇中的细胞表达比例高",
          "  • 特异性 > 50% : 该基因在本簇特异性表达，是关键标记",
          "  • P值 < 0.01   : 统计显著性极高，可靠的差异表达"
        )
        # ===== 增强版结束 =====
      } else {
        # 无定量数据，使用原格式
        for (i in seq_len(nrow(markers_df))) {
          gene <- markers_df$gene[i]
          if (is.null(gene) || is.na(gene) || gene == "") next

          logfc <- if ("avg_log2FC" %in% colnames(markers_df)) markers_df$avg_log2FC[i] else NA
          pct1 <- if ("pct.1" %in% colnames(markers_df)) markers_df$pct.1[i] else NA
          pct2 <- if ("pct.2" %in% colnames(markers_df)) markers_df$pct.2[i] else NA
          pval <- if ("p_val_adj" %in% colnames(markers_df)) markers_df$p_val_adj[i] else NA

          prompt_parts <- c(prompt_parts, paste0(
            gene, ": log2FC=", if (!is.na(logfc)) round(logfc, 2) else "NA",
            ", 在本簇表达率=", if (!is.na(pct1)) round(pct1 * 100, 1) else "NA", "%, ",
            "在其他簇表达率=", if (!is.na(pct2)) round(pct2 * 100, 1) else "NA", "%, ",
            "校正P值=", if (!is.na(pval)) format(pval, scientific = TRUE) else "NA"
          ))
        }
      }
    } else if (is.data.frame(markers_df) && "gene" %in% names(markers_df)) {
      # marker_genes只有gene列
      genes <- head(markers_df$gene, 20)
      prompt_parts <- c(prompt_parts, paste("标记基因:", paste(genes, collapse = ", ")))
    } else {
      # 简化处理
      prompt_parts <- c(prompt_parts, paste("标记基因:", paste(top_markers, collapse = ", ")))
    }
  }

  # 3. CellMarker数据库证据（使用正确的字段路径）
  if (!is.null(knowledge_base$analysis_summary$cellmarker_summary)) {
    cm_summary <- knowledge_base$analysis_summary$cellmarker_summary
    if (!is.null(cm_summary$best_match) && cm_summary$best_match != "Unknown") {
      prompt_parts <- c(
        prompt_parts,
        "",
        "【CellMarker数据库证据】",
        paste0("最佳匹配细胞类型：", cm_summary$best_match),
        paste0("匹配基因数：", cm_summary$matched_markers %||% 0)
      )
    }
  }

  # 4. 功能富集分析（使用gprofiler_summary）
  if (!is.null(knowledge_base$analysis_summary$gprofiler_summary)) {
    gp_summary <- knowledge_base$analysis_summary$gprofiler_summary
    if (!is.null(gp_summary$significant_terms) && gp_summary$significant_terms > 0) {
      prompt_parts <- c(
        prompt_parts,
        "",
        "【功能富集分析】",
        paste0("显著富集条目数：", gp_summary$significant_terms),
        paste0("最佳FDR值：", format(gp_summary$best_fdr, scientific = TRUE))
      )
      # 如果有详细的top_terms，也添加
      if (!is.null(gp_summary$top_terms) && is.data.frame(gp_summary$top_terms) && nrow(gp_summary$top_terms) > 0) {
        prompt_parts <- c(prompt_parts, "Top富集功能：")
        top_terms <- head(gp_summary$top_terms$term_name, 5)
        for (term in top_terms) {
          prompt_parts <- c(prompt_parts, paste0("- ", term))
        }
      }
    }
  }

  # 5. 通路分析（使用clusterprofiler_summary）
  if (!is.null(knowledge_base$analysis_summary$clusterprofiler_summary)) {
    cp_summary <- knowledge_base$analysis_summary$clusterprofiler_summary
    if (!is.null(cp_summary$significant_pathways) && cp_summary$significant_pathways > 0) {
      prompt_parts <- c(
        prompt_parts,
        "",
        "【KEGG通路分析】",
        paste0("显著通路数：", cp_summary$significant_pathways),
        paste0("最佳p值：", format(cp_summary$best_pvalue, scientific = TRUE))
      )
      # 如果有详细的top_pathways，也添加
      if (!is.null(cp_summary$top_pathways) && is.data.frame(cp_summary$top_pathways) && nrow(cp_summary$top_pathways) > 0) {
        prompt_parts <- c(prompt_parts, "Top富集通路：")
        top_pathways <- head(cp_summary$top_pathways$Description, 5)
        for (pathway in top_pathways) {
          prompt_parts <- c(prompt_parts, paste0("- ", pathway))
        }
      }
    }
  }

  # 6. 文献证据（使用literature_summary）
  if (!is.null(knowledge_base$analysis_summary$literature_summary)) {
    lit_summary <- knowledge_base$analysis_summary$literature_summary
    if (!is.null(lit_summary$total_articles) && lit_summary$total_articles > 0) {
      prompt_parts <- c(
        prompt_parts,
        "",
        "【文献支持】",
        paste0("找到相关文献：", lit_summary$total_articles, "篇"),
        paste0("其中近5年文献：", lit_summary$recent_articles, "篇")
      )
    }
  }

  # 7. STRINGdb蛋白质互作网络
  if (!is.null(knowledge_base$analysis_summary$stringdb_summary)) {
    str_summary <- knowledge_base$analysis_summary$stringdb_summary
    if (!is.null(str_summary$interactions) && str_summary$interactions > 0) {
      prompt_parts <- c(
        prompt_parts,
        "",
        "【蛋白质互作网络】",
        paste0("发现", str_summary$interactions, "个蛋白质相互作用"),
        paste0("平均置信度：", round(str_summary$avg_confidence, 0))
      )
    }
  }

  # 7. 要求输出格式
  prompt_parts <- c(
    prompt_parts,
    "",
    "【输出要求】",
    "请基于以上所有证据，给出最终的细胞类型判断。输出格式：",
    "",
    "细胞类型：[具体的细胞类型名称]",
    "判断依据：[简要说明判断的主要依据]",
    "关键证据基因：[3-5个最重要的支持基因]",
    "置信度：[0-1之间的数值]"
  )

  # 🎯 注入自主构建的候选词汇表（来自 build_candidate_vocabulary）
  # rv$major_markers 由数据库查询 + LLM 推理动态生成，非人工预设
  # 同时传递每种类型的参考marker基因，帮助AI更精确判断
  tryCatch(
    {
      if (exists("rv") && !is.null(rv$major_markers) && nrow(rv$major_markers) > 0) {
        # 构建带marker基因的候选类型参考
        marker_reference <- sapply(1:nrow(rv$major_markers), function(i) {
          type_name <- rv$major_markers$细胞类型[i]
          markers <- rv$major_markers$Marker基因[i]
          paste0("- ", type_name, " (参考marker: ", markers, ")")
        })

        prompt_parts <- c(
          prompt_parts,
          "",
          "【候选词汇表 — 由数据库检索 + LLM 推理构建】",
          paste0("以下", nrow(rv$major_markers), "个候选类型来自 PanglaoDB/CellMarker/scType 数据库检索结果。"),
          "每种类型的参考marker基因如下（按特异性排序，前面的更特异）：",
          marker_reference,
          "",
          "请在以上候选范围内选择最匹配的细胞类型。"
        )
      }
    },
    error = function(e) {
      # 如果无法访问rv，静默处理（不影响现有功能）
    }
  )

  # 组合最终Prompt
  final_prompt <- paste(prompt_parts, collapse = "\n")
  return(final_prompt)
}

# ████████████████████████████████████████████████████████████████████████
# 区域：AURA 2.0 多模辩论引擎（行1051-1570）
# ████████████████████████████████████████████████████████████████████████
# 功能：三轮辩论机制（初审→质询→裁决）
# 核心函数：DebateReferee_Engine()
# ════════════════════════════════════════════════════════════════════════

# 生成质询Prompt模板（v2.2 平衡证据评估）
generate_critique_prompt <- function(conclusion, evidence, role = "资深的单细胞RNA测序专家") {
  # 🔧 v2.2更新：平衡质询风格，避免过度依赖"经典marker检查"
  # 问题：v2.1的"直接尖锐"风格导致辩手过度强调marker缺失，误导裁判
  # 解决：引导辩手评估证据链的整体有效性，而非仅检查经典marker存在性
  template <- paste0(
    "【你的角色】\n",
    "你是一位", role, "，正在与另一位专家进行学术辩论。\n\n",
    "【质询任务】\n",
    "审视对方的细胞类型注释结论，提出你的质疑和不同看法。\n\n",
    "【质询方向】（灵活选择，不必全部覆盖）\n",
    "1. **证据链评估**（最重要）\n",
    "   - 对方提供的marker基因组合，是否整体指向该细胞类型？\n",
    "   - 即使缺少某些\"经典marker\"，现有证据是否依然充分？\n",
    "   - 通路富集、数据库匹配等证据是否支持该判断？\n\n",
    "2. **替代解释**\n",
    "   - 这些marker是否可能指向其他细胞类型？\n",
    "   - 是否存在更合理的注释？\n\n",
    "3. **逻辑一致性**\n",
    "   - 对方的推理是否存在逻辑跳跃或矛盾？\n",
    "   - 证据与结论之间的连接是否合理？\n\n",
    "4. **认可有效判断**\n",
    "   - 对于有理有据的判断，也请明确认可\n",
    "   - 学术辩论不是为了否定而否定\n\n",
    "【质询原则】\n",
    "⚠️ 重要提醒：\n",
    "- ❌ 不要仅因\"缺少经典marker X\"就全盘否定对方判断\n",
    "- ✅ 应评估：现有marker组合是否依然能有效支持该结论\n",
    "- ❌ 避免陷入\"marker清单检查\"模式（如：必须有A、B、C才算有效）\n",
    "- ✅ 应关注：证据的整体一致性和相互支持程度\n",
    "- 示例：REG1P、KLK1可以作为acinar cell的有效证据，即使缺少PRSS1\n",
    "- 示例：替代marker + 通路富集 + 数据库支持，可以弥补经典marker的缺失\n\n",
    "【风格要求】\n",
    "客观、严谨、建设性。指出问题时应同时评估现有证据的有效性。\n\n",
    "【输出要求】\n",
    "⚠️ 必须一次性完成所有簇的质询，不要分段输出，不要说\"因篇幅限制\"或\"下一轮继续\"！\n",
    "请一次性给出完整的质询内容。\n\n",
    "【原始证据（所有簇的完整marker基因数据）】\n", evidence, "\n\n",
    "【对方的注释结论】\n", conclusion, "\n\n",
    "【重要】请用自然语言详细回复，不要输出JSON格式！\n\n",
    "请开始你的质询："
  )
  return(template)
}

# 解析裁判裁决结果
parse_referee_verdict <- function(verdict_response) {
  tryCatch(
    {
      response_text <- if (is.list(verdict_response) && !is.null(verdict_response$success)) {
        verdict_response$success
      } else if (is.character(verdict_response)) {
        verdict_response
      } else {
        return(list(
          cell_type = "Unknown",
          confidence = 0.5,
          reasoning = "解析失败",
          key_genes = c(),
          full_response = ""
        ))
      }

      # 🔧 批量模式特殊处理：检测JSON格式（支持新的annotations+reasoning格式）
      if (grepl("^\\s*\\{", response_text)) {
        cat("  [解析] 检测到JSON格式输出\n")

        # 提取完整的JSON部分（支持嵌套结构）
        json_str <- extract_json_string(response_text)

        if (!is.null(json_str)) {
          cat("  [解析] 提取JSON部分，长度:", nchar(json_str), "字符\n")

          # 尝试解析JSON
          parsed_json <- tryCatch(
            jsonlite::fromJSON(json_str, simplifyVector = FALSE),
            error = function(e) NULL
          )

          # 检查是否为新格式（包含annotations和reasoning）
          reasoning_text <- ""
          annotations_json <- json_str

          if (!is.null(parsed_json)) {
            if (!is.null(parsed_json$annotations)) {
              # 新格式：{annotations: {...}, reasoning: "..."}
              cat("  [解析] 检测到新格式JSON（包含annotations和reasoning）\n")
              annotations_json <- jsonlite::toJSON(parsed_json$annotations, auto_unbox = TRUE)
              reasoning_text <- parsed_json$reasoning %||% ""
              cat("  [解析] reasoning长度:", nchar(reasoning_text), "字符\n")
            } else if (!is.null(parsed_json$cluster_annotations)) {
              # 兼容旧格式：{cluster_annotations: [...]}
              cat("  [解析] 检测到cluster_annotations格式\n")
              reasoning_text <- parsed_json$reasoning %||% ""
            } else {
              # 最简格式：{"0": "T cell", ...}
              cat("  [解析] 检测到简单格式JSON\n")
            }
          }

          # 返回特殊标记，表示这是JSON批量结果
          return(list(
            cell_type = "BATCH_JSON_RESULT",
            reasoning = reasoning_text,
            key_genes = c(),
            full_response = annotations_json, # 保存annotations部分
            full_json = json_str, # 保存完整JSON
            is_batch_json = TRUE
          ))
        }
      }

      # 提取细胞类型（增强版，支持更多格式）
      cell_type_patterns <- c(
        "细胞类型[：:：\\s]*([^\\n,;。]+?)\\s*[\\n。,;]",
        "Cell [Tt]ype[：:：\\s]*([^\\n,;。]+?)\\s*[\\n。,;]",
        "最终裁决[：:：\\s]*([^\\n,;。]+?)\\s*[\\n。,;]",
        "判断为[：:：\\s]*([^\\n,;。]+?)\\s*[\\n。,;]",
        "注释为[：:：\\s]*([^\\n,;。]+?)\\s*[\\n。,;]",
        "是([^\\n,;。]{2,30}?)细胞",
        "([^\\n,;。]{2,30}?)细胞\\s*[（\\(]",
        "这是([^\\n,;。]{2,30}?)细胞",
        "应该是([^\\n,;。]{2,30}?)细胞",
        "属于([^\\n,;。]{2,30}?)细胞"
      )

      cell_type <- NULL
      for (pattern in cell_type_patterns) {
        match <- regmatches(response_text, regexpr(pattern, response_text, perl = TRUE, ignore.case = TRUE))
        if (length(match) > 0) {
          type_match <- gsub(pattern, "\\1", match, perl = TRUE)
          # 清理Markdown符号、标点符号、引号
          type_match <- gsub("\\*\\*", "", type_match) # 移除**
          type_match <- gsub("\\*", "", type_match) # 移除*
          type_match <- trimws(gsub("^[:：]+|[:：]+$|^[\"']+|[\"']+$", "", type_match))

          # 过滤无效词汇
          invalid_words <- c("这", "该", "此", "基于", "根据", "相关", "关联", "可能", "应该", "或许", "大概")
          is_valid <- !grepl(paste0("^(", paste(invalid_words, collapse = "|"), ")"), type_match) &&
            nchar(type_match) > 1 && nchar(type_match) < 50

          if (is_valid) {
            cell_type <- type_match
            cat("成功提取细胞类型:", cell_type, "（使用模式:", substr(pattern, 1, 30), "...）\n")
            break
          }
        }
      }

      # 如果正则匹配失败，尝试更智能的提取
      if (is.null(cell_type) || cell_type == "") {
        cat("正则匹配失败，尝试智能提取...\n")

        # 查找常见细胞类型关键词
        cell_keywords <- c(
          "T细胞", "T cell", "CD8\\+.*细胞", "CD4\\+.*细胞",
          "B细胞", "B cell", "浆细胞", "Plasma cell",
          "NK细胞", "NK cell",
          "单核细胞", "Monocyte", "巨噬细胞", "Macrophage",
          "树突状细胞", "Dendritic cell",
          "上皮细胞", "Epithelial cell", "肌上皮细胞", "Myoepithelial",
          "内皮细胞", "Endothelial cell",
          "成纤维细胞", "Fibroblast",
          "干细胞", "Stem cell",
          "癌细胞", "Cancer cell", "肿瘤细胞", "Tumor cell"
        )

        for (keyword in cell_keywords) {
          if (grepl(keyword, response_text, ignore.case = TRUE)) {
            cell_type <- keyword
            cat("关键词匹配成功:", cell_type, "\n")
            break
          }
        }
      }

      # 如果仍然失败，使用完整响应的摘要
      if (is.null(cell_type) || cell_type == "" || cell_type == "Unknown") {
        cat("智能提取失败，使用响应摘要\n")
        # 至少返回响应的前50个字符作为cell_type
        cell_type <- substr(gsub("\\s+", " ", response_text), 1, 50)
        if (nchar(cell_type) < 3) {
          cell_type <- "Unknown"
        }
      }

      # 提取置信度
      confidence_patterns <- c(
        "置信度[：:]+\\s*([0-9]+\\.?[0-9]*)",
        "Confidence[：:]+\\s*([0-9]+\\.?[0-9]*)",
        "confidence:\\s*([0-9]+\\.?[0-9]*)"
      )

      confidence <- 0.5
      for (pattern in confidence_patterns) {
        match <- regmatches(response_text, regexpr(pattern, response_text, perl = TRUE, ignore.case = TRUE))
        if (length(match) > 0) {
          conf_match <- as.numeric(gsub(pattern, "\\1", match, perl = TRUE))
          if (!is.na(conf_match)) {
            confidence <- if (conf_match > 1) conf_match / 100 else conf_match
            break
          }
        }
      }

      # 提取理由
      reasoning_patterns <- c(
        "理由[：:]+\\s*([^【]+)",
        "Reasoning[：:]+\\s*([^【]+)",
        "判断依据[：:]+\\s*([^【]+)"
      )

      reasoning <- ""
      for (pattern in reasoning_patterns) {
        match <- regmatches(response_text, regexpr(pattern, response_text, perl = TRUE, ignore.case = TRUE))
        if (length(match) > 0) {
          reasoning <- trimws(gsub(pattern, "\\1", match, perl = TRUE))
          if (nchar(reasoning) > 10) {
            break
          }
        }
      }

      if (reasoning == "") {
        reasoning <- substr(response_text, 1, min(500, nchar(response_text)))
      }

      # 提取关键基因
      key_genes_patterns <- c(
        "关键基因[：:]+\\s*([^\\n【]+)",
        "Key genes[：:]+\\s*([^\\n【]+)",
        "证据基因[：:]+\\s*([^\\n【]+)"
      )

      key_genes <- c()
      for (pattern in key_genes_patterns) {
        match <- regmatches(response_text, regexpr(pattern, response_text, perl = TRUE, ignore.case = TRUE))
        if (length(match) > 0) {
          genes_text <- gsub(pattern, "\\1", match, perl = TRUE)
          # 分割基因名
          key_genes <- unlist(strsplit(genes_text, "[,，、;；\\s]+"))
          key_genes <- trimws(key_genes)
          key_genes <- key_genes[nchar(key_genes) > 1]
          break
        }
      }

      # ═══════════════════════════════════════════════════════════════
      # 标准化细胞类型名称（去掉括号注释，确保与marker列表匹配）
      # ═══════════════════════════════════════════════════════════════
      # 去掉中文括号及内容：DC（树突状细胞）→ DC
      cell_type <- gsub("（[^）]*）", "", cell_type)
      cell_type <- gsub("\\([^\\)]*\\)", "", cell_type) # 去掉英文括号
      cell_type <- trimws(cell_type) # 去掉首尾空格

      # 如果结果为空，设为Unknown
      if (is.null(cell_type) || cell_type == "" || nchar(cell_type) < 2) {
        cell_type <- "Unknown"
      }

      cat("标准化后的细胞类型:", cell_type, "\n")

      list(
        cell_type = cell_type,
        confidence = max(0, min(1, confidence)),
        reasoning = reasoning,
        key_genes = key_genes,
        full_response = response_text
      )
    },
    error = function(e) {
      cat("解析裁判裁决失败:", e$message, "\n")
      list(
        cell_type = "Unknown",
        confidence = 0.5,
        reasoning = "解析失败",
        key_genes = c(),
        full_response = if (is.character(verdict_response)) verdict_response else ""
      )
    }
  )
}

# 第一轮：并行辩论
parallel_debate <- function(debater_A, debater_B, prompt, api_keys, is_batch_mode = FALSE, api_metrics = NULL) {
  tryCatch(
    {
      cat("\n")
      cat("╔══════════════════════════════════════════════════════════╗\n")
      cat("║              第一轮：初审辩论                            ║\n")
      cat("╚══════════════════════════════════════════════════════════╝\n")
      cat(sprintf("  👤 辩手A: %s\n", debater_A))
      cat(sprintf("  👤 辩手B: %s\n", debater_B))
      cat(sprintf("  📌 批量模式: %s\n", is_batch_mode))

      # 准备API调用函数
      call_llm <- function(model, prompt, api_keys) {
        # 检测是否为快速模型（_fast后缀）
        use_fast_model <- grepl("_fast$", model)
        base_model <- sub("_fast$", "", model)

        if (use_fast_model) {
          cat(sprintf("ℹ️ 使用快速模型版本: %s\n", model))
        }

        switch(base_model,
          "deepseek" = ask_deepseek(prompt,
            system_prompt = "你是一位单细胞RNA测序和细胞类型鉴定专家。【任务目标】基于提供的证据，对细胞类型做出最准确的判断。后续会有另一位专家从不同角度审视你的判断，这不是竞争，而是通过多角度验证来提高准确性。【判断原则】1.证据导向：综合评估marker基因、通路富集、数据库匹配；2.承认不确定性：证据不充分时，诚实标注置信度较低；3.替代marker：生物数据有变异，替代marker同样重要；4.整体一致性：关注证据链的相互支持，而非单一基因。请给出你的专业判断和理由。",
            api_key = api_keys$deepseek,
            use_fast_model = use_fast_model
          ),
          "kimi" = ask_kimi(prompt,
            system_prompt = "你是一位单细胞RNA测序和细胞类型鉴定专家。【任务目标】基于提供的证据，对细胞类型做出最准确的判断。后续会有另一位专家从不同角度审视你的判断，这不是竞争，而是通过多角度验证来提高准确性。【判断原则】1.证据导向：综合评估marker基因、通路富集、数据库匹配；2.承认不确定性：证据不充分时，诚实标注置信度较低；3.替代marker：生物数据有变异，替代marker同样重要；4.整体一致性：关注证据链的相互支持，而非单一基因。请给出你的专业判断和理由。",
            api_key = api_keys$kimi,
            use_fast_model = use_fast_model
          ),
          "glm" = ask_glm(prompt,
            system_prompt = "你是一位单细胞RNA测序和细胞类型鉴定专家。【任务目标】基于提供的证据，对细胞类型做出最准确的判断。后续会有另一位专家从不同角度审视你的判断，这不是竞争，而是通过多角度验证来提高准确性。【判断原则】1.证据导向：综合评估marker基因、通路富集、数据库匹配；2.承认不确定性：证据不充分时，诚实标注置信度较低；3.替代marker：生物数据有变异，替代marker同样重要；4.整体一致性：关注证据链的相互支持，而非单一基因。请给出你的专业判断和理由。",
            api_key = api_keys$glm,
            use_fast_model = use_fast_model
          ),
          "doubao" = ask_douban(prompt,
