        )
      }

      # 调用辩手A
      cat(sprintf("\n  🔄 调用辩手A (%s)...\n", debater_A))
      result_A_raw <- call_llm(debater_A, prompt, api_keys)

      # 【新增】记录辩手A的token使用情况
      if (!is.null(api_metrics) && !is.null(result_A_raw$usage)) {
        api_metrics$total_calls <- api_metrics$total_calls + 1
        if (!is.null(result_A_raw$usage$prompt_tokens)) {
          api_metrics$total_tokens_input <- api_metrics$total_tokens_input + result_A_raw$usage$prompt_tokens
        }
        if (!is.null(result_A_raw$usage$completion_tokens)) {
          api_metrics$total_tokens_output <- api_metrics$total_tokens_output + result_A_raw$usage$completion_tokens
        }
        if (!is.null(result_A_raw$usage$total_tokens)) {
          api_metrics$total_tokens <- api_metrics$total_tokens + result_A_raw$usage$total_tokens
        }
        # 记录模型级别的统计
        model_key <- debater_A
        if (is.null(api_metrics$model_breakdown[[model_key]])) {
          api_metrics$model_breakdown[[model_key]] <- list(calls = 0, tokens_input = 0, tokens_output = 0, tokens_total = 0)
        }
        api_metrics$model_breakdown[[model_key]]$calls <- api_metrics$model_breakdown[[model_key]]$calls + 1
        api_metrics$model_breakdown[[model_key]]$tokens_input <- api_metrics$model_breakdown[[model_key]]$tokens_input + (result_A_raw$usage$prompt_tokens %||% 0)
        api_metrics$model_breakdown[[model_key]]$tokens_output <- api_metrics$model_breakdown[[model_key]]$tokens_output + (result_A_raw$usage$completion_tokens %||% 0)
        api_metrics$model_breakdown[[model_key]]$tokens_total <- api_metrics$model_breakdown[[model_key]]$tokens_total + (result_A_raw$usage$total_tokens %||% 0)
      }

      # 显示辩手A完整返回内容
      if (!is.null(result_A_raw$success)) {
        cat(sprintf("  ✅ 辩手A返回 (%d字符)\n", nchar(result_A_raw$success)))
        if (!is.null(result_A_raw$usage$total_tokens)) {
          cat(sprintf(
            "  💰 Token使用: %d (输入:%d + 输出:%d)\n",
            result_A_raw$usage$total_tokens,
            result_A_raw$usage$prompt_tokens %||% 0,
            result_A_raw$usage$completion_tokens %||% 0
          ))
        }
        # 尝试格式化JSON以便更好显示
        formatted_response_A <- tryCatch(
          {
            jsonlite::prettify(result_A_raw$success)
          },
          error = function(e) {
            result_A_raw$success
          }
        )
        cat("  ┌────────────────────────────────────────────────────────┐\n")
        cat("  │ 辩手A完整回复：\n")
        cat("  │", gsub("\n", "\n  │ ", formatted_response_A), "\n")
        cat("  └────────────────────────────────────────────────────────┘\n")
      } else {
        cat(sprintf("  ❌ 辩手A API调用失败: %s\n", result_A_raw$error))
      }

      # 如果辩手A和辩手B使用同一模型，增加1秒延迟避免并发限制
      if (debater_A == debater_B) {
        cat("  ⏳ 辩手A和B使用同一模型，延迟1秒避免并发...\n")
        Sys.sleep(1)
      }

      # 调用辩手B
      cat(sprintf("\n  🔄 调用辩手B (%s)...\n", debater_B))
      result_B_raw <- call_llm(debater_B, prompt, api_keys)

      # 【新增】记录辩手B的token使用情况
      if (!is.null(api_metrics) && !is.null(result_B_raw$usage)) {
        api_metrics$total_calls <- api_metrics$total_calls + 1
        if (!is.null(result_B_raw$usage$prompt_tokens)) {
          api_metrics$total_tokens_input <- api_metrics$total_tokens_input + result_B_raw$usage$prompt_tokens
        }
        if (!is.null(result_B_raw$usage$completion_tokens)) {
          api_metrics$total_tokens_output <- api_metrics$total_tokens_output + result_B_raw$usage$completion_tokens
        }
        if (!is.null(result_B_raw$usage$total_tokens)) {
          api_metrics$total_tokens <- api_metrics$total_tokens + result_B_raw$usage$total_tokens
        }
        # 记录模型级别的统计
        model_key <- debater_B
        if (is.null(api_metrics$model_breakdown[[model_key]])) {
          api_metrics$model_breakdown[[model_key]] <- list(calls = 0, tokens_input = 0, tokens_output = 0, tokens_total = 0)
        }
        api_metrics$model_breakdown[[model_key]]$calls <- api_metrics$model_breakdown[[model_key]]$calls + 1
        api_metrics$model_breakdown[[model_key]]$tokens_input <- api_metrics$model_breakdown[[model_key]]$tokens_input + (result_B_raw$usage$prompt_tokens %||% 0)
        api_metrics$model_breakdown[[model_key]]$tokens_output <- api_metrics$model_breakdown[[model_key]]$tokens_output + (result_B_raw$usage$completion_tokens %||% 0)
        api_metrics$model_breakdown[[model_key]]$tokens_total <- api_metrics$model_breakdown[[model_key]]$tokens_total + (result_B_raw$usage$total_tokens %||% 0)
      }

      # 显示辩手B完整返回内容
      if (!is.null(result_B_raw$success)) {
        cat(sprintf("  ✅ 辩手B返回 (%d字符)\n", nchar(result_B_raw$success)))
        if (!is.null(result_B_raw$usage$total_tokens)) {
          cat(sprintf(
            "  💰 Token使用: %d (输入:%d + 输出:%d)\n",
            result_B_raw$usage$total_tokens,
            result_B_raw$usage$prompt_tokens %||% 0,
            result_B_raw$usage$completion_tokens %||% 0
          ))
        }
        # 尝试格式化JSON以便更好显示
        formatted_response_B <- tryCatch(
          {
            jsonlite::prettify(result_B_raw$success)
          },
          error = function(e) {
            result_B_raw$success
          }
        )
        cat("  ┌────────────────────────────────────────────────────────┐\n")
        cat("  │ 辩手B完整回复：\n")
        cat("  │", gsub("\n", "\n  │ ", formatted_response_B), "\n")
        cat("  └────────────────────────────────────────────────────────┘\n")
      } else {
        cat(sprintf("  ❌ 辩手B API调用失败: %s\n", result_B_raw$error))
      }

      # 解析结果（批量模式和单簇模式不同处理）
      cat("\n  ────────────────────────────────────────────────────────\n")
      if (is_batch_mode) {
        # 批量模式：直接保存JSON，不调用parse_referee_verdict
        cat("  📦 批量模式：保存JSON字符串，跳过单独解析\n")

        result_A <- if (!is.null(result_A_raw$success)) {
          list(
            cell_type = "Batch_JSON_Mode",
            reasoning = "批量模式JSON结果",
            full_response = result_A_raw$success,
            key_genes = c()
          )
        } else {
          list(cell_type = "Unknown", confidence = 0.1, reasoning = paste("API调用失败:", result_A_raw$error), full_response = "")
        }

        result_B <- if (!is.null(result_B_raw$success)) {
          list(
            cell_type = "Batch_JSON_Mode",
            reasoning = "批量模式JSON结果",
            full_response = result_B_raw$success,
            key_genes = c()
          )
        } else {
          list(cell_type = "Unknown", confidence = 0.1, reasoning = paste("API调用失败:", result_B_raw$error), full_response = "")
        }

        cat(sprintf("  📝 辩手A JSON长度: %d 字符\n", nchar(result_A$full_response)))
        cat(sprintf("  📝 辩手B JSON长度: %d 字符\n", nchar(result_B$full_response)))
        cat("  ✅ 第一轮初审辩论完成（批量模式）\n")
        cat("  ────────────────────────────────────────────────────────\n\n")
      } else {
        # 单簇/约束注释模式：正常解析
        cat("  📝 单簇模式：解析辩手结果...\n")
        result_A <- if (!is.null(result_A_raw$success)) {
          parse_referee_verdict(result_A_raw$success)
        } else {
          list(cell_type = "Unknown", confidence = 0.1, reasoning = paste("API调用失败:", result_A_raw$error))
        }

        result_B <- if (!is.null(result_B_raw$success)) {
          parse_referee_verdict(result_B_raw$success)
        } else {
          list(cell_type = "Unknown", confidence = 0.1, reasoning = paste("API调用失败:", result_B_raw$error))
        }

        cat(sprintf("  📋 辩手A最终结论: %s (置信度: %.2f)\n", result_A$cell_type, result_A$confidence))
        cat(sprintf("  📋 辩手B最终结论: %s (置信度: %.2f)\n", result_B$cell_type, result_B$confidence))
        cat("  ✅ 第一轮初审辩论完成（单簇模式）\n")
        cat("  ────────────────────────────────────────────────────────\n\n")
      }

      return(list(
        result_A = result_A,
        result_B = result_B,
        model_A = debater_A,
        model_B = debater_B,
        timestamp = Sys.time()
      ))
    },
    error = function(e) {
      cat("并行辩论失败:", e$message, "\n")
      return(list(
        result_A = list(cell_type = "Unknown", confidence = 0.1, reasoning = paste("辩论失败:", e$message)),
        result_B = list(cell_type = "Unknown", confidence = 0.1, reasoning = paste("辩论失败:", e$message)),
        model_A = debater_A,
        model_B = debater_B
      ))
    }
  )
}

# 第二轮：交叉质询
cross_examination <- function(conclusion_A, conclusion_B, original_evidence, debater_A, debater_B, api_keys, is_batch_mode = FALSE, cluster_id = NULL, api_metrics = NULL) {
  tryCatch(
    {
      cat("\n")
      cat("╔══════════════════════════════════════════════════════════╗\n")
      cat("║              第二轮：交叉质询                            ║\n")
      cat("╚══════════════════════════════════════════════════════════╝\n")

      cat(sprintf("  📌 is_batch_mode = %s\n", is_batch_mode))
      cat(sprintf("  📌 full_response存在 = %s\n", !is.null(conclusion_A$full_response) && nchar(conclusion_A$full_response) > 10))

      # 构建结论文本
      if (is_batch_mode && !is.null(conclusion_A$full_response) && nchar(conclusion_A$full_response) > 10) {
        # 批量模式：使用完整的JSON作为结论
        cat("\n  ✅ 批量模式：使用完整JSON结果进行交叉质询\n")
        cat("  ────────────────────────────────────────────────────────\n")
        cat("  📋 辩手A的批量注释结果：\n")
        # 格式化JSON以便更好显示
        formatted_json_A <- tryCatch(
          {
            jsonlite::prettify(conclusion_A$full_response)
          },
          error = function(e) {
            conclusion_A$full_response
          }
        )
        cat(sprintf("     %s\n", gsub("\n", "\n     ", formatted_json_A)))

        cat("  📋 辩手B的批量注释结果：\n")
        # 格式化JSON以便更好显示
        formatted_json_B <- tryCatch(
          {
            jsonlite::prettify(conclusion_B$full_response)
          },
          error = function(e) {
            conclusion_B$full_response
          }
        )
        cat(sprintf("     %s\n", gsub("\n", "\n     ", formatted_json_B)))
        cat("  ────────────────────────────────────────────────────────\n\n")

        conclusion_text_A <- paste0(
          "批量细胞类型注释结果（JSON格式）：\n",
          conclusion_A$full_response, "\n",
          "置信度：", conclusion_A$confidence
        )

        conclusion_text_B <- paste0(
          "批量细胞类型注释结果（JSON格式）：\n",
          conclusion_B$full_response, "\n",
          "置信度：", conclusion_B$confidence
        )
      } else {
        # 单簇模式：使用单个细胞类型
        cat("\n  📝 单簇模式：使用单个细胞类型进行交叉质询\n")
        cat(sprintf("  📋 辩手A判断: %s (置信度: %.2f)\n", conclusion_A$cell_type, conclusion_A$confidence))
        cat(sprintf("  📋 辩手B判断: %s (置信度: %.2f)\n", conclusion_B$cell_type, conclusion_B$confidence))

        conclusion_text_A <- paste0(
          "细胞类型：", conclusion_A$cell_type, "\n",
          "置信度：", conclusion_A$confidence, "\n",
          "理由：", conclusion_A$reasoning
        )

        conclusion_text_B <- paste0(
          "细胞类型：", conclusion_B$cell_type, "\n",
          "置信度：", conclusion_B$confidence, "\n",
          "理由：", conclusion_B$reasoning
        )
      }

      # 🔧 质询专用system_prompt：强制自然语言输出，禁止JSON
      critique_system_prompt <- "你是一位资深的单细胞RNA测序专家，正在参与学术讨论。请务必用自然语言详细回复，不要输出JSON格式。"

      # B质询A
      cat("\n  🔍 辩手B质询辩手A的观点...\n")
      critique_prompt_A <- generate_critique_prompt(
        conclusion = conclusion_text_A,
        evidence = original_evidence,
        role = "资深的单细胞注释专家"
      )

      # 检测辩手B是否为快速模型
      use_fast_B <- grepl("_fast$", debater_B)
      base_debater_B <- sub("_fast$", "", debater_B)

      critique_of_A_raw <- switch(base_debater_B,
        "deepseek" = ask_deepseek(critique_prompt_A, system_prompt = critique_system_prompt, api_key = api_keys$deepseek, use_fast_model = use_fast_B),
        "kimi" = ask_kimi(critique_prompt_A, system_prompt = critique_system_prompt, api_key = api_keys$kimi, use_fast_model = use_fast_B),
        "glm" = ask_glm(critique_prompt_A, system_prompt = critique_system_prompt, api_key = api_keys$glm, use_fast_model = use_fast_B),
        "doubao" = ask_douban(critique_prompt_A, system_prompt = critique_system_prompt, api_key = api_keys$doubao, use_fast_model = use_fast_B),
        "qwen" = ask_qwen(critique_prompt_A, system_prompt = critique_system_prompt, api_key = api_keys$qwen, use_fast_model = use_fast_B),
        "hunyuan" = ask_hunyuan(critique_prompt_A, system_prompt = critique_system_prompt, api_key = api_keys$hunyuan, use_fast_model = use_fast_B),
        "ernie" = ask_ernie(critique_prompt_A, system_prompt = critique_system_prompt, api_key = api_keys$ernie, use_fast_model = use_fast_B),
        "stepfun" = ask_stepfun(critique_prompt_A, system_prompt = critique_system_prompt, api_key = api_keys$stepfun, use_fast_model = use_fast_B),
        "spark" = ask_spark(critique_prompt_A, system_prompt = critique_system_prompt, api_key = api_keys$spark, use_fast_model = use_fast_B),
        "minimax" = ask_minimax(critique_prompt_A, system_prompt = critique_system_prompt, api_key = api_keys$minimax, use_fast_model = use_fast_B),
        list(error = "未知的模型")
      )

      # 【新增】记录辩手B质询的token使用情况
      if (!is.null(api_metrics) && !is.null(critique_of_A_raw$usage)) {
        api_metrics$total_calls <- api_metrics$total_calls + 1
        if (!is.null(critique_of_A_raw$usage$prompt_tokens)) {
          api_metrics$total_tokens_input <- api_metrics$total_tokens_input + critique_of_A_raw$usage$prompt_tokens
        }
        if (!is.null(critique_of_A_raw$usage$completion_tokens)) {
          api_metrics$total_tokens_output <- api_metrics$total_tokens_output + critique_of_A_raw$usage$completion_tokens
        }
        if (!is.null(critique_of_A_raw$usage$total_tokens)) {
          api_metrics$total_tokens <- api_metrics$total_tokens + critique_of_A_raw$usage$total_tokens
        }
        # 记录模型级别的统计
        model_key <- debater_B
        if (is.null(api_metrics$model_breakdown[[model_key]])) {
          api_metrics$model_breakdown[[model_key]] <- list(calls = 0, tokens_input = 0, tokens_output = 0, tokens_total = 0)
        }
        api_metrics$model_breakdown[[model_key]]$calls <- api_metrics$model_breakdown[[model_key]]$calls + 1
        api_metrics$model_breakdown[[model_key]]$tokens_input <- api_metrics$model_breakdown[[model_key]]$tokens_input + (critique_of_A_raw$usage$prompt_tokens %||% 0)
        api_metrics$model_breakdown[[model_key]]$tokens_output <- api_metrics$model_breakdown[[model_key]]$tokens_output + (critique_of_A_raw$usage$completion_tokens %||% 0)
        api_metrics$model_breakdown[[model_key]]$tokens_total <- api_metrics$model_breakdown[[model_key]]$tokens_total + (critique_of_A_raw$usage$total_tokens %||% 0)
      }

      # A质询B
      cat("  🔍 辩手A质询辩手B的观点...\n")
      critique_prompt_B <- generate_critique_prompt(
        conclusion = conclusion_text_B,
        evidence = original_evidence,
        role = "资深的单细胞注释专家"
      )

      # 检测辩手A是否为快速模型
      use_fast_A <- grepl("_fast$", debater_A)
      base_debater_A <- sub("_fast$", "", debater_A)

      critique_of_B_raw <- switch(base_debater_A,
        "deepseek" = ask_deepseek(critique_prompt_B, system_prompt = critique_system_prompt, api_key = api_keys$deepseek, use_fast_model = use_fast_A),
        "kimi" = ask_kimi(critique_prompt_B, system_prompt = critique_system_prompt, api_key = api_keys$kimi, use_fast_model = use_fast_A),
        "glm" = ask_glm(critique_prompt_B, system_prompt = critique_system_prompt, api_key = api_keys$glm, use_fast_model = use_fast_A),
        "doubao" = ask_douban(critique_prompt_B, system_prompt = critique_system_prompt, api_key = api_keys$doubao, use_fast_model = use_fast_A),
        "qwen" = ask_qwen(critique_prompt_B, system_prompt = critique_system_prompt, api_key = api_keys$qwen, use_fast_model = use_fast_A),
        "hunyuan" = ask_hunyuan(critique_prompt_B, system_prompt = critique_system_prompt, api_key = api_keys$hunyuan, use_fast_model = use_fast_A),
        "ernie" = ask_ernie(critique_prompt_B, system_prompt = critique_system_prompt, api_key = api_keys$ernie, use_fast_model = use_fast_A),
        "stepfun" = ask_stepfun(critique_prompt_B, system_prompt = critique_system_prompt, api_key = api_keys$stepfun, use_fast_model = use_fast_A),
        "spark" = ask_spark(critique_prompt_B, system_prompt = critique_system_prompt, api_key = api_keys$spark, use_fast_model = use_fast_A),
        "minimax" = ask_minimax(critique_prompt_B, system_prompt = critique_system_prompt, api_key = api_keys$minimax, use_fast_model = use_fast_A),
        list(error = "未知的模型")
      )

      # 【新增】记录辩手A质询的token使用情况
      if (!is.null(api_metrics) && !is.null(critique_of_B_raw$usage)) {
        api_metrics$total_calls <- api_metrics$total_calls + 1
        if (!is.null(critique_of_B_raw$usage$prompt_tokens)) {
          api_metrics$total_tokens_input <- api_metrics$total_tokens_input + critique_of_B_raw$usage$prompt_tokens
        }
        if (!is.null(critique_of_B_raw$usage$completion_tokens)) {
          api_metrics$total_tokens_output <- api_metrics$total_tokens_output + critique_of_B_raw$usage$completion_tokens
        }
        if (!is.null(critique_of_B_raw$usage$total_tokens)) {
          api_metrics$total_tokens <- api_metrics$total_tokens + critique_of_B_raw$usage$total_tokens
        }
        # 记录模型级别的统计
        model_key <- debater_A
        if (is.null(api_metrics$model_breakdown[[model_key]])) {
          api_metrics$model_breakdown[[model_key]] <- list(calls = 0, tokens_input = 0, tokens_output = 0, tokens_total = 0)
        }
        api_metrics$model_breakdown[[model_key]]$calls <- api_metrics$model_breakdown[[model_key]]$calls + 1
        api_metrics$model_breakdown[[model_key]]$tokens_input <- api_metrics$model_breakdown[[model_key]]$tokens_input + (critique_of_B_raw$usage$prompt_tokens %||% 0)
        api_metrics$model_breakdown[[model_key]]$tokens_output <- api_metrics$model_breakdown[[model_key]]$tokens_output + (critique_of_B_raw$usage$completion_tokens %||% 0)
        api_metrics$model_breakdown[[model_key]]$tokens_total <- api_metrics$model_breakdown[[model_key]]$tokens_total + (critique_of_B_raw$usage$total_tokens %||% 0)
      }

      critique_of_A <- if (!is.null(critique_of_A_raw$success)) {
        critique_of_A_raw$success
      } else {
        paste("质询失败:", critique_of_A_raw$error)
      }

      critique_of_B <- if (!is.null(critique_of_B_raw$success)) {
        critique_of_B_raw$success
      } else {
        paste("质询失败:", critique_of_B_raw$error)
      }

      cat("\n  ────────────────────────────────────────────────────────\n")
      cat("  ✅ 交叉质询完成\n")
      cat(sprintf("  📝 B对A的质询长度: %d 字符\n", nchar(critique_of_A)))
      cat(sprintf("  📝 A对B的质询长度: %d 字符\n", nchar(critique_of_B)))

      # 打印完整质询内容
      cat("\n  ┌────────────────────────────────────────────────────────┐\n")
      cat("  │ 辩手B对辩手A的质询（完整）：\n")
      cat("  │", gsub("\n", "\n  │ ", critique_of_A), "\n")
      cat("  └────────────────────────────────────────────────────────┘\n")

      cat("\n  ┌────────────────────────────────────────────────────────┐\n")
      cat("  │ 辩手A对辩手B的质询（完整）：\n")
      cat("  │", gsub("\n", "\n  │ ", critique_of_B), "\n")
      cat("  └────────────────────────────────────────────────────────┘\n")

      return(list(
        critique_of_A = critique_of_A,
        critique_of_B = critique_of_B
      ))
    },
    error = function(e) {
      cat("交叉质询失败:", e$message, "\n")
      return(list(
        critique_of_A = paste("质询失败:", e$message),
        critique_of_B = paste("质询失败:", e$message)
      ))
    }
  )
}

# 第三轮：裁判终审
referee_judgment <- function(debate_record, referee_model, api_keys, knowledge_base, is_batch_mode = FALSE, api_metrics = NULL) {
  tryCatch(
    {
      cat("\n")
      cat("╔══════════════════════════════════════════════════════════╗\n")
      cat("║              第三轮：裁判终审                            ║\n")
      cat("╚══════════════════════════════════════════════════════════╝\n")
      cat(sprintf("  ⚖️ 裁判模型: %s\n", referee_model))

      # 优先使用传入的is_batch_mode参数
      # 如果没有传入，通过all_clusters字段检测批量模式
      if (missing(is_batch_mode) || is.null(is_batch_mode)) {
        is_batch_mode <- !is.null(knowledge_base$all_clusters) &&
          length(knowledge_base$all_clusters) > 1
      }

      cat(sprintf("  📌 批量模式: %s\n", is_batch_mode))

      # 构建裁判Prompt
      cat("  ────────────────────────────────────────────────────────\n")
      if (is_batch_mode) {
        # 批量模式：强制要求JSON输出
        cat("  📋 使用批量模式裁判Prompt（强制JSON输出）\n")

        # 【批量模式三重保险】提取约束部分
        prompt_text <- knowledge_base$enhanced_prompt %||% ""
        constraint_list <- c()

        if (grepl("【重要约束", prompt_text)) {
          constraint_match <- regexpr("【重要约束[^】]*】[^【]*", prompt_text)
          if (constraint_match > 0) {
            constraint_text_batch <- regmatches(prompt_text, constraint_match)
            type_lines <- strsplit(constraint_text_batch, "\n")[[1]]
            constraint_list <- type_lines[grepl("^- ", type_lines)]
            constraint_list <- gsub("^- ", "", constraint_list)
            cat("[调试-批量] 提取到", length(constraint_list), "个候选类型\n")
          }
        }

        referee_prompt <- paste0(
          "🚨🚨🚨 强制裁判规则（必须无条件遵守！违反即为失职！） 🚨🚨🚨\n",
          "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n",
          "规则1：❌ 严禁使用'缺少经典marker X → 排除细胞类型Y'的逻辑\n",
          "   - 错误示例：'GCG缺席，排除alpha cell'\n",
          "   - 正确做法：评估现有marker组合是否整体支持该类型\n\n",
          "规则2：❌ Co-expression cell的严格限定（仅用于真正的混合表达）\n",
          "   - 仅当：细胞同时高表达2+个不同类型的核心激素/特征marker时\n",
          "   - 示例：CD3D(T cell) + CD19(B cell) 同时高表达 → co-expression\n",
          "   - ❌ 禁止用于：marker不完美、证据不足、污染、增殖细胞\n",
          "   - ❌ 禁止用于：辩手争议大、不确定的情况\n\n",
          "规则3：✅ 证据不足时的正确处理\n",
          "   - 应判定为：现有marker最接近的细胞类型（标注置信度较低）\n",
          "   - 禁止默认为：co-expression cell（这是逃避责任的做法）\n\n",
          "规则4：✅ 辩手质询的正确使用\n",
          "   - 质询仅用于发现逻辑矛盾和替代解释\n",
          "   - 辩手提到'缺marker'不等于该类型不成立\n",
          "   - 必须综合评估整体证据链，而非被单一质疑点左右\n",
          "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n",
          "【裁判职责】\n",
          "你是最终裁判，需要基于证据做出独立判断，综合所有可用证据做出最准确的判断。\n\n",
          "【裁决原则】\n",
          "1. **优先认可有效证据，而非追求完美marker组合**\n",
          "   - 即使缺少某些'经典marker'，只要有充分的替代证据和通路富集支持，应判定为该类型\n",
          "   - Marker基因会因样本、测序深度、细胞状态差异而变化，这是正常的生物学变异\n",
          "   - 不应因'缺少教科书marker'而轻易否定辩手基于实际数据的判断\n",
          "   - 示例：REG1P、EGF可以作为acinar cell的有效证据，即使缺少PRSS1\n\n",
          "2. **Co-expression cell的严格定义**\n",
          "   - ⚠️ 仅当细胞**同时高表达多个不同细胞类型的核心marker**时，才判定为co-expression\n",
          "   - 正确示例：同时高表达T细胞(CD3D)和B细胞(CD19)marker → co-expression cell\n",
          "   - ❌ 错误用法：marker证据不完美、缺少经典marker → ❌ 不应默认为co-expression\n",
          "   - ❌ 错误用法：不确定是什么类型 → ❌ 不应用co-expression作为'兜底分类'\n",
          "   - Co-expression应该表示'混合身份'（真正同时表达多类marker），而非'不确定'或'证据不足'\n\n",
          "3. **尊重辩手一致意见**\n",
          "   - 当辩手A和B都判断为同一类型时，这通常表明证据较为充分\n",
          "   - 除非有明确的矛盾证据（如marker基因完全不匹配），否则应认可双方一致意见\n",
          "   - 不应轻易推翻双方都认同的判断\n\n",
          "4. **证据链完整性 > 单一经典marker的存在性**\n",
          "   - 综合考虑多方面证据：marker基因表达 + 通路富集结果 + 数据库匹配 + 生物学合理性\n",
          "   - 不要过度依赖某几个'必需marker'的存在性检查\n",
          "   - 关注证据的整体一致性和相互支持，而非纠结于个别基因的缺失\n",
          "   - 数据库支持、通路富集、多个marker的一致性 > 单个经典基因的缺失\n\n",
          # 注入候选词汇表约束（来自 build_candidate_vocabulary 动态构建）
          if (length(constraint_list) > 0) {
            paste0(
              "【候选词汇表 — 由数据库检索 + LLM 推理构建】\n",
              "以下", length(constraint_list), "个候选类型来自 PanglaoDB/CellMarker/scType 数据库检索：\n",
              paste0("  • ", constraint_list, collapse = "\n"), "\n",
              "请在以上候选范围内选择最匹配的细胞类型。\n\n"
            )
          } else {
            ""
          },
          # 🔧 修复：批量模式也需要包含原始证据（基因表达数据）
          "【原始证据（所有簇的完整marker基因数据）】\n",
          prompt_text, "\n\n",
          "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n",
          "【辩手A（", debate_record$round1$model_A, "）的JSON结果】\n",
          debate_record$round1$result_A$full_response, "\n\n",
          "【辩手B（", debate_record$round1$model_B, "）的JSON结果】\n",
          debate_record$round1$result_B$full_response, "\n\n",
          "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n",
          # 🔧 修复：批量模式也需要包含质询结果
          "【辩手B对辩手A的质询】\n",
          debate_record$round2$critique_of_A, "\n\n",
          "【辩手A对辩手B的质询】\n",
          debate_record$round2$critique_of_B, "\n\n",
          "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n",
          "【裁决要求】\n",
          "🚨 必须输出完整JSON对象，包含annotations和reasoning两个字段！\n\n",
          "```json\n",
          "{\n",
          "  \"annotations\": {\n",
          "    \"0\": \"细胞类型\",\n",
          "    \"1\": \"细胞类型\",\n",
          "    \"2\": \"细胞类型\",\n",
          "    ...\n",
          "  },\n",
          "  \"reasoning\": \"【必需字段】你的综合分析和判断依据，必须包含：\\n1. 双方一致的簇有哪些，为什么你认同这个判断？\\n2. 有争议的簇是哪些？辩手A说X，辩手B说Y，你基于什么证据选择了Z？\\n3. 关键marker基因如何支持你的判断？\\n4. 质询环节暴露了哪些问题影响了你的决策？\"\n",
          "}\n",
          "```\n\n",
          "**annotations字段**（必需）：键是簇ID（字符串），值是细胞类型名称，覆盖所有簇\n",
          "**reasoning字段**（必需）：必须详细说明你的判断依据，至少包含：\n",
          "  • 双方意见一致的簇及你认同的理由\n",
          "  • 双方有争议的簇，你如何裁决及依据\n",
          "  • 关键marker基因证据\n",
          "  • 质询环节的重要发现\n\n",
          "⚠️ 不允许只输出annotations！reasoning字段是必需的！\n\n",
          # 【三重保险2-批量】结尾重复约束
          if (length(constraint_list) > 0) {
            paste0(
              "🚨🚨🚨 输出约束（再次提醒！） 🚨🚨🚨\n",
              "annotations中的所有细胞类型值必须从以下列表精确选择：\n",
              paste0("  • ", constraint_list, collapse = "\n"), "\n\n",
              "⚠️ 严禁输出：中文类型名（如'成纤维'、'肿瘤'）\n",
              "⚠️ 严禁输出：变体名称（如'Endothelial cells'应为'Endothelial'）\n",
              "⚠️ 必须从上述列表中精确选择（区分大小写）\n\n"
            )
          } else {
            ""
          },
          "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n",
          "【最后提醒】\n",
          "🚨 必须输出完整的两个字段：annotations + reasoning\n",
          "🚨 reasoning字段不能为空，必须详细解释你的判断依据\n",
          "🚨 如果只输出annotations，将被视为不合格的裁决\n\n",
          "请直接输出JSON对象（不要markdown代码块，直接从{开始）："
        )
      }
      # ═══════════════════════════════════════════════════════════════
      # 【已废弃】单簇模式裁判Prompt - 现在只使用批量模式
      # ═══════════════════════════════════════════════════════════════

      # 调用裁判模型（使用不同的system_prompt）
      cat(sprintf("\n  🔄 调用裁判模型 (%s)...\n", referee_model))

      system_prompt <- if (is_batch_mode) {
        "你是最终裁判。必须输出完整JSON对象，包含annotations和reasoning两个字段。reasoning字段是必需的，需要详细解释：1)双方一致的簇 2)有争议的簇如何裁决 3)关键证据基因。直接从{开始输出，不要markdown代码块。"
      } else {
        "你是最终裁判，需要综合所有辩论信息做出最准确的判断，并解释你的reasoning。"
      }

      # 检测是否为快速模型（_fast后缀）
      use_fast_model <- grepl("_fast$", referee_model)
      base_referee_model <- sub("_fast$", "", referee_model)

      if (use_fast_model) {
        cat(sprintf("ℹ️ 裁判使用快速模型版本: %s\n", referee_model))
      }

      verdict_raw <- switch(base_referee_model,
        "deepseek" = ask_deepseek(referee_prompt,
          system_prompt = system_prompt,
          api_key = api_keys$deepseek,
          use_fast_model = use_fast_model
        ),
        "kimi" = ask_kimi(referee_prompt,
          system_prompt = system_prompt,
          api_key = api_keys$kimi,
          use_fast_model = use_fast_model
        ),
        "glm" = ask_glm(referee_prompt,
          system_prompt = system_prompt,
          api_key = api_keys$glm,
          use_fast_model = use_fast_model
        ),
        "doubao" = ask_douban(referee_prompt,
          system_prompt = system_prompt,
          api_key = api_keys$doubao,
          use_fast_model = use_fast_model
        ),
        "qwen" = ask_qwen(referee_prompt,
          system_prompt = system_prompt,
          api_key = api_keys$qwen,
          use_fast_model = use_fast_model
        ),
        "hunyuan" = ask_hunyuan(referee_prompt,
          system_prompt = system_prompt,
          api_key = api_keys$hunyuan,
          use_fast_model = use_fast_model
        ),
        "ernie" = ask_ernie(referee_prompt,
          system_prompt = system_prompt,
          api_key = api_keys$ernie,
          use_fast_model = use_fast_model
        ),
        "stepfun" = ask_stepfun(referee_prompt,
          system_prompt = system_prompt,
          api_key = api_keys$stepfun,
          use_fast_model = use_fast_model
        ),
        "spark" = ask_spark(referee_prompt,
          system_prompt = system_prompt,
          api_key = api_keys$spark,
          use_fast_model = use_fast_model
        ),
        "minimax" = ask_minimax(referee_prompt,
          system_prompt = system_prompt,
          api_key = api_keys$minimax,
          use_fast_model = use_fast_model
        ),
        list(error = "未知的裁判模型")
      )

      # 【新增】记录裁判的token使用情况
      if (!is.null(api_metrics) && !is.null(verdict_raw$usage)) {
        api_metrics$total_calls <- api_metrics$total_calls + 1
        if (!is.null(verdict_raw$usage$prompt_tokens)) {
          api_metrics$total_tokens_input <- api_metrics$total_tokens_input + verdict_raw$usage$prompt_tokens
        }
        if (!is.null(verdict_raw$usage$completion_tokens)) {
          api_metrics$total_tokens_output <- api_metrics$total_tokens_output + verdict_raw$usage$completion_tokens
        }
        if (!is.null(verdict_raw$usage$total_tokens)) {
          api_metrics$total_tokens <- api_metrics$total_tokens + verdict_raw$usage$total_tokens
        }
        # 记录模型级别的统计
        model_key <- base_referee_model
        if (is.null(api_metrics$model_breakdown[[model_key]])) {
          api_metrics$model_breakdown[[model_key]] <- list(calls = 0, tokens_input = 0, tokens_output = 0, tokens_total = 0)
        }
        api_metrics$model_breakdown[[model_key]]$calls <- api_metrics$model_breakdown[[model_key]]$calls + 1
        api_metrics$model_breakdown[[model_key]]$tokens_input <- api_metrics$model_breakdown[[model_key]]$tokens_input + (verdict_raw$usage$prompt_tokens %||% 0)
        api_metrics$model_breakdown[[model_key]]$tokens_output <- api_metrics$model_breakdown[[model_key]]$tokens_output + (verdict_raw$usage$completion_tokens %||% 0)
        api_metrics$model_breakdown[[model_key]]$tokens_total <- api_metrics$model_breakdown[[model_key]]$tokens_total + (verdict_raw$usage$total_tokens %||% 0)
      }

      # 显示裁判完整回复
      if (!is.null(verdict_raw$success)) {
        cat(sprintf("  ✅ 裁判返回 (%d字符)\n", nchar(verdict_raw$success)))
        if (!is.null(verdict_raw$usage$total_tokens)) {
          cat(sprintf(
            "  💰 Token使用: %d (输入:%d + 输出:%d)\n",
            verdict_raw$usage$total_tokens,
            verdict_raw$usage$prompt_tokens %||% 0,
            verdict_raw$usage$completion_tokens %||% 0
          ))
        }
        cat("  ┌────────────────────────────────────────────────────────┐\n")
        cat("  │ 裁判完整裁决：\n")
        cat("  │", gsub("\n", "\n  │ ", verdict_raw$success), "\n")
        cat("  └────────────────────────────────────────────────────────┘\n")
      } else {
        cat(sprintf("  ❌ 裁判API调用失败: %s\n", verdict_raw$error))
      }

      # 解析裁判结果
      verdict <- parse_referee_verdict(verdict_raw)

      cat("\n  ────────────────────────────────────────────────────────\n")
      cat(sprintf("  ⚖️ 最终裁决: %s\n", verdict$cell_type))
      cat("  ✅ 第三轮裁判终审完成\n")
      cat("  ────────────────────────────────────────────────────────\n\n")

      # 添加完整辩论记录（包含round3裁判信息）
      verdict$debate_history <- debate_record
      verdict$debate_history$round3 <- list(
        annotation = verdict$cell_type,
        reasoning = verdict$reasoning,
        referee = referee_model,
        full_response = verdict$full_response %||% verdict$reasoning
      )
      verdict$referee_model <- referee_model
      verdict$success <- TRUE

      return(verdict)
    },
    error = function(e) {
      cat("裁判终审失败:", e$message, "\n")
      return(list(
        cell_type = "Unknown",
        confidence = 0.1,
        reasoning = paste("裁判终审失败:", e$message),
        success = FALSE
      ))
    }
  )
}

# ═══════════════════════════════════════════════════════════
# 🔧 JSON处理辅助函数（简化逻辑）
# ═══════════════════════════════════════════════════════════

# 从模型响应中提取纯JSON字符串
extract_json_string <- function(response_text) {
  # 移除markdown代码块标记
  text <- gsub("```json\\s*", "", response_text)
  text <- gsub("```\\s*", "", text)

  # 提取第一个{到最后一个}之间的内容
  first_brace <- regexpr("\\{", text)
  if (first_brace < 0) {
    return(NULL)
  }

  text_from_brace <- substring(text, first_brace)
  last_brace <- tail(gregexpr("\\}", text_from_brace)[[1]], 1)
  if (last_brace < 0) {
    return(NULL)
  }

  return(substring(text_from_brace, 1, last_brace))
}

# 解析JSON为簇ID到细胞类型的映射（支持多种格式）
parse_json_to_cluster_map <- function(json_str) {
  parsed <- tryCatch(
    jsonlite::fromJSON(json_str, simplifyVector = FALSE),
    error = function(e) NULL
  )

  if (is.null(parsed)) {
    return(NULL)
  }

  # 格式1（新）: {"annotations": {"0": "T", ...}, "reasoning": "..."}
  if (!is.null(parsed$annotations)) {
    cat("  [解析] 使用annotations格式\n")
    return(parsed$annotations)
  }

  # 格式2: {"cluster_annotations": [{cluster_id: "0", cell_type: "T"}, ...]}
  if (!is.null(parsed$cluster_annotations)) {
    cluster_map <- list()
    for (item in parsed$cluster_annotations) {
      if (!is.null(item$cluster_id) && !is.null(item$cell_type)) {
        cluster_map[[as.character(item$cluster_id)]] <- item$cell_type
      }
    }
    return(cluster_map)
  }

  # 格式3: {"0": "T", "1": "B", ...}（简单格式，排除reasoning字段）
  if (is.list(parsed) && !is.null(names(parsed))) {
    # 排除非簇ID的字段（如reasoning）
    cluster_map <- parsed[!names(parsed) %in% c("reasoning", "confidence", "key_genes")]
    if (length(cluster_map) > 0) {
      return(cluster_map)
    }
  }

  return(NULL)
}

# 将簇映射转换为细胞级别predictions
convert_clusters_to_predictions <- function(cluster_map, seurat_obj) {
  barcodes <- colnames(seurat_obj)
  clusters <- as.character(seurat_obj$seurat_clusters)

  predictions <- sapply(clusters, function(cid) {
    cluster_map[[cid]] %||% "Unknown"
  })

  names(predictions) <- barcodes
  return(predictions)
}

# ═══════════════════════════════════════════════════════════
# 🎯 单模型注释函数（用于阶段1基准测试）
# ═══════════════════════════════════════════════════════════
call_single_model_annotation <- function(knowledge_base, api_keys, model_name, is_batch_mode = TRUE) {
  tryCatch(
    {
      cat(sprintf("  🤖 调用单模型：%s\n", model_name))

      # 构建批量注释的Prompt
      # 🔧 修复：同时检查batch_super_prompt和enhanced_prompt（兼容不同来源的知识图谱）
      if (is_batch_mode && !is.null(knowledge_base$batch_super_prompt)) {
        prompt <- knowledge_base$batch_super_prompt
        cat("  📝 使用批量约束Prompt (batch_super_prompt)\n")
      } else if (is_batch_mode && !is.null(knowledge_base$enhanced_prompt)) {
        prompt <- knowledge_base$enhanced_prompt
        cat("  📝 使用批量约束Prompt (enhanced_prompt)\n")
      } else {
        prompt <- paste0(
          "请基于以下知识图谱，为所有簇的细胞进行类型注释。\n\n",
          "知识图谱信息：\n",
          jsonlite::toJSON(knowledge_base, auto_unbox = TRUE, pretty = TRUE),
          "\n\n请以JSON格式返回每个簇的注释结果。"
        )
      }

      # 根据模型名称调用对应的API
      # 🎯 批量注释任务：强制使用大max_tokens（触发思考模式）
      # 检测是否为快速模型（_fast后缀）
      use_fast_model <- grepl("_fast$", model_name)
      base_model <- sub("_fast$", "", model_name)

      if (use_fast_model) {
        cat(sprintf("ℹ️ 使用快速模型版本: %s\n", model_name))
      }

      response <- switch(base_model,
        "deepseek" = ask_deepseek(prompt, api_key = api_keys$deepseek, max_tokens = if (is_batch_mode) 16000 else NULL, use_fast_model = use_fast_model),
        "kimi" = ask_kimi(prompt, api_key = api_keys$kimi, use_fast_model = use_fast_model),
        "glm" = ask_glm(prompt, api_key = api_keys$glm, use_fast_model = use_fast_model),
        "doubao" = ask_doubao(prompt, api_key = api_keys$doubao, use_fast_model = use_fast_model),
        "qwen" = ask_qwen(prompt, api_key = api_keys$qwen, use_fast_model = use_fast_model),
        "hunyuan" = ask_hunyuan(prompt, api_key = api_keys$hunyuan, use_fast_model = use_fast_model),
        "ernie" = ask_ernie(prompt, api_key = api_keys$ernie, use_fast_model = use_fast_model),
        "stepfun" = ask_stepfun(prompt, api_key = api_keys$stepfun, use_fast_model = use_fast_model),
        "spark" = ask_spark(prompt, api_key = api_keys$spark, use_fast_model = use_fast_model),
        "minimax" = ask_minimax(prompt, api_key = api_keys$minimax, use_fast_model = use_fast_model),
        list(error = paste("未知模型：", model_name))
      )

      if (!is.null(response$error)) {
        cat(sprintf("  ❌ 模型调用失败：%s\n", response$error))
        return(list(
          cell_type = "Unknown",
          confidence = 0,
          error = response$error
        ))
      }

      # 解析响应
      result_text <- response$success
      cat("  ✅ 模型响应成功\n")

      # 🎯 批量模式：返回特殊标记，让策略2处理JSON解析
      if (is_batch_mode) {
        cat("  📦 批量模式：保存JSON响应供后续解析\n")
        return(list(
          cell_type = "Batch_JSON_Mode",
          reasoning = "批量模式JSON结果",
          full_response = result_text, # 保存完整响应
          model_used = model_name
        ))
      }

      # 单簇模式：正常解析
      return(list(
        cell_type = "Unknown",
        confidence = 0.1,
        reasoning = result_text,
        model_used = model_name
      ))
    },
    error = function(e) {
      cat(sprintf("  ❌ 单模型注释失败：%s\n", e$message))
      return(list(
        cell_type = "Unknown",
        confidence = 0,
        error = e$message
      ))
    }
  )
}

# AURA 2.0 主引擎：辩论-裁判引擎
DebateReferee_Engine <- function(knowledge_base, seurat_obj = NULL, api_keys = list(),
                                 debater_A = "deepseek", debater_B = "kimi",
                                 referee = "glm", is_batch_mode = FALSE, api_metrics = NULL) {
  tryCatch(
    {
      cat("\n")
      cat("╔══════════════════════════════════════════════════════════════════╗\n")
      cat("║        🧬 AURA 2.0 多模态辩论引擎 - 细胞类型注释                 ║\n")
      cat("╠══════════════════════════════════════════════════════════════════╣\n")
      cat(sprintf("║  👤 辩手A: %-20s                                ║\n", debater_A))
      cat(sprintf("║  👤 辩手B: %-20s                                ║\n", debater_B))
      cat(sprintf("║  ⚖️ 裁判:  %-20s                                ║\n", referee))
      cat(sprintf("║  📌 模式:  %-20s                                ║\n", ifelse(is_batch_mode, "批量模式", "单簇模式")))
      cat("╚══════════════════════════════════════════════════════════════════╝\n")

      # 检查API密钥
      if (is.null(api_keys) || length(api_keys) == 0) {
        api_keys <- list(
          deepseek = Sys.getenv("DEEPSEEK_API_KEY"),
          kimi = Sys.getenv("KIMI_API_KEY"),
          glm = Sys.getenv("GLM_API_KEY"),
          doubao = Sys.getenv("DOUBAO_API_KEY"),
          qwen = Sys.getenv("QWEN_API_KEY"),
          hunyuan = Sys.getenv("HUNYUAN_API_KEY"),
          ernie = Sys.getenv("ERNIE_API_KEY"),
          stepfun = Sys.getenv("STEPFUN_API_KEY"),
          spark = Sys.getenv("SPARK_API_KEY"),
          minimax = Sys.getenv("MINIMAX_API_KEY")
        )
      }

      # 获取超级Prompt
      if (is.null(knowledge_base$enhanced_prompt)) {
        print_status("warning", "知识图谱中没有enhanced_prompt，尝试构建...")
        markers <- if (!is.null(knowledge_base$input_markers)) {
          knowledge_base$input_markers
        } else if (!is.null(knowledge_base$marker_genes)) {
          rownames(knowledge_base$marker_genes)[1:min(50, nrow(knowledge_base$marker_genes))]
        } else {
          return(list(success = FALSE, error = "无法获取标记基因"))
        }
        super_prompt <- build_super_prompt(knowledge_base, markers)
      } else {
        super_prompt <- knowledge_base$enhanced_prompt
      }

      # 第一轮：初审辩论（详细输出在parallel_debate函数内部）
      debate_round1 <- parallel_debate(
        debater_A = debater_A,
        debater_B = debater_B,
        prompt = super_prompt,
        api_keys = api_keys,
        is_batch_mode = is_batch_mode,
        api_metrics = api_metrics
      )

      # 第二轮：交叉质询（详细输出在cross_examination函数内部）
      debate_round2 <- cross_examination(
        conclusion_A = debate_round1$result_A,
        conclusion_B = debate_round1$result_B,
        original_evidence = super_prompt,
        debater_A = debater_A,
        debater_B = debater_B,
        api_keys = api_keys,
        is_batch_mode = is_batch_mode,
        cluster_id = knowledge_base$cluster_id, # 传递当前簇ID
        api_metrics = api_metrics
      )

      # 第三轮：裁判终审（详细输出在referee_judgment函数内部）
      final_verdict <- referee_judgment(
        debate_record = list(
          round1 = debate_round1,
          round2 = debate_round2
        ),
        referee_model = referee,
        api_keys = api_keys,
        knowledge_base = knowledge_base,
        is_batch_mode = is_batch_mode, # 传递批量模式参数
        api_metrics = api_metrics
      )

      # 辩论完成总结
      cat("╔══════════════════════════════════════════════════════════════════╗\n")
      cat("║                    🎯 辩论引擎执行完毕                           ║\n")
      cat("╠══════════════════════════════════════════════════════════════════╣\n")
      cat(sprintf("║  📋 最终裁决: %-20s                           ║\n", final_verdict$cell_type))
      cat("╚══════════════════════════════════════════════════════════════════╝\n\n")

      return(final_verdict)
    },
    error = function(e) {
      cat("AURA 2.0 辩论-裁判引擎错误:", e$message, "\n")
      return(list(
        success = FALSE,
        error = paste("辩论引擎错误:", e$message),
        cell_type = "Unknown",
        confidence = 0.1
      ))
    }
  )
}

