# 任务类型分类函数
classify_task_type <- function(knowledge_base, markers) {
  tryCatch(
    {
      # 获取CellMarker匹配基因数
      cellmarker_matched <- if (!is.null(knowledge_base$analysis_summary$cellmarker_summary$matched_markers)) {
        knowledge_base$analysis_summary$cellmarker_summary$matched_markers
      } else {
        0
      }

      # 获取文献数量
      literature_count <- if (!is.null(knowledge_base$analysis_summary$literature_summary$total_articles)) {
        knowledge_base$analysis_summary$literature_summary$total_articles
      } else {
        0
      }

      # 分类逻辑（基于匹配基因数）
      if (cellmarker_matched >= 5 && literature_count > 50) {
        task_type <- "routine_identification" # 常规细胞类型鉴定
        cat("任务类型：常规细胞类型鉴定\n")
      } else if (cellmarker_matched < 2 || literature_count < 10) {
        task_type <- "rare_subtype_exploration" # 罕见/新亚型探索
        cat("任务类型：罕见/新亚型探索\n")
      } else {
        task_type <- "ambiguous_state" # 状态模糊/过渡态
        cat("任务类型：状态模糊/过渡态\n")
      }

      return(task_type)
    },
    error = function(e) {
      cat("任务分类失败:", e$message, ", 使用默认类型\n")
      return("routine_identification")
    }
  )
}

# 任务路由器
TaskRouter <- function(knowledge_base, markers) {
  tryCatch(
    {
      cat("任务路由器启动...\n")

      # 分析任务类型
      task_type <- classify_task_type(knowledge_base, markers)

      # 根据任务类型选择处理策略
      strategy <- switch(task_type,
        "routine_identification" = list(
          engine = "debate_referee",
          debaters = c("deepseek", "kimi"),
          referee = "glm",
          creativity_level = "standard",
          description = "常规鉴定：使用标准辩论流程"
        ),
        "rare_subtype_exploration" = list(
          engine = "debate_referee",
          debaters = c("kimi", "glm"), # 更有创造力的组合
          referee = "deepseek",
          creativity_level = "high",
          description = "罕见亚型：使用高创造力模型组合"
        ),
        "ambiguous_state" = list(
          engine = "debate_referee",
          debaters = c("deepseek", "glm"),
          referee = "kimi",
          creativity_level = "cautious",
          description = "模糊状态：使用谨慎模式"
        ),
        # 默认策略
        list(
          engine = "debate_referee",
          debaters = c("deepseek", "kimi"),
          referee = "glm",
          creativity_level = "standard",
          description = "默认策略"
        )
      )

      cat("任务路由完成：", strategy$description, "\n")
      cat("- 引擎:", strategy$engine, "\n")
      cat("- 辩手:", paste(strategy$debaters, collapse = ", "), "\n")
      cat("- 裁判:", strategy$referee, "\n")

      return(strategy)
    },
    error = function(e) {
      cat("任务路由失败:", e$message, "\n")
      # 返回默认策略
      return(list(
        engine = "debate_referee",
        debaters = c("deepseek", "kimi"),
        referee = "glm",
        creativity_level = "standard",
        description = "默认策略（路由失败）"
      ))
    }
  )
}

# 规则引擎
RulesEngine <- list()

# 前置规则：Prompt注入
RulesEngine$apply_pre_rules <- function(markers, prompt) {
  tryCatch(
    {
      cat("应用前置规则引擎...\n")
      warnings <- c()

      # 规则1：T+B细胞冲突检测
      if ("CD3D" %in% markers && "CD19" %in% markers) {
        warnings <- c(
          warnings,
          "⚠️ [规则引擎警告] T细胞标记(CD3D)和B细胞标记(CD19)同时高表达，请谨慎判断是否存在双细胞(doublet)或技术误差。"
        )
        cat("- 检测到T+B细胞冲突\n")
      }

      # 规则2：干细胞+分化细胞冲突
      if ("CD34" %in% markers && "CD14" %in% markers) {
        warnings <- c(
          warnings,
          "⚠️ [规则引擎警告] 干细胞标记(CD34)和单核细胞标记(CD14)共存，可能是过渡态细胞或分化中间态。"
        )
        cat("- 检测到干细胞+分化细胞冲突\n")
      }

      # 规则3：NK+T细胞混合特征
      if ("CD3D" %in% markers && "NCAM1" %in% markers) {
        warnings <- c(
          warnings,
          "⚠️ [规则引擎警告] 检测到T细胞(CD3D)和NK细胞(NCAM1/CD56)混合标记，可能是NKT细胞。"
        )
        cat("- 检测到NK+T细胞混合特征\n")
      }

      # 规则4：内皮细胞+上皮细胞标记冲突
      if ("PECAM1" %in% markers && "EPCAM" %in% markers) {
        warnings <- c(
          warnings,
          "⚠️ [规则引擎警告] 内皮细胞(PECAM1)和上皮细胞(EPCAM)标记同时存在，需要仔细鉴别。"
        )
        cat("- 检测到内皮+上皮冲突\n")
      }

      # 规则5：红细胞污染检测
      erythrocyte_markers <- intersect(markers, BiologyRules$Erythrocyte_genes)
      if (length(erythrocyte_markers) > 0) {
        warnings <- c(
          warnings,
          paste0(
            "⚠️ [规则引擎警告] 检测到血红蛋白基因(",
            paste(erythrocyte_markers, collapse = ", "),
            ")，可能存在红细胞污染或正在红系分化。"
          )
        )
        cat("- 检测到红细胞基因\n")
      }

      # 规则6：T细胞+单核细胞混合
      if (("CD3D" %in% markers || "CD3E" %in% markers) &&
        ("CD14" %in% markers || "CD68" %in% markers)) {
        warnings <- c(
          warnings,
          "⚠️ [规则引擎警告] T细胞标记和单核/巨噬细胞标记共存，可能是doublet或特殊细胞亚群。"
        )
        cat("- 检测到T+单核细胞混合\n")
      }

      # 规则7：B细胞+单核细胞混合
      if (("CD19" %in% markers || "MS4A1" %in% markers) &&
        ("CD14" %in% markers || "CD68" %in% markers)) {
        warnings <- c(
          warnings,
          "⚠️ [规则引擎警告] B细胞标记和单核/巨噬细胞标记共存，可能是doublet。"
        )
        cat("- 检测到B+单核细胞混合\n")
      }

      # 将警告注入Prompt
      if (length(warnings) > 0) {
        prompt_with_warnings <- paste0(
          prompt, "\n\n",
          "【生物学规则引擎警告】\n",
          paste(warnings, collapse = "\n"),
          "\n\n请在注释时特别注意以上警告，这些可能影响最终判断。"
        )
        cat("前置规则完成，注入", length(warnings), "个警告\n")
      } else {
        prompt_with_warnings <- prompt
        cat("前置规则完成，无警告\n")
      }

      return(list(
        prompt = prompt_with_warnings,
        warnings = warnings,
        warnings_count = length(warnings)
      ))
    },
    error = function(e) {
      cat("前置规则引擎失败:", e$message, "\n")
      return(list(
        prompt = prompt,
        warnings = c(),
        warnings_count = 0
      ))
    }
  )
}

# 后置规则：结论审查
RulesEngine$apply_post_rules <- function(cell_type, markers) {
  tryCatch(
    {
      cat("应用后置规则引擎...\n")

      flags <- list(
        needs_review = FALSE,
        warnings = c()
      )

      # 规则1：T细胞但有B细胞标记
      if (grepl("T.?cell", cell_type, ignore.case = TRUE)) {
        b_markers <- intersect(markers, BiologyRules$B_cell_markers)
        if (length(b_markers) > 0) {
          flags$needs_review <- TRUE
          flags$warnings <- c(
            flags$warnings,
            paste0("注释为T细胞，但检测到B细胞标记(", paste(b_markers, collapse = ", "), ")，建议人工复核。")
          )
          cat("- T细胞+B标记冲突，需要复核\n")
        }
      }

      # 规则2：B细胞但有T细胞标记
      if (grepl("B.?cell", cell_type, ignore.case = TRUE)) {
        t_markers <- intersect(markers, BiologyRules$T_cell_markers)
        if (length(t_markers) > 0) {
          flags$needs_review <- TRUE
          flags$warnings <- c(
            flags$warnings,
            paste0("注释为B细胞，但检测到T细胞标记(", paste(t_markers, collapse = ", "), ")，建议人工复核。")
          )
          cat("- B细胞+T标记冲突，需要复核\n")
        }
      }

      # 规则3：单核/巨噬细胞但有淋巴细胞标记
      if (grepl("Monocyte|Macrophage", cell_type, ignore.case = TRUE)) {
        lymphoid_markers <- c(
          intersect(markers, BiologyRules$T_cell_markers),
          intersect(markers, BiologyRules$B_cell_markers)
        )
        if (length(lymphoid_markers) > 0) {
          flags$needs_review <- TRUE
          flags$warnings <- c(
            flags$warnings,
            paste0("注释为髓系细胞，但检测到淋巴细胞标记(", paste(lymphoid_markers, collapse = ", "), ")，可能是doublet。")
          )
          cat("- 髓系+淋巴标记冲突，需要复核\n")
        }
      }

      # 规则4：标记基因数量检查
      marker_count <- length(markers)
      if (marker_count < 5) {
        flags$warnings <- c(
          flags$warnings,
          paste0("标记基因数量较少(", marker_count, "个)，建议谨慎对待。")
        )
        cat("- 标记基因数量较少\n")
      }

      # 规则5：红细胞基因检查
      erythro_genes <- intersect(markers, BiologyRules$Erythrocyte_genes)
      if (length(erythro_genes) > 0 && !grepl("Erythro|Red.*blood", cell_type, ignore.case = TRUE)) {
        flags$warnings <- c(
          flags$warnings,
          paste0(
            "检测到血红蛋白基因(", paste(erythro_genes, collapse = ", "),
            ")但未注释为红系细胞，可能存在污染。"
          )
        )
        cat("- 红细胞基因但非红系注释，需要复核\n")
      }

      cat(
        "后置规则完成：",
        if (flags$needs_review) "需要复核" else "通过审查", "\n"
      )

      return(list(
        needs_review = flags$needs_review,
        warnings = flags$warnings
      ))
    },
    error = function(e) {
      cat("后置规则引擎失败:", e$message, "\n")
      return(list(
        needs_review = FALSE,
        warnings = c()
      ))
    }
  )
}

