# ============================================================
# AURA 2.0 - 动态权重与自我进化系统 (Dynamic Weights & Self-Evolution)
# ============================================================

# 注：此部分功能为AURA 2.0的高级功能，当前作为可选模块
# 暂时保留代码，未来可通过"启用智能路由"开关激活

# AURA 2.0 高级引擎（集成所有模块，暂未使用）
AURA2_Advanced_Engine <- function(knowledge_base, seurat_obj, api_keys,
                                  mode = "auto", # auto, debate, consensus
                                  debater_A = NULL, debater_B = NULL, referee = NULL,
                                  enable_rules = FALSE, # 规则引擎已禁用
                                  enable_task_router = TRUE,
                                  enable_dynamic_weights = FALSE) {
  tryCatch(
    {
      cat("\n")
      cat("╔═══════════════════════════════════════════════════════════╗\n")
      cat("║         AURA 2.0 高级引擎启动 (可选功能)                   ║\n")
      cat("╚═══════════════════════════════════════════════════════════╝\n")
      cat("模式:", mode, " | 规则引擎:", if (enable_rules) "启用" else "禁用", "\n")
      cat(
        "智能路由:", if (enable_task_router) "启用" else "禁用",
        " | 动态权重:", if (enable_dynamic_weights) "启用" else "禁用", "\n\n"
      )

      # 获取标记基因
      markers <- if (!is.null(knowledge_base$input_markers)) {
        knowledge_base$input_markers
      } else if (!is.null(knowledge_base$marker_genes)) {
        rownames(knowledge_base$marker_genes)
      } else {
        return(list(success = FALSE, error = "无法获取标记基因"))
      }

      cat("标记基因数量:", length(markers), "\n")

      # 确定任务类型（用于动态权重）
      task_type <- classify_task_type(knowledge_base, markers)

      # 步骤1：任务路由 + 动态权重选择
      selected_strategy <- NULL
      if (enable_task_router && mode == "auto") {
        cat("\n[步骤1/4] 任务路由分析...\n")
        selected_strategy <- TaskRouter(knowledge_base, markers)
        actual_mode <- selected_strategy$engine

        # 如果启用动态权重，使用历史表现选择模型
        if (enable_dynamic_weights) {
          cat("使用动态权重选择模型...\n")
          debater_selection <- DynamicWeightAdjuster$select_debaters(task_type)
          referee_selection <- DynamicWeightAdjuster$select_referee(
            task_type,
            exclude_models = c(debater_selection$debater_A, debater_selection$debater_B)
          )
          debater_A <- debater_selection$debater_A
          debater_B <- debater_selection$debater_B
          referee <- referee_selection$referee
        } else {
          # 使用路由器推荐的模型
          debater_A <- selected_strategy$debaters[1]
          debater_B <- selected_strategy$debaters[2]
          referee <- selected_strategy$referee
        }
      } else if (mode == "debate") {
        actual_mode <- "debate"
        if (enable_dynamic_weights) {
          cat("\n[步骤1/4] 使用动态权重选择模型...\n")
          debater_selection <- DynamicWeightAdjuster$select_debaters(task_type)
          referee_selection <- DynamicWeightAdjuster$select_referee(
            task_type,
            exclude_models = c(debater_selection$debater_A, debater_selection$debater_B)
          )
          debater_A <- debater_selection$debater_A
          debater_B <- debater_selection$debater_B
          referee <- referee_selection$referee
        } else {
          debater_A <- debater_A %||% "deepseek"
          debater_B <- debater_B %||% "kimi"
          referee <- referee %||% "glm"
        }
      } else {
        actual_mode <- "consensus"
      }

      # 步骤2：前置规则引擎（如果启用）
      pre_rules_result <- NULL
      if (enable_rules && actual_mode == "debate") {
        cat("\n[步骤2/4] 应用前置规则引擎...\n")
        pre_rules_result <- RulesEngine$apply_pre_rules(markers, knowledge_base$enhanced_prompt)
        knowledge_base$enhanced_prompt <- pre_rules_result$prompt
        knowledge_base$pre_rules_warnings <- pre_rules_result$warnings
      }

      # 步骤3：智能推理引擎
      cat("\n[步骤3/4] 启动", if (actual_mode == "debate") "辩论-裁判" else "共识决策", "引擎...\n")

      if (actual_mode == "debate") {
        # AURA 3.0：辩论-裁判引擎
        result <- DebateReferee_Engine(
          knowledge_base = knowledge_base,
          seurat_obj = seurat_obj,
          api_keys = api_keys,
          debater_A = debater_A,
          debater_B = debater_B,
          referee = referee
        )
        result$aura_mode <- "debate"
        result$pre_rules <- pre_rules_result
      } else {
        # AURA 2.0：多LLM共识决策（向后兼容）
        result <- MultiLLM_Consensus_Engine(
          knowledge_base = knowledge_base,
          seurat_obj = seurat_obj,
          api_keys = api_keys
        )
        result$aura_mode <- "consensus"
      }

      # 步骤4：后置规则引擎（如果启用）
      post_rules_result <- NULL
      if (enable_rules && !is.null(result$cell_type)) {
        cat("\n[步骤4/4] 应用后置规则引擎...\n")
        post_rules_result <- RulesEngine$apply_post_rules(
          cell_type = result$cell_type %||% result$final_annotation,
          markers = markers
        )

        # 更新结果
        result$post_rules <- post_rules_result
        result$needs_review <- post_rules_result$needs_review
      }

      cat("\n")
      cat("╔═══════════════════════════════════════════════════════════╗\n")
      cat("║              AURA 2.0 分析完成                             ║\n")
      cat("╚═══════════════════════════════════════════════════════════╝\n")
      cat("最终注释:", result$cell_type %||% result$final_annotation, "\n")
      if (!is.null(result$needs_review) && result$needs_review) {
        cat("⚠️ 需要人工复核\n")
      }
      cat("\n")

      return(result)
    },
    error = function(e) {
      cat("AURA 2.0高级引擎错误:", e$message, "\n")
      return(list(
        success = FALSE,
        error = paste("AURA 2.0引擎错误:", e$message),
        cell_type = "Unknown"
      ))
    }
  )
}

