# AURA 2.0 - 性能日志系统 (Performance Logging System)
# ============================================================

# 性能日志记录器
PerformanceLogger <- list()

# 初始化日志文件
PerformanceLogger$init <- function(log_file = "model_performance.csv") {
  tryCatch(
    {
      if (!file.exists(log_file)) {
        # 创建新的日志文件
        header <- data.frame(
          timestamp = character(),
          cluster_id = character(),
          task_type = character(),
          model_name = character(),
          role = character(), # debater_A, debater_B, referee
          prediction = character(),
          confidence = numeric(),
          is_correct = logical(),
          user_feedback = character(),
          stringsAsFactors = FALSE
        )
        write.csv(header, log_file, row.names = FALSE)
        cat("性能日志文件初始化完成:", log_file, "\n")
      } else {
        cat("性能日志文件已存在:", log_file, "\n")
      }
    },
    error = function(e) {
      cat("性能日志初始化失败:", e$message, "\n")
    }
  )
}

# 记录单次表现
PerformanceLogger$log_performance <- function(
  cluster_id,
  task_type,
  model_name,
  role,
  prediction,
  confidence,
  is_correct = NA,
  user_feedback = "",
  log_file = "model_performance.csv"
) {
  tryCatch(
    {
      new_entry <- data.frame(
        timestamp = as.character(Sys.time()),
        cluster_id = as.character(cluster_id),
        task_type = task_type,
        model_name = model_name,
        role = role,
        prediction = prediction,
        confidence = confidence,
        is_correct = is_correct,
        user_feedback = user_feedback,
        stringsAsFactors = FALSE
      )

      # 追加到日志文件
      if (file.exists(log_file)) {
        existing <- read.csv(log_file, stringsAsFactors = FALSE)
        updated <- rbind(existing, new_entry)
      } else {
        PerformanceLogger$init(log_file)
        updated <- new_entry
      }

      write.csv(updated, log_file, row.names = FALSE)

      cat("性能日志已记录：", model_name, "-", role, "for cluster", cluster_id, "\n")
    },
    error = function(e) {
      cat("性能日志记录失败:", e$message, "\n")
    }
  )
}

# 获取模型历史表现
PerformanceLogger$get_performance <- function(
  model_name,
  task_type = NULL,
  role = NULL,
  log_file = "model_performance.csv"
) {
  tryCatch(
    {
      if (!file.exists(log_file)) {
        return(list(
          model = model_name,
          accuracy = 0.5,
          total_tasks = 0,
          tasks_with_feedback = 0,
          avg_confidence = 0.5,
          recent_trend = "unknown"
        ))
      }

      log <- read.csv(log_file, stringsAsFactors = FALSE)

      # 筛选
      filtered <- log[log$model_name == model_name, ]

      if (!is.null(task_type)) {
        filtered <- filtered[filtered$task_type == task_type, ]
      }

      if (!is.null(role)) {
        filtered <- filtered[filtered$role == role, ]
      }

      if (nrow(filtered) == 0) {
        return(list(
          model = model_name,
          accuracy = 0.5,
          total_tasks = 0,
          tasks_with_feedback = 0,
          avg_confidence = 0.5,
          recent_trend = "unknown"
        ))
      }

      # 只统计有反馈的记录
      with_feedback <- filtered[!is.na(filtered$is_correct), ]

      accuracy <- if (nrow(with_feedback) > 0) {
        sum(with_feedback$is_correct) / nrow(with_feedback)
      } else {
        0.5 # 默认值
      }

      avg_confidence <- mean(filtered$confidence, na.rm = TRUE)

      # 计算最近趋势（最近10次 vs 之前的记录）
      recent_trend <- "stable"
      if (nrow(with_feedback) > 10) {
        recent_10 <- tail(with_feedback, 10)
        earlier <- head(with_feedback, -10)

        recent_acc <- sum(recent_10$is_correct) / nrow(recent_10)
        earlier_acc <- sum(earlier$is_correct) / nrow(earlier)

        if (recent_acc > earlier_acc + 0.1) {
          recent_trend <- "improving"
        } else if (recent_acc < earlier_acc - 0.1) {
          recent_trend <- "declining"
        }
      }

      return(list(
        model = model_name,
        accuracy = accuracy,
        total_tasks = nrow(filtered),
        tasks_with_feedback = nrow(with_feedback),
        avg_confidence = avg_confidence,
        recent_trend = recent_trend
      ))
    },
    error = function(e) {
      cat("获取模型表现失败:", e$message, "\n")
      return(list(
        model = model_name,
        accuracy = 0.5,
        total_tasks = 0,
        tasks_with_feedback = 0,
        avg_confidence = 0.5,
        recent_trend = "unknown"
      ))
    }
  )
}

# 动态权重调整器
DynamicWeightAdjuster <- list()

# 选择最优辩手组合
DynamicWeightAdjuster$select_debaters <- function(
  task_type,
  available_models = c("deepseek", "kimi", "glm", "doubao", "qwen", "hunyuan", "ernie", "stepfun", "spark", "minimax"),
  log_file = "model_performance.csv"
) {
  tryCatch(
    {
      cat("动态选择辩手...\n")

      # 获取所有模型的历史表现
      performances <- list()
      for (model in available_models) {
        perf <- PerformanceLogger$get_performance(
          model_name = model,
          task_type = task_type,
          role = "debater",
          log_file = log_file
        )
        performances[[model]] <- perf
      }

      # 计算综合得分
      scores <- sapply(performances, function(p) {
        # 综合得分 = 准确率 * 0.7 + 任务经验 * 0.3
        accuracy_score <- p$accuracy * 0.7
        experience_score <- min(p$total_tasks / 50, 1) * 0.3 # 最多50次任务算满分

        # 如果是improving趋势，额外加分
        trend_bonus <- if (p$recent_trend == "improving") 0.05 else 0

        total_score <- accuracy_score + experience_score + trend_bonus
        return(total_score)
      })

      # 选择得分最高的两个作为辩手
      sorted_models <- names(sort(scores, decreasing = TRUE))

      selected_debaters <- list(
        debater_A = sorted_models[1],
        debater_B = sorted_models[2],
        scores = scores[sorted_models[1:2]],
        all_scores = scores
      )

      cat("动态选择辩手：", selected_debaters$debater_A, "vs", selected_debaters$debater_B, "\n")
      cat("- 辩手A得分:", round(selected_debaters$scores[1], 3), "\n")
      cat("- 辩手B得分:", round(selected_debaters$scores[2], 3), "\n")

      return(selected_debaters)
    },
    error = function(e) {
      cat("动态选择辩手失败:", e$message, "\n")
      # 返回默认值
      return(list(
        debater_A = "deepseek",
        debater_B = "kimi",
        scores = c(deepseek = 0.5, kimi = 0.5),
        all_scores = c(deepseek = 0.5, kimi = 0.5, glm = 0.5, doubao = 0.5, qwen = 0.5, hunyuan = 0.5, ernie = 0.5, stepfun = 0.5, spark = 0.5, minimax = 0.5)
      ))
    }
  )
}

# 选择最优裁判
DynamicWeightAdjuster$select_referee <- function(
  task_type,
  exclude_models = c(), # 排除已经作为辩手的模型
  available_models = c("deepseek", "kimi", "glm", "doubao", "qwen", "hunyuan", "ernie", "stepfun", "spark", "minimax"),
  log_file = "model_performance.csv"
) {
  tryCatch(
    {
      cat("动态选择裁判...\n")

      # 排除辩手
      candidate_models <- setdiff(available_models, exclude_models)

      if (length(candidate_models) == 0) {
        cat("警告：所有模型都被排除，使用默认裁判\n")
        return(list(referee = "glm", score = 0.5, all_scores = c(glm = 0.5)))
      }

      # 获取候选模型的裁判表现
      performances <- list()
      for (model in candidate_models) {
        perf <- PerformanceLogger$get_performance(
          model_name = model,
          task_type = task_type,
          role = "referee",
          log_file = log_file
        )
        performances[[model]] <- perf
      }

      # 裁判的综合得分更重视准确率
      scores <- sapply(performances, function(p) {
        accuracy_score <- p$accuracy * 0.8
        confidence_score <- p$avg_confidence * 0.1
        experience_score <- min(p$total_tasks / 30, 1) * 0.1

        total_score <- accuracy_score + confidence_score + experience_score
        return(total_score)
      })

      # 选择得分最高的作为裁判
      best_referee <- names(which.max(scores))

      cat("动态选择裁判：", best_referee, "(得分:", round(scores[best_referee], 3), ")\n")

      return(list(
        referee = best_referee,
        score = scores[best_referee],
        all_scores = scores
      ))
    },
    error = function(e) {
      cat("动态选择裁判失败:", e$message, "\n")
      return(list(
        referee = "glm",
        score = 0.5,
        all_scores = c(glm = 0.5)
      ))
    }
  )
}

# 【已废弃】调整最终置信度 - 置信度系统已移除
# DynamicWeightAdjuster$adjust_confidence <- function(...) { ... }

# 获取所有模型的综合表现报告
DynamicWeightAdjuster$get_all_models_report <- function(log_file = "model_performance.csv") {
  tryCatch(
    {
      if (!file.exists(log_file)) {
        return(data.frame(
          model = character(),
          total_tasks = numeric(),
          accuracy = numeric(),
          trend = character(),
          stringsAsFactors = FALSE
        ))
      }

      models <- c("deepseek", "kimi", "glm", "doubao", "qwen", "hunyuan", "ernie", "stepfun", "spark", "minimax")
      report_data <- data.frame(
        model = character(),
        total_tasks = numeric(),
        feedback_count = numeric(),
        accuracy = numeric(),
        trend = character(),
        stringsAsFactors = FALSE
      )

      for (model in models) {
        perf <- PerformanceLogger$get_performance(model)
        report_data <- rbind(report_data, data.frame(
          model = model,
          total_tasks = perf$total_tasks,
          feedback_count = perf$tasks_with_feedback,
          accuracy = round(perf$accuracy, 3),
          trend = perf$recent_trend,
          stringsAsFactors = FALSE
        ))
      }

      # 按准确率排序
      report_data <- report_data[order(report_data$accuracy, decreasing = TRUE), ]

      return(report_data)
    },
    error = function(e) {
      cat("获取模型报告失败:", e$message, "\n")
      return(data.frame())
    }
  )
}

