# ============================================================
# 模块4：下游分析顾问 (Downstream Analysis Advisor)
# ============================================================

# 下游分析推荐引擎
DownstreamAnalysisAdvisor <- function(all_annotations, seurat_obj = NULL, use_llm = TRUE, api_keys = list()) {
  tryCatch(
    {
      cat("╔═══════════════════════════════════════════════════════════╗\n")
      cat("║         模块4：下游分析顾问启动                            ║\n")
      cat("╚═══════════════════════════════════════════════════════════╝\n\n")

      # 准备细胞类型组成摘要
      if (is.null(all_annotations) || length(all_annotations) == 0) {
        return(list(
          success = FALSE,
          error = "没有可用的细胞类型注释数据"
        ))
      }

      # 构建细胞类型组成摘要（统计信息，不打印每个细胞）
      type_counts <- table(all_annotations)
      cell_composition <- paste0(
        "该单细胞数据集的细胞类型组成如下：\n",
        paste(names(type_counts), ": ", type_counts, "个细胞", collapse = "\n")
      )

      # 分析数据集特征
      total_clusters <- length(all_annotations)
      unique_types <- length(unique(all_annotations))

      cat("\n总簇数:", total_clusters, "\n")
      cat("独特细胞类型数:", unique_types, "\n\n")
      cat("数据集类型: ", determine_dataset_type(all_annotations), "\n\n")

      # 识别主要细胞类型（type_counts已在上面计算）
      dominant_type <- names(type_counts)[which.max(type_counts)]

      # 判断数据集类型
      dataset_type <- determine_dataset_type(all_annotations)

      if (use_llm) {
        # 使用LLM生成智能推荐
        cat("使用LLM生成智能推荐...\n")

        # 构建下游分析推荐Prompt
        advisor_prompt <- paste0(
          "你是一位单细胞RNA测序数据分析专家。基于以下单细胞数据集的细胞类型组成，",
          "请推荐1-2个最有价值的下游生物学分析方向，并简要说明理由。\n\n",
          "【数据集信息】\n",
          "总细胞簇数：", total_clusters, "\n",
          "独特细胞类型数：", unique_types, "\n",
          "主要细胞类型：", dominant_type, "\n",
          "数据集类型：", dataset_type, "\n\n",
          "【细胞类型组成】\n",
          cell_composition, "\n\n",
          "【推荐要求】\n",
          "1. 根据细胞类型组成特点，推荐最合适的下游分析\n",
          "2. 如果有免疫细胞和其他细胞类型，考虑推荐细胞通讯分析(CellChat)\n",
          "3. 如果有不同分化阶段的细胞，考虑推荐伪时序分析(Monocle3/Slingshot)\n",
          "4. 如果有肿瘤相关细胞，考虑推荐差异表达分析或通路分析\n",
          "5. 每个推荐简要说明分析目的和预期发现\n\n",
          "【输出格式】\n",
          "推荐1：[分析名称]\n",
          "理由：[为什么推荐这个分析]\n",
          "预期发现：[可能的生物学发现]\n",
          "工具推荐：[R包名称]\n\n",
          "推荐2：[分析名称]\n",
          "理由：[为什么推荐]\n",
          "预期发现：[可能发现]\n",
          "工具推荐：[R包名称]"
        )

        # 智能获取API密钥：优先UI输入，其次配置文件，最后环境变量
        llm_key <- NULL

        # 1. 优先使用UI面板输入的密钥
        if (!is.null(api_keys$deepseek) && api_keys$deepseek != "") {
          llm_key <- api_keys$deepseek
          cat("ℹ️ 使用UI面板输入的DeepSeek API密钥\n")
        } else {
          # 2. 尝试从多个可能的路径查找API密钥管理.txt
          possible_paths <- c(
            file.path(getwd(), "API密钥管理.txt"),
            file.path(dirname(getwd()), "API密钥管理.txt"),
            file.path(dirname(getwd()), "r6", "API密钥管理.txt"),
            "API密钥管理.txt",
            file.path(Sys.getenv("USERPROFILE"), "Desktop", "SingleR_Cursor", "R6", "r6", "API密钥管理.txt")
          )

          config_file <- NULL
          for (path in possible_paths) {
            if (file.exists(path)) {
              config_file <- path
              break
            }
          }

          if (!is.null(config_file)) {
            tryCatch(
              {
                config_lines <- readLines(config_file, warn = FALSE, encoding = "UTF-8")
                cat(sprintf("ℹ️ 找到配置文件: %s\n", config_file))

                # 查找DeepSeek快速模型配置（支持多种格式）
                in_deepseek_section <- FALSE
                for (line in config_lines) {
                  # 匹配DeepSeek相关的配置节
                  if (grepl("DeepSeek", line, ignore.case = TRUE) && grepl("快速|fast|chat", line, ignore.case = TRUE)) {
                    in_deepseek_section <- TRUE
                    next
                  }
                  # 匹配api_key行
                  if (in_deepseek_section && grepl("api_key", line, ignore.case = TRUE)) {
                    # 支持多种格式：api_key="xxx", api_key=xxx, api_key: xxx
                    key_match <- regmatches(line, regexpr('["\']?[a-zA-Z0-9_-]{20,}["\']?', line))
                    if (length(key_match) > 0) {
                      llm_key <- gsub('["\']', "", key_match[1])
                      cat(sprintf("✓ 从配置文件读取DeepSeek API密钥\n"))
                      break
                    }
                  }
                  # 遇到下一个模型配置节，停止
                  if (in_deepseek_section && grepl("^[A-Z]", line) && !grepl("api_key|base_url|model", line, ignore.case = TRUE)) {
                    break
                  }
                }
              },
              error = function(e) {
                cat("⚠️ 读取配置文件失败:", e$message, "\n")
              }
            )
          }

          # 3. 最后尝试环境变量
          if (is.null(llm_key) || llm_key == "") {
            env_key <- Sys.getenv("DEEPSEEK_API_KEY", "")
            if (env_key != "") {
              llm_key <- env_key
              cat("ℹ️ 使用环境变量DEEPSEEK_API_KEY\n")
            }
          }
        }

        if (!is.null(llm_key) && llm_key != "") {
          # 使用DeepSeek快速模型（deepseek-chat）
          llm_result <- ask_deepseek(
            advisor_prompt,
            system_prompt = "你是一位单细胞RNA测序和下游分析专家，善于根据数据特征推荐合适的分析方向。",
            api_key = llm_key,
            use_fast_model = TRUE # 使用快速模型
          )

          if (!is.null(llm_result$success)) {
            recommendations <- llm_result$success
            cat("✅ DeepSeek推荐生成成功\n")
          } else {
            cat("⚠️ DeepSeek推荐失败，使用规则推荐\n")
            recommendations <- generate_rule_based_recommendations(all_annotations, dataset_type)
          }
        } else {
          cat("ℹ️ 未找到DeepSeek API密钥，使用规则推荐\n")
          recommendations <- generate_rule_based_recommendations(all_annotations, dataset_type)
        }
      } else {
        # 使用规则推荐
        recommendations <- generate_rule_based_recommendations(all_annotations, dataset_type)
      }

      result <- list(
        success = TRUE,
        cell_composition = cell_composition,
        dataset_type = dataset_type,
        dominant_type = dominant_type,
        total_clusters = total_clusters,
        unique_types = unique_types,
        recommendations = recommendations,
        timestamp = Sys.time()
      )

      cat("\n模块4：下游分析顾问完成\n")
      return(result)
    },
    error = function(e) {
      cat("下游分析顾问错误:", e$message, "\n")
      return(list(
        success = FALSE,
        error = paste("下游分析顾问错误:", e$message)
      ))
    }
  )
}

# 判断数据集类型
determine_dataset_type <- function(annotations) {
  types <- tolower(paste(annotations, collapse = " "))

  # 检测免疫相关
  has_immune <- grepl("t.?cell|b.?cell|nk|macrophage|monocyte|dendritic", types, ignore.case = TRUE)

  # 检测肿瘤相关
  has_cancer <- grepl("cancer|tumor|malignant|carcinoma|epithelial.*cancer", types, ignore.case = TRUE)

  # 检测基质细胞
  has_stromal <- grepl("fibroblast|endothelial|pericyte|adipocyte", types, ignore.case = TRUE)

  # 检测干细胞/祖细胞
  has_stem <- grepl("stem|progenitor|precursor", types, ignore.case = TRUE)

  if (has_cancer && has_immune) {
    return("肿瘤微环境（TME）")
  } else if (has_immune && has_stromal) {
    return("免疫-基质互作")
  } else if (has_stem) {
    return("发育/分化谱系")
  } else if (has_cancer) {
    return("肿瘤组织")
  } else if (has_immune) {
    return("免疫系统")
  } else {
    return("混合组织")
  }
}

# 基于规则的推荐（备选方案）
generate_rule_based_recommendations <- function(annotations, dataset_type) {
  recommendations <- list()

  types <- tolower(paste(annotations, collapse = " "))
  unique_count <- length(unique(annotations))

  # 优先推荐：根据数据集特征选择最合适的分析

  # 规则1：如果细胞类型多样（>=5种），推荐伪时序分析
  if (unique_count >= 5 || grepl("stem|progenitor|precursor", types)) {
    recommendations <- append(recommendations, list(list(
      name = "伪时序轨迹分析 (Trajectory Analysis)",
      reason = paste0(
        "数据集包含", unique_count, "种不同细胞类型",
        if (grepl("stem|progenitor", types)) "，且有干/祖细胞" else "",
        "，可能存在分化轨迹"
      ),
      expected = "重建细胞分化轨迹，识别关键分化节点，发现调控分化的关键基因",
      tools = "Monocle3 或 Slingshot (R包)",
      priority = "中"
    )))
  }

  # 规则2：如果有免疫细胞+内皮/基质细胞，推荐细胞通讯分析
  if (grepl("blood|immune|lymphocyte|macrophage", types) &&
    (grepl("endothelial|fibroblast|mesenchymal", types))) {
    recommendations <- append(recommendations, list(list(
      name = "细胞通讯分析 (CellChat)",
      reason = "数据集包含免疫细胞和基质/内皮细胞，适合研究细胞间通讯网络",
      expected = "发现关键的配体-受体对，揭示细胞间相互作用网络，了解组织微环境中的信号传导",
      tools = "CellChat (R包)",
      priority = "高"
    )))
  }

  # 规则3：如果有肿瘤细胞，推荐CNV分析
  if (grepl("cancer|tumor|carcinoma", types)) {
    recommendations <- append(recommendations, list(list(
      name = "拷贝数变异推断 (CNV Analysis)",
      reason = "数据集包含肿瘤细胞，可以从scRNA-seq数据推断CNV",
      expected = "识别肿瘤细胞的染色体拷贝数变化，区分正常细胞和肿瘤细胞",
      tools = "inferCNV (R包)",
      priority = "中"
    )))
  }

  # 确保至少有2个推荐
  if (length(recommendations) == 0) {
    # 默认推荐1：差异表达分析
    recommendations <- append(recommendations, list(list(
      name = "细胞类型特征基因鉴定",
      reason = "识别各细胞类型的标志基因和生物学功能",
      expected = "发现细胞类型特异性标记基因，了解各细胞类型的功能特征",
      tools = "Seurat::FindAllMarkers + clusterProfiler",
      priority = "高"
    )))
  }

  if (length(recommendations) == 1) {
    # 默认推荐2：通路富集分析
    recommendations <- append(recommendations, list(list(
      name = "功能通路富集分析",
      reason = "深入理解各细胞类型的生物学功能和信号通路激活状态",
      expected = "发现激活的信号通路，理解细胞类型的功能状态和生物学特征",
      tools = "clusterProfiler + GSEA",
      priority = "中"
    )))
  }

  # 格式化为文本
  rec_text <- c()
  for (i in seq_along(recommendations)) {
    rec <- recommendations[[i]]
    rec_text <- c(
      rec_text,
      paste0("**推荐", i, "：", rec$name, "**"),
      paste0("理由：", rec$reason),
      paste0("预期发现：", rec$expected),
      paste0("工具推荐：", rec$tools),
      paste0("优先级：", rec$priority),
      ""
    )
  }

  return(paste(rec_text, collapse = "\n"))
}

