# ============================================================
# 模块3增强：独立Massive_Validator
# ============================================================

# 大规模生物学验证器（独立函数）
Massive_Validator <- function(predicted_type, knowledge_base, markers) {
  tryCatch(
    {
      # 静默模式下只显示一行摘要
      if (!QUIET_DATABASE_QUERIES) {
        print_sub_title("3数据库交叉验证", 60)
        cat(sprintf("  预测类型: %s\n", predicted_type))
        print_separator("─", 60)
      }

      if (is.null(predicted_type) || predicted_type == "Unknown") {
        if (!QUIET_DATABASE_QUERIES) print_status("warning", "预测类型为Unknown，跳过验证")
        return(list(
          biological_score = 0.5,
          validation_details = list(),
          evidence_chain = "预测类型未知，无法验证"
        ))
      }

      validation_scores <- list()
      evidence_chain <- c()

      if (!QUIET_DATABASE_QUERIES) {
        cat("  ℹ 验证策略：使用3个细胞类型数据库交叉验证\n")
        print_separator("─", 60)
      }

      # 验证1: CellMarker数据库匹配 (最权威)
      if (!is.null(knowledge_base$analysis_summary$cellmarker_summary)) {
        cm <- knowledge_base$analysis_summary$cellmarker_summary
        if (!is.null(cm$best_match) && cm$best_match != "Unknown") {
          match_similarity <- calculate_type_similarity(predicted_type, cm$best_match)
          matched_count <- cm$matched_markers %||% 0
          validation_scores$cellmarker <- match_similarity * min(1.0, matched_count / 5)

          if (match_similarity > 0.7) {
            evidence_chain <- c(
              evidence_chain,
              paste0(
                "✓ CellMarker: ", cm$best_match, " (相似度", round(match_similarity, 2),
                ", 匹配", matched_count, "个基因)"
              )
            )
          } else {
            evidence_chain <- c(
              evidence_chain,
              paste0("⚠ CellMarker: ", cm$best_match, " (相似度较低", round(match_similarity, 2), ")")
            )
          }
        } else {
          validation_scores$cellmarker <- 0.3
          evidence_chain <- c(evidence_chain, "⚠ CellMarker: 未找到匹配")
        }
      } else {
        validation_scores$cellmarker <- 0.3
        evidence_chain <- c(evidence_chain, "⚠ CellMarker: 数据不可用")
      }

      # 注意：已移除GO/KEGG/STRINGdb/Literature验证
      # 原因：这些数据库只能验证功能/通路/互作，无法直接验证细胞类型
      # 保留它们会稀释真正有效验证的权重

      # 验证2: scType组织特异性验证
      if (!is.null(knowledge_base$analysis_summary$sctype_summary)) {
        st <- knowledge_base$analysis_summary$sctype_summary
        if (!is.null(st$best_match) && st$best_match != "Unknown") {
          sctype_similarity <- calculate_type_similarity(predicted_type, st$best_match)
          overlap_count <- st$best_overlap %||% 0
          validation_scores$sctype <- sctype_similarity * min(1.0, overlap_count / 3)

          if (sctype_similarity > 0.7) {
            evidence_chain <- c(
              evidence_chain,
              paste0(
                "✓ scType: ", st$best_match, " (相似度", round(sctype_similarity, 2),
                ", 组织:", st$tissue, ")"
              )
            )
          } else {
            evidence_chain <- c(
              evidence_chain,
              paste0("⚠ scType: ", st$best_match, " (相似度较低", round(sctype_similarity, 2), ")")
            )
          }
        } else {
          validation_scores$sctype <- 0.3
          evidence_chain <- c(evidence_chain, "⚠ scType: 未找到匹配")
        }
      } else {
        validation_scores$sctype <- 0.3
        evidence_chain <- c(evidence_chain, "⚠ scType: 数据不可用")
      }

      # 验证3: PanglaoDB交叉验证
      if (!is.null(knowledge_base$analysis_summary$panglao_summary)) {
        pl <- knowledge_base$analysis_summary$panglao_summary
        if (!is.null(pl$best_match) && pl$best_match != "Unknown") {
          panglao_similarity <- calculate_type_similarity(predicted_type, pl$best_match)
          panglao_overlap <- pl$best_overlap %||% 0
          validation_scores$panglao <- panglao_similarity * min(1.0, panglao_overlap / 5)

          if (panglao_similarity > 0.7) {
            evidence_chain <- c(
              evidence_chain,
              paste0(
                "✓ PanglaoDB: ", pl$best_match, " (相似度", round(panglao_similarity, 2),
                ", 匹配", pl$matched_cell_types, "种类型)"
              )
            )
          } else {
            evidence_chain <- c(
              evidence_chain,
              paste0("⚠ PanglaoDB: ", pl$best_match, " (相似度较低", round(panglao_similarity, 2), ")")
            )
          }
        } else {
          validation_scores$panglao <- 0.3
          evidence_chain <- c(evidence_chain, "⚠ PanglaoDB: 未找到匹配")
        }
      } else {
        validation_scores$panglao <- 0.3
        evidence_chain <- c(evidence_chain, "⚠ PanglaoDB: 数据不可用")
      }

      # ═══════════════════════════════════════════════════════════════
      # 【注意】以下权重计算已废弃，仅保留用于内部validation_details计算
      # 最终输出使用简单的Match/No Match判断，不使用这些权重
      # ═══════════════════════════════════════════════════════════════
      weights <- c(
        cellmarker = 0.40, # CellMarker最权威
        sctype = 0.35, # scType组织特异性
        panglao = 0.25 # PanglaoDB综合数据库
      )

      # 计算加权平均（仅用于validation_details内部字段）
      biological_score <- sum(sapply(names(weights), function(db) {
        score <- validation_scores[[db]] %||% 0.5
        weights[db] * score
      }))

      # 准备表格数据（只显示3个核心数据库）
      validation_data <- list(
        list(
          "CellMarker", sprintf("%.3f", validation_scores$cellmarker %||% 0.5), "40%",
          sprintf("%.3f", (validation_scores$cellmarker %||% 0.5) * 0.40)
        ),
        list(
          "scType", sprintf("%.3f", validation_scores$sctype %||% 0.5), "35%",
          sprintf("%.3f", (validation_scores$sctype %||% 0.5) * 0.35)
        ),
        list(
          "PanglaoDB", sprintf("%.3f", validation_scores$panglao %||% 0.5), "25%",
          sprintf("%.3f", (validation_scores$panglao %||% 0.5) * 0.25)
        )
      )

      # 静默模式下跳过详细表格输出
      if (!QUIET_DATABASE_QUERIES) {
        # 打印验证表格
        print_table(
          validation_data,
          headers = c("数据库", "原始分", "权重", "加权分"),
          col_widths = c(18, 12, 10, 12)
        )

        print_separator("─", 60)
        cat(sprintf("  ✅ 生物学验证分数: %.3f\n", biological_score))
        cat(sprintf("  📄 证据链条目数: %d\n", length(evidence_chain)))
        print_separator("─", 60)
      }

      return(list(
        biological_score = biological_score,
        validation_details = validation_scores,
        evidence_chain = paste(evidence_chain, collapse = "\n"),
        weights = weights,
        timestamp = Sys.time()
      ))
    },
    error = function(e) {
      cat("Massive_Validator错误:", e$message, "\n")
      return(list(
        biological_score = 0.5,
        validation_details = list(),
        evidence_chain = paste("验证失败:", e$message)
      ))
    }
  )
}

# ══════════════════════════════════════════════════════════════════════
# CellMarker查询（在线API + 超全本地fallback）
# ══════════════════════════════════════════════════════════════════════

# ============================================================
# CellMarker 2.0 官方完整数据库（467种细胞类型）
# 来源：http://bio-bigdata.hrbmu.edu.cn/CellMarker/
