run_cellmarker_analysis <- function(markers, parallel_env = NULL, tissue = "Unknown", log_file = NULL) {
  tryCatch(
    {
      timer <- start_timer("CellMarker查询")

      # 控制台和日志头部
      log_separator("🗄 CellMarker 细胞类型数据库查询", log_file)
      log_info(sprintf("📥 输入基因: %d个", length(markers)), log_file)
      log_debug(sprintf("  → %s", paste(head(markers, 10), collapse = ", ")), log_file)
      if (length(markers) > 10) {
        log_debug(sprintf("  ... 及其他%d个基因", length(markers) - 10), log_file)
      }

      # 第1优先：尝试CellMarker在线API
      online_result <- tryCatch(
        {
          print_status("info", "CellMarker | 尝试在线API...")

          # CellMarker API endpoint（多个备选URL）
          api_urls <- c(
            "http://bio-bigdata.hrbmu.edu.cn/CellMarker/api/search.php",
            "http://bio-bigdata.hrbmu.edu.cn/CellMarker/CellMarker_API.php",
            "http://xteam.xbio.top/CellMarker/api" # 备用镜像
          )

          # 构建查询参数
          marker_string <- paste(markers[1:min(10, length(markers))], collapse = ",")

          # 尝试所有API endpoint
          for (api_url in api_urls) {
            cat(sprintf("    → %s ... ", basename(api_url)))
            result <- tryCatch(
              {
                response <- httr::POST(
                  api_url,
                  body = list(
                    species = "Human",
                    tissue = tissue,
                    genes = marker_string
                  ),
                  encode = "json",
                  httr::timeout(15), # 15秒超时
                  httr::add_headers("User-Agent" = "AURA-2.0-Research-Tool")
                )

                if (httr::status_code(response) == 200) {
                  # 尝试获取原始文本
                  raw_text <- httr::content(response, as = "text", encoding = "UTF-8")

                  # 检查是否为HTML错误页面（如Forbidden）
                  if (grepl("<title>.*Forbidden.*</title>", raw_text, ignore.case = TRUE) ||
                    grepl("Access be denied", raw_text, ignore.case = TRUE) ||
                    grepl("403 Forbidden", raw_text, ignore.case = TRUE)) {
                    cat("⚠ CellMarker API访问被拒绝 (403 Forbidden)，可能是IP限制或API变更\n")
                    return(NULL) # 直接返回NULL，触发本地Fallback
                  }

                  # ===== 调试：输出API原始返回内容 =====
                  cat("✓ 连接成功，解析响应...\n")

                  # 检测返回格式（JSON或XML或其他）
                  content <- NULL
                  matched_types <- NULL

                  # 尝试1：JSON格式
                  if (grepl("^\\s*[\\{\\[]", raw_text)) {
                    cat("→ 检测到JSON格式\n")
                    content <- tryCatch(
                      {
                        jsonlite::fromJSON(raw_text, simplifyVector = FALSE)
                      },
                      error = function(e) {
                        cat("  JSON解析失败:", e$message, "\n")
                        NULL
                      }
                    )

                    if (!is.null(content)) {
                      # JSON解析成功，提取匹配类型
                      matched_types <- if (!is.null(content$results)) {
                        content$results
                      } else if (!is.null(content$matches)) {
                        content$matches
                      } else if (!is.null(content$data)) {
                        content$data
                      } else {
                        list(list(
                          cell_type = content$cell_type %||% content$top_match %||% "Unknown",
                          score = as.numeric(content$score %||% 0.5),
                          matched_genes = content$matched_genes %||% content$genes %||% ""
                        ))
                      }
                    }
                  }

                  # 尝试2：XML格式
                  else if (grepl("^\\s*<", raw_text)) {
                    cat("→ 检测到XML格式，尝试解析...\n")
                    xml_content <- tryCatch(
                      {
                        xml2::read_xml(raw_text)
                      },
                      error = function(e) {
                        cat("  XML解析失败:", e$message, "\n")
                        NULL
                      }
                    )

                    if (!is.null(xml_content)) {
                      # 解析XML中的细胞类型信息
                      # CellMarker API可能的XML结构示例：
                      # <results><cell_type>...</cell_type><score>...</score></results>
                      cell_types <- xml2::xml_find_all(xml_content, ".//cell_type|.//celltype|.//CellType")
                      scores <- xml2::xml_find_all(xml_content, ".//score|.//Score")

                      if (length(cell_types) > 0) {
                        cat(sprintf("  → 找到%d个细胞类型\n", length(cell_types)))
                        matched_types <- lapply(1:length(cell_types), function(i) {
                          list(
                            cell_type = xml2::xml_text(cell_types[[i]]),
                            score = if (i <= length(scores)) as.numeric(xml2::xml_text(scores[[i]])) else 0.8,
                            matched_genes = ""
                          )
                        })
                      } else {
                        cat("  ⚠ XML中未找到细胞类型节点\n")
                      }
                    }
                  }

                  # 尝试3：纯文本或HTML错误
                  else {
                    cat("⚠ API返回未知格式（可能是错误消息）\n")
                    # 返回失败标记，使用本地数据库
                    return(NULL)
                  }

                  # 如果所有解析都失败
                  if (is.null(matched_types)) {
                    cat("⚠ 无法解析API响应，切换到本地数据库\n")
                    return(NULL)
                  }

                  # 如果成功解析
                  if (!is.null(matched_types) && length(matched_types) > 0) {
                    # 显示Top匹配
                    if (length(matched_types) > 0) {
                      log_info("✅ CellMarker在线API返回结果", log_file)
                      log_info("🏆 Top 5 CellMarker在线匹配:", log_file)
                      cat("🏆 Top 5 CellMarker在线匹配:\n")

                      for (i in 1:min(5, length(matched_types))) {
                        match <- matched_types[[i]]
                        cell_type <- match$cell_type %||% match$cellType %||% "Unknown"
                        score <- match$score %||% match$confidence %||% 0.5
                        cat(sprintf("  %d. %s (评分: %.3f)\n", i, cell_type, as.numeric(score)))

                        log_debug(sprintf("  %d. %s (评分: %.3f)", i, cell_type, as.numeric(score)), log_file)
                      }
                      cat("\n")
                    }
                    # ===== 新增结束 =====

                    return(list(
                      best_match = matched_types[[1]]$cell_type %||% content$cell_type %||% content$top_match,
                      best_score = as.numeric(matched_types[[1]]$score %||% content$score %||% 0.8),
                      matched_markers = content$matched_genes %||% matched_types[[1]]$matched_genes,
                      all_matches = matched_types, # 新增：保存所有匹配
                      method = "online_api",
                      api_url = api_url
                    ))
                  }
                }
                NULL
              },
              error = function(e) {
                cat("✗ 失败\n")
                NULL
              }
            )

            if (!is.null(result)) {
              return(result)
            }
          }

          # 所有API都失败
          print_status("warning", "CellMarker | 所有在线API不可用")
          NULL
        },
        error = function(e) {
          cat(" 失败:", e$message, "\n")
          NULL
        }
      )

      # 如果在线API成功，返回结果
      if (!is.null(online_result)) {
        print_status("success", sprintf(
          "CellMarker | 使用在线数据: %s (匹配%d个基因)",
          online_result$best_match, online_result$matched_markers %||% 0
        ))
        print_timing(start_time, "CellMarker查询")
        return(online_result)
      }

      # API失败，使用增强本地库
      log_info("", log_file)
      log_info("📚 使用CellMarker 2.0官方完整本地数据库", log_file)
      log_debug(sprintf("  → 数据库版本: CellMarker 2.0官方完整版"), log_file)
      log_debug(sprintf("  → 细胞类型数: %d种 (覆盖158种人类组织)", length(ENHANCED_CELLMARKER_DB)), log_file)
      log_debug("  → 评分算法: 覆盖率60% + 精确度40%", log_file)
      log_debug("  → 引用文献: Zhang et al. (2019) Nucleic Acids Res", log_file)

      # 计算与每个类型的匹配度
      log_debug("", log_file)
      log_debug("🔍 开始匹配计算...", log_file)
      match_results <- list()

      for (type_name in names(ENHANCED_CELLMARKER_DB)) {
        type_info <- ENHANCED_CELLMARKER_DB[[type_name]]
        type_markers <- type_info$markers

        # 移除"-"等注释符号
        clean_markers <- gsub("[+-]", "", type_markers)
        clean_input <- markers

        # 计算重叠
        overlap_genes <- intersect(clean_input, clean_markers)

        if (length(overlap_genes) > 0) {
          match_results[[type_name]] <- list(
            overlap_count = length(overlap_genes),
            overlap_genes = overlap_genes
          )

          log_trace(sprintf("  %s: 匹配%d个基因", type_name, length(overlap_genes)), log_file)
        }
      }

      log_debug(sprintf("✓ 匹配完成，找到%d个候选类型", length(match_results)), log_file)

      if (length(match_results) == 0) {
        log_warn("⚠ 未找到匹配的细胞类型", log_file)
        log_debug("原因: 输入基因与CellMarker数据库无重叠", log_file)
        stop_timer(timer, log_file)
        log_separator(NULL, log_file)
        return(list(best_match = "Unknown", method = "local_no_match"))
      }

      # 按重叠基因数排序
      sorted_matches <- match_results[order(sapply(match_results, function(x) x$overlap_count), decreasing = TRUE)]
      best_type <- names(sorted_matches)[1]
      best_info <- sorted_matches[[1]]

      # 控制台和日志输出Top 5
      log_info("", log_file)
      log_info(sprintf("✅ 找到 %d 个匹配细胞类型", length(match_results)), log_file)
      log_info("🏆 Top 5 CellMarker匹配:", log_file)

      for (i in seq_len(min(5, length(sorted_matches)))) {
        type_name <- names(sorted_matches)[i]
        type_info <- sorted_matches[[i]]

        if (i <= 3) {
          cat(sprintf("  %d. %s (匹配%d个基因)\n", i, type_name, type_info$overlap_count))
        }

        log_debug(sprintf("  %d. %s", i, type_name), log_file)
        log_debug(sprintf("     → 匹配基因数: %d", type_info$overlap_count), log_file)
        log_trace(sprintf(
          "     → 基因: %s",
          ifelse(length(type_info$overlap_genes) > 5,
            paste0(paste(head(type_info$overlap_genes, 5), collapse = ", "), "..."),
            paste(type_info$overlap_genes, collapse = ", ")
          )
        ), log_file)
      }

      # 统计摘要
      avg_overlap <- mean(sapply(sorted_matches, function(x) x$overlap_count))

      log_info("", log_file)
      log_info("🎯 CellMarker查询摘要:", log_file)
      log_info(sprintf("  → 输入基因: %d个", length(markers)), log_file)
      log_info(sprintf("  → 匹配类型: %d种", length(match_results)), log_file)
      log_info(sprintf("  → 最佳匹配: %s", best_type), log_file)
      log_info(sprintf("  → 最多匹配基因数: %d", best_info$overlap_count), log_file)
      log_debug(sprintf("  → 平均匹配基因数: %.1f", avg_overlap), log_file)

      stop_timer(timer, log_file)
      log_separator(NULL, log_file)

      return(list(
        best_match = best_type,
        matched_markers = best_info$overlap_count,
        overlap_genes = paste(best_info$overlap_genes, collapse = ", "),
        avg_overlap = avg_overlap,
        method = "enhanced_local",
        top_matches = head(sorted_matches, 5), # 返回Top 5匹配
        source = "CellMarker 2.0 Official (467 cell types)",
        citation = "Zhang X et al. (2019) Nucleic Acids Res. 47(D1):D721-D728. doi: 10.1093/nar/gky900"
      ))
    },
    error = function(e) {
      log_error(sprintf("✗ CellMarker分析异常: %s", e$message), log_file)
      log_trace(sprintf("  错误堆栈: %s", paste(as.character(sys.calls()), collapse = " -> ")), log_file)
      log_debug("可能原因: API连接失败、本地数据库损坏或输入基因格式错误", log_file)
      if (exists("timer")) stop_timer(timer, log_file)
      log_separator(NULL, log_file)
      return(list(best_match = "Unknown", method = "error"))
    }
  )
}

# ──────────────────────────────────────────────────────────
# scType查询（组织特异性）
# ──────────────────────────────────────────────────────────
run_sctype_analysis <- function(markers, tissue = "Unknown", log_file = NULL) {
  tryCatch(
    {
      timer <- start_timer("scType查询")

      # 控制台和日志头部
      log_separator("🗄 scType 组织特异性细胞注释", log_file)
      log_info(sprintf("📥 输入基因: %d个", length(markers)), log_file)
      log_info(sprintf("🎯 目标组织: %s", tissue), log_file)
      log_debug(sprintf("  → %s", paste(head(markers, 10), collapse = ", ")), log_file)
      if (length(markers) > 10) {
        log_debug(sprintf("  ... 及其他%d个基因", length(markers) - 10), log_file)
      }

      # scType组织特异性marker库
      sctype_breast_db <- list(
        "T cells" = list(
          positive = c("CD3D", "CD3E", "CD3G", "CD2", "TRAC"),
          negative = c("CD79A", "CD19", "EPCAM", "CD68")
        ),
        "B cells" = list(
          positive = c("CD79A", "CD79B", "MS4A1", "CD19", "IGHM"),
          negative = c("CD3D", "CD68", "EPCAM")
        ),
        "Macrophages" = list(
          positive = c("CD68", "CD163", "C1QA", "C1QB", "C1QC"),
          negative = c("CD3D", "CD79A", "EPCAM")
        ),
        "Cancer epithelial" = list(
          positive = c("EPCAM", "KRT19", "KRT18", "ERBB2", "ESR1"),
          negative = c("CD3D", "CD79A", "CD68", "VWF")
        ),
        "Fibroblasts" = list(
          positive = c("COL1A1", "COL1A2", "DCN", "LUM", "PDGFRA"),
          negative = c("EPCAM", "CD3D", "CD68", "VWF")
        ),
        "Endothelial" = list(
          positive = c("PECAM1", "VWF", "CDH5", "CLDN5"),
          negative = c("EPCAM", "CD3D", "COL1A1")
        )
      )

      # 计算scType匹配（基于正向marker匹配数）
      log_debug("", log_file)
      log_debug("🔍 开始scType匹配计算...", log_file)

      best_match <- "Unknown"
      best_overlap <- 0
      all_matches <- list()

      for (type_name in names(sctype_breast_db)) {
        type_info <- sctype_breast_db[[type_name]]

        # 正marker匹配
        pos_overlap <- length(intersect(markers, type_info$positive))

        # 负marker检查
        neg_overlap <- length(intersect(markers, type_info$negative))

        if (pos_overlap > 0) {
          all_matches[[type_name]] <- list(
            pos_overlap = pos_overlap,
            neg_overlap = neg_overlap
          )

          log_trace(sprintf(
            "  %s: 正向匹配%d个, 负向冲突%d个",
            type_name, pos_overlap, neg_overlap
          ), log_file)
        }

        if (pos_overlap > best_overlap) {
          best_overlap <- pos_overlap
          best_match <- type_name
        }
      }

      log_debug(sprintf("✓ 匹配完成，找到%d个候选类型", length(all_matches)), log_file)

      if (best_match != "Unknown") {
        # 按正向匹配数排序
        sorted_matches <- all_matches[order(sapply(all_matches, function(x) x$pos_overlap), decreasing = TRUE)]

        # 控制台和日志输出
        log_info("", log_file)
        log_info(sprintf("✅ 找到 %d 个候选细胞类型", length(sorted_matches)), log_file)
        log_info("🏆 Top 5 scType匹配:", log_file)

        for (i in seq_len(min(5, length(sorted_matches)))) {
          type_name <- names(sorted_matches)[i]
          type_info <- sorted_matches[[i]]

          if (i <= 3) {
            cat(sprintf("  %d. %s (正向匹配%d个基因)\n", i, type_name, type_info$pos_overlap))
          }

          log_debug(sprintf("  %d. %s", i, type_name), log_file)
          log_debug(sprintf("     → 正向匹配: %d个基因", type_info$pos_overlap), log_file)
          log_debug(sprintf("     → 负向冲突: %d个基因", type_info$neg_overlap), log_file)
        }

        # 统计摘要
        log_info("", log_file)
        log_info("🎯 scType分析摘要:", log_file)
        log_info(sprintf("  → 输入基因: %d个", length(markers)), log_file)
        log_info(sprintf("  → 目标组织: %s", tissue), log_file)
        log_info(sprintf("  → 候选类型: %d种", length(sorted_matches)), log_file)
        log_info(sprintf("  → 最佳匹配: %s", best_match), log_file)
        log_info(sprintf("  → 最多正向匹配: %d个基因", best_overlap), log_file)

        stop_timer(timer, log_file)
        log_separator(NULL, log_file)

        return(list(
          best_match = best_match,
          best_overlap = best_overlap,
          tissue = tissue,
          candidate_types = length(sorted_matches),
          top_matches = head(sorted_matches, 5)
        ))
      } else {
        log_warn("⚠ 未找到匹配的细胞类型", log_file)
        log_debug("原因: 输入基因与组织特异性标记无显著重叠", log_file)
        stop_timer(timer, log_file)
        log_separator(NULL, log_file)
        return(list(best_match = "Unknown"))
      }
    },
    error = function(e) {
      log_error(sprintf("✗ scType分析异常: %s", e$message), log_file)
      log_trace(sprintf("  错误堆栈: %s", paste(as.character(sys.calls()), collapse = " -> ")), log_file)
      log_debug("可能原因: 输入数据格式错误或组织特异性数据库缺失", log_file)
      if (exists("timer")) stop_timer(timer, log_file)
      log_separator(NULL, log_file)
      return(list(best_match = "Unknown"))
    }
  )
}

# ──────────────────────────────────────────────────────────────
# 函数：build_knowledge_base - 整合数据库结果
# ──────────────────────────────────────────────────────────────
build_knowledge_base <- function(stringdb_results = list(),
                                 gprofiler_results = list(),
                                 clusterprofiler_results = list(),
                                 cellmarker_results = list(),
                                 panglao_results = list(),
                                 literature_results = list(),
                                 markers = c(),
                                 markers_full_df = NULL, # ✅ 新增：完整markers数据框（包含log2FC等）
                                 sctype_results = list()) {
  # 整合所有数据库结果为知识库
  knowledge_base <- list(
    analysis_summary = list(
      # gprofiler2摘要
      gprofiler_summary = if (!is.null(gprofiler_results) && !is.null(gprofiler_results$top_terms)) {
        list(
          significant_terms = gprofiler_results$significant_terms %||% 0,
          best_fdr = gprofiler_results$best_fdr %||% 1,
          top_terms = gprofiler_results$top_terms
        )
      } else {
        list(significant_terms = 0, best_fdr = 1)
      },

      # clusterProfiler摘要
      clusterprofiler_summary = if (!is.null(clusterprofiler_results) && !is.null(clusterprofiler_results$top_pathways)) {
        list(
          significant_pathways = clusterprofiler_results$significant_pathways %||% 0,
          best_pvalue = clusterprofiler_results$best_pvalue %||% 1,
          top_pathways = clusterprofiler_results$top_pathways
        )
      } else {
        list(significant_pathways = 0, best_pvalue = 1)
      },

      # CellMarker摘要
      cellmarker_summary = if (!is.null(cellmarker_results) && !is.null(cellmarker_results$best_match)) {
        list(
          best_match = cellmarker_results$best_match,
          matched_markers = cellmarker_results$matched_markers %||% 0
        )
      } else {
        list(best_match = "Unknown", matched_markers = 0)
      },

      # STRINGdb摘要
      stringdb_summary = if (!is.null(stringdb_results) && !is.null(stringdb_results$interactions)) {
        list(
          interactions = stringdb_results$interactions,
          avg_confidence = stringdb_results$avg_confidence %||% 0
        )
      } else {
        list(interactions = 0, avg_confidence = 0)
      },

      # 文献摘要
      literature_summary = if (!is.null(literature_results$total_articles)) {
        list(
          total_articles = literature_results$total_articles,
          recent_articles = literature_results$recent_articles %||% 0
        )
      } else {
        list(total_articles = 0, recent_articles = 0)
      },

      # scType摘要（新增）
      sctype_summary = if (!is.null(sctype_results$best_match)) {
        list(
          best_match = sctype_results$best_match,
          best_overlap = sctype_results$best_overlap %||% 0,
          tissue = sctype_results$tissue %||% "Unknown"
        )
      } else {
        list(best_match = "Unknown", best_overlap = 0, tissue = "Unknown")
      },

      # PanglaoDB摘要（新增）
      panglao_summary = if (!is.null(panglao_results$best_match)) {
        list(
          best_match = panglao_results$best_match,
          best_overlap = panglao_results$best_overlap %||% 0,
          matched_cell_types = panglao_results$matched_cell_types %||% 0,
          top_matches = panglao_results$top_matches
        )
      } else {
        list(best_match = "Unknown", best_overlap = 0, matched_cell_types = 0)
      }
    ),

    # ✅ 保存完整的markers数据框（优先使用markers_full_df，包含定量数据）
    marker_genes = if (!is.null(markers_full_df) && is.data.frame(markers_full_df)) {
      markers_full_df # 使用完整数据框（包含log2FC, pct.1, pct.2, p_val_adj等）
    } else {
      data.frame(gene = markers, stringsAsFactors = FALSE) # 备用：只有基因名
    },
    timestamp = Sys.time()
  )

  return(knowledge_base)
}

# ──────────────────────────────────────────────────────────
# 两层注释：粗分类算法
# ──────────────────────────────────────────────────────────

# 为单个簇分配主要细胞类型
assign_major_cell_type <- function(seurat_obj, cluster_id, marker_table) {
  tryCatch(
    {
      # 获取该簇的细胞
      cluster_cells <- colnames(seurat_obj)[seurat_obj$seurat_clusters == cluster_id]

      if (length(cluster_cells) == 0) {
        return(list(major_type = "Unknown", score = 0, details = list()))
      }

      # 对每个大类计算得分
      type_scores <- list()
      for (i in 1:nrow(marker_table)) {
        cell_type <- marker_table[i, "细胞类型"]
        markers_str <- marker_table[i, "Marker基因"]
        markers <- unlist(strsplit(markers_str, ",\\s*"))

        # 筛选在数据中存在的marker
        available_markers <- intersect(markers, rownames(seurat_obj))

        if (length(available_markers) > 0) {
          # 计算该簇中这些marker的平均表达
          cluster_exp <- GetAssayData(seurat_obj, slot = "data")[available_markers, cluster_cells, drop = FALSE]
          mean_exp <- mean(rowMeans(as.matrix(cluster_exp)))

          type_scores[[cell_type]] <- list(
            score = mean_exp,
            available_markers = length(available_markers),
            total_markers = length(markers)
          )
        } else {
          type_scores[[cell_type]] <- list(score = 0, available_markers = 0, total_markers = length(markers))
        }
      }

      # 找到得分最高的大类
      scores_vec <- sapply(type_scores, function(x) x$score)
      best_type <- names(which.max(scores_vec))
      best_score <- max(scores_vec)

      return(list(
        major_type = best_type,
        score = best_score,
        all_scores = type_scores
      ))
    },
    error = function(e) {
      cat("粗分类失败:", e$message, "\n")
      return(list(major_type = "Unknown", score = 0, details = list()))
    }
  )
}

# 批量粗分类
batch_major_assignment <- function(seurat_obj, marker_table) {
  all_clusters <- sort(unique(seurat_obj$seurat_clusters))
  assignments <- list()

  cat("\n=== 开始粗分类（基于marker表达）===\n")
  for (cid in all_clusters) {
    result <- assign_major_cell_type(seurat_obj, cid, marker_table)
    assignments[[as.character(cid)]] <- result
    cat("簇", cid, "→", result$major_type, "(得分:", round(result$score, 2), ")\n")
  }
  cat("粗分类完成！\n\n")

  return(assignments)
}

# 计算细胞类型相似度
calculate_type_similarity <- function(type1, type2) {
  # 转小写，移除空格
  t1 <- tolower(gsub("[^a-z]", "", type1))
  t2 <- tolower(gsub("[^a-z]", "", type2))

  # 完全匹配
  if (t1 == t2) {
    return(1.0)
  }

  # 包含关系
  if (grepl(t1, t2) || grepl(t2, t1)) {
    return(0.8)
  }

  # 关键词匹配
  keywords1 <- c(
    "tcell", "bcell", "nkcell", "macrophage", "monocyte",
    "epithelial", "endothelial", "fibroblast", "cancer", "tumor"
  )
  keywords2 <- c(
    "tcell", "bcell", "nkcell", "macrophage", "monocyte",
    "epithelial", "endothelial", "fibroblast", "cancer", "tumor"
  )

  matches <- 0
  for (kw in keywords1) {
    if (grepl(kw, t1) && grepl(kw, t2)) {
      matches <- matches + 1
    }
  }

  if (matches > 0) {
    return(0.6)
  }

  # 默认低相似度
  return(0.3)
}

# ──────────────────────────────────────────────────────────
# Marker质量评分（基于Seurat统计指标）
# 参考：Stuart et al. 2019, Cell
# ──────────────────────────────────────────────────────────
# ═══════════════════════════════════════════════════════════════
# 【新方案】返回三个独立marker指标，不合并为单一分数
# ═══════════════════════════════════════════════════════════════
calculate_marker_quality <- function(markers_df, top_n = 10) {
  tryCatch(
    {
      if (is.null(markers_df) || nrow(markers_df) == 0) {
        cat("Marker指标计算：无有效marker数据\n")
        return(list(
          specificity = 0.5,
          expression_strength = 0.5,
          significance = 0.5
        ))
      }

      # 只使用Top N marker（默认10）
      markers_df <- head(markers_df, top_n)

      # 1. 特异性（pct.1 - pct.2）
      if ("pct.1" %in% colnames(markers_df) && "pct.2" %in% colnames(markers_df)) {
        specificity_vec <- markers_df$pct.1 - markers_df$pct.2
        specificity_vec <- pmax(0, pmin(1, specificity_vec))
      } else {
        specificity_vec <- rep(0.5, nrow(markers_df))
      }

      # 2. 表达强度（归一化avg_log2FC）
      if ("avg_log2FC" %in% colnames(markers_df)) {
        strength_vec <- pmin(markers_df$avg_log2FC / 2, 1)
        strength_vec <- pmax(0, strength_vec)
      } else {
        strength_vec <- rep(0.5, nrow(markers_df))
      }

      # 3. 统计显著性（1 - p_val_adj）
      if ("p_val_adj" %in% colnames(markers_df)) {
        significance_vec <- 1 - markers_df$p_val_adj
        significance_vec <- pmax(0, pmin(1, significance_vec))
      } else {
        significance_vec <- rep(0.5, nrow(markers_df))
      }

      # 计算Top N的平均值（三个独立指标）
      specificity <- mean(specificity_vec, na.rm = TRUE)
      expression_strength <- mean(strength_vec, na.rm = TRUE)
      significance <- mean(significance_vec, na.rm = TRUE)

      # 控制台输出（静默模式下跳过）
      if (!QUIET_DATABASE_QUERIES) {
        print_sub_title("Marker指标详情（三个独立维度）", 50)
        cat(sprintf("  使用Top %d marker基因\n", nrow(markers_df)))
        print_separator("─", 50)
        cat("  三个独立指标（无权重合并）：\n")
        cat(sprintf("    • Specificity      : %.3f (pct.1 - pct.2)\n", specificity))
        cat(sprintf("    • Expression       : %.3f (log2FC normalized)\n", expression_strength))
        cat(sprintf("    • Significance     : %.3f (1 - p_val_adj)\n", significance))
        print_separator("─", 50)
      }

      return(list(
        specificity = round(specificity, 3),
        expression_strength = round(expression_strength, 3),
        significance = round(significance, 3)
      ))
    },
    error = function(e) {
      cat("Marker指标计算失败:", e$message, "\n")
      return(list(
        specificity = 0.5,
        expression_strength = 0.5,
        significance = 0.5
      ))
    }
  )
}

