# ============================================================
# 辅助函数：完整JSON提取
# ============================================================

# 提取完整JSON对象（支持嵌套结构）
extract_complete_json <- function(text) {
  tryCatch(
    {
      # 查找第一个 {
      first_brace <- regexpr("\\{", text)
      if (first_brace < 0) {
        cat("未找到JSON起始符号 {\n")
        return(NULL)
      }

      # 【修复Minimax】使用平衡括号算法找到第一个完整JSON对象的结束位置
      # 而不是找最后一个}，避免包含后面的说明文字
      chars <- strsplit(text, "")[[1]]
      depth <- 0
      json_end <- -1

      for (i in first_brace:length(chars)) {
        if (chars[i] == "{") {
          depth <- depth + 1
        } else if (chars[i] == "}") {
          depth <- depth - 1
          if (depth == 0) {
            json_end <- i
            break
          }
        }
      }

      if (json_end < 0) {
        cat("未找到匹配的JSON结束符号 }\n")
        return(NULL)
      }

      # 提取从第一个{到匹配的}
      json_str <- substr(text, first_brace, json_end)

      cat(
        "提取JSON字符串: 起始位置=", first_brace, ", 结束位置=", json_end,
        ", 长度=", nchar(json_str), "字符\n"
      )

      return(json_str)
    },
    error = function(e) {
      cat("JSON提取失败:", e$message, "\n")
      return(NULL)
    }
  )
}

