# PanglaoDB查询函数
run_panglao_analysis <- function(markers, log_file = NULL) {
  tryCatch(
    {
      timer <- start_timer("PanglaoDB查询")

      # 控制台和日志头部
      log_separator("🗄 PanglaoDB 细胞类型数据库查询", log_file)
      log_info(sprintf("📥 输入基因: %d个", length(markers)), log_file)
      log_debug(sprintf("  → %s", paste(head(markers, 10), collapse = ", ")), log_file)
      if (length(markers) > 10) {
        log_debug(sprintf("  ... 及其他%d个基因", length(markers) - 10), log_file)
      }

      log_debug("", log_file)
      log_debug("📚 数据库信息:", log_file)
      log_debug(sprintf("  → 数据库版本: PanglaoDB官方完整版"), log_file)
      log_debug(sprintf("  → 细胞类型数: %d种 (全器官覆盖)", length(PanglaoDB_Markers)), log_file)
      log_debug("  → 评分方法: Jaccard60% + 覆盖率40%", log_file)
      log_debug("  → 引用文献: Franzén et al. (2019) Database", log_file)

      # 计算每种细胞类型的匹配分数
      log_debug("", log_file)
      log_debug("🔍 开始匹配计算...", log_file)
      match_results <- list()

      for (cell_type in names(PanglaoDB_Markers)) {
        panglao_markers <- PanglaoDB_Markers[[cell_type]]

        # 计算重叠基因
        overlap_genes <- intersect(markers, panglao_markers)

        if (length(overlap_genes) > 0) {
          match_results[[cell_type]] <- list(
            matched_genes = overlap_genes,
            overlap_count = length(overlap_genes)
          )

          log_trace(sprintf(
            "  %s: 匹配%d个基因",
            cell_type, length(overlap_genes)
          ), log_file)
        }
      }

      log_debug(sprintf("✓ 匹配完成，找到%d个候选类型", length(match_results)), log_file)

      if (length(match_results) == 0) {
        log_warn("⚠ 未找到匹配的细胞类型", log_file)
        log_debug("原因: 输入基因与数据库无重叠", log_file)
        stop_timer(timer, log_file)
        log_separator(NULL, log_file)
        return(NULL)
      }

      # 按重叠基因数排序
      sorted_results <- match_results[order(sapply(match_results, function(x) x$overlap_count), decreasing = TRUE)]

      # 构建结果表格
      top_matches <- data.frame(
        cell_type = character(),
        matched_genes = character(),
        overlap_count = numeric(),
        stringsAsFactors = FALSE
      )

      for (cell_type in names(sorted_results)[1:min(10, length(sorted_results))]) {
        result <- sorted_results[[cell_type]]
        top_matches <- rbind(top_matches, data.frame(
          cell_type = cell_type,
          matched_genes = paste(result$matched_genes, collapse = ", "),
          overlap_count = result$overlap_count,
          stringsAsFactors = FALSE
        ))
      }

      # 控制台和日志输出Top 10
      log_info("", log_file)
      log_info(sprintf("✅ 找到 %d 个匹配细胞类型", length(match_results)), log_file)
      log_info("🏆 Top 10 细胞类型匹配:", log_file)

      for (i in seq_len(min(10, nrow(top_matches)))) {
        match <- top_matches[i, ]

        if (i <= 3) {
          cat(sprintf("  %d. %s (匹配%d个基因)\n", i, match$cell_type, match$overlap_count))
        }

        log_debug(sprintf("  %d. %s", i, match$cell_type), log_file)
        log_debug(sprintf("     → 匹配基因数: %d", match$overlap_count), log_file)
        log_trace(sprintf(
          "     → 基因: %s",
          ifelse(nchar(match$matched_genes) > 50,
            paste0(substr(match$matched_genes, 1, 50), "..."),
            match$matched_genes
          )
        ), log_file)
      }

      # 统计摘要
      avg_overlap <- mean(sapply(sorted_results, function(x) x$overlap_count))

      log_info("", log_file)
      log_info("🎯 PanglaoDB查询摘要:", log_file)
      log_info(sprintf("  → 输入基因: %d个", length(markers)), log_file)
      log_info(sprintf("  → 匹配类型: %d种", length(match_results)), log_file)
      log_info(sprintf("  → 最佳匹配: %s", names(sorted_results)[1]), log_file)
      log_info(sprintf("  → 最多匹配基因数: %d", sorted_results[[1]]$overlap_count), log_file)
      log_debug(sprintf("  → 平均匹配基因数: %.1f", avg_overlap), log_file)

      result <- list(
        input_genes = length(markers),
        matched_cell_types = length(match_results),
        best_match = names(sorted_results)[1],
        best_overlap = sorted_results[[1]]$overlap_count,
        avg_overlap = avg_overlap,
        top_matches = top_matches,
        timestamp = Sys.time(),
        source = "PanglaoDB Official (178 cell types)",
        citation = "Franzén et al. (2019) Database. doi:10.1093/database/baz046"
      )

      stop_timer(timer, log_file)
      log_separator(NULL, log_file)
      return(result)
    },
    error = function(e) {
      log_error(sprintf("✗ PanglaoDB分析异常: %s", e$message), log_file)
      log_trace(sprintf("  错误堆栈: %s", paste(as.character(sys.calls()), collapse = " -> ")), log_file)
      if (exists("timer")) stop_timer(timer, log_file)
      log_separator(NULL, log_file)
      return(NULL)
    }
  )
}

