# PanglaoDB 数据库结束
# ============================================================

# 轮廓系数计算最佳分辨率函数
# 添加min_clusters参数，确保聚类数 >= 候选细胞类型数
# 科研依据: Kiselev et al., SC3, Nature Methods 2017
find_optimal_resolution_silhouette <- function(pbmc, dims_range, resolutions, reduction = NULL, max_cells = 2000, min_clusters = NULL) {
  # 🎯 修复：自动检测使用哪种降维方法
  if (is.null(reduction)) {
    reduction <- if (!is.null(pbmc@reductions$harmony)) "harmony" else "pca"
  }
  tryCatch(
    {
      cat("开始轮廓系数计算...\n")
      cat("dims_range:", paste(dims_range, collapse = ":"), "\n")
      cat("resolutions:", paste(resolutions, collapse = ","), "\n")
      if (!is.null(min_clusters)) {
        cat("最小聚类数约束:", min_clusters, "（基于候选类型数）\n")
      }

      # 检查reduction是否存在
      if (!reduction %in% names(pbmc@reductions)) {
        cat("错误: reduction", reduction, "不存在\n")
        cat("可用的reductions:", names(pbmc@reductions), "\n")
        return(NULL)
      }

      emb <- Embeddings(pbmc[[reduction]])[, dims_range, drop = FALSE]
      cat("嵌入矩阵维度:", dim(emb), "\n")

      set.seed(42)
      if (nrow(emb) > max_cells) {
        idx <- sample(seq_len(nrow(emb)), max_cells)
        emb_sub <- emb[idx, , drop = FALSE]
        cat("使用子集，样本数:", nrow(emb_sub), "\n")
      } else {
        idx <- seq_len(nrow(emb))
        emb_sub <- emb
        cat("使用全部样本，样本数:", nrow(emb_sub), "\n")
      }

      dist_mat <- dist(emb_sub)
      cat("距离矩阵计算完成\n")

      # 先构建邻接图，避免FindClusters错误
      cat("构建邻接图...\n")
      set.seed(42) # 确保FindNeighbors的可重复性
      pbmc_temp <- FindNeighbors(pbmc, dims = dims_range, reduction = reduction, verbose = FALSE)
      cat("邻接图构建完成\n")

      # 【修改】同时记录轮廓系数和聚类数
      results <- lapply(resolutions, function(r) {
        cat("正在计算分辨率", r, "的轮廓系数...\n")
        set.seed(42) # 确保FindClusters的可重复性
        tmp <- FindClusters(pbmc_temp, resolution = r, verbose = FALSE)
        cl <- as.numeric(Idents(tmp))[idx]
        n_clusters <- length(unique(cl))
        mean_sil <- mean(silhouette(cl, dist_mat)[, "sil_width"], na.rm = TRUE)
        cat(sprintf("分辨率 %.2f: 轮廓系数=%.3f, 簇数=%d\n", r, mean_sil, n_clusters))
        list(resolution = r, silhouette = mean_sil, n_clusters = n_clusters)
      })

      # 转换为向量
      sil <- sapply(results, function(x) x$silhouette)
      n_clusters_vec <- sapply(results, function(x) x$n_clusters)

      # 移除NA值
      valid_indices <- which(!is.na(sil))
      if (length(valid_indices) == 0) {
        cat("错误: 没有有效的轮廓系数值\n")
        return(NULL)
      }

      valid_sil <- sil[valid_indices]
      valid_res <- resolutions[valid_indices]
      valid_n_clusters <- n_clusters_vec[valid_indices]

      cat("\n═══════════════════════════════════════\n")
      cat("使用轮廓系数选择最佳分辨率\n")
      cat("═══════════════════════════════════════\n")

      # 【核心修改】添加最小聚类数约束
      # 科研依据: Kiselev et al., SC3, Nature Methods 2017
      # "Overclustering is preferred over underclustering"
      if (!is.null(min_clusters) && min_clusters > 0) {
        cat(sprintf("\n  📋 最小聚类数约束: %d（基于候选类型数）\n", min_clusters))

        # 筛选满足约束的分辨率
        constrained_indices <- which(valid_n_clusters >= min_clusters)

        if (length(constrained_indices) == 0) {
          # 如果没有满足约束的分辨率，选择聚类数最多的
          cat("  ⚠️ 警告: 没有分辨率满足最小聚类数约束！\n")
          cat("  采用备选方案: 选择聚类数最多的分辨率\n")
          best_idx <- which.max(valid_n_clusters)
        } else {
          # 在满足约束的分辨率中，选轮廓系数最高的
          constrained_sil <- valid_sil[constrained_indices]
          constrained_res <- valid_res[constrained_indices]
          constrained_n <- valid_n_clusters[constrained_indices]

          cat(sprintf(
            "  ✓ %d/%d 个分辨率满足约束（聚类数 >= %d）\n",
            length(constrained_indices), length(valid_indices), min_clusters
          ))

          # 在满足约束的分辨率中找最大轮廓系数
          best_constrained_idx <- which.max(constrained_sil)
          best_res <- constrained_res[best_constrained_idx]
          best_sil <- constrained_sil[best_constrained_idx]
          best_n_clusters <- constrained_n[best_constrained_idx]

          # 找到在原始valid_res中的索引
          best_idx <- constrained_indices[best_constrained_idx]

          cat(sprintf(
            "  🎯 约束后最佳分辨率: %.2f (轮廓系数=%.3f, 簇数=%d)\n",
            best_res, best_sil, best_n_clusters
          ))
        }
      } else {
        # 无约束模式：直接选轮廓系数最大的
        best_idx <- which.max(valid_sil)
      }

      best_res <- valid_res[best_idx]
      best_sil <- valid_sil[best_idx]
      best_n_clusters <- valid_n_clusters[best_idx]

      cat(sprintf("\n  最佳分辨率: %.2f (轮廓系数=%.3f, 簇数=%d)\n", best_res, best_sil, best_n_clusters))
      cat("  方法: 约束轮廓系数法（Constrained Maximum Silhouette）\n")
      cat("  文献: Rousseeuw (1987) + Kiselev et al. (2017)\n")

      # 输出所有分辨率的轮廓系数供参考
      cat("\n  各分辨率详情:\n")
      for (i in seq_along(valid_res)) {
        marker <- if (i == best_idx) " ⭐" else ""
        constraint_mark <- if (!is.null(min_clusters) && valid_n_clusters[i] < min_clusters) " (不满足约束)" else ""
        cat(sprintf(
          "    分辨率 %.2f: 轮廓系数=%.3f, 簇数=%d%s%s\n",
          valid_res[i], valid_sil[i], valid_n_clusters[i], constraint_mark, marker
        ))
      }

      cat("═══════════════════════════════════════\n\n")

      df <- data.frame(Resolution = resolutions, Silhouette = sil, N_Clusters = n_clusters_vec)

      cat("最佳分辨率:", best_res, "簇数:", best_n_clusters, "\n")
      cat("轮廓系数计算完成\n")

      list(best_resolution = best_res, silhouette_data = df, best_n_clusters = best_n_clusters)
    },
    error = function(e) {
      cat("轮廓系数计算错误:", e$message, "\n")
      return(NULL)
    }
  )
}

# 最佳分辨率可视化函数
create_best_resolution_plot <- function(pbmc) {
  tryCatch(
    {
      # 获取聚类信息
      clusters <- pbmc$seurat_clusters
      if (is.null(clusters)) {
        return(NULL)
      }

      # 计算每个聚类的细胞数
      cluster_counts <- as.data.frame(table(clusters))
      colnames(cluster_counts) <- c("Cluster", "CellCount")

      # 计算每个聚类的平均表达量
      if ("percent.mt" %in% colnames(pbmc@meta.data)) {
        mt_data <- pbmc@meta.data[, c("seurat_clusters", "percent.mt")]
        colnames(mt_data) <- c("Cluster", "PercentMT")
        cluster_mt <- aggregate(PercentMT ~ Cluster, data = mt_data, FUN = mean)

        # 创建综合可视化
        p1 <- ggplot(cluster_counts, aes(x = Cluster, y = CellCount, fill = Cluster)) +
          geom_bar(stat = "identity") +
          labs(title = "聚类细胞数分布", x = "聚类", y = "细胞数") +
          theme_minimal() +
          theme(axis.text.x = element_text(angle = 45, hjust = 1))

        p2 <- ggplot(cluster_mt, aes(x = Cluster, y = PercentMT, fill = Cluster)) +
          geom_bar(stat = "identity") +
          labs(title = "聚类线粒体基因含量", x = "聚类", y = "线粒体基因百分比 (%)") +
          theme_minimal() +
          theme(axis.text.x = element_text(angle = 45, hjust = 1))

        # 合并图表
        combined_plot <- p1 + p2 + plot_layout(ncol = 2)
        return(ggplotly(combined_plot, height = 700))
      } else {
        # 如果没有线粒体基因数据，只显示细胞数分布
        p <- ggplot(cluster_counts, aes(x = Cluster, y = CellCount, fill = Cluster)) +
          geom_bar(stat = "identity") +
          labs(title = "最佳分辨率分析 - 聚类细胞数分布", x = "聚类", y = "细胞数") +
          theme_minimal() +
          theme(axis.text.x = element_text(angle = 45, hjust = 1))

        return(ggplotly(p, height = 700))
      }
    },
    error = function(e) {
      return(NULL)
    }
  )
}

# 质控分析函数
create_qc_summary <- function(pbmc) {
  qc_data <- data.frame(
    nFeature_RNA = pbmc$nFeature_RNA,
    nCount_RNA   = pbmc$nCount_RNA,
    percent_mt   = pbmc$percent.mt
  )
  list(
    nFeature_RNA = quantile(qc_data$nFeature_RNA, probs = c(0.01, 0.05, 0.95, 0.99), na.rm = TRUE),
    nCount_RNA   = quantile(qc_data$nCount_RNA, probs = c(0.01, 0.05, 0.95, 0.99), na.rm = TRUE),
    percent_mt   = quantile(qc_data$percent_mt, probs = c(0.95, 0.99), na.rm = TRUE)
  )
}

backup_qc_filter <- function(pbmc) {
  qc <- create_qc_summary(pbmc)
  # 【修复】添加nCount_min参数，基于5%分位数
  nFeature_min <- max(200, round(qc$nFeature_RNA[2] * 0.9)) # 5%分位数的90%
  nFeature_max <- round(qc$nFeature_RNA[3] * 1.1) # 95%分位数的110%
  nCount_min <- max(500, round(qc$nCount_RNA[2] * 0.9)) # 5%分位数的90%
  nCount_max <- round(qc$nCount_RNA[3] * 1.1) # 95%分位数的110%
  mt_threshold <- min(30, round(qc$percent_mt[1] * 1.2)) # 95%分位数的120%
  sprintf(
    "pbmc <- subset(pbmc, nFeature_RNA > %d & nFeature_RNA < %d & nCount_RNA > %d & nCount_RNA < %d & percent.mt < %.1f)",
    nFeature_min, nFeature_max, nCount_min, nCount_max, mt_threshold
  )
}

