            br(),
            tags$script(HTML("
                    // 跟踪手动路径检测状态 - 全局变量
                    var manualPathDetected = false;

                    $(document).ready(function() {
                      // 监听目录选择和手动路径状态
                      var checkDirectorySelection = function() {
                        var directoryPath = $('#directory_path').text();
                        var manualPathInput = $('#manual_path');
                        var useManualPathBtn = $('#use_manual_path');
                        var directoryBtn = $('#directory-button-container').find('button').first();

                        console.log('检查目录选择状态:', directoryPath, manualPathInput.val(), manualPathDetected);

                        // 检查是否是手动路径检测成功状态
                        if (directoryPath && manualPathInput.val() && directoryPath.includes(manualPathInput.val()) && manualPathInput.val().trim() !== '') {
                          manualPathDetected = true;
                          console.log('设置为手动路径检测成功状态');
                        } else if (directoryPath && directoryPath.includes('请选择数据目录')) {
                          manualPathDetected = false;
                          console.log('重置手动路径检测状态');
                        }

                        if (manualPathDetected) {
                          // 手动路径检测成功：禁用选择目录按钮，启用手动路径功能
                          console.log('应用手动路径检测成功状态');
                          if (directoryBtn.length) {
                            directoryBtn.css('opacity', '0.5');
                            directoryBtn.css('pointer-events', 'none');
                            directoryBtn.prop('disabled', true);
                            console.log('已禁用选择目录按钮');
                          }
                          manualPathInput.css('opacity', '1');
                          manualPathInput.css('pointer-events', 'auto');
                          manualPathInput.prop('disabled', false);
                          useManualPathBtn.css('opacity', '1');
                          useManualPathBtn.css('pointer-events', 'auto');
                          useManualPathBtn.prop('disabled', false);
                          console.log('已启用手动路径功能');
                        } else if (directoryPath && !directoryPath.includes('请选择数据目录') && directoryPath.trim() !== '') {
                          // 已选择目录：禁用手动路径功能，启用选择目录按钮
                          console.log('应用已选择目录状态');
                          if (directoryBtn.length) {
                            directoryBtn.css('opacity', '1');
                            directoryBtn.css('pointer-events', 'auto');
                            directoryBtn.prop('disabled', false);
                            console.log('已启用选择目录按钮');
                          }
                          manualPathInput.css('opacity', '0.5');
                          manualPathInput.css('pointer-events', 'none');
                          manualPathInput.prop('disabled', true);
                          useManualPathBtn.css('opacity', '0.5');
                          useManualPathBtn.css('pointer-events', 'none');
                          useManualPathBtn.prop('disabled', true);
                          console.log('已禁用手动路径功能');
                        } else {
                          // 初始状态：检查手动路径是否为空
                          console.log('应用初始状态');
                          var manualPathValue = manualPathInput.val() ? manualPathInput.val().trim() : '';

                          if (manualPathValue !== '') {
                            // 手动路径不为空：禁用选择目录按钮
                            console.log('手动路径不为空，禁用选择目录按钮');
                            if (directoryBtn.length) {
                              directoryBtn.css('opacity', '0.5');
                              directoryBtn.css('pointer-events', 'none');
                              directoryBtn.prop('disabled', true);
                              console.log('已禁用选择目录按钮');
                            }
                            manualPathInput.css('opacity', '1');
                            manualPathInput.css('pointer-events', 'auto');
                            manualPathInput.prop('disabled', false);
                            useManualPathBtn.css('opacity', '1');
                            useManualPathBtn.css('pointer-events', 'auto');
                            useManualPathBtn.prop('disabled', false);
                            console.log('已启用手动路径功能');
                          } else {
                            // 手动路径为空：启用所有功能
                            console.log('手动路径为空，启用所有功能');
                            if (directoryBtn.length) {
                              directoryBtn.css('opacity', '1');
                              directoryBtn.css('pointer-events', 'auto');
                              directoryBtn.prop('disabled', false);
                              console.log('已启用选择目录按钮');
                            }
                            manualPathInput.css('opacity', '1');
                            manualPathInput.css('pointer-events', 'auto');
                            manualPathInput.prop('disabled', false);
                            useManualPathBtn.css('opacity', '1');
                            useManualPathBtn.css('pointer-events', 'auto');
                            useManualPathBtn.prop('disabled', false);
                            console.log('已启用手动路径功能');
                          }
                        }
                      };

                      // 监听手动路径检测按钮点击
                      $(document).on('click', '#use_manual_path', function() {
                        // 延迟检查，等待服务器响应
                        setTimeout(function() {
                          checkDirectorySelection();
                        }, 1000);
                      });

                      // 初始检查
                      setTimeout(checkDirectorySelection, 500);

                      // 监听目录路径变化
                      setInterval(checkDirectorySelection, 1000);

                      // 监听手动路径输入框变化，实时更新按钮状态
                      $(document).on('input', '#manual_path', function() {
                        setTimeout(checkDirectorySelection, 100);
                      });

                      // 修改文件选择弹窗语言
                      $(document).on('shown.bs.modal', function() {
                        // 修改文件选择弹窗的按钮文字
                        setTimeout(function() {
                          $('.modal-footer button:first').text('Cancel');
                          $('.modal-footer button:last').text('OK');
                          $('.modal-title').text('Select Directory');
                        }, 100);
                      });
                    });
                  ")),
