  # ==== AURA2.0 分析函数 ====

  # 获取标记基因函数（优化版）
  GetMarkers <- function(seurat_obj, cluster_id, top_n = 20) {
    tryCatch(
      {
        # 检查是否有聚类信息
        if (!"seurat_clusters" %in% colnames(seurat_obj@meta.data)) {
          cat("Seurat对象中没有seurat_clusters列\n")
          return(NULL)
        }

        # 检查cluster_id是否有效
        unique_clusters <- unique(seurat_obj@meta.data$seurat_clusters)
        if (!(cluster_id %in% unique_clusters)) {
          cat("cluster_id", cluster_id, "不在可用的簇中:", paste(unique_clusters, collapse = ", "), "\n")
          return(NULL)
        }

        # 静默模式下精简输出
        if (!QUIET_DATABASE_QUERIES) {
          cat("开始获取簇", cluster_id, "的标记基因\n")
          cat("可用的簇:", paste(unique_clusters, collapse = ", "), "\n")
        }

        # ========== 🎯 改进1.1：分层参数策略 ==========
        # 计算当前簇的细胞数
        cluster_cells <- sum(seurat_obj@meta.data$seurat_clusters == cluster_id)
        if (!QUIET_DATABASE_QUERIES) cat("簇", cluster_id, "包含", cluster_cells, "个细胞\n")

        # 根据簇大小自适应选择参数
        if (cluster_cells >= 100) {
          # 大簇（>=100细胞）：标准参数
          min_pct_param <- 0.15
          logfc_param <- 0.25
          min_diff_pct_param <- 0.10
          strategy <- "标准参数（大簇）"
        } else if (cluster_cells >= 30) {
          # 中簇（30-99细胞）：宽松参数
          min_pct_param <- 0.10
          logfc_param <- 0.20
          min_diff_pct_param <- 0.08
          strategy <- "宽松参数（中簇）"
        } else if (cluster_cells >= 15) {
          # 小簇（15-29细胞）：更宽松参数
          min_pct_param <- 0.08
          logfc_param <- 0.15
          min_diff_pct_param <- 0.05
          strategy <- "更宽松参数（小簇）"
        } else {
          # 极小簇（<15细胞）：极宽松参数
          min_pct_param <- 0.05
          logfc_param <- 0.10
          min_diff_pct_param <- 0.03
          strategy <- "极宽松参数（极小簇）"
        }

        if (!QUIET_DATABASE_QUERIES) {
          cat("使用策略：", strategy, "\n")
          cat("  min.pct =", min_pct_param, "\n")
          cat("  logfc.threshold =", logfc_param, "\n")
          cat("  min.diff.pct =", min_diff_pct_param, "\n")
        }
        # ===============================================

        # 使用FindMarkers代替FindAllMarkers，提高效率
        if (!QUIET_DATABASE_QUERIES) cat("运行FindMarkers获取簇", cluster_id, "的标记基因...\n")

        # 添加超时保护
        setTimeLimit(cpu = 15, elapsed = 30, transient = TRUE)
        on.exit(setTimeLimit(cpu = Inf, elapsed = Inf, transient = TRUE))

        markers <- tryCatch({
          # 使用分层参数策略
          FindMarkers(seurat_obj,
            ident.1 = cluster_id,
            only.pos = TRUE,
            min.pct = min_pct_param, # 🎯 自适应参数
            logfc.threshold = logfc_param, # 🎯 自适应参数
            min.diff.pct = min_diff_pct_param, # 🎯 新增：要求簇间差异
            test.use = "wilcox",
            min.cells.feature = max(3, round(cluster_cells * 0.05)), # 至少5%细胞表达
            min.cells.group = max(3, round(cluster_cells * 0.05)),
            verbose = FALSE
          )
        }, error = function(e) {
          cat("FindMarkers超时或失败:", e$message, "\n")
          cat("尝试使用更宽松的参数重新计算...\n")

          # 第二次尝试：在原有参数基础上进一步放宽
          tryCatch({
            setTimeLimit(cpu = 10, elapsed = 20, transient = TRUE)
            on.exit(setTimeLimit(cpu = Inf, elapsed = Inf, transient = TRUE))

            # 🎯 改进：第二次尝试的参数比第一次更宽松
            fallback_min_pct <- max(0.03, min_pct_param * 0.5) # 减半，但不低于3%
            fallback_logfc <- max(0.08, logfc_param * 0.6) # 降低40%

            cat("使用回退策略：\n")
            cat("  min.pct =", fallback_min_pct, "\n")
            cat("  logfc.threshold =", fallback_logfc, "\n")

            FindMarkers(seurat_obj,
              ident.1 = cluster_id,
              only.pos = TRUE,
              min.pct = fallback_min_pct, # 🎯 动态回退参数
              logfc.threshold = fallback_logfc, # 🎯 动态回退参数
              test.use = "wilcox",
              min.cells.feature = 1, # 最低要求
              min.cells.group = 1, # 最低要求
              verbose = FALSE
            )
          }, error = function(e2) {
            cat("第二次FindMarkers尝试也失败:", e2$message, "\n")
            # 如果还是失败，使用简单的差异表达计算
            return(NULL)
          }, finally = {
            setTimeLimit(cpu = Inf, elapsed = Inf, transient = TRUE)
          })
        }, finally = {
          setTimeLimit(cpu = Inf, elapsed = Inf, transient = TRUE)
        })

        if (!QUIET_DATABASE_QUERIES) cat("FindMarkers完成，找到", nrow(markers), "个标记基因\n")

        if (is.null(markers) || nrow(markers) == 0) {
          cat("簇", cluster_id, "没有找到标记基因，使用备用方法\n")

          # 使用备用方法：基于平均表达量的简单标记基因识别
          tryCatch(
            {
              # 获取当前簇和其他簇的表达数据
              current_cluster_cells <- colnames(seurat_obj)[seurat_obj$seurat_clusters == cluster_id]
              other_cluster_cells <- colnames(seurat_obj)[seurat_obj$seurat_clusters != cluster_id]

              if (length(current_cluster_cells) > 0 && length(other_cluster_cells) > 0) {
                # 计算平均表达量
                current_expr <- rowMeans(GetAssayData(seurat_obj, slot = "data")[, current_cluster_cells])
                other_expr <- rowMeans(GetAssayData(seurat_obj, slot = "data")[, other_cluster_cells])

                # 计算折叠变化
                fold_change <- current_expr / (other_expr + 0.01)

                # 筛选高表达基因
                high_expr_genes <- names(fold_change[fold_change > 2 & current_expr > 0.1])

                if (length(high_expr_genes) > 0) {
                  # 创建简单的标记基因数据框
                  markers <- data.frame(
                    p_val = rep(0.001, length(high_expr_genes)),
                    p_val_adj = rep(0.001, length(high_expr_genes)),
                    avg_log2FC = log2(fold_change[high_expr_genes]),
                    pct.1 = rep(0.8, length(high_expr_genes)),
                    pct.2 = rep(0.1, length(high_expr_genes)),
                    p_val_drop = rep(0.001, length(high_expr_genes))
                  )
                  rownames(markers) <- high_expr_genes
                  cat("备用方法找到", nrow(markers), "个标记基因\n")
                }
              }
            },
            error = function(e) {
              cat("备用方法也失败:", e$message, "\n")
            }
          )

          # 如果还是失败，启用智能降级策略
          if (is.null(markers) || nrow(markers) == 0) {
            cat("启用智能降级策略\n")

            # 智能降级策略1：使用更简单的统计方法
            tryCatch(
              {
                cat("尝试基于表达量的智能筛选...\n")

                # 获取标准化表达数据
                expr_data <- GetAssayData(seurat_obj, slot = "data")
                cluster_ids <- seurat_obj$seurat_clusters

                # 计算每个基因在当前簇的平均表达量
                current_cluster_expr <- rowMeans(expr_data[, cluster_ids == cluster_id, drop = FALSE])
                other_clusters_expr <- rowMeans(expr_data[, cluster_ids != cluster_id, drop = FALSE])

                # 计算表达倍数和特异性
                fold_change <- current_cluster_expr / (other_clusters_expr + 0.01)
                specificity <- current_cluster_expr / (current_cluster_expr + other_clusters_expr + 0.01)

                # 筛选高表达且特异的基因
                high_expr_genes <- names(which(current_cluster_expr > 0.2))
                specific_genes <- names(which(specificity > 0.6))

                # 取交集
                candidate_genes <- intersect(high_expr_genes, specific_genes)

                if (length(candidate_genes) > 0) {
                  # 按fold_change排序
                  candidate_genes <- candidate_genes[order(fold_change[candidate_genes], decreasing = TRUE)]

                  # 取前top_n个基因
                  top_genes <- head(candidate_genes, top_n)

                  # 创建标记基因数据框
                  markers <- data.frame(
                    p_val = rep(0.001, length(top_genes)),
                    p_val_adj = rep(0.001, length(top_genes)),
                    avg_log2FC = log2(fold_change[top_genes] + 0.01),
                    pct.1 = current_cluster_expr[top_genes],
                    pct.2 = other_clusters_expr[top_genes],
                    p_val_drop = rep(0.001, length(top_genes))
                  )
                  rownames(markers) <- top_genes

                  cat("智能降级策略成功找到", nrow(markers), "个标记基因\n")
                  cat("前5个标记基因:", paste(head(top_genes, 5), collapse = ", "), "\n")
                }
              },
              error = function(e) {
                cat("智能降级策略1失败:", e$message, "\n")
              }
            )

            # 如果还是失败，使用基于方差的方法
            if (is.null(markers) || nrow(markers) == 0) {
              tryCatch(
                {
                  cat("尝试基于方差的智能筛选...\n")

                  # 计算每个基因在所有细胞中的表达方差
                  expr_data <- GetAssayData(seurat_obj, slot = "data")
                  gene_variance <- apply(expr_data, 1, var)

                  # 筛选高方差基因
                  high_var_genes <- names(which(gene_variance > quantile(gene_variance, 0.8, na.rm = TRUE)))

                  # 计算这些基因在当前簇的表达情况
                  current_cluster_cells <- colnames(seurat_obj)[seurat_obj$seurat_clusters == cluster_id]
                  if (length(current_cluster_cells) > 0) {
                    current_expr <- rowMeans(expr_data[, current_cluster_cells, drop = FALSE])
                    high_expr_in_cluster <- names(which(current_expr > 0.1))

                    # 取交集
                    candidate_genes <- intersect(high_var_genes, high_expr_in_cluster)

                    if (length(candidate_genes) > 0) {
                      # 按表达量排序
                      candidate_genes <- candidate_genes[order(current_expr[candidate_genes], decreasing = TRUE)]
                      top_genes <- head(candidate_genes, top_n)

                      markers <- data.frame(
                        p_val = rep(0.001, length(top_genes)),
                        p_val_adj = rep(0.001, length(top_genes)),
                        avg_log2FC = rep(1.0, length(top_genes)),
                        pct.1 = current_expr[top_genes],
                        pct.2 = rep(0.1, length(top_genes)),
                        p_val_drop = rep(0.001, length(top_genes))
                      )
                      rownames(markers) <- top_genes

                      cat("基于方差的智能筛选找到", nrow(markers), "个标记基因\n")
                      cat("前5个标记基因:", paste(head(top_genes, 5), collapse = ", "), "\n")
                    }
                  }
                },
                error = function(e) {
                  cat("基于方差的智能筛选失败:", e$message, "\n")
                }
              )
            }
          }

          # 最终检查：如果仍然没有标记基因，才返回NULL（而不是假基因）
          if (is.null(markers) || nrow(markers) == 0) {
            cat("警告：所有智能降级策略都失败，无法获取真实的标记基因\n")
            return(NULL)
          }
        }

        # 检查必需的列是否存在
        required_cols <- c("p_val_adj")
        if (!all(required_cols %in% colnames(markers))) {
          cat("markers数据框缺少必需的列:", paste(setdiff(required_cols, colnames(markers)), collapse = ", "), "\n")
          cat("可用列:", paste(colnames(markers), collapse = ", "), "\n")
          return(NULL)
        }

        # 按p值排序并取前top_n个
        markers <- markers[order(markers$p_val_adj), ]
        top_markers_df <- head(markers, top_n)
        top_markers_df$gene <- rownames(top_markers_df)

        if (!QUIET_DATABASE_QUERIES) cat("成功获取", nrow(top_markers_df), "个标记基因:", paste(rownames(top_markers_df), collapse = ", "), "\n")
        return(top_markers_df) # 返回完整数据框而不是只返回基因名
      },
      error = function(e) {
        cat("获取标记基因失败:", e$message, "\n")
        # 打印更详细的错误信息
        cat("错误堆栈:\n")
        cat(conditionMessage(e), "\n")
        return(NULL)
      }
    )
  }

  # STRINGdb分析函数
  run_stringdb_analysis <- function(markers, parallel_env = NULL) {
    tryCatch(
      {
        if (!requireNamespace("STRINGdb", quietly = TRUE)) {
          cat("STRINGdb包未安装\n")
          return(NULL)
        }

        # 过滤有效的基因符号
        valid_genes <- markers[markers %in% c(
          "CD3D", "CD3E", "CD8A", "CD4", "CD19", "CD14", "MS4A1",
          "FCGR3A", "NCAM1", "PTPRC", "CD68", "CD163",
          "CD79A", "CD79B", "CD38", "CD27", "CD28",
          "ICOS", "CTLA4", "FOXP3", "IL7R", "CCR7",
          "SELL", "LEF1", "TCF7", "GATA3", "TBX21",
          "RORC", "FOXP3", "BCL2", "BCL6", "IRF4"
        )]

        if (length(valid_genes) < 3) {
          cat("STRINGdb分析：有效基因数不足\n")
          return(NULL)
        }

        cat("开始STRINGdb分析，输入基因:", length(valid_genes), "\n")

        # 初始化STRINGdb
        string_db <- STRINGdb$new(version = "11.5", species = 9606, score_threshold = 400)

        # 映射基因
        gene_mapping <- string_db$map(data.frame(gene = valid_genes), "gene", removeUnmappedRows = TRUE)

        if (nrow(gene_mapping) < 3) {
          cat("STRINGdb分析：映射成功基因数不足\n")
          return(NULL)
        }

        # 获取互作关系
        interactions <- string_db$get_interactions(gene_mapping$STRING_id)

        if (nrow(interactions) == 0) {
          cat("STRINGdb分析：未找到互作关系\n")
          return(NULL)
        }

        # 生成网络图（简化版本）
        network_plot <- paste0(
          "<div style='text-align: center; padding: 20px; background-color: #f8f9fa; border-radius: 8px;'>",
          "<strong>STRINGdb蛋白质互作网络</strong><br>",
          "<small>节点数: ", nrow(gene_mapping), " | 边数: ", nrow(interactions), "</small><br>",
          "<small>平均置信度: ", round(mean(interactions$combined_score), 2), "</small>",
          "</div>"
        )

        # 准备Top互作关系表格
        top_interactions <- head(interactions[order(interactions$combined_score, decreasing = TRUE), ], 10)
        if (nrow(top_interactions) > 0) {
          # 添加基因名称
          gene_names <- gene_mapping[, c("STRING_id", "gene")]
          colnames(gene_names) <- c("from", "from_gene")
          top_interactions <- merge(top_interactions, gene_names, by = "from")

          gene_names <- gene_mapping[, c("STRING_id", "gene")]
          colnames(gene_names) <- c("to", "to_gene")
          top_interactions <- merge(top_interactions, gene_names, by = "to")

          top_interactions <- top_interactions[, c("from_gene", "to_gene", "combined_score")]
          colnames(top_interactions) <- c("基因1", "基因2", "置信度")
        }

        result <- list(
          input_genes = length(valid_genes),
          mapped_genes = nrow(gene_mapping),
          interactions = nrow(interactions),
          avg_confidence = mean(interactions$combined_score),
          network_plot = network_plot,
          top_interactions = top_interactions,
          timestamp = format(Sys.time(), "%Y-%m-%d %H:%M:%S")
        )

        cat("STRINGdb分析完成，找到", nrow(interactions), "个互作关系\n")
        return(result)
      },
      error = function(e) {
        cat("STRINGdb分析失败:", e$message, "\n")
        return(NULL)
      }
    )
  }

  # gprofiler2分析函数（简化版）
  run_gprofiler_analysis <- function(markers, parallel_env = NULL, log_file = NULL) {
    tryCatch(
      {
        timer <- start_timer("gprofiler2查询")

        # 控制台和日志头部
        log_separator("🧬 gprofiler2 GO/Reactome/HP 富集分析", log_file)
        log_info(sprintf("📥 输入基因: %d个", length(markers)), log_file)
        log_debug(sprintf("  → %s", paste(head(markers, 10), collapse = ", ")), log_file)
        if (length(markers) > 10) {
          log_debug(sprintf("  ... 及其他%d个基因", length(markers) - 10), log_file)
        }


        # 检查包安装
        if (!requireNamespace("gprofiler2", quietly = TRUE)) {
          log_error("✗ gprofiler2包未安装", log_file)
          log_debug("建议: install.packages('gprofiler2')", log_file)
          stop_timer(timer, log_file)
          log_separator(NULL, log_file)
          return(NULL)
        }

        log_debug("", log_file)
        log_debug("📡 准备API查询...", log_file)
        log_debug("  → 数据源: GO + Reactome + HP", log_file)
        log_debug("  → 校正方法: FDR", log_file)
        log_debug("  → 物种: Homo sapiens", log_file)
        log_debug("  → 超时设置: 5秒（快速检测）", log_file)

        # ===== 增强：带超时控制的API调用 =====
        log_info("", log_file)
        log_info("🔄 调用gprofiler2 API (超时5秒)...", log_file)

        gost_result <- NULL
        max_attempts <- 1 # 只尝试1次，快速失败
        timeouts <- c(5) # 5秒超时

        for (attempt in 1:max_attempts) {
          api_start_time <- Sys.time()

          # 保存当前curl选项（在循环外定义）
          old_timeout <- getOption("timeout")

          result_attempt <- tryCatch(
            {
              # 设置curl超时（gprofiler2使用httr，httr使用curl）
              options(timeout = timeouts[attempt])

              # 设置httr的全局配置
              if (requireNamespace("httr", quietly = TRUE)) {
                httr::set_config(httr::timeout(timeouts[attempt]))
              }

              # 调用gprofiler2
              result <- gprofiler2::gost(markers,
                organism = "hsapiens",
                sources = c("GO", "REAC", "HP"),
                significant = TRUE,
                correction_method = "fdr"
              )

              # 恢复原选项
              options(timeout = old_timeout)
              if (requireNamespace("httr", quietly = TRUE)) {
                httr::reset_config()
              }

              result
            },
            error = function(e) {
              # 恢复原选项
              tryCatch(
                {
                  options(timeout = old_timeout)
                  if (requireNamespace("httr", quietly = TRUE)) {
                    httr::reset_config()
                  }
                },
                error = function(e2) {
                  # 忽略恢复错误
                }
              )

              elapsed <- as.numeric(difftime(Sys.time(), api_start_time, units = "secs"))

              if (grepl("timeout|timed out|Timeout|connect", e$message, ignore.case = TRUE)) {
                log_warn(sprintf("⚠ 第%d次尝试超时 (%.1f秒)", attempt, elapsed), log_file)
              } else {
                log_error(sprintf("✗ 第%d次尝试错误 (%.1f秒): %s", attempt, elapsed, e$message), log_file)
              }
              NULL
            }
          )

          # 如果成功获取结果，跳出循环
          if (!is.null(result_attempt)) {
            gost_result <- result_attempt
            elapsed <- as.numeric(difftime(Sys.time(), api_start_time, units = "secs"))
            log_info(sprintf("✓ API调用成功 (%.1f秒)", elapsed), log_file)
            break
          }

          # 如果还有重试机会，等待1秒后重试
          if (attempt < max_attempts) {
            log_info(sprintf("→ 等待1秒后进行第%d次重试...", attempt + 1), log_file)
            Sys.sleep(1)
          }
        }

        # 检测失败
        if (is.null(gost_result)) {
          log_warn("⚠ gprofiler2 API连接失败（可能因网络问题）", log_file)
          log_info("→ 跳过gprofiler2，继续使用其他数据库", log_file)
          stop_timer(timer, log_file)
          log_separator(NULL, log_file)
          return(NULL)
        }
        # ===== 增强结束 =====

        if (is.null(gost_result) || nrow(gost_result$result) == 0) {
          log_warn("⚠ gprofiler2: 未找到显著富集结果", log_file)
          log_debug("原因: API返回空结果", log_file)
          stop_timer(timer, log_file)
          log_separator(NULL, log_file)
          return(NULL)
        }

        # 提取显著结果
        log_debug("", log_file)
        log_debug("📋 解析API结果...", log_file)
        log_debug(sprintf("  → 原始结果数: %d条", nrow(gost_result$result)), log_file)

        significant_results <- gost_result$result[gost_result$result$p_value < 0.05, ]
        log_debug(sprintf("  → 显著结果 (p<0.05): %d条", nrow(significant_results)), log_file)

        if (nrow(significant_results) == 0) {
          log_warn("⚠ gprofiler2: 无显著富集结果 (p<0.05)", log_file)
          log_debug("建议: 输入基因可能无明显生物学功能关联", log_file)
          stop_timer(timer, log_file)
          log_separator(NULL, log_file)
          return(NULL)
        }

        # 按p值排序
        significant_results <- significant_results[order(significant_results$p_value), ]

        # 取Top 10
        top_terms <- head(significant_results, 10)

        # 控制台输出：Top 10功能
        log_info("", log_file)
        log_info(sprintf("✅ 找到 %d 个显著富集条目", nrow(significant_results)), log_file)
        log_info("🏆 Top 10 富集功能:", log_file)

        for (i in seq_len(min(10, nrow(significant_results)))) {
          term <- significant_results[i, ]

          if (i <= 3) {
            cat(sprintf("  %d. %s (p=%.2e)\n", i, term$term_name, term$p_value))
          }

          log_debug(sprintf("  %d. [%s] %s", i, term$source, term$term_name), log_file)
          log_debug(sprintf("     → p-value: %.2e", term$p_value), log_file)
          log_debug(sprintf("     → 富集基因数: %d/%d", term$intersection_size, term$term_size), log_file)
          log_trace(sprintf("     → Term ID: %s", term$term_id), log_file)
        }

        # 按数据源统计
        log_debug("", log_file)
        log_debug("📊 数据源分布:", log_file)
        source_counts <- table(significant_results$source)
        for (src in names(source_counts)) {
          src_name <- switch(src,
            "GO:BP" = "GO生物过程",
            "GO:MF" = "GO分子功能",
            "GO:CC" = "GO细胞组分",
            "REAC" = "Reactome通路",
            "HP" = "人类表型",
            src
          )
          log_debug(sprintf("  → %s: %d条", src_name, source_counts[src]), log_file)
        }

        # 最终摘要
        log_info("", log_file)
        log_info("🎯 gprofiler2富集摘要:", log_file)
        log_info(sprintf("  → 输入基因: %d个", length(markers)), log_file)
        log_info(sprintf("  → 显著条目: %d条", nrow(significant_results)), log_file)
        log_info(sprintf(
          "  → 最佳FDR: %.2e (%s)",
          min(significant_results$p_value),
          if (min(significant_results$p_value) < 0.001) "极高显著" else if (min(significant_results$p_value) < 0.01) "高显著" else "显著"
        ), log_file)
        log_debug(sprintf("  → 数据源覆盖: %s", paste(names(source_counts), collapse = ", ")), log_file)
        log_debug(sprintf("  → 最佳功能: %s", significant_results$term_name[1]), log_file)

        result <- list(
          input_genes = length(markers),
          significant_terms = nrow(significant_results),
          best_fdr = min(significant_results$p_value),
          top_terms = top_terms[, c("source", "term_name", "p_value", "term_size", "intersection_size")],
          source_distribution = as.list(source_counts),
          timestamp = format(Sys.time(), "%Y-%m-%d %H:%M:%S")
        )

        stop_timer(timer, log_file)
        log_separator(NULL, log_file)
        return(result)
      },
      error = function(e) {
        log_error(sprintf("✗ gprofiler2分析异常: %s", e$message), log_file)
        log_trace(sprintf("  错误堆栈: %s", paste(as.character(sys.calls()), collapse = " -> ")), log_file)

        # 判断错误类型
        if (grepl("timeout|connect|network", e$message, ignore.case = TRUE)) {
          log_debug("可能原因: 网络连接问题或gprofiler2服务器不可达", log_file)
          log_debug("建议: 1) 检查网络连接  2) 稍后重试  3) 设置HTTP代理", log_file)

          # 标记API不可用
          GPROFILER_API_STATUS$available <<- FALSE
          GPROFILER_API_STATUS$last_test_time <<- Sys.time()
          GPROFILER_API_STATUS$failed_count <<- GPROFILER_API_STATUS$failed_count + 1
        } else {
          log_debug("可能原因: 输入基因格式错误或gprofiler2包版本问题", log_file)
          log_debug("建议: 检查基因名称格式（应为大写基因符号）", log_file)
        }

        if (exists("timer")) stop_timer(timer, log_file)
        log_separator(NULL, log_file)
        return(NULL)
      }
    )
  }

  # clusterProfiler分析函数
  run_clusterprofiler_analysis <- function(markers, parallel_env = NULL, log_file = NULL) {
    tryCatch(
      {
        timer <- start_timer("clusterProfiler查询")

        # 控制台和日志头部
        log_separator("🧬 clusterProfiler KEGG通路富集分析", log_file)
        log_info(sprintf("📥 输入基因: %d个", length(markers)), log_file)
        log_debug(sprintf("  → %s", paste(head(markers, 10), collapse = ", ")), log_file)
        if (length(markers) > 10) {
          log_debug(sprintf("  ... 及其他%d个基因", length(markers) - 10), log_file)
        }

        # 检查包安装
        if (!requireNamespace("clusterProfiler", quietly = TRUE) ||
          !requireNamespace("org.Hs.eg.db", quietly = TRUE)) {
          log_error("✗ clusterProfiler或org.Hs.eg.db包未安装", log_file)
          log_debug("建议: BiocManager::install(c('clusterProfiler', 'org.Hs.eg.db'))", log_file)
          stop_timer(timer, log_file)
          log_separator(NULL, log_file)
          return(NULL)
        }

        # 基因ID转换
        log_debug("", log_file)
        log_debug("🔄 转换基因ID (SYMBOL → ENTREZID)...", log_file)

        gene_entrez <- clusterProfiler::bitr(markers,
          fromType = "SYMBOL", toType = "ENTREZID",
          OrgDb = "org.Hs.eg.db"
        )

        log_debug(sprintf(
          "✓ 转换完成: %d/%d基因成功 (%.1f%%)",
          nrow(gene_entrez),
          length(markers),
          nrow(gene_entrez) / length(markers) * 100
        ), log_file)

        if (nrow(gene_entrez) < 3) {
          log_warn("⚠ 转换成功基因数不足 (<3)", log_file)
          log_debug("原因: 输入基因符号无效或数据库未包含", log_file)
          stop_timer(timer, log_file)
          log_separator(NULL, log_file)
          return(NULL)
        }

        log_trace(sprintf(
          "  → 转换示例: %s",
          paste(sprintf("%s=%s", head(gene_entrez$SYMBOL, 3), head(gene_entrez$ENTREZID, 3)),
            collapse = ", "
          )
        ), log_file)

        # KEGG富集分析
        log_info("", log_file)
        log_info("🌐 调用KEGG API进行通路富集分析...", log_file)
        log_debug("→ 物种: Homo sapiens (hsa)", log_file)
        log_debug("→ p-value阈值: 0.05", log_file)
        log_debug(sprintf("→ 输入EntrezID数: %d", length(gene_entrez$ENTREZID)), log_file)

        kegg_result <- clusterProfiler::enrichKEGG(
          gene = gene_entrez$ENTREZID,
          organism = "hsa",
          pvalueCutoff = 0.05
        )

        log_debug("✓ KEGG API调用完成", log_file)

        if (is.null(kegg_result) || nrow(kegg_result) == 0) {
          log_warn("⚠ 未找到显著KEGG通路 (p<0.05)", log_file)
          log_debug("原因: 输入基因未富集在任何KEGG通路中", log_file)
          stop_timer(timer, log_file)
          log_separator(NULL, log_file)
          return(NULL)
        }

        log_debug("", log_file)
        log_debug("📋 解析KEGG结果...", log_file)
        log_debug(sprintf("→ 显著通路数: %d条", nrow(kegg_result)), log_file)

        # 按p值排序
        kegg_result <- kegg_result[order(kegg_result$pvalue), ]

        # 取Top 10
        top_pathways <- head(kegg_result, 10)

        # 控制台输出：Top 10通路
        log_info("", log_file)
        log_info(sprintf("✅ 找到 %d 个显著KEGG通路", nrow(kegg_result)), log_file)
        log_info("🏆 Top 10 KEGG通路:", log_file)

        for (i in seq_len(min(10, nrow(kegg_result)))) {
          pathway <- kegg_result[i, ]

          if (i <= 3) {
            cat(sprintf("  %d. %s (p=%.2e)\n", i, pathway$Description, pathway$pvalue))
          }

          log_debug(sprintf("  %d. [%s] %s", i, pathway$ID, pathway$Description), log_file)
          log_debug(sprintf("     → p-value: %.2e (adj: %.2e)", pathway$pvalue, pathway$p.adjust), log_file)
          log_debug(sprintf("     → 富集基因数: %s", pathway$Count), log_file)
          log_trace(sprintf(
            "     → 基因: %s",
            ifelse(nchar(pathway$geneID) > 50,
              paste0(substr(pathway$geneID, 1, 50), "..."),
              pathway$geneID
            )
          ), log_file)
        }

        # 统计信息
        avg_count <- mean(as.numeric(kegg_result$Count))
        median_pval <- median(kegg_result$pvalue)

        # 最终摘要
        log_info("", log_file)
        log_info("🎯 clusterProfiler KEGG分析摘要:", log_file)
        log_info(sprintf("  → 输入基因: %d个", length(markers)), log_file)
        log_info(sprintf(
          "  → 成功转换: %d个 (%.1f%%)",
          nrow(gene_entrez),
          nrow(gene_entrez) / length(markers) * 100
        ), log_file)
        log_info(sprintf("  → 显著通路: %d条", nrow(kegg_result)), log_file)
        log_info(sprintf(
          "  → 最佳p-value: %.2e (%s)",
          min(kegg_result$pvalue),
          if (min(kegg_result$pvalue) < 0.001) "极高显著" else if (min(kegg_result$pvalue) < 0.01) "高显著" else "显著"
        ), log_file)
        log_debug(sprintf("  → 平均富集基因数: %.1f", avg_count), log_file)
        log_debug(sprintf("  → 中p-value中位数: %.2e", median_pval), log_file)
        log_debug(sprintf("  → 最佳通路: %s", kegg_result$Description[1]), log_file)

        result <- list(
          input_genes = length(markers),
          mapped_genes = nrow(gene_entrez),
          conversion_rate = nrow(gene_entrez) / length(markers),
          significant_pathways = nrow(kegg_result),
          best_pvalue = min(kegg_result$pvalue),
          avg_gene_count = avg_count,
          median_pvalue = median_pval,
          top_pathways = top_pathways[, c("ID", "Description", "pvalue", "p.adjust", "geneID", "Count")],
          timestamp = format(Sys.time(), "%Y-%m-%d %H:%M:%S")
        )

        stop_timer(timer, log_file)
        log_separator(NULL, log_file)
        return(result)
      },
      error = function(e) {
        log_error(sprintf("✗ clusterProfiler分析异常: %s", e$message), log_file)
        log_trace(sprintf("  错误堆栈: %s", paste(as.character(sys.calls()), collapse = " -> ")), log_file)
        log_debug("可能原因: 网络连接失败、KEGG API不可用或基因ID转换错误", log_file)
        if (exists("timer")) stop_timer(timer, log_file)
        log_separator(NULL, log_file)
        return(NULL)
      }
    )
  }

