  # 禁用所有按钮的函数
  disable_all_buttons <- function(current_button = NULL) {
    # 使用isolate确保立即生效，不受响应式上下文影响
    isolate({
      # 降维分析按钮
      updateActionButton(session, "normalize_data", disabled = TRUE)
      updateActionButton(session, "find_variable_features", disabled = TRUE)
      updateActionButton(session, "scale_data", disabled = TRUE)
      updateActionButton(session, "run_pca", disabled = TRUE)
      updateActionButton(session, "run_harmony", disabled = TRUE)

      # 聚类分析按钮
      updateActionButton(session, "draw_elbow_plot", disabled = TRUE)
      updateActionButton(session, "get_clustering_recommendations", disabled = TRUE)
      updateActionButton(session, "run_clustering", disabled = TRUE)
      updateActionButton(session, "plot_clustree", disabled = TRUE)
      updateActionButton(session, "run_umap_tsne", disabled = TRUE)

      # 注释相关按钮
      updateActionButton(session, "get_annotation", disabled = TRUE)

      # 如果指定了当前按钮，保持其启用状态
      if (!is.null(current_button)) {
        updateActionButton(session, current_button, disabled = FALSE)
      }
    })
  }

  # 恢复按钮状态的函数 - 实现严格10按钮线性执行
  restore_button_states <- function() {
    # 使用isolate确保立即生效，不受响应式上下文影响
    isolate({
      # 严格10按钮线性执行逻辑 - 不能回退到之前步骤：
      # 1. 数据标准化 → 2. 寻找高变基因 → 3. 数据缩放 → 4. 运行PCA → 5. 运行Harmony →
      # 6. 绘制肘部图 → 7. 获取聚类建议 → 8. 运行聚类 → 9. 绘制聚类树 → 10. 运行UMAP/t-SNE

      # 降维分析按钮 - 严格线性控制，完成后禁用防止回退
      updateActionButton(session, "normalize_data", disabled = rv$normalize_done) # 完成后禁用
      updateActionButton(session, "find_variable_features", disabled = !rv$normalize_done || rv$find_variable_done) # 前一步完成才启用，完成后禁用
      updateActionButton(session, "scale_data", disabled = !rv$find_variable_done || rv$scale_done) # 前一步完成才启用，完成后禁用
      updateActionButton(session, "run_pca", disabled = !rv$scale_done || rv$pca_done) # 前一步完成才启用，完成后禁用
      updateActionButton(session, "run_harmony", disabled = !rv$pca_done || rv$harmony_done) # 前一步完成才启用，完成后禁用

      # 聚类分析按钮 - 需要Harmony/PCA完成后才能开始
      # 🎯 修改：肘部图和API推荐变为可选，只要降维完成就可以直接运行聚类
      updateActionButton(session, "draw_elbow_plot", disabled = (!rv$harmony_done && !rv$pca_done) || rv$elbow_done) # PCA或Harmony完成即可，完成后禁用
      updateActionButton(session, "get_clustering_recommendations", disabled = (!rv$harmony_done && !rv$pca_done) || rv$api_recommendations_done) # 🎯 改为：降维完成即可（不强制要求肘部图）
      updateActionButton(session, "run_clustering", disabled = (!rv$harmony_done && !rv$pca_done) || rv$clustering_run_done) # 🎯 改为：降维完成即可（不强制要求API推荐）
      updateActionButton(session, "plot_clustree", disabled = !rv$clustering_run_done || rv$clustree_plot_done) # 前一步完成才启用，完成后禁用
      updateActionButton(session, "run_umap_tsne", disabled = !rv$clustering_done || rv$umap_tsne_done) # 【修改】聚类完成即可，不需要先绘制聚类树

      # 注释相关按钮 - 严格线性控制
      updateActionButton(session, "get_annotation", disabled = !rv$umap_tsne_done || isTRUE(rv$annotation_done)) # UMAP完成才启用，完成后禁用
    })
  }

