    updateActionButton(session, "scale_data", icon = icon("balance-scale-right"), disabled = TRUE)
    updateActionButton(session, "run_pca", icon = icon("project-diagram"), disabled = TRUE)
    updateActionButton(session, "run_harmony", icon = icon("balance-scale"), disabled = TRUE)

    # 聚类分析按钮初始化 - 需要Harmony完成后才能开始
    updateActionButton(session, "draw_elbow_plot", icon = icon("chart-line"), disabled = TRUE)
    updateActionButton(session, "get_clustering_recommendations", icon = icon("magic"), disabled = TRUE)
    updateActionButton(session, "run_clustering", icon = icon("object-group"), disabled = TRUE)
