  # API密钥配置UI（仅显示环境变量配置状态，不进行实际测试）
  output$api_keys_config_ui <- renderUI({
    # 检查每个模型的API密钥是否已配置（仅检查环境变量，不测试连接）
    check_api_key <- function(env_var) {
      key <- Sys.getenv(env_var)
      if (!is.null(key) && key != "") {
        return(list(status = "configured", message = "已配置 ✓", note = "(点击下方按钮测试连接)"))
      } else {
        return(list(status = "not_configured", message = "未配置 ○", note = "(请配置API密钥)"))
      }
    }

    get_status_class <- function(status) {
      if (status == "configured") {
        return("status-green")
      } else if (status == "tested") {
        return("status-green")
      } else if (status == "warning") {
        return("status-yellow")
      } else {
        return("status-gray")
      }
    }

    get_status_color <- function(status) {
      if (status == "configured") {
        return("#27ae60")
      } else if (status == "tested") {
        return("#27ae60")
      } else if (status == "warning") {
        return("#f39c12")
      } else {
        return("#95a5a6")
      }
    }

    # 检查所有10个模型的API密钥状态（仅环境变量检查）
    models_status <- list(
      list(name = "DeepSeek", env = "DEEPSEEK_API_KEY", info = check_api_key("DEEPSEEK_API_KEY")),
      list(name = "Kimi", env = "KIMI_API_KEY", info = check_api_key("KIMI_API_KEY")),
      list(name = "GLM-4.6", env = "GLM_API_KEY", info = check_api_key("GLM_API_KEY")),
      list(name = "豆包", env = "DOUBAO_API_KEY", info = check_api_key("DOUBAO_API_KEY")),
      list(name = "千问", env = "QWEN_API_KEY", info = check_api_key("QWEN_API_KEY")),
      list(name = "混元", env = "HUNYUAN_API_KEY", info = check_api_key("HUNYUAN_API_KEY")),
      list(name = "文心一言", env = "ERNIE_API_KEY", info = check_api_key("ERNIE_API_KEY")),
      list(name = "阶跃星辰", env = "STEPFUN_API_KEY", info = check_api_key("STEPFUN_API_KEY")),
      list(name = "讯飞星火", env = "SPARK_API_KEY", info = check_api_key("SPARK_API_KEY")),
      list(name = "Minimax", env = "MINIMAX_API_KEY", info = check_api_key("MINIMAX_API_KEY"))
    )

    tagList(
      div(
        style = "padding: 10px; background-color: #fff3cd; border: 1px solid #ffc107; border-radius: 5px; margin-bottom: 15px;",
        tags$small(
          style = "color: #856404;",
          "💡 提示：这里仅显示API密钥是否已配置（环境变量）。",
          tags$br(),
          "要测试实际连接，请点击下方的「测试所有API连接」按钮。"
        )
      ),
      lapply(models_status, function(model) {
        status_class <- get_status_class(model$info$status)
        status_color <- get_status_color(model$info$status)
        div(
          style = "margin-bottom: 10px;",
          div(
            style = "display: flex; align-items: center; margin-bottom: 5px;",
            tags$span(class = paste("status-indicator", status_class)),
            tags$strong(model$name, style = "flex: 1;"),
            tags$span(model$info$message, style = paste("color:", status_color, "; font-size: 12px; margin-right: 5px;"))
          ),
          if (!is.null(model$info$note)) {
            tags$small(
              style = paste("color: #6c757d; font-size: 10px; padding-left: 20px;"),
              model$info$note
            )
          }
        )
      })
    )
  })

  # 并行计算进度条
  output$parallel_progress_bar <- renderUI({
