  # ============================================================
  # API密钥警告（非阻塞通知）
  # ============================================================

  # 质控分析页面的API警告
  observeEvent(input$show_api_warning, {
    showNotification(
      "提示：未检测到API密钥。部分功能（如智能分辨率推荐）可能无法使用。您可以在系统设置页面配置API密钥。",
      type = "warning",
      duration = 8,
      closeButton = TRUE
    )
  })

  # 数据上传页面的API警告
  observeEvent(input$show_api_warning_upload, {
    showNotification(
      "提示：未检测到API密钥。部分功能（如智能分辨率推荐）可能无法使用。您可以在系统设置页面配置API密钥。",
      type = "warning",
      duration = 8,
      closeButton = TRUE
    )
  })

  # 手动路径选择
  observeEvent(input$use_manual_path, {
    if (is.null(input$manual_path) || input$manual_path == "") {
      showNotification("请输入有效的目录路径", type = "error")
      return()
    }

    # 验证路径是否存在
    if (!dir.exists(input$manual_path)) {
      showNotification("目录不存在，请检查路径", type = "error")
      return()
    }

    rv$manual_path <- input$manual_path
    rv$current_dir <- input$manual_path
    showNotification("手动路径设置成功", type = "message")
  })

  # 重置手动路径（当使用目录选择器时）
  observeEvent(input$directory, {
    if (!is.null(input$directory)) {
      rv$manual_path <- NULL
    }
  })

  # 原始按钮点击处理（检查目录选择状态）
  observeEvent(input$load_data, {
    # 检查是否已经选择了目录
    if (is.null(rv$manual_path) && is.null(input$directory)) {
      # 如果没有选择目录，显示提示弹窗
      showNotification(
        tags$div(
          tags$h4("请先选择目录"),
          tags$p("您还没有选择数据目录，请先选择目录文件再加载数据。"),
          tags$br(),
          tags$p("您可以通过以下方式选择目录："),
          tags$ul(
            tags$li("点击\"选择数据目录\"按钮浏览并选择目录"),
            tags$li("或者手动输入目录路径并点击\"检测手动路径是否正确\"")
          )
        ),
        type = "warning",
        duration = 8,
        closeButton = TRUE,
        id = "no-directory-warning"
      )
      return() # 不继续执行后续逻辑
    }

    # 如果已经选择了目录，继续原有的确认弹窗逻辑
    # 实际的数据加载逻辑在 input$load_data_confirmed 中处理
  })

  # 数据加载（监听确认事件）
  observeEvent(input$load_data_confirmed, {
    # 防止重复触发
    if (rv$load_data_triggered) {
      cat("数据加载已在进行中，跳过重复触发\n")
      return()
    }

    print_main_title("数据加载流程", 60)
    print_pipeline_progress(1) # 流程步骤1
    rv$load_data_triggered <- TRUE

    # 获取选择的目录路径
    dir_path <- NULL

    if (!is.null(rv$manual_path)) {
      dir_path <- rv$manual_path
      print_status("info", sprintf("数据路径: %s", dir_path))
    } else if (!is.null(input$directory)) {
      dir_path <- parseDirPath(volumes, input$directory)
      print_status("info", sprintf("数据路径: %s", dir_path))
    }

    # 验证是否选择了任何目录
    if (is.null(dir_path) || dir_path == "" || is.na(dir_path)) {
      showNotification("请先选择数据目录或输入手动路径", type = "error")
      print_status("error", "未选择任何数据目录")
      rv$load_data_triggered <- FALSE
      return()
    }

    # 如果是手动路径，检查是否已检测
    if (!is.null(rv$manual_path)) {
      # 检查手动路径是否与当前目录匹配
      if (is.null(rv$current_dir) || rv$current_dir != rv$manual_path) {
        showNotification("请先检测手动路径是否正确", type = "error")
        cat("错误: 手动路径未检测\n")
        rv$load_data_triggered <- FALSE
        return()
      }
    }

    # 验证目录路径是否有效
    if (is.null(dir_path) || !is.character(dir_path) || dir_path == "") {
      showNotification("目录路径无效", type = "error")
      rv$load_data_triggered <- FALSE
      return()
    }

    # 验证目录是否存在
    if (!dir.exists(dir_path)) {
      showNotification("目录不存在，请检查路径", type = "error")
      rv$load_data_triggered <- FALSE
      return()
    }

    rv$current_dir <- dir_path
    rv$loading_cancelled <- FALSE # 重置取消标志

    # 保存数据集路径并自动检测marker配置
    rv$current_dataset_path <- dir_path
    auto_markers <- auto_load_marker_config(dir_path)
    if (!is.null(auto_markers)) {
      rv$major_markers <- auto_markers
      rv$marker_config_auto_loaded <- TRUE
      rv$marker_config_source <- "LLM 结合知识库自主构建"
      showNotification("✓ 候选词表已由 LLM 结合五大知识库自主构建", type = "message", duration = 5)
      updateSelectInput(session, "marker_template", selected = "current")
    } else {
      rv$marker_config_auto_loaded <- FALSE
      rv$marker_config_source <- "默认"
      cat("ℹ️ 候选词表将由 LLM 结合知识库动态构建\n")
    }

    # 设置工作目录
    tryCatch(
      {
        setwd(dir_path)
        cat("当前工作目录:", getwd(), "\n")
      },
      error = function(e) {
        showNotification(paste("设置工作目录失败:", e$message), type = "error")
        rv$load_data_triggered <- FALSE
        return()
      }
    )

    # 查找样本文件夹（支持GSM样本编号、标准10X基因组名称、10X_format文件夹）
    all_dirs <- list.dirs(path = ".", recursive = FALSE, full.names = FALSE)
    # 匹配GSM开头的样本，或标准10X基因组名称（hg19, hg38, mm10, GRCh38等），或10X_format文件夹
    sample_dirs <- all_dirs[grep("^(GSM|hg19|hg38|mm10|mm9|GRCh38|GRCh37|GRCm38|10X_format)", all_dirs)]
    sample_dirs <- sort(sample_dirs)

    print_sub_title("样本扫描", 50)
    if (length(sample_dirs) > 0) {
      print_status("success", sprintf("发现 %d 个数据文件夹", length(sample_dirs)))
      for (i in seq_len(min(5, length(sample_dirs)))) {
        cat(sprintf("    %d. %s\n", i, sample_dirs[i]))
      }
      if (length(sample_dirs) > 5) {
        cat(sprintf("    ... 还有%d个样本\n", length(sample_dirs) - 5))
      }
    } else {
      print_status("error", "未找到数据文件夹（支持格式: GSM样本、10X标准文件夹如hg19/mm10、或10X_format文件夹）")
      showNotification("未找到数据文件夹，请检查目录中是否包含GSM样本、10X标准文件夹（如hg19/mm10）或10X_format文件夹", type = "error")
      rv$load_data_triggered <- FALSE
      return()
    }
    cat("\n")

    # 读取数据
    objs <- list()
    successful_samples <- 0
    total_samples <- length(sample_dirs)

    # 使用进度条显示数据加载进度
    withProgress(message = "正在加载数据...", value = 0, {
      # 使用更准确的进度更新
      start_time <- Sys.time()

      for (i in seq_along(sample_dirs)) {
        # 检查是否用户取消了加载
        if (rv$loading_cancelled) {
          cat("用户取消了数据加载，停止处理\n")
          showNotification("数据加载已取消", type = "warning")
          break # 使用break而不是return，以便正确关闭进度条
        }

        # 基于样本处理进度计算，更准确反映实际进度
        sample_progress <- 0.1 + (i - 1) / total_samples * 0.7
        # 计算完成百分比用于显示
        progress_percent <- round(sample_progress * 100)

        # 更新进度条
        incProgress(sample_progress, detail = paste("正在处理样本", i, "/", total_samples, "(", progress_percent, "%)"))

        # 检查样本文件夹结构（支持10X v2和v3格式）
        sample_path <- sample_dirs[i]

        cat(sprintf("  样本%d: %s [", i, sample_path))

        # 必须存在的文件
        essential_files <- c("matrix.mtx", "barcodes.tsv")

        # 检查必须文件是否存在（支持.gz压缩格式）
        files_exist <- sapply(essential_files, function(f) {
          compressed_exists <- file.exists(file.path(sample_path, paste0(f, ".gz")))
          uncompressed_exists <- file.exists(file.path(sample_path, f))
          compressed_exists || uncompressed_exists
        })

        # 检查基因/特征文件（v2用genes.tsv，v3用features.tsv）
        genes_exist <- file.exists(file.path(sample_path, "genes.tsv")) ||
          file.exists(file.path(sample_path, "genes.tsv.gz"))
        features_exist <- file.exists(file.path(sample_path, "features.tsv")) ||
          file.exists(file.path(sample_path, "features.tsv.gz"))
        gene_file_exist <- genes_exist || features_exist

        all_files_exist <- all(files_exist) && gene_file_exist

        # 显示检测进度
        total_checks <- length(essential_files) + 1
        passed_checks <- sum(files_exist) + as.numeric(gene_file_exist)
        cat(strrep("█", passed_checks), strrep("░", total_checks - passed_checks))
        cat(sprintf("] %d%%\n", round(passed_checks / total_checks * 100)))

        if (!all_files_exist) {
          missing <- c()
          if (!all(files_exist)) missing <- c(missing, essential_files[!files_exist])
          if (!gene_file_exist) missing <- c(missing, "genes.tsv或features.tsv")
          print_status("warning", sprintf("样本%s缺少文件: %s", sample_path, paste(missing, collapse = ", ")))
          showNotification(paste(
            "样本", sample_path, "缺少必要文件:",
            paste(missing, collapse = ", ")
          ), type = "warning")
          next
        }

        # 显示所有文件都存在
        for (f in essential_files) {
          compressed <- file.exists(file.path(sample_path, paste0(f, ".gz")))
          cat(sprintf("    ✓ %s%s\n", f, if (compressed) " (压缩)" else ""))
        }
        if (genes_exist) {
          compressed <- file.exists(file.path(sample_path, "genes.tsv.gz"))
          cat(sprintf("    ✓ genes.tsv%s (10X v2)\n", if (compressed) " (压缩)" else ""))
        } else if (features_exist) {
          compressed <- file.exists(file.path(sample_path, "features.tsv.gz"))
          cat(sprintf("    ✓ features.tsv%s (10X v3)\n", if (compressed) " (压缩)" else ""))
        }

        tryCatch(
          {
            # 读取数据
            mtx <- Read10X(sample_path)

            # 再次检查取消状态
            if (rv$loading_cancelled) {
              cat("用户取消了数据加载，停止处理样本\n")
              break # 使用break而不是return，以便正确关闭进度条
            }

            if (is.null(mtx)) {
              cat("样本", sample_path, "Read10X返回NULL\n")
              next
            }

            if (nrow(mtx) == 0 || ncol(mtx) == 0) {
              print_status("warning", sprintf("样本%s数据为空", sample_path))
              next
            }

            cat(sprintf(
              "    📊 数据大小: %s基因 × %s细胞\n",
              format(nrow(mtx), big.mark = ","),
              format(ncol(mtx), big.mark = ",")
            ))

            # 创建Seurat对象
            seurat_obj <- CreateSeuratObject(
              counts = mtx, project = paste0("sample_", i),
              min.cells = 3, min.features = 200
            )

            # 最终检查取消状态
            if (rv$loading_cancelled) {
              print_status("warning", "用户取消了数据加载")
              break # 使用break而不是return，以便正确关闭进度条
            }

            objs[[i]] <- seurat_obj
            successful_samples <- successful_samples + 1

            print_status("success", sprintf("样本%s处理完成", sample_path))
            cat("\n")
          },
          error = function(e) {
            showNotification(paste("读取样本", sample_path, "失败:", e$message), type = "error")
            cat("错误: 样本", sample_path, "-", e$message, "\n")
          }
        )

        # 强制垃圾回收
        if (i %% 5 == 0) {
          gc()
        }
      }

      if (length(objs) == 0) {
        print_status("error", "没有成功读取任何样本数据")
        showNotification("没有成功读取任何样本数据", type = "error")
        rv$load_data_triggered <- FALSE
        return()
      }

      # 合并数据
      print_sub_title("数据合并", 50)
      cat(sprintf("  合并样本数: %d\n", length(objs)))
      incProgress(0.8, detail = "正在合并数据...")

      merge_start_time <- Sys.time()
      tryCatch(
        {
          # 逐步合并数据
          pbmc <- objs[[1]]

          # 🎯 修复：只有多个样本时才合并
          if (length(objs) > 1) {
            for (i in 2:length(objs)) {
              # 检查是否用户取消了加载
              if (rv$loading_cancelled) {
                print_status("warning", "用户取消了数据加载")
                showNotification("数据加载已取消", type = "warning")
                break # 使用break而不是return，以便正确关闭进度条
              }

              if (!is.null(objs[[i]])) {
                pbmc <- merge(pbmc, objs[[i]])
              }
            }
          } else {
            print_status("info", "单样本数据，跳过合并步骤")
          }

          # 🎯 修复：只有多样本才需要JoinLayers
          if (length(objs) > 1) {
            print_status("info", "整理数据层...")
            pbmc <- JoinLayers(pbmc)
          }

          print_status("info", "计算线粒体基因百分比...")
          pbmc[["percent.mt"]] <- PercentageFeatureSet(pbmc, pattern = "^MT-")

          print_timing(merge_start_time, "数据合并")
          incProgress(0.9, detail = "正在完成数据加载...")
        },
        error = function(e) {
          showNotification(paste("数据合并失败:", e$message), type = "error")
          cat("合并错误:", e$message, "\n")
          rv$data_loaded <- FALSE
          pbmc <- NULL
          rv$load_data_triggered <- FALSE # 重置加载标志
        }
      )

      # 只有在合并成功后才设置pbmc对象
      if (!is.null(pbmc)) {
        rv$pbmc <- pbmc
        rv$pbmc_before_qc <- pbmc # 保存质控前的数据副本
        rv$data_loaded <- TRUE
      } else {
        rv$data_loaded <- FALSE
        rv$load_data_triggered <- FALSE
        return()
      }

      # 强制垃圾回收
      gc()

      # 只有在成功创建pbmc对象后才显示统计信息
      if (exists("pbmc") && !is.null(pbmc)) {
        # 显示数据统计信息
        print_main_title("数据加载完成", 60)
        cat("  📊 总计:\n")
        cat(sprintf("    • 细胞数: %s\n", format(ncol(pbmc), big.mark = ",")))
        cat(sprintf("    • 基因数: %s\n", format(nrow(pbmc), big.mark = ",")))
        cat(sprintf("    • 样本数: %d\n", length(unique(pbmc$orig.ident))))
        cat(sprintf("    • 平均细胞/样本: %s\n", format(round(ncol(pbmc) / length(unique(pbmc$orig.ident))), big.mark = ",")))
        print_separator("═", 60)
        cat("  ✅ 数据已加载到内存，可进行后续分析\n")
        cat("\n")

        showNotification(paste("数据加载成功！共", ncol(pbmc), "个细胞，", nrow(pbmc), "个基因"), type = "message")

        # 更新数据加载状态（用于JavaScript检查）
        session$sendCustomMessage("data_loaded_status", list(status = "数据加载成功"))

        # 自动设置质控前的可视化
        rv$qc_before_ready <- TRUE
      } else {
        showNotification("数据加载失败，请检查数据文件格式", type = "error")
        rv$data_loaded <- FALSE
        rv$load_data_triggered <- FALSE # 重置加载标志
        return()
      }

      # 成功完成，重置加载标志
      rv$load_data_triggered <- FALSE

      # 完成进度条
      incProgress(1.0, detail = "数据加载完成！")
    }) # 结束withProgress块

    # 检查是否用户取消了操作
    if (rv$loading_cancelled) {
      showNotification("数据加载已取消", type = "warning")
      rv$load_data_triggered <- FALSE
      return()
    }
  })

  # 监听进度条关闭事件
  observeEvent(input$progress_cancelled, {
    if (rv$loading_cancelled) {
      return
    }

    cat("用户通过进度条X取消了数据加载\n")
    rv$loading_cancelled <- TRUE
    showNotification("数据加载已取消", type = "warning")
  })

  # 原始重置按钮点击处理（仅用于触发确认弹窗）
  observeEvent(input$reset_data, {
    # 这个事件监听器仅用于确保按钮点击能触发确认弹窗
    # 实际的重置逻辑在 input$reset_data_confirmed 中处理
  })

  # 重置数据（监听确认事件，增强版，确保能中断正在进行的加载）
  observeEvent(input$reset_data_confirmed, {
    cat("重置数据...\n")
    rv$loading_cancelled <- TRUE # 设置取消标志

    # 延迟执行重置以确保取消操作被处理
    invalidateLater(100, session)

    # 执行重置操作
    rv$pbmc <- NULL
    rv$data_loaded <- FALSE
    rv$qc_done <- FALSE
    rv$qc_ready <- FALSE
    rv$qc_before_ready <- FALSE
    rv$dimred_done <- FALSE
    rv$clustering_done <- FALSE
    rv$annotation_done <- FALSE
    rv$annotation <- NULL
    rv$annotation_ready <- FALSE
    rv$current_dir <- NULL
    rv$manual_path <- NULL
    rv$loading_cancelled <- FALSE # 重置取消标志
    rv$load_data_triggered <- FALSE # 重置加载标志

    # 重置步骤状态
    rv$normalize_done <- FALSE
    rv$find_variable_done <- FALSE
    rv$scale_done <- FALSE
    rv$pca_done <- FALSE
    rv$harmony_done <- FALSE
    rv$elbow_done <- FALSE
    rv$api_recommendations_done <- FALSE
    rv$clustering_run_done <- FALSE
    rv$clustree_plot_done <- FALSE
    rv$umap_tsne_done <- FALSE

    # 重置按钮状态
    rv$all_buttons_disabled <- FALSE
    rv$processing_button <- NULL

    # 清空UI中的手动路径输入框
    updateTextInput(session, "manual_path", value = "")

    # 强制垃圾回收
    gc()

    # 恢复按钮状态到初始状态
    restore_button_states()

    showNotification("数据已重置", type = "message")
    cat("数据重置完成\n")

    # 清除数据加载状态（用于JavaScript检查）
    session$sendCustomMessage("data_loaded_status", list(status = "数据未加载"))
  })


  # 数据信息显示
  output$data_info <- renderUI({
    if (!rv$data_loaded) {
      return("")
    }

    pbmc <- rv$pbmc
    total_cells <- ncol(pbmc)
    total_genes <- nrow(pbmc)
    total_samples <- length(unique(pbmc$orig.ident))

    # 计算一些基本统计信息
    mean_genes <- mean(pbmc$nFeature_RNA)
    mean_umi <- mean(pbmc$nCount_RNA)
    mean_mt <- mean(pbmc$percent.mt)

    div(
      class = "data-info-cards",
      # 总体统计卡片
      div(
        class = "info-card",
        div(class = "card-header", "📊 总体统计"),
        div(
          class = "card-body",
          div(
            class = "stat-item",
            div(class = "stat-label", "总细胞数"),
            div(class = "stat-value", format(total_cells, big.mark = ","))
          ),
          div(
            class = "stat-item",
            div(class = "stat-label", "总基因数"),
            div(class = "stat-value", format(total_genes, big.mark = ","))
          ),
          div(
            class = "stat-item",
            div(class = "stat-label", "样本数"),
            div(class = "stat-value", total_samples)
          )
        )
      ),

      # 质控统计卡片
      div(
        class = "info-card",
        div(class = "card-header", "🔬 质控统计"),
        div(
          class = "card-body",
          div(
            class = "stat-item",
            div(class = "stat-label", "平均基因数 (nFeature_RNA)"),
            div(class = "stat-value", format(round(mean_genes, 0), big.mark = ","))
          ),
          div(
            class = "stat-item",
            div(class = "stat-label", "平均UMI数 (nCount_RNA)"),
            div(class = "stat-value", format(round(mean_umi, 0), big.mark = ","))
          ),
          div(
            class = "stat-item",
            div(class = "stat-label", "平均线粒体基因百分比 (percent.mt)"),
            div(class = "stat-value", paste0(round(mean_mt, 1), "%"))
          )
        )
      )
    )
  })

  output$sample_info <- renderUI({
    if (!rv$data_loaded) {
      return(NULL) # 返回NULL而不是"数据未加载"
    }

    pbmc <- rv$pbmc
    sample_info <- table(pbmc$orig.ident)
    sample_names <- names(sample_info)
    sample_counts <- as.numeric(sample_info)

    # 计算每个样本的平均基因数
    sample_genes <- sapply(sample_names, function(sample) {
      sample_cells <- pbmc$orig.ident == sample
      mean(pbmc$nFeature_RNA[sample_cells])
    })

    # 创建样本分布卡片
    div(
      class = "sample-distribution-card",
      div(
        class = "info-card",
        div(class = "card-header", "📈 各样本分布"),
        div(
          class = "card-body",
          div(
            class = "sample-list-container",
            div(
              class = "sample-list",
              # 改为垂直布局，避免重叠
              lapply(1:length(sample_names), function(i) {
                name <- sample_names[i]
                count <- sample_counts[i]
                genes <- round(sample_genes[i], 0)
                div(
                  class = "sample-item",
                  div(class = "sample-name", name),
                  div(
                    class = "sample-stats",
                    div(
                      class = "stat-row",
                      div(class = "stat-label", "细胞数:"),
                      div(class = "stat-value", paste0(count, " 个"))
                    ),
                    div(
                      class = "stat-row",
                      div(class = "stat-label", "基因数:"),
                      div(class = "stat-value", paste0(genes, " 个"))
                    )
                  ),
                  div(
                    class = "sample-bar-container",
                    div(
                      class = "sample-bar",
                      div(style = paste0("width:", round(count / max(sample_counts) * 100, 1), "%;
                                                   background: linear-gradient(90deg, #4CAF50, #8BC34A);
                                                   height: 6px;
                                                   border-radius: 3px;"))
                    ),
                    div(class = "sample-bar-label", "细胞数相对比例")
                  )
                )
              })
            )
          )
        )
      )
    )
  })

  output$data_status <- renderUI({
    if (rv$data_loaded) {
      return(div(class = "data-status success", "✓ 数据已加载"))
    } else {
      return(div(class = "data-status warning", "⚠ 数据未加载"))
    }
  })

  # 自动质控推荐显示
  output$auto_qc_recommendations <- renderText({
    if (!rv$qc_ready) {
      return("等待自动质控分析...")
    }
    rv$qc_recommendations
  })

  # 质控分析
  observeEvent(input$get_qc_recommendations, {
    if (!rv$data_loaded) {
      showNotification("请先加载数据", type = "error")
      return()
    }

    # 检查API密钥（先从输入框获取，如果没有则从环境变量获取）
    api_key <- input$api_key
    if (is.null(api_key) || api_key == "") {
      api_key <- Sys.getenv("DEEPSEEK_API_KEY")
    }
    if (is.null(api_key) || api_key == "") {
      showNotification("请先输入API密钥或配置环境变量DEEPSEEK_API_KEY", type = "error")
      return()
    }

    cat("[质控推荐] 开始获取质控推荐...\n")
    cat("[质控推荐] API密钥已提供，长度:", nchar(api_key), "字符\n")

    # 检查数据是否已加载
    if (is.null(rv$pbmc)) {
      showNotification("数据未加载，请先加载数据", type = "error")
      return()
    }

    pbmc <- rv$pbmc
    cat("[质控推荐] 数据已加载，细胞数:", ncol(pbmc), "\n")

    # 创建质控摘要
    tryCatch(
      {
        qs <- create_qc_summary(pbmc)
        cat("[质控推荐] 质控摘要已创建\n")
        cat("  nFeature_RNA:", paste(round(qs$nFeature_RNA), collapse = "/"), "\n")
        cat("  nCount_RNA:", paste(round(qs$nCount_RNA), collapse = "/"), "\n")
        cat("  percent.mt:", paste(round(qs$percent_mt, 1), collapse = "/"), "\n")
      },
      error = function(e) {
        cat("[质控推荐] ❌ 创建质控摘要失败:", e$message, "\n")
        showNotification(paste("创建质控摘要失败:", e$message), type = "error")
        return()
      }
    )

    query <- sprintf(
      "你是单细胞RNA测序质控专家。请基于以下数据分布的分位数（1%%/5%%/95%%/99%%）推荐过滤阈值：\n
nFeature_RNA (基因数): %s
nCount_RNA (UMI数): %s
percent.mt (线粒体%%): %s (仅95%%和99%%)

【统计学原则】
- 下限：保留5%%分位数附近的细胞，避免过滤稀有细胞类型
- 上限：基于95%%分位数设定，但需考虑数据异质性
- 如果95%%与99%%差异大（>2倍），说明存在高表达细胞亚群，应适当放宽上限
- 线粒体阈值：一般<20%%，但某些组织（心肌、肌肉）天然较高

【输出要求】
严格返回一行R代码，格式：pbmc <- subset(pbmc, nFeature_RNA > X & nFeature_RNA < Y & nCount_RNA > Z & nCount_RNA < W & percent.mt < M)

不要返回代码块标记、解释或其他内容，只返回这一行代码。",
      paste(round(qs$nFeature_RNA), collapse = "/"),
      paste(round(qs$nCount_RNA), collapse = "/"),
      paste(round(qs$percent_mt, 1), collapse = "/")
    )

    cat("[质控推荐] 查询已构建，长度:", nchar(query), "字符\n")
    cat("[质控推荐] 正在调用DeepSeek API...\n")

    # 显示获取中的通知
    showNotification("正在获取质控推荐...", type = "message", duration = 3)

    # 创建进度条并调用API
    result <- NULL
    tryCatch(
      {
        withProgress(message = "正在获取质控推荐...", value = 0.3, {
          setProgress(value = 0.5, message = "正在调用DeepSeek API...")

          # 记录开始时间
          start_time <- Sys.time()

          # 调用API（质控推荐是简单任务，使用快速模型）
          result <- ask_deepseek(query, api_key = api_key, use_fast_model = TRUE)

          # 记录结束时间
          end_time <- Sys.time()
          elapsed_time <- as.numeric(difftime(end_time, start_time, units = "secs"))
          cat(sprintf("[质控推荐] API调用完成，耗时: %.2f秒\n", elapsed_time))

          setProgress(value = 0.8, message = "正在处理结果...")
          incProgress(0.2)
        })
      },
      error = function(e) {
        cat("[质控推荐] ❌ API调用异常:", e$message, "\n")
        showNotification(paste("API调用异常:", e$message), type = "error", duration = 10)
        return()
      }
    )

    # 检查结果
    if (is.null(result)) {
      cat("[质控推荐] ❌ API调用返回NULL\n")
      showNotification("API调用失败：返回NULL", type = "error", duration = 10)
      return()
    }

    if (!is.null(result$error)) {
      # 如果是因为截断，尝试用更大的max_tokens重试一次
      if (!is.null(result$truncated) && result$truncated) {
        cat("[质控推荐] ⚠️ 检测到截断，尝试用更大的max_tokens重试...\n")
        showNotification("API返回被截断，正在用更大参数重试...", type = "warning", duration = 3)

        # 用8000 tokens重试（快速模型支持最大8000）
        result <- ask_deepseek(query, api_key = api_key, max_tokens = 8000, use_fast_model = TRUE)

        if (!is.null(result$error)) {
          cat("[质控推荐] ❌ 重试后仍失败:", result$error, "\n")
          showNotification(paste("API重试失败:", result$error), type = "error", duration = 10)
          return()
        }
        cat("[质控推荐] ✅ 重试成功\n")
      } else {
        cat("[质控推荐] ❌ API错误:", result$error, "\n")
        showNotification(paste("API错误:", result$error), type = "error", duration = 10)
        return()
      }
    }

    if (is.null(result$success) || result$success == "") {
      cat("[质控推荐] ❌ API返回为空\n")
      showNotification("API返回为空，请重试", type = "error", duration = 10)
      return()
    }

    cat("[质控推荐] ✅ API调用成功，返回内容长度:", nchar(result$success), "字符\n")
    cat("[质控推荐] 返回内容预览:", substr(result$success, 1, 200), "...\n")

    # 保存结果
    rv$qc_recommendations <- result$success
    rv$qc_ready <- TRUE

    # 解析API返回的R代码并提取参数值
    tryCatch(
      {
        # 提取subset函数中的参数
        code <- result$success

        # 清理代码（移除可能的代码块标记）
        code <- gsub("```r|```R|```", "", code)
        code <- gsub("^\\s+|\\s+$", "", code)

        cat("[质控推荐] 清理后的代码:", code, "\n")

        # 使用正则表达式提取参数值
        nFeature_min_match <- regmatches(code, regexpr("nFeature_RNA > (\\d+)", code, perl = TRUE))
        nFeature_max_match <- regmatches(code, regexpr("nFeature_RNA < (\\d+)", code, perl = TRUE))
        nCount_min_match <- regmatches(code, regexpr("nCount_RNA > (\\d+)", code, perl = TRUE))
        nCount_max_match <- regmatches(code, regexpr("nCount_RNA < (\\d+)", code, perl = TRUE))
        percent_mt_max_match <- regmatches(code, regexpr("percent\\.mt < ([\\d.]+)", code, perl = TRUE))

        # 更新参数值
        updated_count <- 0
        if (length(nFeature_min_match) > 0) {
          value <- as.numeric(sub("nFeature_RNA > ", "", nFeature_min_match))
          updateNumericInput(session, "nFeature_min", value = value)
          cat("[质控推荐] 更新 nFeature_min:", value, "\n")
          updated_count <- updated_count + 1
        }
        if (length(nFeature_max_match) > 0) {
          value <- as.numeric(sub("nFeature_RNA < ", "", nFeature_max_match))
          updateNumericInput(session, "nFeature_max", value = value)
          cat("[质控推荐] 更新 nFeature_max:", value, "\n")
          updated_count <- updated_count + 1
        }
        if (length(nCount_min_match) > 0) {
          value <- as.numeric(sub("nCount_RNA > ", "", nCount_min_match))
          updateNumericInput(session, "nCount_min", value = value)
          cat("[质控推荐] 更新 nCount_min:", value, "\n")
          updated_count <- updated_count + 1
        }
        if (length(nCount_max_match) > 0) {
          value <- as.numeric(sub("nCount_RNA < ", "", nCount_max_match))
          updateNumericInput(session, "nCount_max", value = value)
          cat("[质控推荐] 更新 nCount_max:", value, "\n")
          updated_count <- updated_count + 1
        }
        if (length(percent_mt_max_match) > 0) {
          value <- as.numeric(sub("percent\\.mt < ", "", percent_mt_max_match))
          updateNumericInput(session, "percent_mt_max", value = value)
          cat("[质控推荐] 更新 percent_mt_max:", value, "\n")
          updated_count <- updated_count + 1
        }

        if (updated_count > 0) {
          cat("[质控推荐] ✅ 成功更新", updated_count, "个参数\n")
          showNotification(paste("✅ 质控推荐获取成功并已更新", updated_count, "个参数"), type = "message", duration = 5)
        } else {
          cat("[质控推荐] ⚠️ 未能提取参数值\n")
          showNotification("质控推荐获取成功，但未能提取参数值。请手动查看推荐结果。", type = "warning", duration = 10)
        }
      },
      error = function(e) {
        cat("[质控推荐] ❌ 参数解析失败:", e$message, "\n")
        safe_showNotification("质控推荐获取成功，但参数解析时出现问题，请手动检查", type = "warning", duration = 10)
      }
    )
  })

  # 一键执行后续步骤 (质控分析页面)
  observeEvent(input$run_all_steps, {
    if (!rv$data_loaded) {
      showNotification("请先加载数据", type = "error")
      return()
    }

    if (is.null(input$api_key) || input$api_key == "") {
      showNotification("请先输入API密钥", type = "error")
      return()
    }

    # 数据已加载，发送信号给前端开始执行
    session$sendCustomMessage("start_auto_execution", list(start = TRUE))
  })

  # 一键执行后续步骤 (数据上传页面)
  observeEvent(input$run_all_steps_upload, {
    # 从系统设置页面获取DeepSeek API密钥
    deepseek_api_key <- input$deepseek_key

    if (is.null(deepseek_api_key) || deepseek_api_key == "") {
      showNotification("请先在系统设置页面配置DeepSeek API密钥", type = "error")
      return()
    }

    # 将系统设置的API密钥同步到质控分析页面
    updateTextInput(session, "api_key", value = deepseek_api_key)

    # 发送信号给前端开始执行（包含数据加载步骤）
    session$sendCustomMessage("start_auto_execution_upload", list(start = TRUE))
  })

  # 🚀 自动流水线：批量注释模式
  observeEvent(input$auto_batch_pipeline, {
