    deepseek_api_key <- input$deepseek_key
    if (!is.null(deepseek_api_key) && deepseek_api_key != "") {
      updateTextInput(session, "api_key", value = deepseek_api_key)
    }

    # 【关键】自动设置AURA的前置条件为TRUE，避免阻塞
    rv$aura2_status$dependencies_checked <- TRUE
    rv$aura2_status$api_keys_configured <- TRUE
    rv$aura2_status$parallel_env_ready <- TRUE

    # 启动流水线
    rv$auto_pipeline_active <- TRUE
    rv$auto_pipeline_mode <- "batch"
    rv$auto_pipeline_step <- "qc"

    cat("\n════════════════════════════════════════\n")
    cat("🚀 启动自动流水线 - 批量注释模式\n")
    cat("════════════════════════════════════════\n\n")

    showNotification("🚀 批量注释流水线已启动！", type = "message", duration = 5)

    # 触发"一键执行后续步骤"
    Sys.sleep(0.5)
    session$sendCustomMessage("start_auto_execution_upload", list(start = TRUE))
  })

  # 🚀 自动流水线：逐簇注释模式
