  })

  observeEvent(input$apply_qc_filter, {
    if (!rv$data_loaded) {
      showNotification("请先加载数据", type = "error")
      return()
    }

    print_main_title("质量控制分析", 60)
    print_pipeline_progress(2) # 流程步骤2

    pbmc <- rv$pbmc
    pbmc_before <- pbmc
    cells_before <- ncol(pbmc_before)

    # 显示过滤参数
    cat("  ℹ 过滤参数:\n")
    cat(sprintf("    • 最小基因数: %d\n", input$nFeature_min))
    cat(sprintf("    • 最大基因数: %d\n", input$nFeature_max))
    cat(sprintf("    • 最小UMI数: %d\n", input$nCount_min))
    cat(sprintf("    • 最大UMI数: %d\n", input$nCount_max))
    cat(sprintf("    • 最大线粒体比例: %.1f%%\n", input$percent_mt_max))
    cat("\n")

    # 应用过滤
    print_sub_title("应用质控过滤", 50)
    pbmc <- subset(
      pbmc,
      nFeature_RNA > input$nFeature_min &
        nFeature_RNA < input$nFeature_max &
        nCount_RNA > input$nCount_min &
        nCount_RNA < input$nCount_max &
        percent.mt < input$percent_mt_max
    )

    rv$pbmc <- pbmc
    rv$qc_done <- TRUE

    # 【新增】记录质控参数到reactive值
    rv$qc_params$min_features <- input$nFeature_min
    rv$qc_params$max_features <- input$nFeature_max
    rv$qc_params$min_counts <- input$nCount_min
    rv$qc_params$max_counts <- input$nCount_max
    rv$qc_params$max_mito <- input$percent_mt_max

    # 更新统计信息
    cells_after <- ncol(pbmc)
    cells_removed <- cells_before - cells_after

    cat(sprintf("  过滤前: %s 细胞\n", format(cells_before, big.mark = ",")))
    cat(sprintf("  过滤后: %s 细胞\n", format(cells_after, big.mark = ",")))
    cat(sprintf(
      "  ✗ 移除: %s 细胞 (%.1f%%)\n",
      format(cells_removed, big.mark = ","),
      round(cells_removed / cells_before * 100, 1)
    ))
    cat("\n")

    print_main_title("质控完成", 60)
    cat(sprintf(
      "  ✅ 保留高质量细胞: %s (%.1f%%)\n",
      format(cells_after, big.mark = ","),
      round(cells_after / cells_before * 100, 1)
    ))
    cat("\n")

    output$qc_stats <- renderText({
      paste(
        "过滤统计:",
        "\n过滤前:", format(cells_before, big.mark = ","), "个细胞",
        "\n过滤后:", format(cells_after, big.mark = ","), "个细胞",
        "\n保留率:", round(cells_after / cells_before * 100, 1), "%"
      )
    })

    showNotification("质控过滤完成！", type = "message")

    # 【自动流水线】更新步骤
    if (rv$auto_pipeline_active && rv$auto_pipeline_step == "qc") {
      rv$auto_pipeline_step <- "dimred"
    }
  })

  # ═══════════════════════════════════════════════════════════════
  # 🎯 跳过质控（用于已经质控过的公开数据集）
  # ═══════════════════════════════════════════════════════════════
  observeEvent(input$skip_qc_filter, {
    if (!rv$data_loaded) {
      showNotification("请先加载数据", type = "error")
      return()
    }

    print_main_title("跳过质量控制", 60)
    cat("  ℹ 使用场景：已质控的公开数据集（如PBMC 3K, Baron Pancreas等）\n")
    cat("  ℹ 说明：数据集发布时已经过Cell Ranger质控，无需再次过滤\n\n")

    pbmc <- rv$pbmc
    cells_count <- ncol(pbmc)

    # 不执行任何过滤，直接标记质控完成
    rv$qc_done <- TRUE

    # 记录质控参数（跳过模式）
    rv$qc_params$min_features <- 0
    rv$qc_params$max_features <- Inf
    rv$qc_params$min_counts <- 0
    rv$qc_params$max_counts <- Inf
    rv$qc_params$max_mito <- 100
    rv$qc_params$skipped <- TRUE # 标记为跳过模式

    cat(sprintf("  ✅ 保留全部细胞: %s\n", format(cells_count, big.mark = ",")))
    cat("  ✅ 质控步骤已跳过，可直接进行降维聚类\n\n")

    output$qc_stats <- renderText({
      paste(
        "质控模式: 已跳过（使用预质控数据）",
        "\n细胞数:", format(cells_count, big.mark = ","), "个",
        "\n保留率: 100%"
      )
    })

    showNotification("已跳过质控！数据集保留全部细胞", type = "message")

    # 【自动流水线】更新步骤
    if (rv$auto_pipeline_active && rv$auto_pipeline_step == "qc") {
      rv$auto_pipeline_step <- "dimred"
    }
  })

  # 质控可视化 - 质控前 (线粒体百分比 vs UMI数)
  output$qc_before_plot_mt_container <- renderUI({
    if (!rv$data_loaded || !rv$qc_before_ready) {
      return(NULL)
    }

    # 使用质控前的数据副本
    pbmc <- rv$pbmc_before_qc

    # 创建质控前的散点图 - 线粒体百分比 vs UMI数
    p1 <- FeatureScatter(pbmc, feature1 = "nCount_RNA", feature2 = "percent.mt", raster = FALSE) +
      ggtitle("nCount_RNA (Y) vs percent.mt (X)") +
      theme(plot.title = element_text(hjust = 0.5, size = 10))

    # 生成临时图片文件并转换为base64
    temp_file <- tempfile(fileext = ".png")
    png(temp_file, width = 600, height = 450, res = 120)
    print(p1)
    dev.off()

    # 读取图片并转换为base64
    img_data <- base64enc::base64encode(temp_file)
    unlink(temp_file)

    # 创建HTML图片标签
    tags$div(
      style = "text-align: center; padding: 10px;",
      tags$img(
        src = paste0("data:image/png;base64,", img_data),
        alt = "Mitochondrial Percentage vs UMI Count",
        style = "width: 100%; height: auto; max-height: 700px; object-fit: contain; border-radius: 8px; box-shadow: 0 4px 8px rgba(0,0,0,0.1); background: white;"
      )
    )
  })

