  # 降维分析
  observeEvent(input$normalize_data, {
    if (!rv$qc_done) {
      showNotification("请先完成质控分析", type = "error")
      return()
    }

    print_main_title("数据标准化", 60)
    print_pipeline_progress(3) # 流程步骤3

    # 立即禁用所有按钮，只保留当前按钮
    rv$all_buttons_disabled <- TRUE
    rv$processing_button <- "normalize_data"
    disable_all_buttons("normalize_data")

    start_time <- Sys.time()

    print_sub_title("步骤1: Log归一化", 50)
    cat("  ℹ 方法: LogNormalize\n")
    cat("  ℹ 缩放因子: 10,000\n")
    cat("\n")

    withProgress(message = "正在运行数据标准化...", value = 0, {
      rv$pbmc <- NormalizeData(rv$pbmc, verbose = FALSE)
      incProgress(1.0)
    })

    print_status("success", "Log归一化完成")
    print_timing(start_time, "数据标准化")
    cat("\n")

    # 更新步骤状态
    rv$normalize_done <- TRUE

    output$dimred_status <- renderText({
      "数据标准化完成"
    })

    # 恢复按钮状态
    rv$all_buttons_disabled <- FALSE
    rv$processing_button <- NULL
    restore_button_states()

    print_main_title("标准化完成", 60)
    cat("  ✅ 数据已标准化，可进行高变基因识别\n\n")

    showNotification("数据标准化完成！", type = "message")
  })

  observeEvent(input$find_variable_features, {
    if (!rv$qc_done) {
      showNotification("请先完成质控分析", type = "error")
      return()
    }
    if (!rv$normalize_done) {
      showNotification("请先完成数据标准化", type = "error")
      return()
    }

    print_sub_title("步骤2: 高变基因识别", 50)
    cat("  ℹ 方法: vst\n")
    cat("  ℹ 选择基因数: 2,000\n")
    cat("\n")

    # 立即禁用所有按钮，只保留当前按钮
    rv$all_buttons_disabled <- TRUE
    rv$processing_button <- "find_variable_features"
    disable_all_buttons("find_variable_features")

    start_time <- Sys.time()

    withProgress(message = "正在寻找高变基因...", value = 0, {
      rv$pbmc <- FindVariableFeatures(rv$pbmc, verbose = FALSE)
      incProgress(1.0)
    })

    # 获取Top高变基因
    top_variable <- head(VariableFeatures(rv$pbmc), 5)

    print_status("success", "识别出 2,000 个高变基因")
    cat(sprintf("  📊 Top 5 高变基因: %s\n", paste(top_variable, collapse = ", ")))
    print_timing(start_time, "高变基因识别")
    cat("\n")

    # 更新步骤状态
    rv$find_variable_done <- TRUE

    output$dimred_status <- renderText({
      "高变基因识别完成"
    })

    # 恢复按钮状态
    rv$all_buttons_disabled <- FALSE
    rv$processing_button <- NULL
    restore_button_states()

    showNotification("高变基因识别完成！", type = "message")
  })

  observeEvent(input$scale_data, {
