    cat("  ✅ 数据已准备好进行降维分析\n\n")

    showNotification("数据缩放完成！", type = "message")
  })

  observeEvent(input$run_pca, {
    if (!rv$qc_done) {
      showNotification("请先完成质控分析", type = "error")
      return()
    }
    if (!rv$scale_done) {
      showNotification("请先完成数据缩放", type = "error")
      return()
    }

    print_main_title("降维分析（PCA）", 60)
    print_pipeline_progress(4) # 流程步骤4

    print_sub_title("步骤1: PCA降维", 50)
    cat(sprintf("  ℹ 使用维度数: %d\n", input$npcs))
    cat(sprintf("  ℹ 使用基因数: %d\n", length(VariableFeatures(rv$pbmc))))
    cat("\n")

    # 立即禁用所有按钮，只保留当前按钮
    rv$all_buttons_disabled <- TRUE
    rv$processing_button <- "run_pca"
    disable_all_buttons("run_pca")

    start_time <- Sys.time()

    withProgress(message = "正在运行PCA...", value = 0, {
      set.seed(42) # 【可重复性】确保PCA结果一致
      rv$pbmc <- RunPCA(rv$pbmc, npcs = input$npcs, verbose = FALSE)
      incProgress(1.0)
    })

    # 提取PCA信息
    pca_results <- rv$pbmc@reductions$pca
    top_genes_pc1 <- head(rownames(pca_results@feature.loadings)[order(abs(pca_results@feature.loadings[, 1]), decreasing = TRUE)], 3)

    print_status("success", "PCA计算完成")
    cat(sprintf("  📊 主成分分析结果:\n"))
    cat(sprintf("    • Top 3 基因 (PC1): %s\n", paste(top_genes_pc1, collapse = ", ")))
    print_timing(start_time, "PCA降维")
    cat("\n")

    # 更新步骤状态
    rv$pca_done <- TRUE

    output$dimred_status <- renderText({
      paste("PCA完成，主成分数:", input$npcs)
    })

    # 恢复按钮状态
    rv$all_buttons_disabled <- FALSE
    rv$processing_button <- NULL
    restore_button_states()

    print_main_title("PCA降维完成", 60)
    cat("  ✅ 降维空间已准备好\n\n")

    showNotification("PCA分析完成！", type = "message")
  })

  observeEvent(input$run_harmony, {
    if (is.null(rv$pbmc@reductions$pca)) {
      showNotification("请先运行PCA", type = "error")
      return()
    }
    if (!rv$pca_done) {
      showNotification("请先完成PCA分析", type = "error")
      return()
    }

    print_sub_title("步骤2: Harmony批次校正", 50)
    cat("  ℹ 批次变量: orig.ident\n")
    cat("  ℹ 最大迭代: 10\n")
    cat("\n")

    # 立即禁用所有按钮，只保留当前按钮
    rv$all_buttons_disabled <- TRUE
    rv$processing_button <- "run_harmony"
    disable_all_buttons("run_harmony")

    start_time <- Sys.time()

    # 🎯 修复：检查样本数，单样本自动跳过Harmony
    n_samples <- length(unique(rv$pbmc$orig.ident))

    if (n_samples < 2) {
      print_status("info", sprintf("检测到单样本数据（%d个样本），跳过Harmony批次校正", n_samples))
      cat("  ℹ Harmony需要≥2个样本，使用PCA结果继续分析\n\n")

      # 设置状态为完成（使用PCA替代）
      rv$dimred_done <- TRUE
      rv$harmony_done <- TRUE
      output$dimred_status <- renderText({
        "单样本数据，已跳过Harmony（使用PCA）"
      })

      # 恢复按钮状态
      rv$all_buttons_disabled <- FALSE
      rv$processing_button <- NULL
      restore_button_states()

      print_main_title("降维分析完成", 60)
      cat("  ✅ 降维空间已准备好，可开始聚类\n\n")

      showNotification("单样本数据已跳过Harmony，使用PCA继续分析", type = "message")
      return()
    }

    # 多样本：正常运行Harmony
    tryCatch(
      {
        withProgress(message = "正在运行Harmony批次校正...", value = 0, {
          set.seed(42) # 【可重复性】确保Harmony结果一致
          rv$pbmc <- RunHarmony(rv$pbmc, "orig.ident", verbose = FALSE)
          incProgress(1.0)
        })

        print_status("success", "Harmony批次校正完成")
        print_timing(start_time, "Harmony校正")
        cat("\n")

        rv$dimred_done <- TRUE
        rv$harmony_done <- TRUE
        output$dimred_status <- renderText({
          "Harmony批次校正完成"
        })

        # 恢复按钮状态
        rv$all_buttons_disabled <- FALSE
        rv$processing_button <- NULL
        restore_button_states()

        print_main_title("降维分析完成", 60)
        cat("  ✅ 降维空间已准备好，可开始聚类\n\n")

        showNotification("Harmony批次校正完成！", type = "message")
      },
      error = function(e) {
        print_status("error", sprintf("Harmony批次校正失败: %s", e$message))
        showNotification(paste("Harmony批次校正失败:", e$message), type = "error")
        output$dimred_status <- renderText({
          paste("Harmony批次校正失败:", e$message)
        })

        # 恢复按钮状态（即使出错也要恢复）
        rv$all_buttons_disabled <- FALSE
        rv$processing_button <- NULL
        restore_button_states()
      }
    )
  })

  observeEvent(c(input$run_umap_tsne, rv$trigger_umap_tsne), {
    cat("[UMAP/t-SNE启动] 触发源:", if (!is.null(input$run_umap_tsne)) "手动按钮" else "自动流水线", "\n")
    # 检查聚类是否完成
    if (!rv$clustering_done) {
      # showNotification("请先完成聚类分析", type = "error")
      return()
    }

    # 立即禁用所有按钮，只保留当前按钮
    rv$all_buttons_disabled <- TRUE
    rv$processing_button <- "run_umap_tsne"
    disable_all_buttons("run_umap_tsne")

    withProgress(message = "正在运行UMAP和t-SNE...", value = 0, {
      # 使用用户选择的dims范围
      dims_range <- input$dims_min:input$dims_max

      cat("═══════════════════════════════════════\n")
      cat("运行UMAP和t-SNE\n")
      cat("═══════════════════════════════════════\n")
      cat("  dims范围:", paste(dims_range, collapse = ":"), "\n")
      cat("  细胞数:", ncol(rv$pbmc), "\n")
      cat("  簇数:", length(unique(rv$pbmc$seurat_clusters)), "\n")

      # 【关键】设置随机种子保证结果可重现
      set.seed(42)
      cat("  ✓ 设置随机种子: 42\n")
      cat("═══════════════════════════════════════\n\n")

      # 🎯 修复：动态选择降维方法
      use_reduction <- if (!is.null(rv$pbmc@reductions$harmony)) "harmony" else "pca"
      cat(sprintf("  ℹ 使用降维方法: %s\n\n", use_reduction))

      rv$pbmc <- RunUMAP(rv$pbmc, dims = dims_range, reduction = use_reduction, verbose = FALSE)
      cat("  ✓ UMAP完成\n")
      incProgress(0.5)

      rv$pbmc <- RunTSNE(rv$pbmc, dims = dims_range, reduction = use_reduction, verbose = FALSE)
      cat("  ✓ t-SNE完成\n")
      incProgress(1.0)
    })

    rv$dimred_done <- TRUE
    rv$umap_tsne_done <- TRUE
    rv$umap_done <- TRUE
    output$clustering_status <- renderText({
      "UMAP和t-SNE可视化完成"
    })

    # ═══════════════════════════════════════════════════════════════
    # 【修改】仅创建测试文件夹，不保存图片（图片将在AURA注释完成后保存）
    # ═══════════════════════════════════════════════════════════════
    tryCatch(
      {
        cat("\n═══════════════════════════════════════\n")
        cat("准备测试结果文件夹\n")
        cat("═══════════════════════════════════════\n")

        # 1. 创建测试结果文件夹（如果还没创建）
        if (is.null(rv$test_folder)) {
          rv$test_folder <- create_test_result_folder(mode = NULL, sample_name = rv$sample_path)
          cat("  ✓ 创建测试文件夹:", rv$test_folder, "\n")

          # 2. 保存参数列表
          dims_range <- input$dims_min:input$dims_max
          # 【修复】使用实际执行的分辨率，而不是界面输入框的值
          resolution <- rv$best_resolution %||% input$resolution %||% 0.5
          save_parameters_to_md(
            folder = rv$test_folder,
            resolution = resolution,
            dims_range = dims_range,
            qc_params = rv$qc_params,
            sample_path = rv$sample_path
          )
        } else {
          cat("  ℹ 使用现有测试文件夹:", rv$test_folder, "\n")
        }

        # 【新增】如果已经有AURA注释，立即保存图片
        if (rv$has_aura_annotation) {
          cat("\n  ℹ 检测到已有AURA注释，立即保存可视化图片...\n")
          saved_files <- save_visualization_plots(
            folder = rv$test_folder,
            pbmc_obj = rv$pbmc,
            has_aura = TRUE
          )
          if (length(saved_files) > 0) {
            cat("  ✅ 已保存", length(saved_files), "个可视化图片\n")
          }
        } else {
          cat("\n  ℹ 可视化图片将在AURA注释完成后保存\n")
        }

        cat("═══════════════════════════════════════\n\n")
      },
      error = function(e) {
        cat("  ⚠️ 准备测试结果文件夹时出错:", e$message, "\n")
      }
    )

    # 恢复按钮状态
    rv$all_buttons_disabled <- FALSE
    rv$processing_button <- NULL
    restore_button_states()

    notification_msg <- if (rv$has_aura_annotation) {
      "UMAP和t-SNE可视化完成！已保存带AURA注释的图片。"
    } else {
      "UMAP和t-SNE可视化完成！请进行AURA注释后，图片将自动保存。"
    }
    showNotification(notification_msg, type = "message", duration = 5)

    # 【自动流水线】如果在自动流水线中，标记流水线完成
    if (rv$auto_pipeline_active && rv$auto_pipeline_step == "umap") {
      rv$auto_pipeline_active <- FALSE
      rv$auto_pipeline_step <- "done"

      cat("\n════════════════════════════════════════════════════════\n")
      cat("🎉🎉🎉 自动流水线执行完成！🎉🎉🎉\n")
      cat("════════════════════════════════════════════════════════\n")
      cat("  ✅ 质控分析完成\n")
      cat("  ✅ 降维分析完成\n")
      cat("  ✅ 聚类分析完成\n")
      if (rv$auto_pipeline_mode == "batch") {
        cat("  ✅ AURA批量注释完成\n")
      } else {
        cat("  ✅ AURA逐簇注释完成\n")
      }
      cat("  ✅ UMAP/t-SNE可视化完成\n")
      cat("  📁 测试结果文件夹:", rv$test_folder, "\n")
      cat("════════════════════════════════════════════════════════\n\n")

      showNotification(
        "🎉 自动流水线执行完成！所有图片已保存。",
        type = "message",
        duration = 10
      )
    }
  })

  # 降维可视化
  output$pca_plot <- renderPlotly({
    if (is.null(rv$pbmc@reductions$pca)) {
      return(NULL)
    }
    ggplotly(DimPlot(rv$pbmc, reduction = "pca"), height = 700)
  })

  output$harmony_plot <- renderPlotly({
    if (is.null(rv$pbmc@reductions$harmony)) {
      return(NULL)
    }
    ggplotly(DimPlot(rv$pbmc, reduction = "harmony"), height = 700)
  })

  output$pca_plot_container <- renderUI({
    tryCatch(
      {
        if (is.null(rv$pbmc) || is.null(rv$pbmc@reductions$pca)) {
          tags$div(
            style = "text-align: center; padding: 50px; color: #666;",
            p("请先运行PCA分析", style = "font-size: 16px; margin: 0;")
          )
        } else {
          plotlyOutput("pca_plot", height = "700px")
        }
      },
      error = function(e) {
        tags$div(
          style = "text-align: center; padding: 50px; color: #666;",
          p("请先运行PCA分析", style = "font-size: 16px; margin: 0;")
        )
      }
    )
  })

  output$harmony_plot_container <- renderUI({
    tryCatch(
      {
        if (is.null(rv$pbmc) || is.null(rv$pbmc@reductions$harmony)) {
          tags$div(
            style = "text-align: center; padding: 50px; color: #666;",
            p("请先运行Harmony批次校正", style = "font-size: 16px; margin: 0;")
          )
        } else {
          plotlyOutput("harmony_plot", height = "700px")
        }
      },
      error = function(e) {
        tags$div(
          style = "text-align: center; padding: 50px; color: #666;",
          p("请先运行Harmony批次校正", style = "font-size: 16px; margin: 0;")
        )
      }
