  output$umap_plot <- renderPlotly({
    if (is.null(rv$pbmc@reductions$umap)) {
      return(NULL)
    }

    # 智能选择着色依据：优先使用AURA注释
    has_aura <- tryCatch(
      {
        !is.null(rv$pbmc$AURA_annotation) && isTRUE(rv$has_aura_annotation)
      },
      error = function(e) FALSE
    )

    if (has_aura) {
      color_by <- "AURA_annotation"
      plot_title <- "UMAP图 - AURA细胞类型注释"

      # 获取细胞类型和固定颜色
      cell_types <- unique(rv$pbmc$AURA_annotation)
      cell_colors <- assign_celltype_color(cell_types)

      # 生成图表（带固定颜色）
      p <- DimPlot(rv$pbmc,
        reduction = "umap",
        group.by = color_by,
        label = TRUE,
        label.size = 6,
        label.box = TRUE,
        repel = TRUE,
        cols = cell_colors
      ) +
        ggtitle(plot_title) +
        theme_minimal() +
        theme(
          legend.position = "right",
          legend.key.size = unit(1.2, "cm"),
          legend.text = element_text(size = 12)
        )
    } else {
      color_by <- "seurat_clusters"
      plot_title <- "UMAP图 - Cluster编号"

      # 生成图表（cluster编号）
      p <- DimPlot(rv$pbmc,
        reduction = "umap",
        group.by = color_by,
        label = TRUE,
        label.size = 5,
        repel = TRUE
      ) +
        ggtitle(plot_title) +
        theme_minimal() +
        theme(
          legend.position = "right",
          legend.key.size = unit(1.2, "cm"),
          legend.text = element_text(size = 12)
        )
    }

    ggplotly(p, height = 700)
  })

  output$tsne_plot <- renderPlotly({
