      plot_title <- "t-SNE图 - AURA细胞类型注释"

      # 获取细胞类型和固定颜色
      cell_types <- unique(rv$pbmc$AURA_annotation)
      cell_colors <- assign_celltype_color(cell_types)

      # 生成图表（带固定颜色）
      p <- DimPlot(rv$pbmc,
        reduction = "tsne",
        group.by = color_by,
        label = TRUE,
        label.size = 6,
        label.box = TRUE,
        repel = TRUE,
        cols = cell_colors
      ) +
        ggtitle(plot_title) +
        theme_minimal() +
        theme(
          legend.position = "right",
          legend.key.size = unit(1.2, "cm"),
          legend.text = element_text(size = 12)
        )
    } else {
