        style = "background: #f8f9fa; padding: 15px; border-radius: 8px; border-left: 4px solid var(--gray-400);",
        icon("info-circle", class = "fa-lg", style = "color: var(--gray-600);"), " ",
        strong("默认模式：Cluster编号", style = "color: var(--gray-700); font-size: 14px;"),
        br(),
        tags$small(
          style = "color: var(--gray-600); margin-top: 5px; display: block;",
          "完成AURA分析后将自动切换为细胞类型显示"
        )
      )
    }
  })

  # ═══════════════════════════════════════════════════════════════
  # 【新增】导出AURA注释结果
  # ═══════════════════════════════════════════════════════════════

  # 导出CSV（细胞级注释）
  output$download_annotation_csv <- downloadHandler(
    filename = function() {
      paste0("AURA_annotation_", Sys.Date(), ".csv")
    },
    content = function(file) {
      if (is.null(rv$pbmc$AURA_annotation)) {
        showNotification("请先完成AURA分析", type = "error")
        return(NULL)
      }

      tryCatch(
        {
          # 创建导出数据
          export_data <- data.frame(
            cell_barcode = colnames(rv$pbmc),
            cluster = as.character(rv$pbmc$seurat_clusters),
            AURA_annotation = rv$pbmc$AURA_annotation,
            AURA_confidence = rv$pbmc$AURA_confidence,
            AURA_mode = rv$pbmc$AURA_mode,
            stringsAsFactors = FALSE
          )

          write.csv(export_data, file, row.names = FALSE)
          showNotification(paste0("已导出 ", nrow(export_data), " 个细胞的注释数据"), type = "message")
        },
        error = function(e) {
          showNotification(paste("导出失败:", e$message), type = "error")
        }
      )
    }
  )

