  output$best_resolution_container <- renderUI({
    tryCatch(
      {
        if (is.null(rv$pbmc)) {
          tags$div(
            style = "text-align: center; padding: 50px; color: #666;",
            p("请先完成数据加载", style = "font-size: 16px; margin: 0;")
          )
        } else if (!is.null(rv$best_resolution_data)) {
