  # 细胞注释
  observeEvent(input$get_annotation, {
    # 立即显示开始通知
    showNotification("正在获取API注释...", type = "message")

    if (!rv$clustering_done) {
      # showNotification("请先完成聚类分析", type = "error")
      return()
    }

    if (!rv$umap_done) {
      showNotification("请先完成UMAP和t-SNE分析", type = "error")
      return()
    }

    # 立即禁用所有按钮，只保留当前按钮
    rv$all_buttons_disabled <- TRUE
    rv$processing_button <- "get_annotation"
    disable_all_buttons("get_annotation")

    # 获取标记基因 - 使用FindAllMarkers动态计算真实的标记基因
    pbmc <- rv$pbmc
    Idents(pbmc) <- pbmc$seurat_clusters

    # 显示计算真实标记基因的通知
    showNotification("正在计算各聚类的真实标记基因...", type = "message")

    # 获取所有聚类
    clusters <- levels(pbmc$seurat_clusters)

    # 使用FindAllMarkers计算每个聚类的真实标记基因
    tryCatch(
      {
        # 计算标记基因 - 添加进度条
        withProgress(message = "正在计算标记基因...", value = 0, {
          incProgress(0.1, detail = "准备计算标记基因")

          # 使用优化后的FindMarkers来避免卡死
          tryCatch({
            # 添加超时保护
            setTimeLimit(cpu = 30, elapsed = 60, transient = TRUE)
            on.exit(setTimeLimit(cpu = Inf, elapsed = Inf, transient = TRUE))

            cluster_markers <- FindAllMarkers(pbmc,
              only.pos = TRUE,
              min.pct = 0.1, # 降低阈值
              logfc.threshold = 0.25,
              verbose = FALSE
            )
          }, error = function(e) {
            cat("FindAllMarkers超时或失败:", e$message, "\n")
            cat("使用备用方案计算标记基因...\n")

            # 备用方案：逐个聚类计算
            clusters <- levels(pbmc$seurat_clusters)
            clusters <- clusters[!is.na(clusters)]

            cluster_markers_list <- lapply(clusters, function(cluster_id) {
              tryCatch({
                setTimeLimit(cpu = 10, elapsed = 20, transient = TRUE)
                on.exit(setTimeLimit(cpu = Inf, elapsed = Inf, transient = TRUE))

                markers <- FindMarkers(pbmc,
                  ident.1 = cluster_id,
                  only.pos = TRUE,
                  min.pct = 0.1,
                  logfc.threshold = 0.25,
                  verbose = FALSE
                )
                markers$cluster <- cluster_id
                markers
              }, error = function(e2) {
                cat("聚类", cluster_id, "计算失败:", e2$message, "\n")
                return(NULL)
              }, finally = {
                setTimeLimit(cpu = Inf, elapsed = Inf, transient = TRUE)
              })
            })

            # 合并结果
            cluster_markers <- do.call(rbind, cluster_markers_list[!sapply(cluster_markers_list, is.null)])
            if (is.null(cluster_markers)) {
              cluster_markers <- data.frame() # 创建空数据框
            }
          }, finally = {
            setTimeLimit(cpu = Inf, elapsed = Inf, transient = TRUE)
          })

          incProgress(0.3, detail = "标记基因计算完成，正在处理结果...")

          log_info("", rv$log_file)
          log_info("📋 提取每个聚类的Top 5标记基因...", rv$log_file)

          # 为每个聚类选择Top标记基因
          markers <- data.frame()
          total_clusters <- length(clusters)
          clusters_with_markers <- 0

          for (i in seq_along(clusters)) {
            cluster_id <- clusters[i]
            incProgress(0.6 / total_clusters, detail = paste("正在处理聚类", cluster_id, "(", i, "/", total_clusters, ")"))

            cluster_specific_markers <- cluster_markers[cluster_markers$cluster == cluster_id, ]
            # 按avg_log2FC排序，取前5个
            if (nrow(cluster_specific_markers) > 0) {
              top_markers <- cluster_specific_markers[order(cluster_specific_markers$avg_log2FC, decreasing = TRUE), ][1:5, ]
              markers <- rbind(markers, top_markers[, c("cluster", "gene", "avg_log2FC")])
              clusters_with_markers <- clusters_with_markers + 1

              # 输出Top 3基因到日志
              top_genes <- head(top_markers, 3)
              log_debug(sprintf(
                "→ 聚类%s: %s", cluster_id,
                paste(sprintf("%s(%.2f)", rownames(top_genes), top_genes$avg_log2FC),
                  collapse = ", "
                )
              ), rv$log_file)
            } else {
              # 如果没有找到标记基因，使用占位符
              markers <- rbind(markers, data.frame(
                cluster = cluster_id,
                gene = "No_marker_found",
                avg_log2FC = 0
              ))
              log_warn(sprintf("⚠ 聚类%s: 未找到标记基因", cluster_id), rv$log_file)
            }
          }

          incProgress(0.1, detail = "标记基因处理完成")

          # 最终统计
          log_info("", rv$log_file)
          log_info("🎯 标记基因计算摘要:", rv$log_file)
          log_info(sprintf("  → 总聚类数: %d", total_clusters), rv$log_file)
          log_info(sprintf(
            "  → 成功聚类: %d (%.1f%%)",
            clusters_with_markers,
            clusters_with_markers / total_clusters * 100
          ), rv$log_file)
          log_info(sprintf("  → 总标记基因数: %d", nrow(markers)), rv$log_file)

          if (nrow(cluster_markers) > 0) {
            avg_logfc <- mean(cluster_markers$avg_log2FC)
            log_debug(sprintf("  → 平均log2FC: %.2f", avg_logfc), rv$log_file)
          }

          stop_timer(timer, rv$log_file)
          log_separator(NULL, rv$log_file)
        })

        showNotification("标记基因计算完成！", type = "message")
      },
      error = function(e) {
        log_error(sprintf("✗ 标记基因计算异常: %s", e$message), rv$log_file)
        log_trace(sprintf("  错误堆栈: %s", paste(as.character(sys.calls()), collapse = " -> ")), rv$log_file)
        log_debug("可能原因: Seurat对象异常、内存不足或计算超时", rv$log_file)
        if (exists("timer")) stop_timer(timer, rv$log_file)
        log_separator(NULL, rv$log_file)

        showNotification(paste("计算标记基因失败:", e$message), type = "error")
        # 如果计算失败，返回空的数据框
        markers <- data.frame(
          cluster = clusters,
          gene = "Calculation_failed",
          avg_log2FC = 0
        )
      }
    )

    # 构建查询
    clusters <- levels(pbmc$seurat_clusters)
    desc <- sapply(clusters, function(cl) {
      genes <- markers$gene[markers$cluster == cl][1:5]
      paste0("\"", cl, "\": [", paste(sprintf("\"%s\"", na.omit(genes)), collapse = ", "), "]")
    })

    # 候选细胞类型枚举：优先从候选词表（major_markers）动态取，与候选词汇表约束一致；
    # 候选表由 build_candidate_vocabulary 动态构建或数据集 marker_config 加载（含该组织的标准细胞类型）
    allowed <- as.character(rv$major_markers[["细胞类型"]])
    if (is.null(allowed) || length(allowed) == 0 || all(is.na(allowed))) {
      allowed <- c(
        "T_cells", "B_cells", "Macrophages", "Mast_cells", "Monocyte", "DC", "NK",
        "Fibroblast", "Endothelial_cells", "cancer"
      )
    }
    allowed <- unique(allowed[!is.na(allowed) & allowed != ""])

    prompt <- sprintf(
      paste0(
        "你是一位单细胞测序专家。下面是每个聚类簇的Top标记基因（最多5个），这些标记基因是通过FindAllMarkers基于实际数据计算得出的。",
        "请仅基于这些真实的差异表达标记基因，为每个簇给出**唯一的细胞类型**。",
        "\\n\\nclusters_to_genes = { ", paste(desc, collapse = ", "), " }",
        "\\n\\n要求：",
        "\\n1) 只输出**严格JSON格式**，不要任何代码块标记、注释、说明文字或其他内容。",
        "\\n2) 直接输出JSON对象，形如 {\"0\":\"T_cells\",\"1\":\"Cancer_cells\",...}，键是簇ID（字符串），值是下列枚举之一：", paste(allowed, collapse = "/"), "。",
        "\\n3) 必须覆盖**所有簇**：", paste(sprintf('"%s"', clusters), collapse = ", "), "；若不确定也要择优其一，不要输出 Unknown。",
        "\\n4) 基于标记基因判断（CD3D/E→T_cells；MS4A1/MZB1→B/Plasma_B；PECAM1/VWF→Endothelial；ACTA2/PDGFRB→Fibroblast；C1QA/B/LYZ→髓系等）。",
        "\\n5) 严禁使用markdown格式，不要包含```json或任何其他标记。"
      )
    )

    # 调用API，统一使用质控页面的API密钥
    api_key <- input$api_key

    # 检查API密钥是否存在
    if (is.null(api_key) || api_key == "") {
      showNotification("请在质控分析页面输入API密钥", type = "warning")
      return()
    }

    # 创建进度条弹窗
    withProgress(message = "正在获取API注释...", value = 0.3, {
      result <- ask_deepseek(prompt, api_key = api_key)
      incProgress(0.7)
    })

    if (!is.null(result$error)) {
      output$annotation_api_response <- renderText({
        paste("API错误:", result$error)
      })
    } else {
      output$annotation_api_response <- renderText({
        paste("API注释结果:\n", result$success)
      })

      # 解析JSON结果
      tryCatch(
        {
          # 调试：显示API返回的原始内容
          cat("API返回原始内容:\n", result$success, "\n")
          cat("API返回内容长度:", nchar(result$success), "\n")

          # 尝试解析JSON - 先清理返回内容
          clean_result <- result$success

          # 尝试提取JSON部分（如果API返回了markdown格式的响应）
          # 查找JSON对象的开始和结束
          json_start <- regexpr("\\{", clean_result)
          json_end <- regexpr("\\}[[:space:]]*$", clean_result)

          if (json_start > 0 && json_end > 0) {
            clean_result <- substr(clean_result, json_start, json_end)
            cat("提取的JSON内容:\n", clean_result, "\n")
          }

          # 如果还是没有找到JSON，尝试查找```json代码块
          if (json_start <= 0) {
            json_block_start <- regexpr("```json", clean_result)
            if (json_block_start > 0) {
              # 找到代码块开始后的JSON
              after_block <- substr(clean_result, json_block_start + 7, nchar(clean_result))
              json_start <- regexpr("\\{", after_block)
              if (json_start > 0) {
                clean_result <- substr(after_block, json_start, nchar(after_block))
                # 找到代码块结束
                block_end <- regexpr("```", clean_result)
                if (block_end > 0) {
                  clean_result <- substr(clean_result, 1, block_end - 1)
                }
                cat("从代码块提取的JSON内容:\n", clean_result, "\n")
              }
            }
          }

          # 尝试解析
          annotation <- jsonlite::fromJSON(clean_result)
          cat("JSON解析成功，注释结果:\n")
          print(annotation)

          rv$annotation <- annotation
          rv$annotation_ready <- TRUE

          # 自动应用注释结果
          clusters <- sort(unique(rv$pbmc$seurat_clusters))
          new_names <- sapply(clusters, function(cl) {
            cluster_key <- as.character(cl)
            if (cluster_key %in% names(rv$annotation)) {
              rv$annotation[[cluster_key]]
            } else {
              "Unknown"
            }
          })
          names(new_names) <- as.character(clusters)

          # 重命名聚类
          tryCatch(
            {
              # 按照参考代码的格式重命名聚类
              new.cluster.ids <- unlist(new_names)
              rv$pbmc <- RenameIdents(rv$pbmc, new.cluster.ids)
              rv$pbmc$celltype <- Idents(rv$pbmc)
              rv$annotation_done <- TRUE

              # 生成对比图 - 按照参考代码格式
              if (!is.null(rv$pbmc@reductions$umap)) {
                cat("生成注释对比图...\n")
                p1 <- DimPlot(rv$pbmc, group.by = "seurat_clusters", label = TRUE, raster = FALSE) +
                  ggtitle("原始聚类")
                p2 <- DimPlot(rv$pbmc, label = TRUE, raster = FALSE) +
                  ggtitle("DeepSeek 自动注释（JSON）")
                combined_plot <- cowplot::plot_grid(p1, p2, ncol = 2)
              }
            },
            error = function(e) {
              showNotification(paste("自动应用注释失败:", e$message), type = "error")
            }
          )

          showNotification("API注释获取成功！已自动应用注释结果。", type = "message")

          # 恢复按钮状态
          rv$all_buttons_disabled <- FALSE
          rv$processing_button <- NULL
          restore_button_states()
        },
        error = function(e) {
          # 显示详细的错误信息
          cat("JSON解析错误详情:\n")
          cat("错误信息:", e$message, "\n")
          cat("API返回内容前200字符:\n", substr(result$success, 1, 200), "\n")
          cat("API返回内容后200字符:\n", substr(result$success, nchar(result$success) - 199, nchar(result$success)), "\n")

          # JSON解析失败时不再显示弹窗
          # showNotification(paste("JSON解析失败:", e$message), type = "error")

          # 出错时也要恢复按钮状态
          rv$all_buttons_disabled <- FALSE
          rv$processing_button <- NULL
          restore_button_states()
        }
      )
    }
  })

  # 注释表格
  output$annotation_table <- renderDT({
    if (!rv$clustering_done) {
      return(NULL)
    }

    clusters <- sort(unique(rv$pbmc$seurat_clusters))
    df <- data.frame(
      Cluster = clusters,
      CellType = if (!is.null(rv$annotation)) {
        sapply(clusters, function(cl) {
          if (as.character(cl) %in% names(rv$annotation)) {
            rv$annotation[[as.character(cl)]]
          } else {
            "Unknown"
          }
        })
      } else {
        rep("Unknown", length(clusters))
      }
    )

    datatable(df, options = list(pageLength = 10))
  })


  # 注释可视化
  output$annotation_umap_plot <- renderPlotly({
    if (!rv$annotation_done) {
      return(NULL)
    }

    # 检查是否有UMAP降维结果
    if (!"umap" %in% names(rv$pbmc@reductions)) {
      # 没有UMAP时显示提示信息
      p <- ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "请先运行UMAP降维分析", size = 6, color = "#6c757d") +
        theme_void() +
        xlim(0, 1) +
        ylim(0, 1)
      return(ggplotly(p, height = 700))
    }

    p <- DimPlot(rv$pbmc, reduction = "umap", group.by = "celltype", label = TRUE) +
      theme(legend.key.size = unit(1.2, "cm"), legend.text = element_text(size = 12))
    ggplotly(p, height = 700)
  })

  # 【已废弃】动态显示下载按钮UI - 已统一到"导出注释结果"box
  # output$download_annotated_rds_ui <- renderUI({
  #   if (!is.null(rv$annotation_done) && rv$annotation_done) {
  #     downloadButton("download_annotated_rds",
  #       "📥 导出注释结果 (RDS)",
  #       icon = icon("download"),
  #       class = "btn-success"
  #     )
  #   } else {
  #     NULL
  #   }
  # })

  # 下载处理器 - 下载注释后的Seurat对象
  output$download_annotated_rds <- downloadHandler(
    filename = function() {
      paste0("annotated_seurat_object_", Sys.Date(), ".rds")
    },
    content = function(file) {
      # 显示进度条，提升用户体验
      withProgress(message = "正在保存RDS文件...", value = 0, {
        incProgress(0.3, detail = "准备数据...")

        # 【新增】保存API成本和时间统计到@misc槽位（向后兼容）
        if (!is.null(rv$aura_metrics)) {
          tryCatch(
            {
              metrics <- rv$aura_metrics

              # 详细metrics信息
              rv$pbmc@misc$aura_metrics <- metrics

              # 简化metrics（向后兼容）
              rv$pbmc@misc$llm_cost <- metrics$total_cost_usd
              rv$pbmc@misc$llm_duration <- metrics$runtime_seconds

              cat("✅ 已保存API成本和时间统计到@misc槽位\n")
              cat(sprintf("  - llm_cost: $%.4f\n", metrics$total_cost_usd))
              cat(sprintf("  - llm_duration: %.2f 秒\n", metrics$runtime_seconds))
              cat(sprintf("  - total_api_calls: %d\n", metrics$total_api_calls))
              cat(sprintf("  - total_tokens: %d\n", metrics$total_tokens$total))
            },
            error = function(e) {
              cat("⚠️ 保存metrics失败:", e$message, "\n")
            }
          )
        } else {
          cat("⚠️ 未找到aura_metrics，跳过保存\n")
        }

        # 保存最终的Seurat对象
        saveRDS(rv$pbmc, file)

        incProgress(0.7, detail = "保存完成")
      })
    }
  )

  # 可视化页面
  observe({
    if (rv$data_loaded && !is.null(rv$pbmc)) {
      # 更新基因选择
      genes <- rownames(rv$pbmc)
      updateSelectInput(session, "selected_genes", choices = genes, selected = head(genes, 5))

      # 更新聚类选择
      if (rv$clustering_done) {
        clusters <- sort(unique(rv$pbmc$seurat_clusters))
        updateSelectInput(session, "de_cluster", choices = clusters)
      }
    }
  })

  observeEvent(input$plot_genes, {
    if (!rv$data_loaded || is.null(input$selected_genes)) {
      return()
    }

    output$gene_expression_plot <- renderPlotly({
      ggplotly(FeaturePlot(rv$pbmc, features = input$selected_genes, ncol = 2, reduction = "umap"), height = 700)
    })
  })

  output$sample_celltype_plot <- renderPlotly({
    if (!rv$annotation_done) {
      return(NULL)
    }

    df_stack <- as.data.frame(table(Sample = rv$pbmc$orig.ident, CellType = rv$pbmc$celltype))
    colnames(df_stack) <- c("Sample", "CellType", "Count")

    df_stack <- df_stack %>%
      group_by(Sample) %>%
      mutate(Percentage = Count / sum(Count)) %>%
      ungroup()

    p <- ggplot(df_stack, aes(x = Sample, y = Percentage, fill = CellType)) +
      geom_bar(stat = "identity", position = "stack") +
      labs(title = "样本细胞类型分布", x = "样本", y = "比例") +
      theme_minimal() +
      theme(axis.text.x = element_text(angle = 45, hjust = 1))

    ggplotly(p, height = 700)
  })

  observeEvent(input$run_de_analysis, {
    if (!rv$annotation_done || is.null(input$de_cluster)) {
      return()
    }

    pbmc <- rv$pbmc
    Idents(pbmc) <- pbmc$celltype

    # 添加进度条显示差异表达基因计算进度
    withProgress(message = "正在计算差异表达基因...", value = 0, {
      incProgress(0.5, detail = "运行差异表达分析...")

      # 使用更高效的参数来避免卡死
      tryCatch({
        # 添加超时保护
        setTimeLimit(cpu = 30, elapsed = 60, transient = TRUE)
        on.exit(setTimeLimit(cpu = Inf, elapsed = Inf, transient = TRUE))

        de_markers <- FindAllMarkers(pbmc,
          only.pos = TRUE,
          min.pct = 0.1, # 降低阈值
          logfc.threshold = 0.25,
          verbose = FALSE
        )
      }, error = function(e) {
        cat("FindAllMarkers超时或失败:", e$message, "\n")
        cat("使用简化版的差异表达分析...\n")

        # 备用方案：只分析主要聚类
        clusters <- unique(pbmc$seurat_clusters)
        clusters <- clusters[!is.na(clusters)]

        if (length(clusters) > 10) {
          clusters <- head(clusters, 10) # 限制分析的聚类数量
        }

        de_markers_list <- lapply(clusters, function(cluster_id) {
          tryCatch(
            {
              FindMarkers(pbmc,
                ident.1 = cluster_id,
                only.pos = TRUE,
                min.pct = 0.1,
                logfc.threshold = 0.25,
                verbose = FALSE
              )
            },
            error = function(e) {
              cat("聚类", cluster_id, "分析失败:", e$message, "\n")
              return(NULL)
            }
          )
        })

        # 合并结果
        de_markers <- do.call(rbind, de_markers_list[!sapply(de_markers_list, is.null)])
        if (is.null(de_markers)) {
          de_markers <- data.frame() # 创建空数据框
        }
      }, finally = {
        setTimeLimit(cpu = Inf, elapsed = Inf, transient = TRUE)
      })

      incProgress(0.3, detail = "处理差异表达结果...")
    })

    # 创建火山图
    de_markers$neglog10p <- -log10(pmax(de_markers$p_val_adj, .Machine$double.xmin))

    p <- ggplot(de_markers, aes(x = avg_log2FC, y = neglog10p)) +
      geom_point(alpha = 0.6) +
      theme_minimal() +
      labs(title = "差异表达火山图", x = "log2 Fold Change", y = "-log10(adj.P)")

    output$volcano_plot <- renderPlotly(ggplotly(p, height = 700))

    # 显示差异表达表格
    de_table <- de_markers %>%
      arrange(desc(avg_log2FC)) %>%
      head(100)

    output$de_table <- renderDT({
      datatable(de_table, options = list(pageLength = 10))
    })
  })

  # ==================== 可视化页面功能 ====================

  # 图表描述信息
  plot_descriptions <- reactive({
    list(
      "umap_clusters" = "UMAP聚类图：显示细胞在UMAP降维空间中的分布，不同颜色代表不同的聚类簇。",
      "tsne_clusters" = "t-SNE聚类图：显示细胞在t-SNE降维空间中的分布，不同颜色代表不同的聚类簇。",
      "umap_aura" = "UMAP-AURA注释图：显示AURA 2.0智能注释的细胞类型分布，图例显示细胞类型名称（如Fibroblasts、Cancer、Endothelial等），不同细胞类型用不同颜色区分。",
      "tsne_aura" = "t-SNE-AURA注释图：显示AURA 2.0智能注释的细胞类型分布，图例显示细胞类型名称（如Fibroblasts、Cancer、Endothelial等），不同细胞类型用不同颜色区分。",
      "qc_violin" = "QC小提琴图：显示质控指标（nFeature_RNA、nCount_RNA、percent.mt）在不同样本中的分布。",
      "sample_distribution" = "样本分布图：显示不同样本的细胞数量分布。",
      "feature_genes" = "特征基因表达图：显示选定特征基因在不同细胞中的表达水平。",
      "marker_dotplot" = "标记基因点图：显示不同细胞类型的标记基因表达情况。",
      "celltype_violin" = "细胞类型小提琴图：显示选定基因在不同细胞类型中的表达分布。",
      "celltype_ridge" = "细胞类型山脊图：显示选定基因在不同细胞类型中的表达密度分布。",
      "sample_celltype_stacked" = "样本细胞类型堆叠图：显示不同样本中各细胞类型的堆叠分布情况。",
      "qc_scatter" = "QC散点图：显示质控指标之间的相关性。"
    )
  })

  # 动态参数UI
  output$plot_parameters <- renderUI({
    if (is.null(rv$pbmc)) {
      return(NULL)
    }

    switch(input$plot_type,
      "feature_genes" = {
        tagList(
          selectInput("feature_genes", "选择特征基因",
            choices = rownames(rv$pbmc)[1:50],
            multiple = TRUE, selected = rownames(rv$pbmc)[1:5]
          )
        )
      },
      "celltype_violin" = {
