      )
    }
  })

  # 重新检查依赖
  observeEvent(input$recheck_dependencies, {
    withProgress(message = "正在检查依赖包...", value = 0.5, {
      aura2_packages <- c(
        "R6", "future.apply", "digest", "httr2", "jsonlite",
        "STRINGdb", "gprofiler2", "clusterProfiler", "org.Hs.eg.db",
        "msigdbr", "enrichR", "easyPubMed", "easybio", "future",
        "promises", "plotly", "DT", "igraph"
      )

      # 安全的依赖检查 - 避免installed.packages()卡死
      tryCatch(
        {
          # 使用简单的超时机制获取已安装包
          installed_packages <- tryCatch(
            {
              # 使用setTimeLimit创建超时机制
              setTimeLimit(cpu = 10, elapsed = 10, transient = TRUE)
              on.exit(setTimeLimit(cpu = Inf, elapsed = Inf, transient = TRUE))

              result <- tryCatch(
                {
                  rownames(installed.packages())
                },
                error = function(e) {
                  NULL
                }
              )

              if (is.null(result)) {
                # 如果超时，使用基本方法
                loaded_packages <- (.packages())
                # 添加一些常见已安装的包
                common_packages <- c("shiny", "shinydashboard", "DT", "ggplot2", "plotly", "dplyr", "Seurat")
                loaded_packages <- union(loaded_packages, common_packages)
                loaded_packages
              } else {
                result
              }
            },
            error = function(e) {
              # 降级到基本方法
              loaded_packages <- (.packages())
              common_packages <- c("shiny", "shinydashboard", "DT", "ggplot2", "plotly", "dplyr", "Seurat")
              union(loaded_packages, common_packages)
            }
          )

          missing_packages <- aura2_packages[!aura2_packages %in% installed_packages]

          rv$aura2_dependencies <- list(
            total_packages = length(aura2_packages),
            installed_packages = length(aura2_packages) - length(missing_packages),
            missing_packages = missing_packages,
            check_time = Sys.time(),
            check_method = ifelse(length(grep("timeout", installed_packages)) > 0, "降级模式", "完整模式")
          )

          rv$aura2_status$dependencies_checked <- TRUE

          if (length(missing_packages) == 0) {
            showNotification("所有依赖包检查通过！", type = "message", duration = 5)
          } else {
            showNotification(paste("发现", length(missing_packages), "个缺失的依赖包"), type = "warning", duration = 5)
          }
        },
        error = function(e) {
          # 如果整个过程出错，提供基本的错误信息
          rv$aura2_dependencies <- list(
            total_packages = length(aura2_packages),
            installed_packages = NA,
            missing_packages = aura2_packages,
            check_time = Sys.time(),
            check_error = e$message,
            check_method = "错误模式"
          )

          rv$aura2_status$dependencies_checked <- TRUE
          showNotification("依赖检查出错，请检查网络连接或稍后重试", type = "error", duration = 5)
        }
      )
    })
  })

