  # API连接测试结果
  output$api_test_results_ui <- renderUI({
    req(input$test_api_connections)

    # 使用isolate确保只在按钮点击时执行，避免重复触发
    isolate({
      withProgress(message = "正在测试API连接...", value = 0, {
        api_results <- list()

        # 定义所有10个模型的测试配置
        test_configs <- list(
          list(name = "DeepSeek", func = ask_deepseek, env_var = "DEEPSEEK_API_KEY"),
          list(name = "Kimi", func = ask_kimi, env_var = "KIMI_API_KEY"),
          list(name = "GLM-4.6", func = ask_glm, env_var = "GLM_API_KEY"),
          list(name = "豆包", func = ask_douban, env_var = "DOUBAO_API_KEY"),
          list(name = "千问", func = ask_qwen, env_var = "QWEN_API_KEY"),
          list(name = "混元", func = ask_hunyuan, env_var = "HUNYUAN_API_KEY"),
          list(name = "文心一言", func = ask_ernie, env_var = "ERNIE_API_KEY"),
          list(name = "阶跃星辰", func = ask_stepfun, env_var = "STEPFUN_API_KEY"),
          list(name = "讯飞星火", func = ask_spark, env_var = "SPARK_API_KEY"),
          list(name = "Minimax", func = ask_minimax, env_var = "MINIMAX_API_KEY")
        )

        total_models <- length(test_configs)

        # 测试所有10个模型
        for (i in seq_along(test_configs)) {
          config <- test_configs[[i]]

          # 更新进度条
          setProgress(
            value = i / total_models,
            message = paste0("正在测试 ", config$name, " (", i, "/", total_models, ")..."),
            detail = paste0("已测试 ", i - 1, " 个模型")
          )

          # 记录开始时间（用于调试）
          start_time <- Sys.time()
          cat(sprintf("[API测试] 开始测试 %s...\n", config$name))

          tryCatch(
            {
              # 从环境变量获取API密钥
              api_key <- Sys.getenv(config$env_var)
              if (is.null(api_key) || api_key == "") {
                cat(sprintf("[API测试] %s: API密钥未配置\n", config$name))
                api_results[[config$name]] <- list(status = "warning", message = "API密钥未配置")
                next
              }

              # 测试API连接（使用简短的测试消息，设置较大的max_tokens避免截断）
              cat(sprintf("[API测试] %s: 正在调用API...\n", config$name))
              # 为测试设置较大的max_tokens（3000足够测试连接，避免不必要的截断）
              # 对于简单的"你好"测试，即使模型返回较长内容也不会被截断
              test_result <- config$func("你好", api_key = api_key, max_tokens = 3000)

              # 记录结束时间
              end_time <- Sys.time()
              elapsed_time <- as.numeric(difftime(end_time, start_time, units = "secs"))

              # 检查结果（优化后的逻辑：只要返回内容不为空就认为连接成功）
              if (!is.null(test_result$success)) {
                # 检查是否有截断警告
                if (!is.null(test_result$truncated) && test_result$truncated) {
                  # 有截断但有返回内容，仍然认为连接成功
                  content_length <- nchar(test_result$success)
                  if (!is.null(test_result$warning)) {
                    cat(sprintf(
                      "[API测试] %s: ✅ 连接正常 (耗时: %.2f秒, 返回内容长度: %d字符, %s)\n",
                      config$name, elapsed_time, content_length, test_result$warning
                    ))
                  } else {
                    cat(sprintf(
                      "[API测试] %s: ✅ 连接正常 (耗时: %.2f秒, 返回内容长度: %d字符, 可能有截断)\n",
                      config$name, elapsed_time, content_length
                    ))
                  }
                  api_results[[config$name]] <- list(
                    status = "success",
                    message = paste0(config$name, "连接正常（返回内容长度: ", content_length, "字符）"),
                    elapsed_time = elapsed_time,
                    content_length = content_length
                  )
                } else {
                  # 正常返回，无截断
                  content_length <- nchar(test_result$success)
                  cat(sprintf(
                    "[API测试] %s: ✅ 连接正常 (耗时: %.2f秒, 返回内容长度: %d字符)\n",
                    config$name, elapsed_time, content_length
                  ))
                  api_results[[config$name]] <- list(
                    status = "success",
                    message = paste0(config$name, "连接正常（返回内容长度: ", content_length, "字符）"),
                    elapsed_time = elapsed_time,
                    content_length = content_length
                  )
                }
              } else {
                # 没有返回内容，检查错误信息
                error_msg <- ifelse(!is.null(test_result$error), test_result$error, "连接失败")
                cat(sprintf("[API测试] %s: ❌ 连接失败 - %s (耗时: %.2f秒)\n", config$name, error_msg, elapsed_time))
                api_results[[config$name]] <- list(
                  status = "error",
                  message = paste0(config$name, ": ", error_msg),
                  elapsed_time = elapsed_time
                )
              }
            },
            error = function(e) {
              end_time <- Sys.time()
              elapsed_time <- as.numeric(difftime(end_time, start_time, units = "secs"))
              cat(sprintf("[API测试] %s: ❌ 异常错误 - %s (耗时: %.2f秒)\n", config$name, e$message, elapsed_time))
              api_results[[config$name]] <- list(
                status = "error",
                message = paste0(config$name, ": ", e$message),
                elapsed_time = elapsed_time
              )
            }
          )

          # 短暂延迟，避免API请求过快
          Sys.sleep(0.5)
        }

        # 完成进度条
        setProgress(value = 1, message = "测试完成！")

        # 检查是否有至少一个模型配置成功
        success_count <- sum(sapply(api_results, function(x) x$status == "success"))
        error_count <- sum(sapply(api_results, function(x) x$status == "error"))
        warning_count <- sum(sapply(api_results, function(x) x$status == "warning"))

        if (success_count > 0) {
          rv$aura2_status$api_keys_configured <- TRUE
        }

        # 显示测试结果
        result_html <- ""
        for (api_name in names(api_results)) {
          result <- api_results[[api_name]]
          elapsed_time_str <- if (!is.null(result$elapsed_time)) {
            sprintf(" (%.2f秒)", result$elapsed_time)
          } else {
            ""
          }

          if (result$status == "success") {
            result_html <- paste0(
              result_html,
              '<div style="padding: 8px; margin: 5px 0; background-color: rgba(39, 174, 96, 0.1); border-left: 4px solid #27ae60; border-radius: 3px;">',
              "<strong>", api_name, ':</strong> <span style="color: #27ae60;">', result$message, elapsed_time_str, "</span></div>"
            )
          } else if (result$status == "error") {
            result_html <- paste0(
              result_html,
              '<div style="padding: 8px; margin: 5px 0; background-color: #f8d7da; border-left: 4px solid #dc3545; border-radius: 3px;">',
              "<strong>", api_name, ':</strong> <span style="color: #721c24;">', result$message, elapsed_time_str, "</span></div>"
            )
          } else if (result$status == "warning") {
            result_html <- paste0(
              result_html,
              '<div style="padding: 8px; margin: 5px 0; background-color: #fff3cd; border-left: 4px solid #ffc107; border-radius: 3px;">',
              "<strong>", api_name, ':</strong> <span style="color: #856404;">', result$message, "</span></div>"
            )
          }
        }

        # 添加总结
        summary_html <- paste0(
          '<div style="padding: 12px; margin: 10px 0; background-color: rgba(48, 43, 99, 0.1); border-radius: 5px; border: 1px solid rgba(48, 43, 99, 0.2);">',
          "<strong>测试总结:</strong> ",
          '<span style="color: #27ae60;">', success_count, "个模型连接正常</span>, ",
          '<span style="color: #dc3545;">', error_count, "个模型连接失败</span>, ",
          '<span style="color: #ffc107;">', warning_count, "个模型未配置</span>",
          tags$br(),
          tags$small(
            style = "color: #6c757d; margin-top: 5px; display: block;",
            "💡 提示：此测试结果反映实际API连接状态，与上方配置状态（环境变量检查）不同。"
          )
        )

        div(HTML(paste0(summary_html, result_html)))
      })
    })
  })

