  # AURA 3.0 模型表现历史表格
  output$model_performance_table <- renderDT({
    tryCatch(
      {
        report <- DynamicWeightAdjuster$get_all_models_report()

        if (nrow(report) == 0) {
          return(datatable(
            data.frame(提示 = "暂无历史数据，使用系统一段时间后将显示各模型的表现统计"),
            options = list(dom = "t", ordering = FALSE)
          ))
        }

        # 美化列名
        colnames(report) <- c("模型", "总任务数", "反馈数", "准确率", "趋势")

        # 添加趋势emoji
        report$趋势 <- sapply(report$趋势, function(t) {
          switch(t,
            "improving" = "📈 上升",
            "declining" = "📉 下降",
            "stable" = "➡️ 稳定",
            "❓ 未知"
          )
        })

        datatable(
          report,
          options = list(
            pageLength = 10,
            dom = "t",
            ordering = TRUE,
            order = list(list(3, "desc")) # 按准确率降序
          ),
          rownames = FALSE
        ) %>%
          formatPercentage("准确率", 1) %>%
          formatStyle(
            "准确率",
            backgroundColor = styleInterval(c(0.7, 0.9), c("#f8d7da", "#fff3cd", "#d4edda"))
          )
      },
      error = function(e) {
        datatable(
          data.frame(错误 = paste("加载失败:", e$message)),
          options = list(dom = "t")
        )
      }
    )
  })

