  # 提交反馈事件处理
  observeEvent(input$submit_feedback, {
    tryCatch(
      {
        result <- rv$llm_consensus_result

        if (is.null(result) || is.null(result$debate_history)) {
          showNotification("没有可用的分析结果", type = "warning")
          return()
        }

        # 确定是否正确
        is_correct <- switch(input$user_feedback_correct,
          "correct" = TRUE,
          "partial" = TRUE, # 部分正确也记为TRUE
          "incorrect" = FALSE,
          NA
        )

        user_comments <- input$user_feedback_comments %||% ""

        # 记录辩手A的表现
        PerformanceLogger$log_performance(
          cluster_id = rv$aura2_results$cluster %||% "unknown",
          task_type = classify_task_type(rv$knowledge_base, rv$knowledge_base$input_markers),
          model_name = result$debate_history$round1$model_A,
          role = "debater",
          prediction = result$debate_history$round1$result_A$cell_type,
          confidence = result$debate_history$round1$result_A$confidence,
          is_correct = is_correct,
          user_feedback = user_comments
        )

        # 记录辩手B的表现
        PerformanceLogger$log_performance(
          cluster_id = rv$aura2_results$cluster %||% "unknown",
          task_type = classify_task_type(rv$knowledge_base, rv$knowledge_base$input_markers),
          model_name = result$debate_history$round1$model_B,
          role = "debater",
          prediction = result$debate_history$round1$result_B$cell_type,
          confidence = result$debate_history$round1$result_B$confidence,
          is_correct = is_correct,
          user_feedback = user_comments
        )

        # 记录裁判的表现
        PerformanceLogger$log_performance(
          cluster_id = rv$aura2_results$cluster %||% "unknown",
          task_type = classify_task_type(rv$knowledge_base, rv$knowledge_base$input_markers),
          model_name = result$referee_model,
          role = "referee",
          prediction = result$cell_type,
          confidence = result$confidence,
          is_correct = is_correct,
          user_feedback = user_comments
        )

        rv$feedback_submitted <- TRUE

        showNotification(
          "反馈已记录！AURA 3.0将根据您的反馈持续优化。",
          type = "message",
          duration = 5
        )

        cat(
          "用户反馈已记录：",
          if (is_correct) "正确" else if (!is.na(is_correct)) "错误" else "不确定", "\n"
        )
      },
      error = function(e) {
        cat("提交反馈失败:", e$message, "\n")
        showNotification(
          paste("反馈提交失败:", e$message),
          type = "error",
          duration = 5
        )
      }
    )
  })

