  # 约束注释详细表格
  output$constrained_annotation_table <- renderDT({
    if (!is.null(rv$hierarchical_results) && length(rv$hierarchical_results) > 0) {
      df <- data.frame(
        簇 = character(),
        细胞类型 = character(),
        标记质量 = numeric(),
        辩论分数 = numeric(),
        验证分数 = numeric(),
        标记基因 = character(),
        stringsAsFactors = FALSE
      )

      for (cid in names(rv$hierarchical_results)) {
        r <- rv$hierarchical_results[[cid]]
        df <- rbind(df, data.frame(
          簇 = paste0("Cluster ", cid),
          细胞类型 = r$annotation,
          标记质量 = r$marker_quality %||% 0,
          辩论分数 = r$debate_score %||% 0.75,
          验证分数 = r$validation_score %||% 0.70,
          标记基因 = r$markers,
          stringsAsFactors = FALSE
        ))
      }

      datatable(df,
        options = list(
          pageLength = 25,
          scrollX = TRUE,
          dom = "Bfrtip"
        ),
        caption = "约束注释结果：完整AURA流程，输出限定在候选类型"
      )
    }
  })

  # 批量分析结果UI
  output$batch_results_ui <- renderUI({
    if (!is.null(rv$batch_analysis_done) && rv$batch_analysis_done) {
      total <- length(rv$batch_results)
      success <- sum(sapply(rv$batch_results, function(x) x$status == "success"))

      tagList(
        div(
