  # AURA 2.0 规则引擎报告展示
  output$rules_engine_report_ui <- renderUI({
    if (!rv$aura2_status$analysis_complete) {
      return(div(
        style = "text-align: center; padding: 30px; color: #999;",
        p("等待分析完成...")
      ))
    }

    result <- rv$llm_consensus_result

    if (is.null(result)) {
      return(div(
        style = "text-align: center; padding: 30px; color: #6c757d;",
        p("分析结果不可用")
      ))
    }

    # 如果规则引擎未启用或无规则数据，显示提示
    if (is.null(result$pre_rules) && is.null(result$post_rules)) {
      return(div(
        style = "text-align: center; padding: 30px; color: #6c757d;",
        p("规则引擎未启用或无规则数据"),
        p(style = "font-size: 12px;", "勾选\"启用生物学规则引擎\"以查看规则报告")
      ))
    }

    # 收集前置和后置规则的警告
    pre_warnings <- if (!is.null(result$pre_rules) && !is.null(result$pre_rules$warnings)) {
      result$pre_rules$warnings
    } else {
      c()
    }

    post_warnings <- if (!is.null(result$post_rules) && !is.null(result$post_rules$warnings)) {
      result$post_rules$warnings
    } else {
      c()
    }

    needs_review <- if (!is.null(result$needs_review)) result$needs_review else FALSE

    tagList(
      # 规则引擎总览
      div(
        style = "background: #f8f9fa; padding: 15px; border-radius: 8px; margin-bottom: 20px;",
        h4(icon("shield-alt"), " 规则引擎审查总览", style = "color: #2c3e50; margin-top: 0;"),
        div(
          style = "display: grid; grid-template-columns: repeat(3, 1fr); gap: 15px;",
          # 前置规则
          div(
            style = "background: white; padding: 12px; border-radius: 5px; border-left: 4px solid #3498db;",
            div(style = "font-size: 24px; font-weight: bold; color: #3498db;", length(pre_warnings)),
            div(style = "color: #6c757d; font-size: 12px;", "前置规则警告")
          ),
          # 后置规则
          div(
            style = "background: white; padding: 12px; border-radius: 5px; border-left: 4px solid #e74c3c;",
            div(style = "font-size: 24px; font-weight: bold; color: #e74c3c;", length(post_warnings)),
            div(style = "color: #6c757d; font-size: 12px;", "后置规则警告")
          ),
          # 审查状态
          div(
            style = paste0(
              "background: white; padding: 12px; border-radius: 5px; border-left: 4px solid ",
              if (needs_review) "#dc3545" else "var(--primary)", ";"
            ),
            div(
              style = paste0(
                "font-size: 20px; font-weight: bold; color: ",
                if (needs_review) "#dc3545" else "var(--primary)", ";"
              ),
              icon(if (needs_review) "exclamation-triangle" else "check-circle")
            ),
            div(
              style = "color: #6c757d; font-size: 12px;",
              if (needs_review) "需要复核" else "通过审查"
            )
          )
        )
      ),

      # 前置规则警告详情
      if (length(pre_warnings) > 0) {
        div(
          style = "margin-bottom: 20px;",
          h5(icon("exclamation-triangle"), " 前置规则警告（标记冲突检测）", style = "color: var(--primary);"),
          div(
            style = "background: rgba(48, 43, 99, 0.08); border: 1px solid rgba(48, 43, 99, 0.2); border-radius: 5px; padding: 15px;",
            tags$ul(
              style = "margin: 0; padding-left: 20px;",
              lapply(pre_warnings, function(w) {
                tags$li(style = "color: var(--primary); margin-bottom: 8px;", w)
              })
            )
          )
        )
      },

      # 后置规则警告详情
      if (length(post_warnings) > 0) {
        div(
          style = "margin-bottom: 20px;",
          h5(icon("search"), " 后置规则审查（结论验证）", style = "color: #721c24;"),
          div(
            style = "background: #f8d7da; border: 1px solid #f5c6cb; border-radius: 5px; padding: 15px;",
            tags$ul(
              style = "margin: 0; padding-left: 20px;",
              lapply(post_warnings, function(w) {
                tags$li(style = "color: #721c24; margin-bottom: 8px;", w)
              })
            )
          )
        )
      },

      # 综合建议
      div(
        style = "background: #e7f3ff; border-left: 4px solid #2196f3; border-radius: 5px; padding: 15px;",
        h5(icon("lightbulb-o"), " 规则引擎综合建议", style = "color: #1976d2; margin-top: 0;"),
        p(
          style = "margin: 0; color: #495057;",
          if (needs_review) {
            "⚠️ 规则引擎检测到潜在问题，强烈建议进行人工复核。注释结果可能存在细胞doublet、技术误差或过渡态细胞等情况。"
          } else if (length(pre_warnings) > 0) {
            "✓ 虽然检测到一些前置警告，但后置审查未发现严重问题，结果基本可信。"
          } else {
            "✓ 规则引擎未检测到明显问题，注释结果可信度较高。"
          }
        )
      )
    )
  })

  # AURA2.0状态显示
  output$aura2_status_ui <- renderUI({
    status_items <- list(
      list(name = "依赖检查", status = TRUE, icon = "cogs"), # 暂时屏蔽依赖检查
      list(name = "API配置", status = TRUE, icon = "key"), # 暂时屏蔽API配置检查
      list(name = "并行环境", status = TRUE, icon = "microchip"), # 暂时屏蔽并行环境检查
      list(name = "系统就绪", status = TRUE, icon = "check-circle") # 暂时屏蔽系统就绪检查
    )

    status_html <- ""
    for (item in status_items) {
      if (item$status) {
        status_html <- paste0(
          status_html,
          '<div style="display: flex; align-items: center; margin: 8px 0; padding: 8px; background-color: rgba(48, 43, 99, 0.08); border-radius: 5px;">',
          '<i class="fa fa-', item$icon, '" style="color: var(--primary); margin-right: 10px;"></i>',
          '<span style="color: var(--primary);">', item$name, "</span>",
          '<span style="margin-left: auto; color: var(--primary);">✓</span></div>'
        )
      } else {
        status_html <- paste0(
          status_html,
          '<div style="display: flex; align-items: center; margin: 8px 0; padding: 8px; background-color: #f8f9fa; border: 1px solid #dee2e6; border-radius: 5px;">',
          '<i class="fa fa-', item$icon, '" style="color: #6c757d; margin-right: 10px;"></i>',
          '<span style="color: #6c757d;">', item$name, "</span>",
          '<span style="margin-left: auto; color: #6c757d;">○</span></div>'
        )
      }
    }

    div(HTML(status_html))
  })

  # ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  # 两层注释：Marker配置管理辅助函数
  # ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

  # 从CSV读取marker配置
  load_marker_from_csv <- function(csv_path) {
    tryCatch(
      {
        marker_df <- read.csv(csv_path, stringsAsFactors = FALSE, fileEncoding = "UTF-8")
        # 确保列名正确
        if (ncol(marker_df) == 2) {
          colnames(marker_df) <- c("细胞类型", "Marker基因")
        }
        return(marker_df)
      },
      error = function(e) {
        cat(sprintf("读取marker配置失败: %s\n", e$message))
        return(NULL)
      }
    )
  }

  # 候选词表统一由 build_candidate_vocabulary() 基于五大知识库动态构建；
  # 数据目录中的 marker_config.csv 为可选的用户自定义候选配置，非默认候选词表来源。
  # 自动检测并加载数据集的marker配置
  auto_load_marker_config <- function(dataset_path) {
    if (is.null(dataset_path) || !dir.exists(dataset_path)) {
      return(NULL)
    }

    marker_config_path <- file.path(dataset_path, "marker_config.csv")
    if (file.exists(marker_config_path)) {
      cat("✓ 候选词表由 LLM 结合知识库自主构建\n")
      return(load_marker_from_csv(marker_config_path))
    }

    return(NULL)
  }

  # 获取模板配置
  get_template_markers <- function(template_name) {
    if (template_name == "pbmc3k") {
      # ⚠️ PBMC 3K 演示模板（Shiny 交互用），非基准测试候选词表；
      #    基准候选词表由 build_candidate_vocabulary() 动态构建。
      # PBMC 3K - 9种细胞类型（优化版：独特marker在前，共有marker在后）
      return(data.frame(
        细胞类型 = c(
          "Naive CD4 T", "Memory CD4 T", "CD8 T", "B",
          "CD14+ Mono", "FCGR3A+ Mono", "NK", "DC", "Platelet"
        ),
        Marker基因 = c(
          # Naive CD4 T: SELL/CCR7/LEF1是naive特异，IL7R是共有
          "SELL,CCR7,LEF1,TCF7,CD27,IL7R",
          # Memory CD4 T: S100A4/CD44/AQP3是memory特异，IL7R是共有
          "S100A4,CD44,AQP3,GPR183,CXCR4,IL7R",
          # CD8 T: CD8A/CD8B是特异，GZMK区分于NK，CD3D是T细胞共有
          "CD8A,CD8B,GZMK,CD3D",
          # B: CD79A/CD79B/MS4A1都是B细胞特异
          "CD79A,CD79B,MS4A1,CD19,TCL1A",
          # CD14+ Mono: CD14是特异，S100A8/S100A9是组合特异
          "CD14,S100A8,S100A9,LYZ,VCAN",
          # FCGR3A+ Mono: FCGR3A/MS4A7是特异，区分于CD14+ Mono
          "FCGR3A,MS4A7,CDKN1C,VMO1,LST1",
          # NK: GNLY/NKG7/PRF1是特异，NCAM1(CD56)是NK标志
          "GNLY,NKG7,PRF1,NCAM1,KLRD1",
          # DC: FCER1A/CLEC10A是特异，CST3是共有
          "FCER1A,CLEC10A,CD1C,HLA-DRA,CST3",
          # Platelet: PPBP/PF4/GP9都是血小板特异
          "PPBP,PF4,GP9,ITGA2B,TUBB1"
        ),
        stringsAsFactors = FALSE
      ))
    } else if (template_name == "pbmc68k") {
      # PBMC 68k与PBMC 3K相同
      return(get_template_markers("pbmc3k"))
    } else if (template_name == "baron") {
      # Baron Pancreas - 14种细胞类型（优化版：独特marker在前，共有marker在后）
      return(data.frame(
        细胞类型 = c(
          "alpha", "beta", "delta", "gamma", "epsilon",
          "acinar", "ductal", "endothelial",
          "activated_stellate", "quiescent_stellate",
          "macrophage", "mast", "schwann", "t_cell"
        ),
        Marker基因 = c(
          # alpha: GCG是特异，TTR/MAFB/ARX增强区分
          "GCG,TTR,MAFB,ARX,IRX2,TM4SF4",
          # beta: INS/IAPP是特异，NKX6-1/PDX1是转录因子
          "INS,IAPP,HADH,NKX6-1,PDX1,DLK1",
          # delta: SST是特异，HHEX/RBP4增强区分
          "SST,HHEX,RBP4,LEPR,PCSK1",
          # gamma(PP): PPY是特异，SERTM1/ETV1增强
          "PPY,SERTM1,ETV1,CARTPT,MEIS2",
          # epsilon: GHRL是特异
          "GHRL,OPRK1,ACSL1,ARX",
          # acinar: PRSS1/AMY2A/CPA1是消化酶特异
          "PRSS1,AMY2A,CPA1,PNLIP,CTRB1,CEL",
          # ductal: KRT19/SOX9是导管特异，CFTR区分于acinar
          "KRT19,SOX9,CFTR,SPP1,MUC1,ANXA4",
          # endothelial: PECAM1/VWF/CDH5是内皮特异
          "PECAM1,VWF,CDH5,PLVAP,ENG,ERG",
          # activated_stellate: ACTA2/RGS5是激活特异，COL1A1是共有
          "ACTA2,RGS5,PDGFRB,COL1A1,COL3A1",
          # quiescent_stellate: DCN/LUM是静息特异，PDGFRA区分于激活
          "DCN,LUM,PDGFRA,FBLN1,COL1A1",
          # macrophage: CD68/AIF1/C1QA是巨噬细胞特异
          "CD68,AIF1,C1QA,C1QB,LYZ,CD14",
          # mast: KIT/TPSAB1/CPA3是肥大细胞特异
          "KIT,TPSAB1,CPA3,HPGDS,GATA2,MS4A2",
          # schwann: SOX10/MPZ/S100B是雪旺细胞特异
          "SOX10,MPZ,S100B,PLP1,NGFR,CDH19",
          # t_cell: CD3D/CD3E是T细胞特异
          "CD3D,CD3E,TRAC,CD2,IL7R,LCK"
        ),
        stringsAsFactors = FALSE
      ))
    } else if (template_name == "lung" || template_name == "tabula_muris_lung") {
      # Tabula Muris Lung - 13种细胞类型（优化版：独特marker在前）
      return(data.frame(
        细胞类型 = c(
          "alveolar macrophage", "lung endothelial cell", "stromal cell",
          "T cell", "B cell", "natural killer cell",
          "classical monocyte", "non-classical monocyte", "myeloid cell",
          "type II pneumocyte", "ciliated columnar cell of tracheobronchial tree",
          "leukocyte", "mast cell"
        ),
        Marker基因 = c(
          # alveolar macrophage: Siglecf/Marco是肺泡巨噬特异，Cd68是巨噬共有
          "Siglecf,Marco,Mrc1,Car4,Cd68,Itgax",
          # lung endothelial: Pecam1/Cdh5/Vwf是内皮特异
          "Pecam1,Cdh5,Vwf,Kdr,Emcn,Erg",
          # stromal: Pdgfra/Dcn是基质特异，Col1a1是共有
          "Pdgfra,Dcn,Col1a1,Col3a1,Vim,Lum",
          # T cell: Cd3d/Cd3e是T细胞特异
          "Cd3d,Cd3e,Cd3g,Trac,Lck,Cd28",
          # B cell: Cd79a/Cd79b/Ms4a1是B细胞特异
          "Cd79a,Cd79b,Ms4a1,Cd19,Pax5,Bank1",
          # NK: Ncr1/Klrb1c是NK特异，Nkg7/Prf1是细胞毒性共有
          "Ncr1,Klrb1c,Klrk1,Nkg7,Gzma,Prf1",
          # classical monocyte: Ly6c2/Ccr2是经典单核特异
          "Ly6c2,Ccr2,Cd14,Sell,Itgam,Csf1r",
          # non-classical monocyte: Cx3cr1/Nr4a1是非经典特异
          "Cx3cr1,Nr4a1,Ear2,Ace,Itgal,Cd43",
          # myeloid cell: Lyz2/Csf1r是髓系特异，Cd68/Itgam是共有
          "Lyz2,Csf1r,Fcgr1,Cd68,Itgam,Adgre1",
          # type II pneumocyte: Sftpc/Sftpb是AT2特异
          "Sftpc,Sftpb,Sftpa1,Abca3,Lamp3,Napsa",
          # ciliated cell: Foxj1/Dnah5是纤毛细胞特异
          "Foxj1,Dnah5,Tppp3,Ccdc78,Cfap126,Pifo",
          # leukocyte: Ptprc(Cd45)是白细胞通用标志
          "Ptprc,Cd47,Cd53,Spi1,Coro1a",
          # mast cell: Kit/Cpa3/Mcpt4是肥大细胞特异
          "Kit,Cpa3,Mcpt4,Tpsb2,Cma1,Hdc"
        ),
        stringsAsFactors = FALSE
      ))
    } else if (template_name == "kidney" || template_name == "wu_kidney") {
      # Wu Kidney - 23种细胞类型（优化版：独特marker在前，区分不同节段）
      return(data.frame(
        细胞类型 = c(
          "PT(S1)", "PT(S2)", "PT(S3)", "PT(S1-S2)", "Prolif. PT", "Dediff. PT",
          "LH(AL)", "LH(DL)", "TAL", "DL and tAL",
          "DCT", "CNT", "CD-PC",
          "IC", "IC-A", "IC-B",
          "EC", "Fib.1", "Fib.2", "MC", "Pod", "MØ", "JGA"
        ),
        Marker基因 = c(
          # PT(S1): SLC5A2/SLC22A6是S1特异，SLC34A1/CUBN是PT共有
          "SLC5A2,SLC22A6,SLC34A1,CUBN,LRP2,ALDOB",
          # PT(S2): SLC22A8/GPX3是S2特异
          "SLC22A8,GPX3,SLC34A1,SLC22A7,MIOX",
          # PT(S3): SLC7A13/CRYAB是S3特异
          "SLC7A13,CRYAB,PDZK1IP1,SLC22A7,MT1G",
          # PT(S1-S2): 过渡段特征
          "SLC34A1,SLC5A2,LRP2,CUBN,SLC22A8",
          # Prolif. PT: MKI67/TOP2A是增殖特异
          "MKI67,TOP2A,PCNA,CDK1,BIRC5,UBE2C",
          # Dediff. PT: VCAM1/HAVCR1是去分化特异
          "VCAM1,HAVCR1,SPP1,CD44,VIM,ITGB6",
          # LH(AL): UMOD/CLDN16是升支特异，SLC12A1是LH共有
          "UMOD,CLDN16,KCNJ1,SLC12A1,CASR",
          # LH(DL): CLDN10/CLDN3是降支特异
          "CLDN10,CLDN3,SLC12A1,BSND,CLCNKB",
          # TAL: EGF/UMOD是TAL特异
          "EGF,UMOD,CLDN16,SLC12A1,NOS1",
          # DL and tAL: AQP1/CLDN10组合特异
          "AQP1,CLDN10,SLC12A1,CLCNKA,BSND",
          # DCT: SLC12A3/TRPM6是DCT特异
          "SLC12A3,TRPM6,PVALB,CALB1,SLC8A1",
          # CNT: SLC8A1/FXYD4是CNT特异，CALB1是共有
          "SLC8A1,FXYD4,CALB1,AQP2,SCNN1G",
          # CD-PC: AQP2/AQP3是集合管主细胞特异
          "AQP2,AQP3,FXYD4,SCNN1B,SCNN1G",
          # IC: ATP6V1G3/FOXI1是间插细胞特异
          "ATP6V1G3,ATP6V0D2,FOXI1,SLC4A1,SLC26A4",
          # IC-A: SLC4A1(AE1)是IC-A特异
          "SLC4A1,ATP6V1G3,ATP6V0D2,FOXI1,CLCNKB",
          # IC-B: SLC26A4(Pendrin)是IC-B特异
          "SLC26A4,ATP6V1G3,SLC4A9,FOXI1,INSRR",
          # EC: PECAM1/CDH5/VWF是内皮特异
          "PECAM1,CDH5,VWF,ERG,EMCN,KDR",
          # Fib.1: DCN/LUM/PDGFRA是成纤维1特异
          "DCN,LUM,PDGFRA,COL1A1,COL3A1,COL6A1",
          # Fib.2: ACTA2/MYH11是成纤维2（肌成纤维细胞）特异
          "ACTA2,MYH11,PDGFRB,TAGLN,COL1A1",
          # MC: DES/CNN1是系膜细胞特异
          "DES,CNN1,PDGFRB,ITGA8,ACTA2",
          # Pod: NPHS1/NPHS2/WT1是足细胞特异
          "NPHS1,NPHS2,WT1,PODXL,SYNPO,PTPRO",
          # MØ: CD68/AIF1是巨噬细胞特异
          "CD68,AIF1,C1QA,CD14,CSF1R,LYZ",
          # JGA: REN是肾小球旁器特异
          "REN,AGT,NOS1,AGTR1,AKAP12"
        ),
        stringsAsFactors = FALSE
      ))
    } else if (template_name == "liver" || template_name == "zhao_liver") {
      # Zhao Liver - 29种细胞类型（优化版：独特趋化因子/受体在前）
      return(data.frame(
        细胞类型 = c(
          "CCR7+ CD4", "CCR7+ CD8", "CXCR3+ CD4", "CRCR3+ CD8",
          "CX3CR1+ CD8", "CXCR6+ CD8", "CXCR6+ NK", "CX3CR1+ NK",
          "Treg", "MAIT",
          "Naive B", "TCL1A+ naive B", "Classical mem B", "CD11c+ mem B",
          "MZB", "ZBTB32+ mem B",
          "CD14+ Mo", "CD16+ Mo", "MerTK+ Mo", "Macrophage",
          "CD1c+ DCs", "noncycling ASC", "cycling ASC",
          "Megakaryocyte", "Cycling",
          "Doublets", "NKT doublet", "NKT remove", "Mo doublet"
        ),
        Marker基因 = c(
          # CCR7+ CD4: CCR7/SELL是naive特异，CD4是CD4 T特异
          "CCR7,SELL,LEF1,TCF7,CD4,IL7R",
          # CCR7+ CD8: CCR7/SELL是naive特异，CD8A是CD8 T特异
          "CCR7,SELL,LEF1,TCF7,CD8A,CD8B",
          # CXCR3+ CD4: CXCR3/TBX21是Th1特异
          "CXCR3,TBX21,IFNG,CD4,STAT4",
          # CXCR3+ CD8: CXCR3/GZMK是effector特异
          "CXCR3,GZMK,CD8A,CD8B,EOMES",
          # CX3CR1+ CD8: CX3CR1/FGFBP2是终末分化特异
          "CX3CR1,FGFBP2,FCGR3A,CD8A,CD8B,PRF1",
          # CXCR6+ CD8: CXCR6/ITGA1是组织驻留特异
          "CXCR6,ITGA1,CD69,CD8A,CD8B,GZMB",
          # CXCR6+ NK: CXCR6是组织驻留NK特异
          "CXCR6,CD69,NCAM1,NKG7,GNLY,KLRD1",
          # CX3CR1+ NK: CX3CR1/FGFBP2是循环NK特异
          "CX3CR1,FGFBP2,FCGR3A,NCAM1,NKG7,PRF1",
          # Treg: FOXP3/IL2RA是Treg特异
          "FOXP3,IL2RA,CTLA4,IKZF2,CD4,TIGIT",
          # MAIT: SLC4A10/TRAV1-2是MAIT特异
          "SLC4A10,TRAV1-2,KLRB1,ZBTB16,CD8A",
          # Naive B: IGHD/IL4R是naive B特异
          "IGHD,IL4R,MS4A1,CD19,FCER2,TCL1A",
          # TCL1A+ naive B: TCL1A高表达是特异
          "TCL1A,IGHD,FCER2,MS4A1,CD19,YBX3",
          # Classical mem B: CD27/IGHG1是记忆B特异
          "CD27,IGHG1,CD38,MS4A1,TNFRSF13B",
          # CD11c+ mem B: ITGAX(CD11c)是特异
          "ITGAX,FCRL5,TBXAS1,CD27,MS4A1",
          # MZB: MZB1/JCHAIN是边缘区B特异
          "MZB1,JCHAIN,IGHM,CD27,XBP1",
          # ZBTB32+ mem B: ZBTB32是特异
          "ZBTB32,CD27,IGHG1,MS4A1,FCRL4",
          # CD14+ Mo: CD14/S100A8是经典单核特异
          "CD14,S100A8,S100A9,VCAN,LYZ,FCN1",
          # CD16+ Mo: FCGR3A(CD16)是非经典单核特异
          "FCGR3A,MS4A7,CX3CR1,CDKN1C,MTSS1",
          # MerTK+ Mo: MERTK/MARCO是组织单核特异
          "MERTK,MARCO,C1QA,C1QB,CD14,FOLR2",
          # Macrophage: CD68/CD163是巨噬细胞特异
          "CD68,CD163,C1QA,C1QB,MARCO,VSIG4",
          # CD1c+ DCs: CD1C/FCER1A是cDC2特异
          "CD1C,FCER1A,CLEC10A,CD1E,HLA-DRA",
          # noncycling ASC: XBP1/JCHAIN是浆细胞特异
          "XBP1,JCHAIN,MZB1,IGHG1,SDC1,PRDM1",
          # cycling ASC: MKI67+浆细胞特异
          "MKI67,XBP1,JCHAIN,TOP2A,IGHG1",
          # Megakaryocyte: PPBP/PF4是巨核细胞特异
          "PPBP,PF4,GP9,ITGA2B,TUBB1,TREML1",
          # Cycling: MKI67/TOP2A是增殖特异
          "MKI67,TOP2A,PCNA,CDK1,BIRC5,UBE2C",
          # Doublets: 混合标志
          "MIXED_SIGNATURE",
          # NKT doublet: NKT混合标志
          "CD3D,NCAM1,NKG7,CD4",
          # NKT remove: 低质量标志
          "LOW_QUALITY",
          # Mo doublet: 单核混合标志
          "CD14,CD3D,FCGR3A"
        ),
        stringsAsFactors = FALSE
      ))
    }

    # 从数据库缓存加载组织参考信息
    if (template_name %in% names(TISSUE_REFERENCE_CACHE)) {
      template_df <- TISSUE_REFERENCE_CACHE[[template_name]]
      # 统一列名格式（数据库缓存使用标准化列名）
      if ("标志基因" %in% colnames(template_df)) {
        colnames(template_df)[colnames(template_df) == "标志基因"] <- "Marker基因"
      }
      return(template_df)
    }

    return(NULL)
  }

  # ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  # 两层注释：Marker编辑器
  # ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

  # 配置状态提示
  output$marker_config_status <- renderUI({
    if (rv$marker_config_auto_loaded) {
      div(
        style = "padding: 5px; background-color: #d4edda; border: 1px solid #c3e6cb; border-radius: 3px; margin-bottom: 8px; font-size: 11px; color: #155724;",
        icon("check-circle"), sprintf(" 候选词表已构建（%s）", rv$marker_config_source)
      )
    } else if (rv$marker_config_source != "默认") {
      div(
        style = "padding: 5px; background-color: #d1ecf1; border: 1px solid #bee5eb; border-radius: 3px; margin-bottom: 8px; font-size: 11px; color: #0c5460;",
        icon("info-circle"), sprintf(" 当前配置来源：%s", rv$marker_config_source)
      )
    } else {
      div(
        style = "padding: 5px; background-color: #fff3cd; border: 1px solid #ffeeba; border-radius: 3px; margin-bottom: 8px; font-size: 11px; color: #856404;",
        icon("exclamation-triangle"), " 使用默认配置（PBMC 3K）"
      )
    }
  })

  # 显示marker编辑器
  observeEvent(input$show_marker_editor, {
    showModal(modalDialog(
      title = "📊 编辑候选类型Marker表",
      size = "l",
      div(
        style = "padding: 15px;",
        p("定义候选的主要细胞类型和对应marker基因（逗号分隔）"),
        p(
          style = "color: var(--gray-500); font-size: 12px;",
          "AI将从这些类型中选择，不会输出其他类型"
        ),
        DTOutput("marker_editor_table"),
        br(),
        fluidRow(
          column(
            6,
            actionButton("add_marker_row", "➕ 添加新类型", icon = icon("plus"))
          ),
          column(
            6,
            actionButton("reset_markers", "🔄 恢复默认", icon = icon("undo"))
          )
        )
      ),
      footer = tagList(
        actionButton("save_markers", "💾 保存", class = "btn-primary"),
        modalButton("取消")
      )
    ))
  })

  # 渲染可编辑marker表
  output$marker_editor_table <- renderDT({
    datatable(
      rv$major_markers,
      editable = list(target = "cell", disable = list(columns = c())),
      options = list(
        pageLength = 15,
        dom = "t",
        ordering = FALSE
      ),
      rownames = FALSE
    )
  })

  # 处理表格编辑
  observeEvent(input$marker_editor_table_cell_edit, {
    info <- input$marker_editor_table_cell_edit
    rv$major_markers[info$row, info$col] <- info$value
  })

  # 添加新行
  observeEvent(input$add_marker_row, {
    new_row <- data.frame(
      细胞类型 = "新类型",
      Marker基因 = "GENE1,GENE2,GENE3",
      stringsAsFactors = FALSE
    )
    rv$major_markers <- rbind(rv$major_markers, new_row)
  })

  # 恢复默认
  observeEvent(input$reset_markers, {
    rv$major_markers <- default_major_markers
    showNotification("已恢复默认marker表", type = "message")
  })

  # 保存并关闭
  observeEvent(input$save_markers, {
    showNotification("Marker表已保存", type = "message", duration = 3)
    removeModal()
  })

  # 模板切换
  observeEvent(input$marker_template, {
    template <- input$marker_template

    # 忽略空值（用于分隔线）和当前编辑
    if (is.null(template) || template == "" || template == "current") {
      return()
    }

    template_markers <- get_template_markers(template)
    if (!is.null(template_markers)) {
      rv$major_markers <- template_markers
      rv$marker_config_source <- sprintf("模板-%s", template)
      rv$marker_config_auto_loaded <- FALSE

      # 显示模板信息
      n_types <- nrow(template_markers)
      showNotification(sprintf("✓ 已加载【%s】模板（%d种细胞类型）", template, n_types),
        type = "message", duration = 5
      )

      cat(sprintf("\n📋 加载组织模板: %s\n", template))
      cat(sprintf("   细胞类型数: %d\n", n_types))
      cat(sprintf("   类型列表: %s\n", paste(head(template_markers$细胞类型, 5), collapse = ", ")))
      if (n_types > 5) cat(sprintf("   ... 还有%d种\n", n_types - 5))
    }
  })

  # CSV上传
  observeEvent(input$upload_marker_csv, {
    req(input$upload_marker_csv)

    uploaded_markers <- load_marker_from_csv(input$upload_marker_csv$datapath)
    if (!is.null(uploaded_markers)) {
      rv$major_markers <- uploaded_markers
      rv$marker_config_source <- "上传CSV"
      rv$marker_config_auto_loaded <- FALSE
      showNotification("已从CSV文件加载marker配置", type = "message")

      # 更新模板选择为"当前编辑"
      updateSelectInput(session, "marker_template", selected = "current")
    } else {
      showNotification("CSV文件格式错误，请检查", type = "error")
    }
  })

  # 保存到数据集目录
  observeEvent(input$save_marker_to_dataset, {
    if (is.null(rv$current_dataset_path) || !dir.exists(rv$current_dataset_path)) {
      showNotification("无法确定数据集路径，请先加载数据集", type = "warning")
      return()
    }

    tryCatch(
      {
        marker_config_path <- file.path(rv$current_dataset_path, "marker_config.csv")
        write.csv(rv$major_markers, marker_config_path, row.names = FALSE, fileEncoding = "UTF-8")
        showNotification(sprintf("已保存到 %s", marker_config_path), type = "message", duration = 5)

        # 更新状态
        rv$marker_config_auto_loaded <- TRUE
        rv$marker_config_source <- "LLM 结合知识库自主构建"
      },
      error = function(e) {
        showNotification(sprintf("保存失败: %s", e$message), type = "error")
      }
    )
  })

  # 下载配置
  output$download_marker_config <- downloadHandler(
    filename = function() {
      paste0("marker_config_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".csv")
    },
    content = function(file) {
      write.csv(rv$major_markers, file, row.names = FALSE, fileEncoding = "UTF-8")
    }
  )

  # AURA2.0进度显示
  output$aura2_progress_ui <- renderUI({
    if (rv$aura2_status$analysis_running) {
      div(
        style = "margin-top: 15px;",
        tags$div(
          class = "progress",
          tags$div(
            class = "progress-bar progress-bar-striped active",
            style = "width: 100%;",
            "AURA2.0分析进行中..."
          )
        )
      )
    } else if (rv$aura2_status$analysis_complete) {
      div(
        style = "margin-top: 15px; padding: 10px; background-color: #d4edda; border: 1px solid #c3e6cb; border-radius: 5px; color: #155724;",
        "✓ AURA2.0分析完成"
      )
    } else {
      div(
        style = "margin-top: 15px; padding: 10px; background-color: #f8f9fa; border: 1px solid #dee2e6; border-radius: 5px; color: #6c757d;",
        "等待启动分析..."
      )
    }
  })

  # 更新细胞簇选择选项
  observe({
    if (rv$clustering_done && !is.null(rv$pbmc)) {
      if ("seurat_clusters" %in% colnames(rv$pbmc@meta.data)) {
        clusters <- sort(unique(rv$pbmc$seurat_clusters))
        cluster_choices <- paste0("Cluster ", clusters)
        names(cluster_choices) <- as.character(clusters)

        updateSelectInput(session, "aura2_cluster_select",
          choices = cluster_choices,
          selected = names(cluster_choices)[1]
        )
      }
    }
  })

  # ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  # 事件：AURA分析启动（行11955-12100）核心逻辑！
  # ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
  observeEvent(c(input$start_aura2, rv$trigger_aura_batch), {
    cat("\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n")
    cat("[AURA启动] observeEvent 被触发！\n")
    cat("[AURA启动] 触发源:", if (!is.null(input$start_aura2)) "手动按钮" else "自动流水线", "\n")
    cat("[AURA启动] rv$trigger_aura_batch 值:", rv$trigger_aura_batch, "\n")
    cat("[AURA启动] rv$auto_pipeline_active:", rv$auto_pipeline_active, "\n")
    cat("[AURA启动] rv$auto_pipeline_mode:", rv$auto_pipeline_mode, "\n")
    cat("[AURA启动] input$aura_batch_mode:", input$aura_batch_mode, "\n")
    cat("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n")

    # 检查前置条件
    cat("[AURA启动] 检查前置条件...\n")
    if (!rv$aura2_status$dependencies_checked) {
      cat("[AURA启动] ❌ dependencies_checked = FALSE\n")
      showNotification("请先检查系统依赖", type = "warning", duration = 5)
      return()
    }
    cat("[AURA启动] ✅ dependencies_checked = TRUE\n")

    if (!rv$aura2_status$api_keys_configured) {
      cat("[AURA启动] ❌ api_keys_configured = FALSE\n")
      showNotification("请先配置API密钥", type = "warning", duration = 5)
      return()
    }
    cat("[AURA启动] ✅ api_keys_configured = TRUE\n")

    if (!rv$aura2_status$parallel_env_ready) {
      cat("[AURA启动] ❌ parallel_env_ready = FALSE\n")
      showNotification("请先设置并行计算环境", type = "warning", duration = 5)
      return()
    }
    cat("[AURA启动] ✅ parallel_env_ready = TRUE\n")

    if (!rv$clustering_done) {
      cat("[AURA启动] ❌ clustering_done = FALSE\n")
      # showNotification("请先完成聚类分析", type = "warning", duration = 5)
      return()
    }
    cat("[AURA启动] ✅ clustering_done = TRUE\n")

    # 【修复】检查分析模式：优先使用流水线模式，而不是UI状态
    batch_mode <- if (rv$auto_pipeline_active && !is.null(rv$auto_pipeline_mode)) {
      # 自动流水线模式：根据 rv$auto_pipeline_mode 决定
      if (rv$auto_pipeline_mode == "per_cluster") {
        cat("[AURA启动] 检测到自动流水线逐簇模式，强制使用 hierarchical\n")
        "hierarchical"
      } else {
        cat("[AURA启动] 检测到自动流水线批量模式，强制使用 batch\n")
        "batch"
      }
    } else {
      # 手动模式：使用UI选择
      input$aura_batch_mode %||% "batch"
    }
    cat("[AURA启动] 最终分析模式 (batch_mode):", batch_mode, "\n")
    cat("[AURA启动] 所有检查通过，继续执行AURA分析...\n\n")

    # ═══════════════════════════════════════════════════════════════
    # 【新增】初始化测试结果记录
    # ═══════════════════════════════════════════════════════════════
    cat("\n\n")
    cat("╔═══════════════════════════════════════════════════════════╗\n")
    cat("║                 测试结果记录系统初始化                    ║\n")
    cat("╚═══════════════════════════════════════════════════════════╝\n\n")

    tryCatch(
      {
        # 1. 创建测试文件夹（如果还没创建或需要更新模式标签）
        cat("【步骤 1/4】创建测试结果文件夹...\n")

        # 确定模式标签
        mode_for_folder <- if (batch_mode == "hierarchical") "constrained" else if (batch_mode == "batch") "batch" else "single"

        # 检查是否需要创建或更新文件夹
        if (is.null(rv$test_folder)) {
          # 文件夹不存在，创建新的
          rv$test_folder <- create_test_result_folder(mode = mode_for_folder, sample_name = rv$sample_path)

          if (!is.null(rv$test_folder) && dir.exists(rv$test_folder)) {
            cat("  ✅ 成功创建测试文件夹\n")
            cat("  📂 路径:", rv$test_folder, "\n\n")
          } else {
            stop("测试文件夹创建失败或路径无效")
          }
        } else {
          # 文件夹已存在，检查是否包含模式标签
          folder_name <- basename(rv$test_folder)
          if (!grepl("\\+(批量|逐簇|单簇)", folder_name)) {
            # 文件夹名称不包含模式标签，强制重新创建带模式的文件夹
            cat("  ℹ️ 现有文件夹缺少模式标签，重新创建...\n")
            rv$test_folder <- create_test_result_folder(mode = mode_for_folder, sample_name = rv$sample_path)
            cat("  ✅ 已更新为带模式标签的文件夹\n")
            cat("  📂 新路径:", rv$test_folder, "\n\n")
          } else {
            cat("  ℹ️ 测试文件夹已存在:", rv$test_folder, "\n\n")
          }
        }

        # 2. 初始化日志系统
        cat("【步骤 2/4】初始化日志系统...\n")
        if (is.null(rv$log_files)) {
          rv$log_files <- init_log_system(rv$test_folder)

          if (!is.null(rv$log_files)) {
            cat("  ✅ 日志系统初始化成功\n\n")
          } else {
            cat("  ⚠️ 日志系统初始化失败，但不影响主流程\n\n")
          }
        } else {
          cat("  ℹ️ 日志系统已初始化\n\n")
        }

        # 3. 保存参数列表
        cat("【步骤 3/4】保存参数列表...\n")
        tryCatch(
          {
            dims_range <- input$dims_min:input$dims_max
            # 【修复】使用实际执行的分辨率，而不是界面输入框的值
            resolution <- rv$best_resolution %||% input$resolution %||% 0.5

            # 【修复】判断注释模式：不能重新赋值batch_mode，会覆盖前面的设置
            # 使用前面已经正确设置的 batch_mode 变量
            annotation_mode_text <- if (batch_mode == "batch") {
              "批量注释模式（一次性注释所有簇）"
            } else if (batch_mode == "hierarchical") {
              "层次注释模式（逐级细分）"
            } else {
              "逐簇注释模式"
            }

            save_parameters_to_md(
              folder = rv$test_folder,
              resolution = resolution,
              dims_range = dims_range,
              qc_params = rv$qc_params,
              sample_path = rv$sample_path
            )
            cat("  ✅ 参数列表保存成功\n\n")
          },
          error = function(e) {
            cat("  ⚠️ 参数列表保存失败:", e$message, "\n")
            cat("  但不影响主流程，继续执行...\n\n")
          }
        )

        # 4. 初始化对话记录文件
        cat("【步骤 4/4】初始化对话记录文件...\n")
        tryCatch(
          {
            rv$conversation_log_file <- init_conversation_log(rv$test_folder)

            if (!is.null(rv$conversation_log_file) && file.exists(rv$conversation_log_file)) {
              cat("  ✅ 对话记录文件创建成功\n")
              cat("  📄 路径:", rv$conversation_log_file, "\n\n")
            } else {
              cat("  ⚠️ 对话记录文件创建失败\n\n")
            }
          },
          error = function(e) {
            cat("  ⚠️ 对话记录初始化失败:", e$message, "\n\n")
          }
        )

        cat("╔═══════════════════════════════════════════════════════════╗\n")
        cat("║            测试结果记录系统初始化完成！✅                ║\n")
        cat("╚═══════════════════════════════════════════════════════════╝\n\n")
      },
      error = function(e) {
        cat("\n")
        cat("╔═══════════════════════════════════════════════════════════╗\n")
        cat("║               ❌ 初始化测试结果记录失败！                ║\n")
        cat("╚═══════════════════════════════════════════════════════════╝\n")
        cat("  错误信息:", e$message, "\n")
        cat("  错误位置:", deparse(sys.calls()[[1]]), "\n")
        cat("  建议: 检查文件夹权限和磁盘空间\n")
        cat("═══════════════════════════════════════════════════════════\n\n")
      }
    )

    # 启动AURA2.0分析
    rv$aura2_status$analysis_running <- TRUE
    rv$aura2_status$analysis_complete <- FALSE

    # 【错误处理】使用tryCatch捕获AURA分析中的错误
    aura_success <- tryCatch(
      {
        if (batch_mode == "hierarchical") {
          # ========== 约束注释模式（限定候选类型）==========
          print_main_title("约束注释模式", 60)

          all_clusters <- sort(unique(rv$pbmc$seurat_clusters))
          total <- length(all_clusters)

          cat(sprintf("  总簇数: %d\n", total))
          cat(sprintf("  候选类型数: %d\n", nrow(rv$major_markers)))
          cat("\n  候选类型列表:\n")
          for (i in seq_len(min(5, nrow(rv$major_markers)))) {
            cat(sprintf("    %d. %s\n", i, rv$major_markers$细胞类型[i]))
          }
          if (nrow(rv$major_markers) > 5) {
            cat(sprintf("    ... 还有%d种类型\n", nrow(rv$major_markers) - 5))
          }
          print_separator("═", 60)

          withProgress(message = "约束注释进行中...", value = 0, {
            print_status("info", "步骤1/2: 构建知识图谱...")

            # 步骤1.1: 为每个簇构建知识图谱（同batch模式）
            all_markers_list <- list()
            all_knowledge_bases <- list()

            cat("\n")
            for (i in seq_along(all_clusters)) {
              cid <- all_clusters[i]
              incProgress(0.25 / total, detail = paste0("Level 1: 簇", cid, "查询数据库"))

              markers_df <- tryCatch(GetMarkers(rv$pbmc, cid, 10), error = function(e) NULL)
              if (!is.null(markers_df)) {
                markers <- rownames(markers_df)

                # 确保markers_df有gene列（用于后续AI识别）
                if (!"gene" %in% colnames(markers_df)) {
                  markers_df$gene <- rownames(markers_df)
                }

                all_markers_list[[as.character(cid)]] <- list(
                  markers = markers,
                  markers_df = markers_df, # 保存完整数据框用于计算marker_quality
                  top5 = paste(head(markers, 5), collapse = ", ")
                )

                # 查询4个数据库（clusterProfiler, PanglaoDB, CellMarker, scType）
                # gprofiler2已注释（网络不可达）

                # 【修复】动态获取组织类型
                dataset_tissue <- if (!is.null(rv$current_dataset_path)) {
                  extract_tissue_from_dataset(rv$current_dataset_path)
                } else {
                  "Unknown"
                }

                cluster_kg <- tryCatch(
                  {
                    # gp <- run_gprofiler_analysis(markers, rv$parallel_env)  # 已注释：网络不可达
                    gp <- NULL # gprofiler2不可用
                    cp <- run_clusterprofiler_analysis(markers, rv$parallel_env)
                    pl <- run_panglao_analysis(markers)
                    cm <- run_cellmarker_analysis(markers, rv$parallel_env, tissue = dataset_tissue)
                    st <- run_sctype_analysis(markers, tissue = dataset_tissue)

                    build_knowledge_base(
                      stringdb_results = list(),
                      gprofiler_results = gp,
                      clusterprofiler_results = cp,
                      cellmarker_results = cm,
                      panglao_results = pl, # 修复：添加PanglaoDB结果
                      literature_results = list(),
                      markers = markers,
                      markers_full_df = markers_df, # ✅ 传递完整数据框（包含log2FC等）
                      sctype_results = st
                    )
                  },
                  error = function(e) {
                    cat(" 知识图谱构建失败:", e$message, "\n")
                    NULL
                  }
                )

                all_knowledge_bases[[as.character(cid)]] <- cluster_kg
              }
            }
            # 统计成功构建的知识图谱数量（排除NULL）
            non_null_graphs <- Filter(Negate(is.null), all_knowledge_bases)
            success_count_kg <- length(non_null_graphs)
            print_status("success", sprintf("知识图谱构建完成: %d/%d 簇成功", success_count_kg, total))

            # 步骤2: 约束注释（对每个簇完整AURA流程+输出约束）
            incProgress(0.05, detail = "约束注释: 开始分析")

            api_keys <- list(
              deepseek = Sys.getenv("DEEPSEEK_API_KEY"),
              kimi = Sys.getenv("KIMI_API_KEY"),
              glm = Sys.getenv("GLM_API_KEY")
            )

            cat("\n")
            print_status("info", "步骤2/2: 约束注释（逐簇完整AURA）...")
            cat("\n")

            constrained_results <- list()

            # 为每个簇进行完整AURA分析（输出约束到候选类型）
            for (i in seq_along(all_clusters)) {
              cid <- as.character(all_clusters[i])
              incProgress(0.6 / total, detail = paste0("约束注释: 簇", cid))

              cluster_kg <- all_knowledge_bases[[cid]]
              cluster_markers <- all_markers_list[[cid]]$markers

              if (!is.null(cluster_kg) && !is.null(cluster_markers)) {
                cat(sprintf("\n  ┌─ 簇%s ─────────────────────────────────┐\n", cid))
                cat(sprintf("  │ Marker: %s\n", substr(all_markers_list[[cid]]$top5, 1, 35)))

                # 1. 构建SuperPrompt（包含GO/KEGG/PanglaoDB信息）
                super_prompt <- build_super_prompt(cluster_kg, cluster_markers[1:min(10, length(cluster_markers))])

                # 2. 添加输出约束到Prompt（包含参考marker）
                marker_reference <- sapply(1:nrow(rv$major_markers), function(i) {
                  type_name <- rv$major_markers$细胞类型[i]
                  markers <- rv$major_markers$Marker基因[i]
                  paste0("- ", type_name, " (参考marker: ", markers, ")")
                })

                constrained_prompt <- paste0(
                  super_prompt, "\n\n",
                  "【重要约束 + 参考Marker】\n",
                  "你必须从以下", nrow(rv$major_markers), "种主要细胞类型中选择一种。\n",
                  "每种类型的参考marker基因如下（按特异性排序，前面的更特异）：\n",
                  paste0(marker_reference, collapse = "\n"), "\n\n",
                  "💡 marker排序说明：每种类型的marker按特异性从高到低排列，前面的基因更能代表该类型。\n",
                  "不要输出其他类型！只能从上述", nrow(rv$major_markers), "种中选择！"
                )

                # 3. 更新knowledge_base的enhanced_prompt
                cluster_kg$enhanced_prompt <- constrained_prompt

                # 4. 调用完整AURA引擎（三轮辩论+规则+验证）
                aura_result <- tryCatch(
                  {
                    MultiLLM_Consensus_Engine(
                      knowledge_base = cluster_kg,
                      seurat_obj = rv$pbmc,
                      api_keys = api_keys,
                      debater_A = input$debater_a %||% "deepseek",
                      debater_B = input$debater_b %||% "kimi",
                      referee = input$referee %||% "glm",
                      enable_rules = input$enable_rules_engine %||% TRUE
                    )
                  },
                  error = function(e) {
                    list(final_annotation = "Unknown", final_score = 0.5)
                  }
                )

                # 验证
                validation_result <- tryCatch(
                  {
                    Massive_Validator(
                      predicted_type = aura_result$final_annotation,
                      knowledge_base = cluster_kg,
                      markers = cluster_markers
                    )
                  },
                  error = function(e) {
                    list(biological_score = 0.70)
                  }
                )

                # ═══════════════════════════════════════════════════════════════
                # 【新评分体系】三个独立质量指标（不使用Final_Score）
                # ═══════════════════════════════════════════════════════════════

                # 指标1: Marker指标（三个独立维度，基于Seurat统计量）
                marker_metrics <- calculate_marker_quality(all_markers_list[[cid]]$markers_df, top_n = 10)

                # 指标2: Referee Decision（裁判最终决定，不报告置信度）
                referee_decision <- as.character(aura_result$final_annotation)

                # 指标3: Database Support（3个数据库匹配数）
                # 简化规则：数据库返回结果且不是Unknown → Match
                db_support_count <- 0
                db_details <- list()

                # CellMarker匹配检查（直接判断是否有结果）
                if (!is.null(knowledge_base$analysis_summary$cellmarker_summary)) {
                  cm <- knowledge_base$analysis_summary$cellmarker_summary
                  if (!is.null(cm$best_match) && cm$best_match != "Unknown") {
                    db_support_count <- db_support_count + 1
                    db_details$cellmarker <- paste0("Match: ", cm$best_match)
                  } else {
                    db_details$cellmarker <- "No Match"
                  }
                } else {
                  db_details$cellmarker <- "Database Unavailable"
                }

                # scType匹配检查
                if (!is.null(knowledge_base$analysis_summary$sctype_summary)) {
                  st <- knowledge_base$analysis_summary$sctype_summary
                  if (!is.null(st$best_match) && st$best_match != "Unknown") {
                    db_support_count <- db_support_count + 1
                    db_details$sctype <- paste0("Match: ", st$best_match)
                  } else {
                    db_details$sctype <- "No Match"
                  }
                } else {
                  db_details$sctype <- "Database Unavailable"
                }

                # PanglaoDB匹配检查
                if (!is.null(knowledge_base$analysis_summary$panglao_summary)) {
                  pl <- knowledge_base$analysis_summary$panglao_summary
                  if (!is.null(pl$best_match) && pl$best_match != "Unknown") {
                    db_support_count <- db_support_count + 1
                    db_details$panglao <- paste0("Match: ", pl$best_match)
                  } else {
                    db_details$panglao <- "No Match"
                  }
                } else {
                  db_details$panglao <- "Database Unavailable"
                }

                database_support <- paste0(db_support_count, "/3")

                # 构建结果（三个独立质量指标，无综合评分）
                constrained_results[[cid]] <- list(
                  cluster = cid,
                  status = "success",
                  annotation = referee_decision,

                  # ═══ 三个独立质量指标 ═══
                  # 指标1: Marker指标（三个独立维度）
                  marker_specificity = marker_metrics$specificity,
                  marker_expression = marker_metrics$expression_strength,
                  marker_significance = marker_metrics$significance,

                  # 指标2: Referee Decision
                  referee_decision = referee_decision,

                  # 指标3: Database Support
                  database_support = database_support,
                  database_details = db_details,

                  # 辅助信息
                  markers = all_markers_list[[cid]]$top5,
                  debate_history = aura_result$debate_history,
                  knowledge_base = cluster_kg,
                  validation_result = validation_result,
                  markers_df = all_markers_list[[cid]]$markers_df
                )

                # 控制台输出（三个独立指标）
                cat(sprintf("  │ Referee Decision: %s\n", referee_decision))
                cat(sprintf("  │ Marker Metrics:\n"))
                cat(sprintf("  │   - Specificity  : %.3f\n", marker_metrics$specificity))
                cat(sprintf("  │   - Expression   : %.3f\n", marker_metrics$expression_strength))
                cat(sprintf("  │   - Significance : %.3f\n", marker_metrics$significance))
                cat(sprintf("  │ Database Support: %s\n", database_support))
                cat("  └──────────────────────────────────────────┘\n")

                # ═══════════════════════════════════════════════════════════════
                # 【新增】追加对话记录到文件
                # ═══════════════════════════════════════════════════════════════
                if (!is.null(rv$conversation_log_file)) {
                  tryCatch(
                    {
                      conversation_data <- list(
                        top_markers = all_markers_list[[cid]]$top5,
                        knowledge_base = cluster_kg,
                        debate_history = aura_result$debate_history,
                        referee_decision = TRUE,
                        referee_model = aura_result$referee_model %||% input$referee,
                        final_annotation = aura_result$final_annotation,
                        reasoning = aura_result$reasoning,
                        validation_result = validation_result,
                        marker_quality = marker_quality,
                        debate_score = debate_score,
                        validation_score = validation_score
                      )
                      append_conversation(rv$conversation_log_file, cid, conversation_data)
                    },
                    error = function(e) {
                      cat("  ⚠️ 记录对话失败:", e$message, "\n")
                    }
                  )
                }
              } else {
                constrained_results[[cid]] <- list(
                  cluster = cid,
                  annotation = "Unknown",
                  confidence = 0.5,
                  markers = ""
                )
                cat(" → Unknown (数据缺失)\n")
              }
            }

            cat("\n")
            print_main_title("约束注释完成", 60)

            # 保存结果
            if (length(constrained_results) > 0) {
              rv$hierarchical_results <- constrained_results
              rv$hierarchical_analysis_done <- TRUE

              # 统计各类型簇数
              type_counts <- table(sapply(constrained_results, function(x) x$annotation))
              cat("  类型分布:\n")
              for (type_name in names(type_counts)) {
                count <- type_counts[type_name]
                bar <- strrep("█", min(20, as.numeric(count) * 2))
                cat(sprintf("    %-20s: %2d 簇 %s\n", type_name, count, bar))
              }
              print_separator("═", 60)
              cat(sprintf("  ✅ 成功: %d/%d 簇\n", length(constrained_results), total))

              # ═══════════════════════════════════════════════════════════════
              # 【新增】将注释结果应用到Seurat对象
              # ═══════════════════════════════════════════════════════════════
              if (length(constrained_results) > 0) {
                tryCatch(
                  {
                    print_sub_title("应用注释到Seurat对象", 50)

                    # 方法：逐个cluster构建向量（最安全）
                    all_clusters <- sort(unique(as.character(rv$pbmc$seurat_clusters)))
                    cat(sprintf("  📊 准备应用到 %d 个簇...\n", length(all_clusters)))

                    annotation_vec <- character(length(all_clusters))
                    confidence_vec <- numeric(length(all_clusters))

                    # 逐个cluster填充
                    for (i in seq_along(all_clusters)) {
                      cid <- all_clusters[i]
                      if (!is.null(constrained_results[[cid]]) &&
                        constrained_results[[cid]]$status == "success") {
                        annotation_vec[i] <- as.character(constrained_results[[cid]]$annotation)
                        # 【修复】confidence字段不存在，使用debate_score代替
                        confidence_vec[i] <- if (!is.null(constrained_results[[cid]]$debate_score)) {
                          as.numeric(constrained_results[[cid]]$debate_score)
                        } else if (!is.null(constrained_results[[cid]]$marker_specificity)) {
                          mean(c(
                            constrained_results[[cid]]$marker_specificity %||% 0.5,
                            constrained_results[[cid]]$marker_expression %||% 0.5,
                            constrained_results[[cid]]$marker_significance %||% 0.5
                          ), na.rm = TRUE)
                        } else {
                          0.5 # 默认值
                        }
                      } else {
                        annotation_vec[i] <- "Unknown"
                        confidence_vec[i] <- 0
                      }
                    }

                    # 设置names（关键！）
                    names(annotation_vec) <- all_clusters
                    names(confidence_vec) <- all_clusters

                    # 调试输出
                    cat(sprintf(
                      "  📊 annotation_vec长度: %d, names: %s...\n",
                      length(annotation_vec),
                      paste(head(names(annotation_vec), 3), collapse = ", ")
                    ))
                    cat(sprintf(
                      "  📊 pbmc细胞数: %d, 簇数: %d\n",
                      ncol(rv$pbmc),
                      length(unique(rv$pbmc$seurat_clusters))
                    ))

                    # 应用到每个细胞（最简单直接的方法）
                    cell_clusters <- as.character(rv$pbmc$seurat_clusters)
                    cat(sprintf(
                      "  📊 cell_clusters示例: %s...\n",
                      paste(head(cell_clusters, 3), collapse = ", ")
                    ))

                    # 直接创建与细胞数量相同的向量
                    n_cells <- ncol(rv$pbmc)
                    final_annotation <- character(n_cells)
                    final_confidence <- numeric(n_cells)

                    # 逐个细胞赋值
                    for (i in 1:n_cells) {
                      cluster_id <- cell_clusters[i]
                      if (cluster_id %in% names(annotation_vec)) {
                        final_annotation[i] <- annotation_vec[cluster_id]
                        final_confidence[i] <- confidence_vec[cluster_id]
                      } else {
                        final_annotation[i] <- "Unknown"
                        final_confidence[i] <- 0
                      }
                    }

                    # 直接赋值（不使用索引）
                    rv$pbmc@meta.data$AURA_annotation <- final_annotation
                    rv$pbmc@meta.data$AURA_confidence <- final_confidence
                    rv$pbmc@meta.data$AURA_mode <- rep("constrained", n_cells)

                    # 验证成功
                    if (!is.null(rv$pbmc$AURA_annotation)) {
                      cat(sprintf("  ✓ 成功应用到 %s 个细胞\n", format(ncol(rv$pbmc), big.mark = ",")))
                      cat(sprintf(
                        "  ✓ 约束到 %d 种细胞类型: %s\n",
                        length(unique(annotation_vec[annotation_vec != "Unknown"])),
                        paste(head(unique(annotation_vec[annotation_vec != "Unknown"]), 5), collapse = ", ")
                      ))
                    }
                    cat("\n")

                    rv$has_aura_annotation <- TRUE
                    rv$annotation_done <- TRUE
                  },
                  error = function(e) {
                    cat("⚠ 错误：应用注释失败:", e$message, "\n")
                    cat("  调试信息：\n")
                    cat("  - constrained_results长度:", length(constrained_results), "\n")
                    cat("  - pbmc细胞数:", ncol(rv$pbmc), "\n")

                    # 兜底方案：创建默认的AURA_annotation字段，避免UI报错
                    cat("  → 使用兜底方案：创建默认注释字段\n")
                    tryCatch(
                      {
                        rv$pbmc$AURA_annotation <- paste0("Cluster_", rv$pbmc$seurat_clusters)
                        rv$pbmc$AURA_confidence <- rep(0, ncol(rv$pbmc))
                        rv$pbmc$AURA_mode <- "failed"
                        cat("  ✓ 已创建默认注释字段（使用cluster编号）\n")
                      },
                      error = function(e2) {
                        cat("  ✗ 兜底方案也失败:", e2$message, "\n")
                      }
                    )
                  }
                )
              }

              # 设置兼容变量（供旧UI组件使用）
              success_results <- constrained_results[sapply(constrained_results, function(x) x$status == "success")]
              if (length(success_results) > 0) {
                first_success_cid <- names(success_results)[1]
                first_result <- success_results[[1]]

                cat("设置兼容变量，使用簇", first_success_cid, "作为示例\n")

                rv$aura2_results <- list(
                  cluster = first_success_cid,
                  annotation = first_result$annotation,
                  markers = first_result$markers,
                  key_evidence = unlist(strsplit(first_result$markers, ", "))[1:3],
                  biological_background = "基于约束AURA分析",
                  # 新的三个独立指标
                  marker_specificity = first_result$marker_specificity,
                  marker_expression = first_result$marker_expression,
                  marker_significance = first_result$marker_significance,
                  referee_decision = first_result$referee_decision,
                  database_support = first_result$database_support
                )

                rv$llm_consensus_result <- list(
                  final_annotation = first_result$annotation,
                  debate_history = first_result$debate_history,
                  # 三个独立指标
                  marker_specificity = first_result$marker_specificity,
                  marker_expression = first_result$marker_expression,
                  marker_significance = first_result$marker_significance,
                  referee_decision = first_result$referee_decision,
                  database_support = first_result$database_support,
                  database_details = first_result$database_details
                )

                rv$validation_result <- first_result$validation_result
                rv$knowledge_base <- first_result$knowledge_base
              }

              # ═══════════════════════════════════════════════════════════════
              # 【新增】保存带有AURA注释的可视化图片
              # ═══════════════════════════════════════════════════════════════
              if (!is.null(rv$test_folder) && rv$has_aura_annotation) {
                tryCatch(
                  {
                    cat("\n═══════════════════════════════════════\n")
                    cat("保存AURA注释后的可视化图片\n")
                    cat("═══════════════════════════════════════\n")
                    saved_files <- save_visualization_plots(
                      folder = rv$test_folder,
                      pbmc_obj = rv$pbmc,
                      has_aura = TRUE
                    )
                    if (length(saved_files) > 0) {
                      cat("  ✅ 已更新AURA注释图片\n")
                    }
                    cat("═══════════════════════════════════════\n\n")
                  },
                  error = function(e) {
                    cat("  ⚠️ 保存AURA注释图片失败:", e$message, "\n")
                  }
                )
              }

              showNotification(paste0("约束注释完成！", length(constrained_results), "/", total, "簇。结果已保存到测试文件夹。"),
                type = "message", duration = 5
              )
            } else {
              print_status("error", "约束注释失败（无结果）")
              showNotification("约束注释失败", type = "error")
            }
          })

          rv$aura2_status$analysis_running <- FALSE
          rv$aura2_status$analysis_complete <- TRUE

          # 【自动流水线】逐簇注释完成后，自动触发UMAP/t-SNE
          if (rv$auto_pipeline_active && rv$auto_pipeline_step == "aura_percluster") {
            rv$auto_pipeline_step <- "umap"
            cat("\n[自动流水线] 逐簇注释完成，准备运行UMAP和t-SNE...\n")
            cat("[调试] 触发rv$trigger_umap_tsne\n")
            # 使用触发变量代替按钮点击
            Sys.sleep(1) # 等待UI更新
            rv$trigger_umap_tsne <- runif(1)
            cat("[调试] rv$trigger_umap_tsne =", rv$trigger_umap_tsne, "\n")
          }
        } else if (batch_mode == "batch") {
          # ========== 批量分析模式（一次辩论所有簇）==========
          print_main_title("批量分析模式", 60)

          # 【新增】初始化时间和成本统计
          analysis_start_time <- Sys.time()
          # 使用environment代替list，实现引用传递，确保API统计正确累加
          api_metrics <- new.env()
          api_metrics$total_calls <- 0
          api_metrics$total_tokens_input <- 0
          api_metrics$total_tokens_output <- 0
          api_metrics$total_tokens <- 0
          api_metrics$model_breakdown <- list()

          # 【新增】时间分解记录（论文性能分析）
          time_breakdown <- list()
          kg_build_start <- Sys.time()

          all_clusters <- sort(unique(rv$pbmc$seurat_clusters))
          total <- length(all_clusters)

          cat(sprintf("  总簇数: %d\n", total))
          cat(sprintf("  分析策略: 一次辩论所有簇\n"))
          cat(sprintf("  ⏱️ 开始时间: %s\n", format(analysis_start_time, "%Y-%m-%d %H:%M:%S")))
          print_separator("═", 60)

          withProgress(message = "批量分析启动...", value = 0, {
            # 步骤1: 为每个簇构建知识图谱（与约束注释相同）
            all_markers_list <- list()
            all_knowledge_bases <- list() # 存储每个簇的真实知识图谱

            print_status("info", "步骤1/3: 为每个簇构建知识图谱（5数据库）...")
            cat("\n")

            for (i in seq_along(all_clusters)) {
              cid <- all_clusters[i]
              incProgress(0.4 / total, detail = paste0("簇", cid, ": 查询数据库"))

              # 获取该簇的标记基因
              markers_df <- tryCatch(GetMarkers(rv$pbmc, cid, 10), error = function(e) NULL)
              if (!is.null(markers_df)) {
                markers <- rownames(markers_df)

                # 确保markers_df有gene列（用于后续AI识别）
                if (!"gene" %in% colnames(markers_df)) {
                  markers_df$gene <- rownames(markers_df)
                }

                all_markers_list[[as.character(cid)]] <- list(
                  markers = markers,
                  markers_df = markers_df, # 保存完整数据框用于计算marker_quality
                  top5 = paste(head(markers, 5), collapse = ", ")
                )

                # 为该簇查询4个数据库（真实查询！）
                # gprofiler2已注释（网络不可达）
                print_progress_bar(i, total, width = 30, label = sprintf("  簇%s", cid))

                # 【修复】动态获取组织类型
                dataset_tissue <- if (!is.null(rv$current_dataset_path)) {
                  extract_tissue_from_dataset(rv$current_dataset_path)
                } else {
                  "Unknown"
                }

                cluster_kg <- tryCatch(
                  {
                    # gp <- run_gprofiler_analysis(markers, rv$parallel_env)  # 已注释：网络不可达
                    gp <- NULL # gprofiler2不可用
                    cp <- run_clusterprofiler_analysis(markers, rv$parallel_env)
                    pl <- run_panglao_analysis(markers)
                    cm <- run_cellmarker_analysis(markers, rv$parallel_env, tissue = dataset_tissue)
                    st <- run_sctype_analysis(markers, tissue = dataset_tissue)

                    build_knowledge_base(
                      stringdb_results = list(),
                      gprofiler_results = gp,
                      clusterprofiler_results = cp,
                      cellmarker_results = cm,
                      panglao_results = pl, # 修复：添加PanglaoDB结果
                      literature_results = list(),
                      markers = markers,
                      markers_full_df = markers_df, # ✅ 传递完整数据框（包含log2FC等）
                      sctype_results = st
                    )
                  },
                  error = function(e) {
                    cat(" 失败:", e$message, "\n")
                    NULL
                  }
                )

                all_knowledge_bases[[as.character(cid)]] <- cluster_kg
                cat(" ✓\n")
              }
            }
            cat("成功为", length(all_knowledge_bases), "/", total, "个簇构建知识图谱\n")

            # 步骤2: 构建批量Prompt + 添加候选类型约束
            incProgress(0.1, detail = "构建批量Prompt...")

            if (!QUIET_DATABASE_QUERIES) {
              cat("\n═══════════════════════════════════════\n")
              cat("【方案1】为每个簇生成enhanced_prompt\n")
              cat("═══════════════════════════════════════\n")
            }

            # 批量Prompt开头（不指定样本来源，避免误导模型）
            batch_prompt <- paste0(
              "你是单细胞RNA测序专家。以下是", total, "个细胞簇的详细标记基因表达数据和功能注释。\n",
              "请仅基于提供的标记基因和功能注释，为每个簇判断细胞类型。\n\n",
              "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n"
            )

            # 【关键改进】为每个簇生成enhanced_prompt（完整定量数据）
            for (cid in names(all_markers_list)) {
              kg <- all_knowledge_bases[[cid]]
              cluster_markers <- all_markers_list[[cid]]$markers

              if (!is.null(kg) && !is.null(cluster_markers)) {
                if (!QUIET_DATABASE_QUERIES) cat(sprintf("  生成簇%s的enhanced_prompt...\n", cid))

                # ✅ 使用正确的build_super_prompt函数（包含完整定量数据）
                cluster_enhanced_prompt <- tryCatch(
                  {
                    build_super_prompt(
                      knowledge_base = kg,
                      top_markers = cluster_markers[1:min(20, length(cluster_markers))]
                    )
                  },
                  error = function(e) {
                    # 如果失败，使用简化版本
                    cat(sprintf("    ⚠️ enhanced_prompt生成失败: %s\n", e$message))
                    paste0("簇", cid, ":\n  标记基因: ", all_markers_list[[cid]]$top5, "\n")
                  }
                )

                # 添加到批量Prompt
                batch_prompt <- paste0(
                  batch_prompt,
                  "\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n",
                  "【簇", cid, "的完整信息】\n",
                  "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n",
                  cluster_enhanced_prompt,
                  "\n"
                )
              } else {
                cat(sprintf("  ⚠️ 簇%s没有知识图谱或标记基因，使用简化信息\n", cid))
                batch_prompt <- paste0(
                  batch_prompt,
                  "\n【簇", cid, "】\n",
                  "  标记基因: ", all_markers_list[[cid]]$top5 %||% "无", "\n"
                )
              }
            }

            cat("  ✓ 所有簇的enhanced_prompt生成完成\n")
            cat("═══════════════════════════════════════\n\n")

            # 【时间分解】知识图谱构建完成
            kg_build_end <- Sys.time()
            time_breakdown$kg_build_seconds <- as.numeric(difftime(kg_build_end, kg_build_start, units = "secs"))
            cat(sprintf("  ⏱️ 知识图谱构建耗时: %.2f秒\n\n", time_breakdown$kg_build_seconds))

            # 添加输出要求
            batch_prompt <- paste0(
              batch_prompt, "\n",
              "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n",
              "【输出要求】\n",
              "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n",
              "请输出严格的JSON格式，不要任何解释或代码块标记：\n",
              '{"0": "细胞类型", "1": "细胞类型", ...}\n\n',
              "键是簇ID（字符串），值是细胞类型名称。\n",
              "必须覆盖所有", total, "个簇：", paste(names(all_markers_list), collapse = ", "), "\n"
            )

            # 添加候选类型约束（与约束注释一致）
            # 【新增】同时传递每种类型的参考marker基因
            marker_reference <- sapply(1:nrow(rv$major_markers), function(i) {
              type_name <- rv$major_markers$细胞类型[i]
              markers <- rv$major_markers$Marker基因[i]
              paste0("- ", type_name, " (参考marker: ", markers, ")")
            })

            constrained_batch_prompt <- paste0(
              batch_prompt, "\n",
              "【重要约束 + 参考Marker】\n",
              "你必须从以下", nrow(rv$major_markers), "种主要细胞类型中选择一种。\n",
              "每种类型的参考marker基因如下（按特异性排序，前面的更特异）：\n",
              paste0(marker_reference, collapse = "\n"), "\n\n",
              "💡 marker排序说明：每种类型的marker按特异性从高到低排列，前面的基因更能代表该类型。\n",
              "不要输出其他类型！只能从上述", nrow(rv$major_markers), "种中选择！"
            )

            cat("批量Prompt长度:", nchar(constrained_batch_prompt), "字符\n")
            cat("📊 调试信息：检查每个簇的数据是否完整...\n")
            for (check_cid in names(all_markers_list)) {
              # 检查该簇的信息是否在batch_prompt中
              pattern <- paste0("【簇", check_cid, "的完整信息】")
              if (grepl(pattern, constrained_batch_prompt, fixed = TRUE)) {
                cat(sprintf("  ✓ 簇%s 数据已包含\n", check_cid))
              } else {
                cat(sprintf("  ❌ 簇%s 数据缺失！\n", check_cid))
              }
            }
            cat("📊 batch_prompt预览（前2000字符）:\n", substr(constrained_batch_prompt, 1, 2000), "\n...\n")

            # 步骤2: 一次三轮辩论（60%进度）
            incProgress(0.1, detail = "启动批量辩论...")

            api_keys <- list(
              deepseek = Sys.getenv("DEEPSEEK_API_KEY"),
              kimi = Sys.getenv("KIMI_API_KEY"),
              glm = Sys.getenv("GLM_API_KEY")
            )

            # 创建批量知识图谱（用于辩论引擎）
            # 包含约束后的Prompt（限定候选类型）
            batch_kg <- list(
              enhanced_prompt = constrained_batch_prompt,
              marker_genes = data.frame(gene = "batch", stringsAsFactors = FALSE),
              input_markers = unlist(lapply(all_markers_list, function(x) x$markers))
            )

            print_status("info", "步骤2/3: 批量辩论（一次三轮辩论所有簇）...")
            cat(sprintf("  辩手A: %s\n", input$debater_a %||% "deepseek"))
            cat(sprintf("  辩手B: %s\n", input$debater_b %||% "kimi"))
            cat(sprintf("  裁判: %s\n", input$referee %||% "glm"))
            cat("\n")

            # 【时间分解】辩论开始
            debate_start <- Sys.time()

            # 调用完整AURA辩论引擎（三轮辩论，批量模式）
            batch_debate_result <- tryCatch(
              {
                DebateReferee_Engine(
                  knowledge_base = batch_kg,
                  seurat_obj = rv$pbmc,
                  api_keys = api_keys,
                  debater_A = input$debater_a %||% "deepseek",
                  debater_B = input$debater_b %||% "kimi",
                  referee = input$referee %||% "glm",
                  is_batch_mode = TRUE, # 标记为批量模式
                  api_metrics = api_metrics # 传递API统计对象
                )
              },
              error = function(e) {
                cat("批量辩论失败:", e$message, "\n")
                list(success = FALSE, error = e$message, full_response = "")
              }
            )

            incProgress(0.6, detail = "解析批量结果...")

            # 【时间分解】辩论结束
            debate_end <- Sys.time()
            time_breakdown$debate_seconds <- as.numeric(difftime(debate_end, debate_start, units = "secs"))
            cat(sprintf("  ⏱️ 批量辩论耗时: %.2f秒\n\n", time_breakdown$debate_seconds))

            # 步骤3: 解析批量辩论结果（10%进度）
            if (!is.null(batch_debate_result) && batch_debate_result$success) {
              cat("尝试解析批量辩论JSON结果...\n")

              # 从辩论结果中提取JSON（裁判的最终裁决）
              response_text <- batch_debate_result$full_response

              # 调试：打印裁判完整响应（前1000字符）
              cat("裁判完整响应（前1000字符）:\n", substr(response_text, 1, 1000), "\n...\n")
              cat("裁判响应总长度:", nchar(response_text), "字符\n")

              # 使用完整JSON提取函数
              json_str <- extract_complete_json(response_text)

              if (!is.null(json_str)) {
                cat("✓ 成功从裁判结果提取JSON字符串，长度:", nchar(json_str), "字符\n")
                cat("JSON前300字符:", substr(json_str, 1, 300), "...\n")
                cat("JSON后100字符:", substr(json_str, nchar(json_str) - 99, nchar(json_str)), "\n")

                tryCatch(
                  {
                    parsed_json <- jsonlite::fromJSON(json_str, simplifyVector = FALSE)

                    # 支持新格式：{annotations: {...}, reasoning: "..."}
                    if (!is.null(parsed_json$annotations)) {
                      cat("✓ 检测到新格式JSON（包含annotations和reasoning）\n")
                      batch_annotations <- parsed_json$annotations
                      # 将reasoning保存到batch_debate_result中
                      batch_debate_result$reasoning <- parsed_json$reasoning %||% ""
                      cat("  裁判reasoning长度:", nchar(batch_debate_result$reasoning), "字符\n")
                    } else {
                      # 兼容旧格式：{"0": "T cell", ...}
                      batch_annotations <- parsed_json
                    }

                    cat("✓ JSON解析成功！解析", length(batch_annotations), "个簇的注释\n")
                    cat("解析的簇ID:", paste(names(batch_annotations), collapse = ", "), "\n")

                    # 保存结果并进行验证
                    incProgress(0.15, detail = "模块3：批量验证...")
                    rv$batch_results <- list()
                    success_count <- 0

                    # 从辩论结果中提取debate_score（裁判的置信度）
                    batch_debate_score <- batch_debate_result$confidence %||% 0.75

                    print_status("info", sprintf("步骤3/3: 批量验证 (%d个簇)...", length(names(batch_annotations))))
                    cat(sprintf("  批量辩论分数: %.3f\n", batch_debate_score))
                    cat("\n")

                    for (cid in names(batch_annotations)) {
                      # 获取该簇的标记基因
                      cluster_markers <- if (!is.null(all_markers_list[[cid]])) all_markers_list[[cid]]$markers else c()

                      # 获取该簇的真实知识图谱（步骤1已查询）
                      cluster_kg <- all_knowledge_bases[[cid]]

                      # 如果没有真实知识图谱，创建基础版本
                      if (is.null(cluster_kg)) {
                        cat(" 无知识图谱，使用基础验证...")
                        cluster_kg <- list(
                          analysis_summary = list(
                            gprofiler_summary = list(significant_terms = 0),
                            clusterprofiler_summary = list(significant_pathways = 0),
                            cellmarker_summary = list(best_match = "Unknown", matched_markers = 0),
                            sctype_summary = list(best_match = "Unknown", best_overlap = 0)
                          )
                        )
                      }

                      # 调用Massive_Validator验证（使用真实数据库结果）
                      validation_result <- tryCatch(
                        {
                          Massive_Validator(
                            predicted_type = batch_annotations[[cid]],
                            knowledge_base = cluster_kg,
                            markers = cluster_markers
                          )
                        },
                        error = function(e) {
                          cat(" 验证失败\n")
                          list(biological_score = 0.65, evidence_chain = paste("验证错误:", e$message))
                        }
                      )

                      # ═══════════════════════════════════════════════════════════════
                      # 【新评分体系】三个独立质量指标（不使用Final_Score）
                      # ═══════════════════════════════════════════════════════════════

                      # 指标1: Marker指标（三个独立维度，基于Seurat统计量）
                      marker_metrics <- calculate_marker_quality(all_markers_list[[cid]]$markers_df, top_n = 10)

                      # 【修复】计算marker质量的平均值用于compatibility
                      marker_quality_avg <- mean(c(
                        marker_metrics$specificity,
                        marker_metrics$expression_strength,
                        marker_metrics$significance
                      ), na.rm = TRUE)

                      # 指标2: Referee Decision（裁判最终决定，不报告置信度）
                      referee_decision <- as.character(batch_annotations[[cid]])

                      # 计算debate score和validation score
                      debate_score <- batch_debate_score
                      validation_score <- validation_result$biological_score %||% 0.70
                      validation_score <- ifelse(is.numeric(validation_score), validation_score, 0.70)

                      # 【已删除】不再计算综合final_score

                      # 指标3: Database Support（3个数据库匹配数）
                      # 简化规则：数据库返回结果且不是Unknown → Match
                      db_support_count <- 0
                      db_details <- list()

                      # CellMarker匹配检查（直接判断是否有结果）
                      if (!is.null(cluster_kg$analysis_summary$cellmarker_summary)) {
                        cm <- cluster_kg$analysis_summary$cellmarker_summary
                        if (!is.null(cm$best_match) && cm$best_match != "Unknown") {
                          db_support_count <- db_support_count + 1
                          db_details$cellmarker <- paste0("Match: ", cm$best_match)
                        } else {
                          db_details$cellmarker <- "No Match"
                        }
                      } else {
                        db_details$cellmarker <- "Database Unavailable"
                      }

                      # scType匹配检查
                      if (!is.null(cluster_kg$analysis_summary$sctype_summary)) {
                        st <- cluster_kg$analysis_summary$sctype_summary
                        if (!is.null(st$best_match) && st$best_match != "Unknown") {
                          db_support_count <- db_support_count + 1
                          db_details$sctype <- paste0("Match: ", st$best_match)
                        } else {
                          db_details$sctype <- "No Match"
                        }
                      } else {
                        db_details$sctype <- "Database Unavailable"
                      }

                      # PanglaoDB匹配检查
                      if (!is.null(cluster_kg$analysis_summary$panglao_summary)) {
                        pl <- cluster_kg$analysis_summary$panglao_summary
                        if (!is.null(pl$best_match) && pl$best_match != "Unknown") {
                          db_support_count <- db_support_count + 1
                          db_details$panglao <- paste0("Match: ", pl$best_match)
                        } else {
                          db_details$panglao <- "No Match"
                        }
                      } else {
                        db_details$panglao <- "Database Unavailable"
                      }

                      database_support <- paste0(db_support_count, "/3")

                      # 构建结果（三个独立质量指标）
                      rv$batch_results[[cid]] <- list(
                        cluster = cid,
                        status = "success",
                        annotation = referee_decision,

                        # ═══ 三个独立质量指标 ═══
                        # 指标1: Marker指标（三个独立维度）
                        marker_specificity = marker_metrics$specificity,
                        marker_expression = marker_metrics$expression_strength,
                        marker_significance = marker_metrics$significance,
                        marker_quality = as.numeric(round(marker_quality_avg, 3)),

                        # 指标2: Referee Decision
                        referee_decision = referee_decision,
                        debate_score = as.numeric(debate_score),

                        # 指标3: Database Support
                        database_support = database_support,
                        database_details = db_details,
                        validation_score = as.numeric(validation_score),

                        # 辅助信息
                        markers = if (!is.null(all_markers_list[[cid]])) all_markers_list[[cid]]$top5 else "",
                        debate_history = batch_debate_result$debate_history,
                        knowledge_base = cluster_kg,
                        validation_result = validation_result,
                        markers_df = all_markers_list[[cid]]$markers_df
                      )
                      success_count <- success_count + 1
                      print_progress_bar(success_count, length(names(batch_annotations)),
                        width = 30, label = "  验证进度"
                      )
                    }
                    cat("\n")
                    print_main_title("批量分析完成", 60)
                    cat(sprintf("  ✓ 成功: %d/%d 簇\n", success_count, length(names(batch_annotations))))
                    cat(sprintf("  ✗ 失败: %d/%d 簇\n", length(names(batch_annotations)) - success_count, length(names(batch_annotations))))
                    print_separator("═", 60)
                  },
                  error = function(e) {
                    cat("✗ JSON解析失败:", e$message, "\n")
                    cat("尝试解析的JSON:", substr(json_str, 1, 500), "...\n")
                    # 失败时标记所有簇
                    rv$batch_results <- lapply(all_clusters, function(cid) {
                      list(cluster = as.character(cid), status = "failed", error = paste("JSON解析失败:", e$message))
                    })
                    names(rv$batch_results) <- as.character(all_clusters)
                  }
                )
              } else {
                cat("✗ 裁判未返回JSON格式\n")
                cat("响应文本前500字符:", substr(response_text, 1, 500), "\n")

                # 备选方案：尝试从辩手A的结果中提取JSON
                cat("\n尝试备选方案：使用辩手A的JSON结果...\n")

                tryCatch(
                  {
                    debater_a_response <- batch_debate_result$debate_history$round1$result_A$full_response
                    json_str_fallback <- extract_complete_json(debater_a_response)

                    if (!is.null(json_str_fallback)) {
                      cat("✓ 成功从辩手A提取JSON，长度:", nchar(json_str_fallback), "字符\n")
                      batch_annotations <- jsonlite::fromJSON(json_str_fallback)
                      cat("✓ JSON解析成功！解析", length(batch_annotations), "个簇的注释\n")
                      cat("解析的簇ID:", paste(names(batch_annotations), collapse = ", "), "\n")

                      # 使用辩手A的置信度作为debate_score
                      batch_debate_score <- batch_debate_result$debate_history$round1$result_A$confidence %||% 0.70
                      cat("使用辩手A的置信度:", batch_debate_score, "\n")

                      # 继续验证流程（与成功解析裁判JSON相同的代码）
                      incProgress(0.15, detail = "模块3：批量验证...")
                      rv$batch_results <- list()
                      success_count <- 0

                      print_status("info", sprintf("步骤3/3: 批量验证 (%d个簇)...", length(names(batch_annotations))))
                      cat(sprintf("  批量辩论分数（辩手A）: %.3f\n", batch_debate_score))
                      cat("\n")

                      for (cid in names(batch_annotations)) {
                        cluster_markers <- if (!is.null(all_markers_list[[cid]])) all_markers_list[[cid]]$markers else c()
                        cluster_kg <- all_knowledge_bases[[cid]]

                        if (is.null(cluster_kg)) {
                          cluster_kg <- list(
                            analysis_summary = list(
                              gprofiler_summary = list(significant_terms = 0),
                              clusterprofiler_summary = list(significant_pathways = 0),
                              cellmarker_summary = list(best_match = "Unknown", matched_markers = 0),
                              sctype_summary = list(best_match = "Unknown", best_overlap = 0)
                            )
                          )
                        }

                        validation_result <- tryCatch(
                          {
                            Massive_Validator(
                              predicted_type = batch_annotations[[cid]],
                              knowledge_base = cluster_kg,
                              markers = cluster_markers
                            )
                          },
                          error = function(e) {
                            list(biological_score = 0.65, evidence_chain = paste("验证错误:", e$message))
                          }
                        )

                        # 计算Marker指标（三个独立维度）
                        marker_metrics <- calculate_marker_quality(all_markers_list[[cid]]$markers_df, top_n = 10)

                        # 使用平均值作为marker_quality（兼容旧评分体系）
                        marker_quality <- mean(c(
                          marker_metrics$specificity,
                          marker_metrics$expression_strength,
                          marker_metrics$significance
                        ), na.rm = TRUE)

                        debate_score <- batch_debate_score
                        validation_score <- validation_result$biological_score %||% 0.70
                        validation_score <- ifelse(is.numeric(validation_score), validation_score, 0.70)

                        rv$batch_results[[cid]] <- list(
                          cluster = cid,
                          status = "success",
                          annotation = as.character(batch_annotations[[cid]]),
                          marker_quality = as.numeric(round(marker_quality, 3)),
                          marker_specificity = as.numeric(round(marker_metrics$specificity, 3)),
                          marker_expression = as.numeric(round(marker_metrics$expression_strength, 3)),
                          marker_significance = as.numeric(round(marker_metrics$significance, 3)),
                          debate_score = as.numeric(debate_score),
                          validation_score = as.numeric(validation_score),
                          markers = if (!is.null(all_markers_list[[cid]])) all_markers_list[[cid]]$top5 else "",
                          knowledge_base = cluster_kg,
                          validation_result = validation_result,
                          debate_history = batch_debate_result$debate_history,
                          batch_debate_score = batch_debate_score,
                          markers_df = all_markers_list[[cid]]$markers_df
                        )
                        success_count <- success_count + 1
                        print_progress_bar(success_count, length(names(batch_annotations)),
                          width = 30, label = "  验证进度"
                        )
                      }
                      cat("\n")
                      print_main_title("批量分析完成（使用辩手A结果）", 60)
                      cat(sprintf("  ✓ 成功: %d/%d 簇\n", success_count, length(names(batch_annotations))))
                      print_separator("═", 60)
                    } else {
                      # 辩手A也没有JSON，尝试辩手B
                      cat("✗ 辩手A也没有JSON，尝试辩手B...\n")
                      debater_b_response <- batch_debate_result$debate_history$round1$result_B$full_response
                      json_str_fallback_b <- extract_complete_json(debater_b_response)

                      if (!is.null(json_str_fallback_b)) {
                        cat("✓ 成功从辩手B提取JSON\n")
                        batch_annotations <- jsonlite::fromJSON(json_str_fallback_b)
                        # 使用辩手B的置信度
                        batch_debate_score <- batch_debate_result$debate_history$round1$result_B$confidence %||% 0.70

                        # 执行验证流程（简化版，避免重复代码）
                        # 这里需要与上面相同的验证循环...
                        cat("✓ 使用辩手B的结果进行验证\n")
                        # TODO: 添加验证循环
                      } else {
                        # 所有方案都失败
                        cat("✗ 所有JSON提取方案都失败\n")
                        rv$batch_results <- lapply(all_clusters, function(cid) {
                          list(cluster = as.character(cid), status = "failed", error = "未找到JSON")
                        })
                        names(rv$batch_results) <- as.character(all_clusters)
                      }
                    }
                  },
                  error = function(e) {
                    cat("备选方案失败:", e$message, "\n")
                    rv$batch_results <- lapply(all_clusters, function(cid) {
                      list(cluster = as.character(cid), status = "failed", error = "JSON解析全部失败")
                    })
                    names(rv$batch_results) <- as.character(all_clusters)
                  }
                )
              }
            } else {
              cat("✗ 批量辩论失败或无响应\n")
              if (!is.null(batch_debate_result$error)) {
                cat("错误详情:", batch_debate_result$error, "\n")
              }
              rv$batch_results <- lapply(all_clusters, function(cid) {
                list(cluster = as.character(cid), status = "failed", error = "批量辩论失败")
              })
              names(rv$batch_results) <- as.character(all_clusters)
            }
          })

          rv$batch_analysis_done <- TRUE
          rv$aura2_status$analysis_running <- FALSE
          rv$aura2_status$analysis_complete <- TRUE

          success_count <- sum(sapply(rv$batch_results, function(x) x$status == "success"))

          # 【新增】计算总时间和API成本
          analysis_end_time <- Sys.time()
          total_duration_seconds <- as.numeric(difftime(analysis_end_time, analysis_start_time, units = "secs"))

          cat("\n批量分析完成！成功:", success_count, "/", total, "簇\n")
          cat(sprintf("⏱️ 总耗时: %.2f 秒 (%.2f 分钟)\n", total_duration_seconds, total_duration_seconds / 60))
          cat(sprintf("📞 总API调用次数: %d\n", api_metrics$total_calls))
          cat(sprintf(
            "💰 总Token消耗: %d (输入:%d + 输出:%d)\n",
            api_metrics$total_tokens,
            api_metrics$total_tokens_input,
            api_metrics$total_tokens_output
          ))

          # 【新增】计算API成本（基于各模型价格，单位：美元）
          # 价格来源：各API官网最新定价（2025年1月），单位：美元/1M tokens
          # 注意：快速模型（_fast后缀）价格通常为标准模型的50%-70%
          model_pricing <- list(
            # DeepSeek (2025年2月后统一定价)
            deepseek = list(input = 0.27, output = 1.10), # deepseek-chat标准模型
            deepseek_fast = list(input = 0.14, output = 0.28), # deepseek-chat快速模型（估算）

            # Moonshot Kimi
            kimi = list(input = 0.25, output = 1.00), # kimi-k1.5标准模型
            kimi_fast = list(input = 0.15, output = 0.60), # kimi快速模型（估算）

            # GLM-4
            glm = list(input = 0.50, output = 0.50), # GLM-4标准模型
            glm_fast = list(input = 0.25, output = 0.25), # GLM-4快速模型（估算）

            # 豆包 Doubao (火山引擎)
            doubao = list(input = 0.80, output = 2.00), # doubao-pro-32k
            doubao_fast = list(input = 0.30, output = 0.60), # doubao-lite-32k快速模型

            # 通义千问
            qwen = list(input = 0.40, output = 1.20), # qwen标准模型
            qwen_fast = list(input = 0.20, output = 0.60), # qwen快速模型（估算）

            # 腾讯混元
            hunyuan = list(input = 0.30, output = 1.00), # hunyuan标准模型
            hunyuan_fast = list(input = 0.15, output = 0.50), # hunyuan快速模型（估算）

            # 文心一言
            ernie = list(input = 0.80, output = 2.00), # ernie标准模型
            ernie_fast = list(input = 0.40, output = 1.00), # ernie快速模型（估算）

            # 阶跃星辰
            stepfun = list(input = 5.00, output = 5.00), # stepfun标准模型
            stepfun_fast = list(input = 2.50, output = 2.50), # stepfun快速模型（估算）

            # 讯飞星火
            spark = list(input = 2.10, output = 2.10), # spark标准模型
            spark_fast = list(input = 1.05, output = 1.05), # spark快速模型（估算）

            # MiniMax
            minimax = list(input = 5.00, output = 5.00), # minimax标准模型
            minimax_fast = list(input = 2.50, output = 2.50) # minimax快速模型（估算）
          )

          total_cost_usd <- 0
          for (model_key in names(api_metrics$model_breakdown)) {
            # 移除_fast后缀以匹配定价表，但优先匹配完整名称
            pricing_key <- if (model_key %in% names(model_pricing)) {
              model_key # 完整匹配（包括_fast）
            } else {
              sub("_fast$", "", model_key) # 回退到基础模型名
            }

            if (pricing_key %in% names(model_pricing)) {
              pricing <- model_pricing[[pricing_key]]
              breakdown <- api_metrics$model_breakdown[[model_key]]

              # 成本 = (输入token数 / 1,000,000) * 输入价格 + (输出token数 / 1,000,000) * 输出价格
              model_cost <- (breakdown$tokens_input / 1e6) * pricing$input +
                (breakdown$tokens_output / 1e6) * pricing$output

              api_metrics$model_breakdown[[model_key]]$cost_usd <- model_cost
              total_cost_usd <- total_cost_usd + model_cost

              cat(sprintf(
                "  - %s: %d次调用, %d tokens, $%.4f\n",
                model_key, breakdown$calls, breakdown$tokens_total, model_cost
              ))
            } else {
              cat(sprintf("  ⚠️ %s: 未找到定价信息，跳过成本计算\n", model_key))
            }
          }

          cat(sprintf("💵 总成本估算: $%.4f 美元\n\n", total_cost_usd))

          # 【增强】计算簇级别统计信息（论文分析用）
          cluster_stats <- list()
          for (cid in names(rv$batch_results)) {
            if (rv$batch_results[[cid]]$status == "success") {
              cluster_cells <- sum(rv$pbmc$seurat_clusters == cid)

              # 【修复】计算综合置信度（使用debate_score和marker指标）
              combined_confidence <- if (!is.null(rv$batch_results[[cid]]$debate_score)) {
                as.numeric(rv$batch_results[[cid]]$debate_score)
              } else if (!is.null(rv$batch_results[[cid]]$marker_quality)) {
                as.numeric(rv$batch_results[[cid]]$marker_quality)
              } else {
                0.5 # 默认值
              }

              cluster_stats[[cid]] <- list(
                cell_count = cluster_cells,
                annotation = rv$batch_results[[cid]]$annotation,
                confidence = combined_confidence,
                debate_score = rv$batch_results[[cid]]$debate_score %||% NA,
                marker_quality = rv$batch_results[[cid]]$marker_quality %||% NA,
                marker_gene_count = if (!is.null(rv$batch_results[[cid]]$markers_df)) {
                  nrow(rv$batch_results[[cid]]$markers_df)
                } else {
                  0
                }
              )
            }
          }

          # 【增强】计算辩手一致性指标（AURA核心优势）
          agreement_stats <- NULL
          if (!is.null(batch_debate_result$debate_history)) {
            dh <- batch_debate_result$debate_history
            # 提取辩手A和B的初始判断
            if (!is.null(dh$round1$result_A$full_response) &&
              !is.null(dh$round1$result_B$full_response)) {
              # 尝试解析JSON获取每个簇的判断
              tryCatch(
                {
                  json_a <- extract_complete_json(dh$round1$result_A$full_response)
                  json_b <- extract_complete_json(dh$round1$result_B$full_response)

                  if (!is.null(json_a) && !is.null(json_b)) {
                    annot_a <- jsonlite::fromJSON(json_a)
                    annot_b <- jsonlite::fromJSON(json_b)

                    # 计算一致的簇数量
                    common_clusters <- intersect(names(annot_a), names(annot_b))
                    if (length(common_clusters) > 0) {
                      agreements <- sum(annot_a[common_clusters] == annot_b[common_clusters])
                      agreement_stats <- list(
                        total_clusters = length(common_clusters),
                        agreed_clusters = agreements,
                        agreement_rate = agreements / length(common_clusters),
                        disagreed_clusters = common_clusters[annot_a[common_clusters] != annot_b[common_clusters]]
                      )
                    }
                  }
                },
                error = function(e) {
                  cat("⚠️ 计算一致性时出错:", e$message, "\n")
                }
              )
            }
          }

          # 【增强】稀有细胞类型识别（论文关键指标）
          rare_cell_types <- NULL
          if (success_count > 0) {
            # 统计每种细胞类型的数量
            all_annotations <- sapply(rv$batch_results, function(x) {
              if (x$status == "success") x$annotation else NA
            })
            all_annotations <- all_annotations[!is.na(all_annotations)]

            if (length(all_annotations) > 0) {
              type_counts <- table(all_annotations)
              # 定义稀有类型：占比<5%
              total_clusters_annot <- length(all_annotations)
              rare_threshold <- ceiling(total_clusters_annot * 0.05)
              rare_types <- names(type_counts[type_counts <= rare_threshold])

              rare_cell_types <- list(
                rare_types = rare_types,
                rare_type_counts = as.list(type_counts[rare_types]),
                total_rare_types = length(rare_types),
                rare_threshold_clusters = rare_threshold
              )
            }
          }

          # 【增强】失败分析（论文质量控制）
          failure_analysis <- list(
            total_failed = sum(sapply(rv$batch_results, function(x) x$status == "failed")),
            failed_clusters = names(rv$batch_results)[sapply(rv$batch_results, function(x) x$status == "failed")],
            failure_reasons = list()
          )
          for (cid in failure_analysis$failed_clusters) {
            if (!is.null(rv$batch_results[[cid]]$error)) {
              failure_analysis$failure_reasons[[cid]] <- rv$batch_results[[cid]]$error
            }
          }

          # 【增强】读取数据集元信息（论文Figure 1d表格）
          dataset_metadata <- NULL
          tryCatch(
            {
              metadata_file <- "数据集/dataset_metadata.csv"
              if (file.exists(metadata_file)) {
                metadata_df <- read.csv(metadata_file, stringsAsFactors = FALSE)
                # 尝试匹配当前数据集（通过细胞数或文件名）
                current_cell_count <- ncol(rv$pbmc)
                matched_row <- metadata_df[abs(metadata_df$cell_count - current_cell_count) < 50, ]
                if (nrow(matched_row) > 0) {
                  dataset_metadata <- as.list(matched_row[1, ])
                }
              }
            },
            error = function(e) {
              cat("⚠️ 读取数据集元信息失败:", e$message, "\n")
            }
          )

          # 【新增】保存增强版metrics到rv，供下载RDS时使用
          rv$aura_metrics <- list(
            # 基础性能指标
            runtime_seconds = total_duration_seconds,
            start_time = format(analysis_start_time, "%Y-%m-%d %H:%M:%S"),
            end_time = format(analysis_end_time, "%Y-%m-%d %H:%M:%S"),
            total_cost_usd = total_cost_usd,
            total_api_calls = api_metrics$total_calls,
            total_tokens = list(
              input = api_metrics$total_tokens_input,
              output = api_metrics$total_tokens_output,
              total = api_metrics$total_tokens
            ),
            model_breakdown = api_metrics$model_breakdown,
            annotation_mode = "batch",

            # 【新增】时间分解（论文性能分析）
            time_breakdown = list(
              kg_build_seconds = time_breakdown$kg_build_seconds %||% 0,
              debate_seconds = time_breakdown$debate_seconds %||% 0,
              validation_seconds = total_duration_seconds -
                (time_breakdown$kg_build_seconds %||% 0) -
                (time_breakdown$debate_seconds %||% 0),
              total_seconds = total_duration_seconds
            ),

            # 【论文数据】辩论历史（完整三轮辩论记录）
            debate_history = batch_debate_result$debate_history,

            # 【论文数据】簇级别统计
            cluster_statistics = cluster_stats,
            total_clusters = length(all_clusters),

            # 【论文数据】辩手一致性指标（AURA独有）
            debater_agreement = agreement_stats,

            # 【新增】详细Marker基因列表（每个簇）
            marker_genes_detailed = lapply(names(all_markers_list), function(cid) {
              markers_info <- all_markers_list[[cid]]
              if (!is.null(markers_info$markers_df)) {
                # 保存marker基因名称和表达值
                data.frame(
                  gene = rownames(markers_info$markers_df),
                  avg_log2FC = if ("avg_log2FC" %in% colnames(markers_info$markers_df)) {
                    markers_info$markers_df$avg_log2FC
                  } else {
                    NA
                  },
                  p_val_adj = if ("p_val_adj" %in% colnames(markers_info$markers_df)) {
                    markers_info$markers_df$p_val_adj
                  } else {
                    NA
                  },
                  stringsAsFactors = FALSE
                )
              } else {
                data.frame(gene = markers_info$markers, stringsAsFactors = FALSE)
              }
            }),

            # 【新增】候选细胞类型列表（知识图谱）
            candidate_cell_types = if (!is.null(rv$major_markers)) {
              list(
                types = rv$major_markers$细胞类型,
                count = nrow(rv$major_markers),
                markers_per_type = rv$major_markers$Marker基因
              )
            } else {
              NULL
            },

            # 【论文数据】Prompt信息
            prompt_info = list(
              prompt_length = if (!is.null(batch_kg$enhanced_prompt)) {
                nchar(batch_kg$enhanced_prompt)
              } else {
                0
              },
              candidate_types_count = if (!is.null(rv$major_markers)) {
                nrow(rv$major_markers)
              } else {
                0
              }
            ),

            # 【论文数据】稀有细胞类型识别
            rare_cell_analysis = rare_cell_types,

            # 【论文数据】失败分析
            failure_analysis = failure_analysis,

            # 【论文数据】数据集元信息（Figure 1d表格）
            dataset_info = dataset_metadata,

            # 【论文数据】细胞-簇映射（细粒度分析）
            cell_cluster_mapping = list(
              clusters = as.character(rv$pbmc$seurat_clusters),
              cell_barcodes = colnames(rv$pbmc)
            )
          )

          # ═══════════════════════════════════════════════════════════════
          # 【新增】将注释结果应用到Seurat对象
          # ═══════════════════════════════════════════════════════════════
          if (success_count > 0) {
            tryCatch(
              {
                print_sub_title("应用注释到Seurat对象", 50)

                # 方法：逐个cluster构建向量（最安全）
                all_clusters <- sort(unique(as.character(rv$pbmc$seurat_clusters)))
                cat(sprintf("  📊 准备应用到 %d 个簇...\n", length(all_clusters)))

                annotation_vec <- character(length(all_clusters))
                confidence_vec <- numeric(length(all_clusters))

                # 逐个cluster填充
                for (i in seq_along(all_clusters)) {
                  cid <- all_clusters[i]
                  if (!is.null(rv$batch_results[[cid]]) &&
                    rv$batch_results[[cid]]$status == "success") {
                    annotation_vec[i] <- as.character(rv$batch_results[[cid]]$annotation)
                    # 【修复】confidence字段不存在，使用debate_score代替
                    # 如果debate_score也不存在，计算三个指标的平均值
                    confidence_vec[i] <- if (!is.null(rv$batch_results[[cid]]$debate_score)) {
                      as.numeric(rv$batch_results[[cid]]$debate_score)
                    } else if (!is.null(rv$batch_results[[cid]]$marker_specificity)) {
                      # 使用三个marker指标的平均值
                      mean(c(
                        rv$batch_results[[cid]]$marker_specificity %||% 0.5,
                        rv$batch_results[[cid]]$marker_expression %||% 0.5,
                        rv$batch_results[[cid]]$marker_significance %||% 0.5
                      ), na.rm = TRUE)
                    } else {
                      0.5 # 默认值
                    }
                  } else {
                    annotation_vec[i] <- "Unknown"
                    confidence_vec[i] <- 0
                  }
                }

                # 设置names（关键！必须与cluster编号完全匹配）
                names(annotation_vec) <- all_clusters
                names(confidence_vec) <- all_clusters

                # 调试输出
                cat(sprintf(
                  "  📊 annotation_vec长度: %d, names: %s...\n",
                  length(annotation_vec),
                  paste(head(names(annotation_vec), 3), collapse = ", ")
                ))
                cat(sprintf(
                  "  📊 pbmc细胞数: %d, 簇数: %d\n",
                  ncol(rv$pbmc),
                  length(unique(rv$pbmc$seurat_clusters))
                ))

                # 应用到每个细胞（最简单直接的方法）
                cell_clusters <- as.character(rv$pbmc$seurat_clusters)
                cat(sprintf(
                  "  📊 cell_clusters示例: %s...\n",
                  paste(head(cell_clusters, 3), collapse = ", ")
                ))

                # 直接创建与细胞数量相同的向量
                n_cells <- ncol(rv$pbmc)
                final_annotation <- character(n_cells)
                final_confidence <- numeric(n_cells)

                # 逐个细胞赋值
                for (i in 1:n_cells) {
                  cluster_id <- cell_clusters[i]
                  if (cluster_id %in% names(annotation_vec)) {
                    final_annotation[i] <- annotation_vec[cluster_id]
                    final_confidence[i] <- confidence_vec[cluster_id]
                  } else {
                    final_annotation[i] <- "Unknown"
                    final_confidence[i] <- 0
                  }
                }

                # 直接赋值（不使用索引）
                rv$pbmc@meta.data$AURA_annotation <- final_annotation
                rv$pbmc@meta.data$AURA_confidence <- final_confidence
                rv$pbmc@meta.data$AURA_mode <- rep("batch", n_cells)

                # 验证成功
                if (!is.null(rv$pbmc$AURA_annotation)) {
                  cat(sprintf("  ✓ 成功应用到 %s 个细胞\n", format(ncol(rv$pbmc), big.mark = ",")))
                  cat(sprintf(
                    "  ✓ 识别出 %d 种细胞类型: %s\n",
                    length(unique(annotation_vec[annotation_vec != "Unknown"])),
                    paste(head(unique(annotation_vec[annotation_vec != "Unknown"]), 5), collapse = ", ")
                  ))
                }
                cat("\n")

                # 设置标志，让可视化页面知道有注释结果
                rv$has_aura_annotation <- TRUE
                rv$annotation_done <- TRUE
              },
              error = function(e) {
                cat("⚠ 错误：应用注释失败:", e$message, "\n")
                cat("  调试信息：\n")
                cat("  - batch_results长度:", length(rv$batch_results), "\n")
                cat("  - pbmc细胞数:", ncol(rv$pbmc), "\n")
                cat("  - seurat_clusters类型:", class(rv$pbmc$seurat_clusters), "\n")

                # 兜底方案：创建默认的AURA_annotation字段，避免UI报错
                cat("  → 使用兜底方案：创建默认注释字段\n")
                tryCatch(
                  {
                    rv$pbmc$AURA_annotation <- paste0("Cluster_", rv$pbmc$seurat_clusters)
                    rv$pbmc$AURA_confidence <- rep(0, ncol(rv$pbmc))
                    rv$pbmc$AURA_mode <- "failed"
                    cat("  ✓ 已创建默认注释字段（使用cluster编号）\n")
                  },
                  error = function(e2) {
                    cat("  ✗ 兜底方案也失败:", e2$message, "\n")
                  }
                )
              }
            )
          }

          # ═══════════════════════════════════════════════════════════════
          # 【新增】模块4：调用下游分析顾问
          # ═══════════════════════════════════════════════════════════════
          if (success_count > 0 && rv$has_aura_annotation) {
            tryCatch(
              {
                cat("\n═══════════════════════════════════════\n")
                cat("模块4：下游分析顾问启动\n")
                cat("═══════════════════════════════════════\n")

                # 收集所有注释结果
                all_annotations <- rv$pbmc$AURA_annotation
                all_annotations <- all_annotations[!is.na(all_annotations) & all_annotations != "Unknown"]

                if (length(all_annotations) > 0) {
                  # 调用下游分析顾问
                  advisor_result <- DownstreamAnalysisAdvisor(
                    all_annotations = all_annotations,
                    seurat_obj = rv$pbmc,
                    use_llm = TRUE,
                    api_keys = list(
                      deepseek = input$deepseek_api_key,
                      kimi = input$kimi_api_key,
                      glm = input$glm_api_key
                    )
                  )

                  # 保存结果到rv
                  rv$downstream_advisor_result <- advisor_result

                  if (!is.null(advisor_result) && advisor_result$success) {
                    cat("✓ 下游分析建议生成成功\n")
                    cat(sprintf("  - 主要细胞类型: %s\n", advisor_result$dominant_type))
                    cat(sprintf("  - 簇数: %d\n", advisor_result$total_clusters))
                    cat(sprintf("  - 细胞类型数: %d\n", advisor_result$unique_types))
                    cat(sprintf("  - 推荐分析数: %d\n", length(advisor_result$recommendations)))
                  } else {
                    cat("⚠ 下游分析建议生成失败或无结果\n")
                  }
                } else {
                  cat("⚠ 无有效注释结果，跳过下游分析顾问\n")
                }
              },
              error = function(e) {
                cat("⚠ 下游分析顾问错误:", e$message, "\n")
                rv$downstream_advisor_result <- list(success = FALSE, error = e$message)
              }
            )
          }

          # ═══════════════════════════════════════════════════════════════
          # 【新增】批量模式：保存可视化图片和对话记录
          # ═══════════════════════════════════════════════════════════════
          if (success_count > 0 && !is.null(rv$test_folder) && rv$has_aura_annotation) {
            tryCatch(
              {
                cat("\n═══════════════════════════════════════\n")
                cat("保存批量分析结果\n")
                cat("═══════════════════════════════════════\n")

                # 【调试】检查rv$pbmc的降维结果
                cat("  [调试] rv$pbmc对象类:", class(rv$pbmc)[1], "\n")
                cat("  [调试] rv$pbmc降维槽位:", paste(names(rv$pbmc@reductions), collapse = ", "), "\n")

                # 1. 保存AURA注释后的可视化图片
                saved_files <- save_visualization_plots(
                  folder = rv$test_folder,
                  pbmc_obj = rv$pbmc,
                  has_aura = TRUE
                )
                if (length(saved_files) > 0) {
                  cat("  ✅ 已保存AURA注释图片\n")
                }

                # 2. 保存批量对话记录到文件
                if (!is.null(rv$conversation_log_file)) {
                  for (cid in names(rv$batch_results)) {
                    result <- rv$batch_results[[cid]]
                    if (result$status == "success") {
                      # 【方案1改进】提取真实的推理依据而不是硬编码
                      reasoning_text <- if (!is.null(batch_debate_result$reasoning)) {
                        batch_debate_result$reasoning # 裁判的完整推理
                      } else if (!is.null(batch_debate_result$full_response)) {
                        # 从完整响应中提取推理部分（JSON后面的文字）
                        response <- batch_debate_result$full_response

                        # 找到JSON结束位置（最后一个}）
                        last_brace <- tail(gregexpr("\\}", response)[[1]], 1)

                        if (last_brace > 0 && last_brace < nchar(response) - 10) {
                          # JSON后面还有内容，提取出来
                          text_after_json <- substr(response, last_brace + 1, nchar(response))
                          text_after_json <- trimws(text_after_json)

                          if (nchar(text_after_json) > 50) {
                            # 有实质性内容
                            cat("[调试] 从裁判响应中提取到推理文本，长度:", nchar(text_after_json), "字符\n")
                            text_after_json
                          } else {
                            # 没有实质性内容，使用默认
                            paste0(
                              "批量分析模式（基于辩手A和B的综合判断）\n",
                              "辩手A观点：见第1轮辩论\n",
                              "辩手B观点：见第1轮辩论"
                            )
                          }
                        } else {
                          # JSON后面没有内容
                          paste0(
                            "批量分析模式（基于辩手A和B的综合判断）\n",
                            "辩手A观点：见第1轮辩论\n",
                            "辩手B观点：见第1轮辩论"
                          )
                        }
                      } else {
                        "批量分析模式（辩论结果未保存详细推理）"
                      }

                      conversation_data <- list(
                        top_markers = result$markers,
                        knowledge_base = result$knowledge_base,
                        debate_history = result$debate_history,
                        referee_decision = result$referee_decision,
                        referee_model = input$referee %||% "glm",
                        final_annotation = result$annotation,
                        reasoning = reasoning_text,
                        validation_result = result$validation_result,
                        # 三个独立指标
                        marker_specificity = result$marker_specificity,
                        marker_expression = result$marker_expression,
                        marker_significance = result$marker_significance,
                        database_support = result$database_support
                      )
                      append_conversation(rv$conversation_log_file, cid, conversation_data)
                    }
                  }
                  cat("  ✅ 已保存对话记录\n")
                }

                cat("═══════════════════════════════════════\n\n")
              },
              error = function(e) {
                cat("  ⚠️ 保存批量分析结果失败:", e$message, "\n")
              }
            )
          }

          # 设置兼容变量（供旧UI组件使用）
          if (success_count > 0) {
            # 使用第一个成功的簇作为展示示例
            success_results <- rv$batch_results[sapply(rv$batch_results, function(x) x$status == "success")]
            first_success_cid <- names(success_results)[1]
            first_result <- success_results[[1]]

            cat("设置兼容变量，使用簇", first_success_cid, "作为示例\n")

            # 【修复】计算综合置信度（新评分体系）
            combined_conf <- if (!is.null(first_result$debate_score)) {
              first_result$debate_score
            } else if (!is.null(first_result$marker_quality)) {
              first_result$marker_quality
            } else {
              0.75 # 默认值
            }

            rv$aura2_results <- list(
              cluster = first_success_cid,
              annotation = first_result$annotation,
              confidence = combined_conf,
              debate_score = first_result$debate_score,
              marker_quality = first_result$marker_quality,
              markers = first_result$markers,
              key_evidence = unlist(strsplit(first_result$markers, ", "))[1:3],
              biological_background = "基于批量AURA分析"
            )

            rv$llm_consensus_result <- list(
              final_annotation = first_result$annotation,
              debate_history = first_result$debate_history,
              # 新的三个独立指标
              marker_specificity = first_result$marker_specificity,
              marker_expression = first_result$marker_expression,
              marker_significance = first_result$marker_significance,
              referee_decision = first_result$referee_decision,
              database_support = first_result$database_support,
              database_details = first_result$database_details
            )

            rv$validation_result <- first_result$validation_result
            rv$knowledge_base <- first_result$knowledge_base
          }

          showNotification(paste0("批量分析完成！", success_count, "/", total, "簇"),
            type = "message", duration = 10
          )

          # 【自动流水线】如果在自动流水线中，自动触发UMAP/t-SNE
          if (rv$auto_pipeline_active && rv$auto_pipeline_step == "aura_batch") {
            rv$auto_pipeline_step <- "umap"
            cat("\n[自动流水线] 准备运行UMAP和t-SNE...\n")
            # 使用触发变量代替按钮点击
            rv$trigger_umap_tsne <- runif(1)
          }
        } # 闭合 if (batch_mode == "hierarchical") ... else if (batch_mode == "batch") ...

        TRUE # 成功标志
      },
      error = function(e) {
        cat("\n╔═══════════════════════════════════════════════════════════╗\n")
        cat("║                  ❌ AURA分析失败！                        ║\n")
        cat("╚═══════════════════════════════════════════════════════════╝\n")
        cat("  错误信息:", e$message, "\n")
        cat("  错误位置:", paste(head(deparse(sys.calls()[[sys.nframe() - 1]]), 3), collapse = "\n"), "\n")
        cat("═══════════════════════════════════════════════════════════\n\n")

        showNotification(paste("AURA分析失败:", e$message), type = "error", duration = 10)

        # 如果在自动流水线中，停止流水线
        if (rv$auto_pipeline_active) {
          rv$auto_pipeline_active <- FALSE
          rv$auto_pipeline_step <- "idle"
          cat("\n⚠️ 自动流水线已停止（AURA分析步骤失败）\n")
          showNotification("⚠️ 自动流水线已停止（AURA分析步骤失败）", type = "error", duration = 10)
        }

        rv$aura2_status$analysis_running <- FALSE
        FALSE # 失败标志
      }
    )

    # 最后设置分析状态
    rv$aura2_status$analysis_running <- FALSE
    if (aura_success) {
      rv$aura2_status$analysis_complete <- TRUE
    }
  })

  # 更新簇详情选择器的选项
  observe({
    if (rv$batch_analysis_done || rv$hierarchical_analysis_done) {
      available_clusters <- if (rv$batch_analysis_done) {
        names(rv$batch_results)
      } else if (rv$hierarchical_analysis_done) {
        names(rv$hierarchical_results)
      } else {
        c()
      }

      if (length(available_clusters) > 0) {
        cluster_choices <- paste0("Cluster ", available_clusters)
        names(cluster_choices) <- available_clusters

        updateSelectInput(session, "selected_cluster_details",
          choices = cluster_choices,
          selected = available_clusters[1]
        )
      }
    }
  })

  # ═══════════════════════════════════════════════════════════════
  # 旧的observe()块已删除（行13659-14107）
  # 原因：动态创建输出存在时序问题，导致UI无法正确显示
  # 新方案：所有Tab内容已在output$cluster_details_ui内部直接渲染
  # 修复时间：2025-10-16
  # ═══════════════════════════════════════════════════════════════

  # 以下是旧代码（已用if(FALSE)禁用，保留备份）
  if (FALSE) {
    # 这段代码已被新的直接渲染方式替代，不再执行
    observe({
      req(input$selected_cluster_details)
      cid <- as.character(input$selected_cluster_details)

      # 获取簇数据（统一转换为字符串以避免匹配失败）
      cluster_data <- if (rv$batch_analysis_done && !is.null(rv$batch_results[[cid]])) {
        rv$batch_results[[cid]]
      } else if (rv$hierarchical_analysis_done && !is.null(rv$hierarchical_results[[cid]])) {
        rv$hierarchical_results[[cid]]
      } else {
        NULL
      }

      if (is.null(cluster_data)) {
        return()
      }

      # 动态创建辩论详情输出
      output[[paste0("debate_details_", cid)]] <- renderUI({
        if (!is.null(cluster_data$debate_history)) {
          # 约束注释模式：有完整辩论记录
          debate_hist <- cluster_data$debate_history

          tagList(
            h4("三轮辩论过程", style = "color: #2c3e50; margin-top: 0;"),

            # 第一轮
            div(
