              h5(icon("gavel"), " 第一轮：初审辩论", style = "color: var(--primary);"),
              fluidRow(
                column(
                  6,
                  div(
                    style = "background: linear-gradient(135deg, var(--primary-dark), var(--primary)); color: white; padding: 15px; border-radius: 8px;",
                    h6("辩手A (", debate_hist$round1$model_A, ")", style = "color: white; margin-top: 0;"),
                    div(
                      style = "background: rgba(255,255,255,0.1); padding: 10px; border-radius: 5px; margin-bottom: 8px;",
                      strong("结论："), debate_hist$round1$result_A$cell_type
                    ),
                    div(
                      style = "background: rgba(255,255,255,0.1); padding: 10px; border-radius: 5px;",
                      strong("置信度："), round(debate_hist$round1$result_A$confidence, 3)
                    )
                  )
                ),
                column(
                  6,
                  div(
                    style = "background: linear-gradient(135deg, var(--primary), var(--primary-light)); color: white; padding: 15px; border-radius: 8px;",
                    h6("辩手B (", debate_hist$round1$model_B, ")", style = "color: white; margin-top: 0;"),
                    div(
                      style = "background: rgba(255,255,255,0.1); padding: 10px; border-radius: 5px; margin-bottom: 8px;",
                      strong("结论："), debate_hist$round1$result_B$cell_type
                    ),
                    div(
                      style = "background: rgba(255,255,255,0.1); padding: 10px; border-radius: 5px;",
                      strong("置信度："), round(debate_hist$round1$result_B$confidence, 3)
                    )
                  )
                )
              )
            ),

            # 第二轮
            div(
              style = "margin-bottom: 20px;",
              h5(icon("balance-scale"), " 第二轮：交叉质询", style = "color: var(--primary);"),
              div(
                style = "background: #f8f9fa; padding: 15px; border-radius: 8px; border: 1px solid var(--gray-300);",
                p(style = "color: var(--gray-700); font-size: 13px;", "辩手互相质询对方观点，寻找逻辑漏洞")
              )
            ),

            # 第三轮
            div(
              style = "margin-bottom: 15px;",
              h5(icon("certificate"), " 第三轮：裁判终审", style = "color: var(--primary);"),
              div(
                style = "background: linear-gradient(135deg, var(--primary-dark), var(--primary)); color: white; padding: 20px; border-radius: 8px;",
                h6(icon("check-circle"), " 最终裁决", style = "color: white; text-align: center;"),
                div(
                  style = "background: rgba(255,255,255,0.9); color: var(--gray-900); padding: 15px; border-radius: 5px; margin-top: 10px;",
                  div(
                    style = "text-align: center; margin-bottom: 10px;",
                    div(style = "font-size: 24px; font-weight: bold; color: var(--primary);", cluster_data$annotation),
                    div(
                      style = "font-size: 14px; color: var(--gray-600); margin-top: 5px;",
                      "置信度: ", round(cluster_data$debate_score, 3)
                    )
                  )
                )
              )
            )
          )
        } else {
          # 批量分析模式：显示共享的批量辩论信息
          div(
            style = "background: #e7f3ff; border-left: 4px solid var(--primary); padding: 15px; border-radius: 5px;",
            h5(icon("info-circle"), " 批量辩论模式", style = "color: var(--primary); margin-top: 0;"),
            p("此簇属于批量分析模式，所有簇共享一次三轮辩论结果。"),
            div(
              style = "background: white; padding: 12px; border-radius: 5px; margin-top: 10px;",
              strong("批量辩论分数："), round(cluster_data$batch_debate_score %||% cluster_data$debate_score, 3),
              br(), br(),
              tags$small("该分数由裁判对所有簇综合判断后给出，适用于所有簇的评分计算。")
            )
          )
        }
      })

      # 动态创建规则引擎详情输出
      output[[paste0("rules_details_", cid)]] <- renderUI({
        if (!is.null(cluster_data$pre_rules) || !is.null(cluster_data$post_rules)) {
          pre_warnings <- cluster_data$pre_rules$warnings %||% c()
          post_warnings <- cluster_data$post_rules$warnings %||% c()
          needs_review <- cluster_data$needs_review %||% FALSE

          tagList(
            h4("生物学规则引擎报告", style = "color: #2c3e50; margin-top: 0;"),

            # 审查状态
            div(
              style = paste0(
                "background: ", if (needs_review) "#f8d7da" else "#d4edda",
                "; border-left: 4px solid ", if (needs_review) "#dc3545" else "#28a745",
                "; padding: 15px; border-radius: 5px; margin-bottom: 20px;"
              ),
              div(
                style = "text-align: center;",
                icon(if (needs_review) "exclamation-triangle" else "check-circle",
                  class = "fa-2x",
                  style = paste0("color: ", if (needs_review) "#721c24" else "#155724", ";")
                ),
                h5(if (needs_review) "⚠️ 需要人工复核" else "✓ 通过审查",
                  style = paste0("color: ", if (needs_review) "#721c24" else "#155724", "; margin: 10px 0;")
                )
              )
            ),

            # 前置规则警告
            if (length(pre_warnings) > 0) {
              div(
                style = "margin-bottom: 20px;",
