                  tags$small("原始分数")
                )
              )
            ),

            # scType
            div(
              style = "background: white; border-left: 4px solid #3498db; padding: 15px; border-radius: 5px; margin-bottom: 10px;",
              div(
                style = "display: flex; justify-content: space-between; align-items: center;",
                div(
                  strong(icon("dna"), " scType组织特异性 (25%)"),
                  br(),
                  tags$small(style = "color: var(--gray-500);", "乳腺组织特异标记")
                ),
                div(
                  style = "text-align: right;",
                  div(
                    style = "font-size: 20px; font-weight: bold; color: #3498db;",
                    round(validation$validation_details$sctype %||% 0.5, 3)
                  )
                )
              )
            ),

            # PanglaoDB
            div(
              style = "background: white; border-left: 4px solid #e74c3c; padding: 15px; border-radius: 5px; margin-bottom: 10px;",
              div(
                style = "display: flex; justify-content: space-between; align-items: center;",
                div(
                  strong(icon("th"), " PanglaoDB (20%)"),
                  br(),
                  tags$small(style = "color: var(--gray-500);", "广谱细胞标记库")
                ),
                div(
                  style = "text-align: right;",
                  div(
                    style = "font-size: 20px; font-weight: bold; color: #e74c3c;",
