                )
              )
            ),

            # KEGG通路
            div(
              style = "background: white; border-left: 4px solid #27ae60; padding: 15px; border-radius: 5px; margin-bottom: 10px;",
              div(
                style = "display: flex; justify-content: space-between; align-items: center;",
                div(
                  strong(icon("project-diagram"), " KEGG通路 (5%)"),
                  br(),
                  tags$small(style = "color: var(--gray-500);", "信号通路分析")
                ),
                div(
                  style = "text-align: right;",
                  div(
                    style = "font-size: 20px; font-weight: bold; color: #27ae60;",
                    round(validation$validation_details$kegg_pathway %||% 0.5, 3)
                  )
                )
              )
            ),

            # STRINGdb
            div(
              style = "background: white; border-left: 4px solid #95a5a6; padding: 15px; border-radius: 5px;",
              div(
                style = "display: flex; justify-content: space-between; align-items: center;",
                div(
                  strong(icon("share-alt"), " STRINGdb互作 (5%)"),
                  br(),
                  tags$small(style = "color: var(--gray-500);", "蛋白质互作网络")
                ),
                div(
                  style = "text-align: right;",
                  div(
                    style = "font-size: 20px; font-weight: bold; color: #95a5a6;",
                    round(validation$validation_details$string_network %||% 0.5, 3)
                  )
                )
              )
            ),
            hr(),

            # 证据链文本
            if (!is.null(validation$evidence_chain) && validation$evidence_chain != "") {
              div(
                style = "background: #f8f9fa; padding: 15px; border-radius: 8px; border: 1px solid var(--gray-300);",
