                div(
                  style = "font-size: 12px;",
                  paste0("Expression: ", round(cluster_data$marker_expression %||% 0, 3))
                ),
                div(
                  style = "font-size: 12px;",
                  paste0("Significance: ", round(cluster_data$marker_significance %||% 0, 3))
                )
