            if (!is.null(cluster_data$debate_history)) {
              debate_hist <- cluster_data$debate_history
              # 安全访问字段
              round1_A <- debate_hist$round1$result_A %||% list(cell_type = "N/A", confidence = 0)
              round1_B <- debate_hist$round1$result_B %||% list(cell_type = "N/A", confidence = 0)
              model_A <- debate_hist$round1$model_A %||% "未知"
              model_B <- debate_hist$round1$model_B %||% "未知"

              tagList(
                h4("三轮辩论过程", style = "color: #2c3e50; margin-top: 0;"),
                # 第一轮
                div(
