              needs_review <- cluster_data$needs_review %||% FALSE
              pre_warnings <- cluster_data$pre_rules$warnings %||% c()
              post_warnings <- cluster_data$post_rules$warnings %||% c()

              tagList(
                h4("生物学规则引擎报告", style = "color: #2c3e50; margin-top: 0;"),

                # 审查状态卡片
                div(
