                    p(strong("显著通路: "), val_result$validation_details$kegg_count %||% 0),
                    tags$small(style = "color: var(--gray-600);", "信号通路分析")
                  ),

                  # STRINGdb
                  div(
                    style = "background: white; border: 1px solid var(--gray-300); padding: 15px; border-radius: 8px;",
                    h6("🔗 STRINGdb验证 (5%)", style = "color: var(--primary); margin-top: 0;"),
