                tabPanel(
                  title = "STRINGdb互作网络",
                  div(
                    style = "padding: 15px;",
                    h5("蛋白质互作网络", style = "color: #2c3e50;"),
                    if (!is.null(kg$stringdb_summary)) {
                      tagList(
                        div(
                          style = "display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-top: 15px;",
                          div(
                            style = "background: white; border: 1px solid var(--gray-300); padding: 12px; border-radius: 5px; text-align: center;",
                            div(style = "font-size: 20px; font-weight: bold; color: var(--primary);", kg$stringdb_summary$edges_count %||% 0),
                            div(style = "font-size: 12px; color: var(--gray-600); margin-top: 5px;", "互作边数")
                          ),
                          div(
                            style = "background: white; border: 1px solid var(--gray-300); padding: 12px; border-radius: 5px; text-align: center;",
                            div(style = "font-size: 20px; font-weight: bold; color: var(--primary);", kg$stringdb_summary$nodes_count %||% 0),
                            div(style = "font-size: 12px; color: var(--gray-600); margin-top: 5px;", "节点数")
                          ),
                          div(
                            style = "background: white; border: 1px solid var(--gray-300); padding: 12px; border-radius: 5px; text-align: center;",
                            div(style = "font-size: 20px; font-weight: bold; color: var(--primary);", round(kg$stringdb_summary$avg_score %||% 0, 3)),
