                ),

                # 子Tab 2: 功能富集
                tabPanel(
                  title = "功能富集分析",
                  div(
                    style = "padding: 15px;",
                    h5("gprofiler2 GO富集", style = "color: #2c3e50;"),
                    if (!is.null(kg$gprofiler_summary)) {
                      tagList(
                        p(strong("显著条目: "), kg$gprofiler_summary$significant_terms %||% 0),
                        p(strong("最佳FDR: "), format(kg$gprofiler_summary$best_fdr %||% 1, scientific = TRUE)),
                        if (length(kg$gprofiler_summary$top_terms %||% c()) > 0) {
                          div(
                            style = "margin-top: 15px;",
                            h6("Top 5 功能:", style = "color: var(--primary);"),
                            tags$ul(
                              style = "list-style-type: disc; padding-left: 20px;",
                              lapply(head(kg$gprofiler_summary$top_terms, 5), function(t) tags$li(t))
                            )
