                        }
                      )
                    } else {
                      div(
                        style = "text-align: center; padding: 30px; color: var(--gray-500);",
                        p("功能富集数据不可用")
                      )
                    }
                  )
                ),

                # 子Tab 3: 通路分析
                tabPanel(
                  title = "通路分析",
                  div(
                    style = "padding: 15px;",
