                    if (!is.null(kg$clusterprofiler_summary)) {
                      tagList(
                        p(strong("显著通路: "), kg$clusterprofiler_summary$significant_pathways %||% 0),
                        if (length(kg$clusterprofiler_summary$top_pathways %||% c()) > 0) {
                          div(
                            style = "margin-top: 15px;",
                            h6("Top 5 通路:", style = "color: var(--primary);"),
                            tags$ul(
                              style = "list-style-type: disc; padding-left: 20px;",
                              lapply(head(kg$clusterprofiler_summary$top_pathways, 5), function(p) tags$li(p))
                            )
                          )
                        }
                      )
                    } else {
                      div(
