                    h5("CellMarker数据库验证", style = "color: #2c3e50;"),
                    if (!is.null(kg$cellmarker_summary)) {
                      tagList(
                        div(
                          style = "background: #f8f9fa; border: 1px solid var(--gray-300); padding: 15px; border-radius: 8px; margin-top: 15px;",
                          p(strong("最佳匹配: "), kg$cellmarker_summary$best_match %||% "无"),
                          p(strong("相似度: "), round(kg$cellmarker_summary$similarity %||% 0, 3)),
                          p(strong("匹配基因数: "), kg$cellmarker_summary$matched_genes %||% 0)
                        )
                      )
