  })

  # AURA2.0结果摘要
  output$aura2_results_summary_ui <- renderUI({
    # 优先显示批量/约束注释的统计信息
    if (rv$batch_analysis_done || rv$hierarchical_analysis_done) {
      # 获取结果数据
      results_data <- if (rv$batch_analysis_done) {
        rv$batch_results
      } else {
        rv$hierarchical_results
      }

      mode_name <- if (rv$batch_analysis_done) "批量分析" else "约束注释"

      if (is.null(results_data) || length(results_data) == 0) {
        return(div(
          style = "padding: 20px; text-align: center; color: #6c757d;",
          "分析结果为空"
        ))
      }

      # 统计信息
      total <- length(results_data)
      success <- sum(sapply(results_data, function(x) x$status == "success"))
      failed <- total - success

      # 统计各细胞类型数量
      success_results <- results_data[sapply(results_data, function(x) x$status == "success")]
      if (length(success_results) > 0) {
        type_counts <- table(sapply(success_results, function(x) x$annotation))
      } else {
        type_counts <- table(character(0))
      }

      # 显示美观的统计卡片
      tagList(
        # 总体统计卡片
        div(
          style = "background: linear-gradient(135deg, var(--primary-dark), var(--primary)); color: white; padding: 20px; border-radius: 12px; margin-bottom: 20px;",
          h4(paste0(mode_name, "完成"), style = "color: white; margin-top: 0; text-align: center;"),
          div(
            style = "display: grid; grid-template-columns: repeat(3, 1fr); gap: 15px; margin-top: 15px;",
            div(
              style = "text-align: center;",
              div(style = "font-size: 32px; font-weight: bold;", total),
              div(style = "font-size: 13px; opacity: 0.9;", "总簇数")
            ),
            div(
              style = "text-align: center;",
              div(style = "font-size: 32px; font-weight: bold; color: #4ade80;", success),
              div(style = "font-size: 13px; opacity: 0.9;", "成功")
            ),
            div(
              style = "text-align: center;",
              div(style = "font-size: 32px; font-weight: bold; color: #f87171;", failed),
              div(style = "font-size: 13px; opacity: 0.9;", "失败")
            )
          )
        ),

        # 细胞类型分布
        if (length(type_counts) > 0) {
          div(
            style = "background: white; padding: 20px; border-radius: 12px; border: 1px solid var(--gray-300); margin-bottom: 20px;",
            h5("📊 细胞类型分布", style = "color: #2c3e50; margin-top: 0;"),
            div(
              style = "display: flex; flex-wrap: wrap; gap: 10px;",
              lapply(names(type_counts), function(type_name) {
                count <- type_counts[type_name]
                percentage <- round(count / success * 100, 1)
                div(
                  style = "background: linear-gradient(135deg, var(--primary-lightest), rgba(48, 43, 99, 0.05)); border-left: 4px solid var(--primary); padding: 12px; border-radius: 8px; flex: 1; min-width: 200px;",
                  div(
                    style = "display: flex; justify-content: space-between; align-items: center;",
                    div(
                      strong(style = "color: var(--primary);", type_name),
                      br(),
                      tags$small(style = "color: var(--gray-600);", paste0(count, "个簇 (", percentage, "%)"))
                    ),
                    div(style = "font-size: 28px; font-weight: bold; color: var(--primary);", count)
                  )
                )
              })
            )
          )
        },

        # 【新增】应用成功提示
        if (!is.null(rv$pbmc$AURA_annotation)) {
          div(
            style = "background: #d4edda; border-left: 4px solid #28a745; padding: 15px; border-radius: 8px; margin-bottom: 15px;",
            icon("check-circle"), " ",
            strong("注释已应用："),
            sprintf(
              " %s 个细胞已标注为 %d 种细胞类型",
              format(ncol(rv$pbmc), big.mark = ","),
              length(unique(rv$pbmc$AURA_annotation))
            ),
            br(),
            tags$small(
              style = "color: var(--gray-700); margin-top: 8px; display: block;",
              "提示：前往'聚类分析'页面，在可视化选项中选择'AURA注释'即可在UMAP/t-SNE图上查看细胞类型标签。"
            )
          )
        },

        # 提示信息
        div(
          style = "background: #e7f3ff; border-left: 4px solid var(--primary); padding: 15px; border-radius: 8px;",
          icon("info-circle"), " ",
          strong("提示："),
          paste0("这是", mode_name, "的总体统计。要查看单个簇的详细证据（辩论过程、规则引擎、验证证据、知识图谱），请使用下方的'查看单个簇的详细证据'功能。")
        )
      )
    } else if (rv$aura2_status$analysis_complete && !is.null(rv$aura2_results)) {
      # 旧版兼容代码（如果变量存在但批量/约束标志未设置）
      results <- rv$aura2_results

      div(
        style = "padding: 15px; background-color: #f8f9fa; border-radius: 8px; border: 1px solid #dee2e6;",
        h4("分析结果（示例簇）", style = "color: #2c3e50; margin-top: 0;"),
        div(
          style = "display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 15px;",
          div(
            style = "padding: 10px; background: white; border-radius: 5px; border-left: 4px solid var(--primary);",
            strong("细胞簇:"), results$cluster
          ),
          div(
            style = "padding: 10px; background: white; border-radius: 5px; border-left: 4px solid var(--primary);",
            strong("注释结果:"), results$annotation
          ),
          div(
            style = "padding: 10px; background: white; border-radius: 5px; border-left: 4px solid var(--primary);",
            strong("综合评分:"), round(results$confidence, 3)
          )
        ),
        div(
          style = "padding: 10px; background: white; border-radius: 5px; margin-bottom: 10px;",
          strong("关键证据:"),
          {
            # 安全处理key_evidence
            if (!is.null(results$key_evidence)) {
              # 尝试转换为字符向量
              evidence_char <- tryCatch(
                {
                  if (is.character(results$key_evidence)) {
                    results$key_evidence
                  } else if (is.vector(results$key_evidence) && !is.list(results$key_evidence)) {
                    as.character(results$key_evidence)
                  } else if (is.factor(results$key_evidence)) {
                    as.character(results$key_evidence)
                  } else {
                    # 其他类型，尝试通用转换
                    as.character(results$key_evidence)
                  }
                },
                error = function(e) {
                  character(0)
                }
              )

              # 清理和验证
              evidence_char <- evidence_char[!is.na(evidence_char) & evidence_char != "" & nchar(evidence_char) > 0]

              if (length(evidence_char) > 0) {
                paste(evidence_char, collapse = ", ")
              } else {
                "无有效证据数据"
              }
            } else {
              "无证据数据"
            }
          }
        ),
        div(
          style = "padding: 10px; background: white; border-radius: 5px;",
          strong("生物学背景:"),
          {
            # 安全处理biological_background
            if (!is.null(results$biological_background)) {
              # 尝试转换为字符
              bg_char <- tryCatch(
                {
                  if (is.character(results$biological_background)) {
                    results$biological_background
                  } else {
                    as.character(results$biological_background)
                  }
                },
                error = function(e) {
                  "生物学背景转换失败"
                }
              )

              # 验证结果
              if (is.character(bg_char) && !is.na(bg_char) && nchar(bg_char) > 0) {
                bg_char
              } else {
                "无有效生物学背景信息"
              }
            } else {
              "无生物学背景信息"
            }
          }
        )
      )
    } else {
      div(
        style = "padding: 20px; text-align: center; color: #6c757d;",
        "暂无分析结果"
      )
    }
  })

  # 批量结果可视化：细胞类型分布饼图
  output$batch_type_distribution <- renderPlotly({
    req(rv$batch_results)

    # 统计各细胞类型数量
    success_results <- rv$batch_results[sapply(rv$batch_results, function(x) x$status == "success")]
    if (length(success_results) == 0) {
      return(NULL)
    }

    type_counts <- table(sapply(success_results, function(x) x$annotation))

    plot_ly(
      labels = names(type_counts),
      values = as.numeric(type_counts),
      type = "pie",
      marker = list(colors = RColorBrewer::brewer.pal(min(length(type_counts), 11), "Set3")),
      textposition = "inside",
      textinfo = "label+percent"
    ) %>%
      layout(
        title = "细胞类型分布",
        showlegend = TRUE
      )
  })

  # 批量结果可视化：三维度评分箱线图
  output$batch_score_distribution <- renderPlotly({
    req(rv$batch_results)

    # 提取评分数据
    success_results <- rv$batch_results[sapply(rv$batch_results, function(x) x$status == "success")]
    if (length(success_results) == 0) {
      return(NULL)
    }

    # 新的数据结构：三个Marker子指标 + Database Support
    scores_df <- data.frame(
      cluster = names(success_results),
      marker_specificity = sapply(success_results, function(x) x$marker_specificity %||% 0),
      marker_expression = sapply(success_results, function(x) x$marker_expression %||% 0),
      marker_significance = sapply(success_results, function(x) x$marker_significance %||% 0),
      database_support_num = sapply(success_results, function(x) {
        ds <- x$database_support %||% "0/3"
        as.numeric(strsplit(ds, "/")[[1]][1])
      }),
      stringsAsFactors = FALSE
    )

    # reshape数据为长格式（三个Marker子指标）
    scores_long <- data.frame(
      cluster = rep(scores_df$cluster, 3),
      dimension = rep(c("Marker Specificity", "Marker Expression", "Marker Significance"), each = nrow(scores_df)),
      score = c(scores_df$marker_specificity, scores_df$marker_expression, scores_df$marker_significance),
      stringsAsFactors = FALSE
    )

    plot_ly(scores_long,
      x = ~dimension, y = ~score, type = "box",
      color = ~dimension,
      colors = c("#4B0082", "#6A5ACD", "#9370DB")
    ) %>%
      layout(
        title = "三维度评分分布",
        yaxis = list(title = "分数", range = c(0, 1)),
        xaxis = list(title = "评分维度"),
        showlegend = FALSE
      )
  })

  # STRINGdb分析UI
  output$stringdb_ui <- renderUI({
    if (!is.null(rv$stringdb_results) && length(rv$stringdb_results) > 0) {
      div(
        style = "height: 100%; overflow-y: auto;",
        h5("STRINGdb蛋白质互作网络分析", style = "color: #2c3e50;"),
        p("分析完成时间:", rv$stringdb_results$timestamp, style = "font-size: 12px; color: #6c757d;"),
        tags$div(
          style = "margin-bottom: 15px;",
          HTML("<strong>关键统计:</strong>"),
          br(),
          paste("输入基因数:", rv$stringdb_results$input_genes),
          br(),
          paste("互作关系数:", rv$stringdb_results$interactions),
          br(),
          paste("平均置信度:", round(rv$stringdb_results$avg_confidence, 2))
        ),
        if (!is.null(rv$stringdb_results$network_plot) && rv$stringdb_results$network_plot != "") {
          tags$div(
            style = "text-align: center; margin-bottom: 15px;",
            htmltools::HTML(rv$stringdb_results$network_plot)
          )
        },
        if (!is.null(rv$stringdb_results$top_interactions)) {
          tags$div(
            style = "margin-top: 15px;",
            h6("Top 10 互作关系", style = "color: #495057;"),
            DT::dataTableOutput("stringdb_table")
          )
        }
      )
    } else if (rv$aura2_status$analysis_complete) {
      # 分析失败或数据不足
      div(
        style = "height: 100%; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 20px;",
        icon("exclamation-circle", class = "fa-2x", style = "color: #f39c12; margin-bottom: 15px;"),
        h5("STRINGdb分析未完成", style = "color: #6c757d;"),
        p(
          style = "font-size: 12px; color: #999; text-align: center;",
          "标记基因可能不在数据库中，",
          br(),
          "这不影响辩论引擎，其他数据库正常"
        )
      )
    } else {
      div(
        style = "height: 100%; display: flex; align-items: center; justify-content: center; color: #6c757d;",
        "请先完成AURA2.0分析"
      )
    }
  })

  # STRINGdb数据表格输出
  output$stringdb_table <- DT::renderDT({
