  # 验证证据链UI
  output$evidence_chain_ui <- renderUI({
    if (rv$aura2_status$analysis_complete && !is.null(rv$validation_result)) {
      validation <- rv$validation_result
      kg <- rv$knowledge_base

      div(
        style = "height: 100%; overflow-y: auto;",
        h5("验证证据链", style = "color: #2c3e50;"),
        p("验证完成时间:", format(Sys.time(), "%Y-%m-%d %H:%M:%S"), style = "font-size: 12px; color: #6c757d;"),
        div(
          style = "margin-top: 15px;",
          div(
            style = "padding: 15px; background: white; border-radius: 8px; border: 1px solid #dee2e6; margin-bottom: 15px;",
            h6("生物学可信度评分", style = "color: #3498db; margin-top: 0;"),
            p(strong("验证分数:"), if (is.numeric(validation$biological_score)) round(validation$biological_score, 2) else "N/A"),
