              div(style = "color: #6f42c1; font-weight: bold; margin-bottom: 5px;", "📚 文献支持验证"),
              p("相关文献:", kg$analysis_summary$literature_summary$total_articles),
              p("近期文献:", kg$analysis_summary$literature_summary$recent_articles %||% 0)
            )
